export const DOMAINS_SRC = "# -*- coding: utf-8 -*-\n\"\"\"算法分类的运行时副本——AUTO-GENERATED，请勿手改。\n来源：data/families.json（家族 short 标签）+ data/algos.json（每个算法的 family）；\n生成：python tools/gen_taxonomy.py（build_pages.py 每次构建自动执行）。\n\n算法下拉框的分组标签一律经 category_of() 得出，TSP 页与各问题域页因此永远与站点家族一致。\n\"\"\"\n\nFAMILY_SHORT = {\n    \"F1\": \"进化计算\",\n    \"F2\": \"群体智能\",\n    \"F3\": \"物理·化学·数学启发\",\n    \"F4\": \"人类与社会启发\",\n    \"F5\": \"免疫与其他生物\",\n    \"F10\": \"局部搜索与轨迹法\",\n    \"F6\": \"混合与框架\",\n    \"F7\": \"多目标\",\n    \"F8\": \"新范式\",\n    \"F9\": \"隐喻批评\",\n    \"F0\": \"专用求解（对照）\"\n}\n\nALGO_CATEGORY = {\n    \"abc\": \"群体智能\",\n    \"aco\": \"群体智能\",\n    \"afsa\": \"群体智能\",\n    \"ais\": \"免疫与其他生物\",\n    \"alo\": \"群体智能\",\n    \"ao\": \"群体智能\",\n    \"ba\": \"群体智能\",\n    \"bbo\": \"进化计算\",\n    \"bfo\": \"群体智能\",\n    \"boa\": \"群体智能\",\n    \"cem\": \"进化计算\",\n    \"cma-es\": \"进化计算\",\n    \"cs\": \"群体智能\",\n    \"cscrow\": \"群体智能\",\n    \"da\": \"群体智能\",\n    \"de\": \"进化计算\",\n    \"eo\": \"物理·化学·数学启发\",\n    \"fa\": \"群体智能\",\n    \"fpa\": \"群体智能\",\n    \"fwa\": \"群体智能\",\n    \"ga\": \"进化计算\",\n    \"grasp\": \"局部搜索与轨迹法\",\n    \"gsa\": \"物理·化学·数学启发\",\n    \"gwo\": \"群体智能\",\n    \"hho\": \"群体智能\",\n    \"hs\": \"人类与社会启发\",\n    \"ica\": \"人类与社会启发\",\n    \"ils\": \"局部搜索与轨迹法\",\n    \"jaya\": \"物理·化学·数学启发\",\n    \"kh\": \"群体智能\",\n    \"lk\": \"专用求解（对照）\",\n    \"mfo\": \"群体智能\",\n    \"mpa\": \"群体智能\",\n    \"pso\": \"群体智能\",\n    \"sa\": \"物理·化学·数学启发\",\n    \"salp\": \"群体智能\",\n    \"sca\": \"物理·化学·数学启发\",\n    \"sfla\": \"群体智能\",\n    \"sma\": \"群体智能\",\n    \"sos\": \"群体智能\",\n    \"ssa\": \"群体智能\",\n    \"tlbo\": \"人类与社会启发\",\n    \"ts\": \"局部搜索与轨迹法\",\n    \"vns\": \"局部搜索与轨迹法\",\n    \"woa\": \"群体智能\"\n}\n\n\n# 分组标签 → 展示顺序（= families.json 里的家族顺序）；不在家族体系里的标签排在最前（基线/构造件）\nCATEGORY_RANK = {\"进化计算\": 0, \"群体智能\": 1, \"物理·化学·数学启发\": 2, \"人类与社会启发\": 3, \"免疫与其他生物\": 4, \"局部搜索与轨迹法\": 5, \"混合与框架\": 6, \"多目标\": 7, \"新范式\": 8, \"隐喻批评\": 9, \"专用求解（对照）\": 10}\n\n\ndef category_rank(category):\n    return CATEGORY_RANK.get(category, -1)\n\n\n# 域内核的后缀与 algos.json 里的算法键不一致的少数几个\n_KERNEL_ALIAS = {\"cmaes\": \"cma-es\"}\n\n\ndef category_of(key, default=None):\n    \"\"\"算法键 → 分组标签。问题域里的变种内核（bv_pso / pk_sma / as_eo）取其基础算法的分类；\n    不在家族体系里的（random/hc/贪心基线等）返回 default。\"\"\"\n    base = key.split(\"_\", 1)[1] if key[:3] in (\"bv_\", \"pk_\", \"as_\") else key\n    base = _KERNEL_ALIAS.get(base, base)\n    return ALGO_CATEGORY.get(base, default)\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\nP1 域引擎组件库 —— 问题域侧可复用组件（S1-1 组件化重构，2026-09-17）\n==========================================================================\n单一事实来源：py/domains.py（背包/连续/排列域引擎）中跨算法重复的骨架件全部搬到这里。\n与 py/components.py 的分工：\n  components.py      = TSP 排列域通用算子（构造/局部搜索/交叉/编码），服务 solvers.py\n  domain_components.py = 问题域引擎的通用骨架件（最优追踪/种群基建/二进制与排列算子），服务 domains.py\n\n构建期行为与 components.py 同款：build_pages.py 把本文件与 domains.py 拼进同一名字\n空间执行，此时 domains.py 里的 `from domain_components import ...` 抛 ImportError →\nexcept 分支跳过（所有名字已在空间内），两种环境行为完全一致。\n\n纪律：本文件所有函数都必须保持 RNG 调用顺序与被替换的内联写法严格一致——\nbench/selfcheck/tests 全部依赖固定 seed 的可复现性，顺序一变=行为一变。\n\"\"\"\n\nimport random\nfrom typing import List, Optional, Tuple\n\n\n# ============================ 最优追踪 ============================\n\ndef bump(best, bs, v, s, mode: str = \"max\"):\n    \"\"\"最优解追踪：v 优于 best 时返回 (v, list(s))，否则原样返回。\n\n    替换各算法里成对的 `if v > best: best, bs = v, list(s)`；\n    min 模式（连续域最小化）传 mode=\"min\"。\n    \"\"\"\n    if (v > best) if mode == \"max\" else (v < best):\n        return v, list(s)\n    return best, bs\n\n\ndef argbest(vals: List, mode: str = \"max\") -> int:\n    \"\"\"种群最优个体下标（并列取最先出现，与内联 max/min(range(...)) 写法一致）。\"\"\"\n    if mode == \"max\":\n        return max(range(len(vals)), key=lambda i: vals[i])\n    return min(range(len(vals)), key=lambda i: vals[i])\n\n\ndef argworst(vals: List, mode: str = \"max\") -> int:\n    \"\"\"种群最差个体下标（mode=max 时最差=最小值）。\"\"\"\n    return argbest(vals, mode=\"min\" if mode == \"max\" else \"max\")\n\n\n# ============================ 二进制编码算子（背包域） ============================\n\ndef bits_uniform(pa: List[int], pb: List[int], rng: random.Random) -> List[int]:\n    \"\"\"均匀交叉：逐位以 0.5 概率取父本 1 或 2（RNG 顺序 = 先随机后取位，与内联一致）。\"\"\"\n    return [pa[i] if rng.random() < 0.5 else pb[i] for i in range(len(pa))]\n\n\ndef bits_mutate(child: List[int], pm: float, rng: random.Random) -> List[int]:\n    \"\"\"逐位翻转变异：每位以 pm 概率翻转（原地修改并返回）。\"\"\"\n    for i in range(len(child)):\n        if rng.random() < pm:\n            child[i] ^= 1\n    return child\n\n\ndef bits_flip(s: List[int], rng: random.Random, k: int = 1) -> List[int]:\n    \"\"\"随机 k 位翻转（返回新列表）。\"\"\"\n    s = list(s)\n    for _ in range(k):\n        s[rng.randrange(len(s))] ^= 1\n    return s\n\n\ndef bits_pop_init(ctx, p: dict, rng: random.Random) -> Tuple[List, List]:\n    \"\"\"种群初始化基建：ctx.random 生成 + ctx.value 评估（背包域口径）。\"\"\"\n    pop = [ctx.random(rng) for _ in range(p[\"n_pop\"])]\n    return pop, [ctx.value(s) for s in pop]\n\n\ndef greedy_replace(pop: list, vals: list, i: int, cand, v, mode: str = \"max\") -> bool:\n    \"\"\"贪心逐位替换（DE/WOA/GWO/CS 家族共用的「新解优于当前个体则替换」基建）。\n    返回是否发生替换；最优追踪由调用方随后 bump。\"\"\"\n    if (v > vals[i]) if mode == \"max\" else (v < vals[i]):\n        pop[i], vals[i] = cand, v\n        return True\n    return False\n\n\n# ============================ 排列域算子（图着色 + 装箱共用） ============================\n\ndef pm_ox(a: List[int], b: List[int], rng: random.Random) -> List[int]:\n    \"\"\"OX 顺序交叉（与 TSP 组件 _ox_crossover 同款；域名字空间自含一份，\n    因 domains_src.js 与 solvers_src.js 是两个独立 Pyodide 名字空间）。\"\"\"\n    n = len(a)\n    i, j = sorted(rng.sample(range(n), 2))\n    child: List[Optional[int]] = [None] * n\n    child[i:j + 1] = a[i:j + 1]\n    seg = set(child[i:j + 1])\n    fill = [x for x in b if x not in seg]\n    k = 0\n    for idx in range(n):\n        if child[idx] is None:\n            child[idx] = fill[k]\n            k += 1\n    return child\n\n\ndef pm_swap(perm: List[int], rng: random.Random) -> List[int]:\n    \"\"\"交换邻域：随机取两位互换。\"\"\"\n    p = list(perm)\n    i, j = rng.sample(range(len(p)), 2)\n    p[i], p[j] = p[j], p[i]\n    return p\n\n\ndef pm_insert(perm: List[int], rng: random.Random) -> List[int]:\n    \"\"\"插入邻域：随机取一位移到随机位置。\"\"\"\n    p = list(perm)\n    v = p.pop(rng.randrange(len(p)))\n    p.insert(rng.randrange(len(p)), v)\n    return p\n\n\ndef pm_polish(ctx, perm: List[int], rng: random.Random, moves: int) -> List[int]:\n    \"\"\"memetic 组件：随机交换邻域的首改进爬山（小预算，元组字典序目标）。\"\"\"\n    perm = list(perm)\n    c = ctx.decode(perm)\n    for _ in range(moves):\n        cand = pm_swap(perm, rng)\n        cc = ctx.decode(cand)\n        if cc < c:  # 元组字典序：(主指标, 次级指标)\n            perm, c = cand, cc\n    return perm\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\nentryseq（原子词条域）：变体的实例生成器与目标函数。\n\n一个变体 = 两个函数：\n    @_maker(\"名字\")      生成实例   fn(variant, n, seed, rng) -> dict\n    @_objective(\"名字\")  目标函数   fn(self, s) -> 数值（越小越好）\n新增一个变体 = 在本文件加这一对函数，并在 py/registry.py 之外无需再改任何登记表——\nVARIANTS 由注册顺序自动得出。\n\n本文件由 domains.py 里原来的 es_make / _ES.obj（两条各数百行的 if 链）机械拆分而来，函数体逐字保留；\n拆分前后 tests/golden 快照逐项一致。自包含：只依赖 math / random。\n\"\"\"\nimport math\nimport random\n\n_MAKERS = {}\n_OBJS = {}\n_DETAIL = {}\n\n\ndef _detail(*variants):\n    \"\"\"页面可视化需要的、由当前最优解推出的附加信息（路线、机器分配、聚类中心、设计变量与约束……）。\n    引擎在每个状态里把它并进去；页面只画，不重算。\"\"\"\n    def deco(fn):\n        for v in variants:\n            _DETAIL[v] = fn\n        return fn\n    return deco\n\n\ndef _maker(*variants):\n    def deco(fn):\n        for v in variants:\n            assert v not in _MAKERS, f\"变体 {v} 重复登记\"\n            _MAKERS[v] = fn\n        return fn\n    return deco\n\n\nFIDELITY_LEVELS = (\"standard\", \"simplified\", \"illustrative\")\nFIDELITY = {}  # 变体 -> {\"level\": ..., \"note\": 与标准定义的差异（非 standard 必填）}\nES_ENCODINGS = (\"perm\", \"bits\", \"real\")  # 不叫 ENCODINGS：userproblem.py 里已有同名顶层名字，浏览器里会互相覆盖\nENCODING = {}  # 变体 -> 解的编码：perm 排列（默认）/ bits 位向量（每位选或不选）/ real 实数向量\n\n\ndef _objective(*variants, fidelity, note=\"\", encoding=\"perm\"):\n    \"\"\"登记目标函数。encoding 是解的编码（perm 排列 / bits 位向量 / real 实数向量，默认排列）：它决定该变体用哪一族算法，\n    也决定 `ctx.random` 产生什么样的解——所以和目标函数写在一起，不在别处另列清单。fidelity 必填——\n        standard     与教科书/文献定义一致，结果可与文献对照\n        simplified   问题本身是真的，但解码/约束做了教学级简化，数值不能与文献对照\n        illustrative 只借这个问题的名字演示其形态，模型并不是该问题本身\n    非 standard 必须写 note：一句话说明「与标准定义的差异」，页面与上传校验都会显示它。\"\"\"\n    assert fidelity in FIDELITY_LEVELS, fidelity\n    assert encoding in ES_ENCODINGS, encoding\n    assert fidelity == \"standard\" or note, f\"{variants}: 非 standard 必须写 note\"\n\n    def deco(fn):\n        for v in variants:\n            assert v not in _OBJS, f\"变体 {v} 重复登记\"\n            _OBJS[v] = fn\n            FIDELITY[v] = {\"level\": fidelity, \"note\": note}\n            ENCODING[v] = encoding\n        return fn\n    return deco\n\n\n# ============================================================ 实例生成\n\n\n@_maker('vrp')\ndef _make_vrp(variant, n, seed, rng):\n    # 带容量车辆路径（CVRP）：1 仓库（居中）+ n 个客户；车辆容量按「平均每车 5 个客户左右」定，\n    # 车队规模 = 理论最少车数 + 1（留一辆余量，否则随机顺序大多无法切成合法路线）\n    k = max(5, min(n, 40))\n    pts = [[50.0, 50.0]] + [[round(rng.uniform(0, 100), 2), round(rng.uniform(0, 100), 2)] for _ in range(k)]\n    demand = [0] + [rng.randint(1, 9) for _ in range(k)]\n    cap = max(max(demand), int(sum(demand) / max(1, round(k / 5))) + 1)\n    m_veh = -(-sum(demand) // cap) + 1\n    return {\"variant\": variant, \"pts\": pts, \"demand\": demand, \"cap\": cap,\n            \"m_veh\": m_veh, \"n\": k}  # n=客户数（pts[0]=仓库）\n\n\n@_maker('vrptw', 'vrpstw')\ndef _make_vrptw(variant, n, seed, rng):\n    # 带时间窗的车辆路径（VRPTW 硬时间窗；vrpstw 软时间窗共用本生成器）：1 仓库（居中）+ k 个客户，速度 1（行驶时间 = 欧氏距离），服务时间每个客户 10。\n    # 先随机造一组满足容量的参考路线，把每个客户在参考路线里的到达时刻 t 当作时间窗的中心：窗 = [t - w/2, t + w/2]（w 取 30..60）。\n    # 这样「至少有一个可行解」是构造出来的；仓库的窗 [0, H] 的 H 取「所有参考路线回仓时刻、每个客户单独跑一趟的回仓时刻」的最大值向上取整。\n    # 车队规模 = 参考路线数 + 1。\n    k = max(5, min(n, 40))\n    pts = [[50.0, 50.0]] + [[round(rng.uniform(0, 100), 2), round(rng.uniform(0, 100), 2)] for _ in range(k)]\n    demand = [0] + [rng.randint(1, 9) for _ in range(k)]\n    cap = max(max(demand), int(sum(demand) / max(1, round(k / 5))) + 1)\n    svc = [0] + [10] * k\n    order = list(range(1, k + 1))\n    rng.shuffle(order)\n    ref, cur, load = [], [], 0\n    for c in order:\n        if load + demand[c] > cap:\n            ref.append(cur)\n            cur, load = [], 0\n        cur.append(c)\n        load += demand[c]\n    ref.append(cur)\n    e, l = [0.0] * (k + 1), [0.0] * (k + 1)\n    ret_max = 0.0\n    for route in ref:\n        t, prev = 0.0, 0\n        for c in route:\n            t += math.dist(pts[prev], pts[c])\n            w = rng.uniform(30, 60)\n            e[c], l[c] = round(max(0.0, t - w / 2), 2), round(t + w / 2, 2)\n            t += svc[c]\n            prev = c\n        ret_max = max(ret_max, t + math.dist(pts[prev], pts[0]))\n    solo = max(l[c] + svc[c] + math.dist(pts[c], pts[0]) for c in range(1, k + 1))\n    H = float(math.ceil(max(ret_max, solo)))\n    l[0] = H\n    out = {\"variant\": variant, \"pts\": pts, \"demand\": demand, \"cap\": cap, \"m_veh\": len(ref) + 1, \"n\": k,\n           \"e\": e, \"l\": l, \"svc\": svc}  # n=客户数；e/l/svc 下标与 pts 一致（0 = 仓库）\n    if variant == \"vrpstw\":\n        out[\"lam\"] = 2.0  # 软时间窗：每晚到 1 个时间单位罚 lam 个里程单位（客户窗与仓库关门都算）\n    return out\n\n\n@_maker('mdvrp')\ndef _make_mdvrp(variant, n, seed, rng):\n    # 多车场车辆路径（MDVRP）：D 个仓库（2 或 3 个）+ k 个客户；每个仓库有自己的 m_dep 辆车（同容量 cap），车从自己的仓库出发、回到自己的仓库。\n    # 解 = 长度 k + D - 1 的排列：0..k-1 是客户，k..k+D-2 是「仓库分隔符」——第 d 段（分隔符把序列切成 D 段）里的客户归第 d 个仓库。\n    k = max(5, min(n, 40))\n    D = 2 if k <= 12 else 3\n    depots = [[25.0, 50.0], [75.0, 50.0]] if D == 2 else [[25.0, 30.0], [75.0, 30.0], [50.0, 80.0]]\n    pts = depots + [[round(rng.uniform(0, 100), 2), round(rng.uniform(0, 100), 2)] for _ in range(k)]\n    demand = [0] * D + [rng.randint(1, 9) for _ in range(k)]\n    cap = max(max(demand), int(sum(demand) / max(1, round(k / 5))) + 1)\n    need = -(-sum(demand) // cap)  # 总车数下限\n    m_dep = -(-need // D) + 1  # 按仓库均分，再留一辆余量\n    return {\"variant\": variant, \"pts\": pts, \"demand\": demand, \"cap\": cap, \"m_dep\": m_dep, \"D\": D,\n            \"n\": k + D - 1}  # n = 排列长度 = len(pts) - 1；pts 前 D 个是仓库\n\n\n# ---- 调度 / 路径类标准模型（2026-10 重做）----\n\n_TAI_M = 2147483647\n\n\ndef _tai_unif(seed, low, high):\n    \"\"\"Taillard (1993) 的伪随机数发生器（Lehmer LCG, a=16807）：论文里的基准实例就是用它和公开的种子造出来的。\"\"\"\n    a, b, c = 16807, 127773, 2836\n    k = seed[0] // b\n    seed[0] = a * (seed[0] % b) - k * c\n    if seed[0] < 0:\n        seed[0] += _TAI_M\n    return low + int(seed[0] / _TAI_M * (high - low + 1))\n\n\n@_maker('fss')\ndef _make_fss(variant, n, seed, rng):\n    # 置换流水车间 PFSP：n 个作业 × 5 台机器、加工时间 1–99。n=20 时就是 Taillard 的 ta001（时间种子 873654221，最优 1278）；其余规模用同一发生器造\n    nn = max(5, min(n, 20))\n    m = 5\n    sd = [873654221 if nn == 20 else (seed * 7919 + nn * 104729) % (_TAI_M - 1) + 1]\n    p = [[_tai_unif(sd, 1, 99) for _ in range(nn)] for _ in range(m)]\n    return {\"variant\": variant, \"p\": p, \"n\": nn, \"m_mach\": m, \"name\": \"ta001\" if nn == 20 else \"\", \"opt\": 1278 if nn == 20 else None}\n\n\n@_maker('oss')\ndef _make_oss(variant, n, seed, rng):\n    # 开放车间：n 个作业 × n 台机器，每个作业在每台机器上各做一次、机器顺序自由；时间 1–99（同 Taillard 开放车间的设定）。排列长度 = n² 个工序\n    nn = max(3, min(n, 6))\n    sd = [(seed * 6007 + nn * 15485863) % (_TAI_M - 1) + 1]\n    t = [[_tai_unif(sd, 1, 99) for _ in range(nn)] for _ in range(nn)]\n    lb = max(max(sum(r) for r in t), max(sum(t[j][k] for j in range(nn)) for k in range(nn)))\n    return {\"variant\": variant, \"t\": t, \"n\": nn * nn, \"n_jobs\": nn, \"m_mach\": nn, \"lb\": lb}\n\n\n_FT06 = [[(2, 1), (0, 3), (1, 6), (3, 7), (5, 3), (4, 6)], [(1, 8), (2, 5), (4, 10), (5, 10), (0, 10), (3, 4)],\n         [(2, 5), (3, 4), (5, 8), (0, 9), (1, 1), (4, 7)], [(1, 5), (0, 5), (2, 5), (3, 3), (4, 8), (5, 9)],\n         [(2, 9), (1, 3), (4, 5), (5, 4), (0, 3), (3, 1)], [(1, 3), (3, 3), (5, 9), (0, 10), (4, 4), (2, 1)]]\n\n\n@_maker('jss')\ndef _make_jss(variant, n, seed, rng):\n    # 作业车间 JSP：每个作业有自己的机器路线。n=6 时是 Fisher–Thompson 的 ft06（6×6，最优 55）；其余规模随机（5 台机器、时间 1–20、每个作业一条随机路线）\n    nn = max(4, min(n, 10))\n    if nn == 6:\n        jobs, m, name, opt = [[list(op) for op in j] for j in _FT06], 6, \"ft06\", 55\n    else:\n        m, name, opt = 5, \"\", None\n        jobs = [[[k, rng.randint(1, 20)] for k in rng.sample(range(m), m)] for _ in range(nn)]\n    mload = [0] * m\n    for j in jobs:\n        for (k, t) in j:\n            mload[k] += t\n    lb = max(max(mload), max(sum(t for _k, t in j) for j in jobs))\n    return {\"variant\": variant, \"jobs\": jobs, \"n\": nn * m, \"n_jobs\": nn, \"m_mach\": m, \"name\": name, \"opt\": opt, \"lb\": lb}\n\n\n@_maker('fjsp')\ndef _make_fjsp(variant, n, seed, rng):\n    # 柔性作业车间：n 个作业各 3 道工序（顺序固定），每道工序可在 2–3 台机器（共 5 台）中的任一台做，时间因机器而异（2–10）\n    nn = max(4, min(n, 8))\n    m, nops = 5, 3\n    jobs = []\n    for _ in range(nn):\n        ops = []\n        for _o in range(nops):\n            ks = rng.sample(range(m), rng.randint(2, 3))\n            ops.append([[k, rng.randint(2, 10)] for k in sorted(ks)])\n        jobs.append(ops)\n    lb_job = max(sum(min(t for _k, t in op) for op in j) for j in jobs)\n    lb_work = -(-sum(min(t for _k, t in op) for j in jobs for op in j) // m)\n    return {\"variant\": variant, \"jobs\": jobs, \"n\": nn * nops, \"n_jobs\": nn, \"m_mach\": m, \"lb\": max(lb_job, lb_work)}\n\n\n@_maker('hc')\ndef _make_hc(variant, n, seed, rng):\n    # 哈密顿回路：随机图（植入一条哈密顿回路，再以 0.12 的概率加其余边）。目标 = 排列相邻对里「不是边」的个数，0 就找到了回路\n    nn = max(6, min(n, 14))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    cyc = list(range(nn))\n    rng.shuffle(cyc)\n    E = {(min(cyc[i], cyc[(i + 1) % nn]), max(cyc[i], cyc[(i + 1) % nn])) for i in range(nn)}\n    for a in range(nn):\n        for b in range(a + 1, nn):\n            if rng.random() < 0.12:\n                E.add((a, b))\n    return {\"variant\": variant, \"pts\": pts, \"edges\": [list(e) for e in sorted(E)], \"n\": nn}\n\n\n@_maker('lpath')\ndef _make_lpath(variant, n, seed, rng):\n    # 最长路径：随机图（植入一条哈密顿路径，权重 5–20；其余边以 0.25 的概率出现，权重 1–20）。目标 = 沿排列走、碰到非边就停时累计的权重（最大化）\n    nn = max(6, min(n, 12))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    order = list(range(nn))\n    rng.shuffle(order)\n    W = {}\n    for i in range(nn - 1):\n        a, b = order[i], order[i + 1]\n        W[(min(a, b), max(a, b))] = rng.randint(5, 20)\n    for a in range(nn):\n        for b in range(a + 1, nn):\n            if (a, b) not in W and rng.random() < 0.25:\n                W[(a, b)] = rng.randint(1, 20)\n    return {\"variant\": variant, \"pts\": pts, \"edges\": [[a, b, w] for (a, b), w in sorted(W.items())], \"n\": nn}\n\n\ndef _carp_graph(rng, nv):\n    \"\"\"随机路网：每点连最近的 3 个点，再并入最小生成树的边（保证连通）；边费用 = 欧氏长度取整。\"\"\"\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nv)]\n    E = set()\n    for i in range(nv):\n        for j in sorted((j for j in range(nv) if j != i), key=lambda j: math.dist(pts[i], pts[j]))[:3]:\n            E.add((min(i, j), max(i, j)))\n    par = list(range(nv))\n\n    def find(x):\n        while par[x] != x:\n            par[x] = par[par[x]]\n            x = par[x]\n        return x\n    for (d, a, b) in sorted((math.dist(pts[a], pts[b]), a, b) for a in range(nv) for b in range(a + 1, nv)):\n        ra, rb = find(a), find(b)\n        if ra != rb:\n            par[ra] = rb\n            E.add((a, b))\n    return pts, [[a, b, max(1, round(math.dist(pts[a], pts[b])))] for (a, b) in sorted(E)]\n\n\n@_maker('carp', 'rpostman')\ndef _make_carp(variant, n, seed, rng):\n    # 弧路由：一张随机路网（14 个路口），其中 n 条边「必须服务」（carp 还带需求量，车容量 20）；rpostman = 不限容量，一条回路覆盖全部必需边\n    nr = max(6, min(n, 12))\n    nv = 14\n    pts, edges = _carp_graph(rng, nv)\n    req = sorted(rng.sample(range(len(edges)), min(nr, len(edges))))\n    dem = {k: (rng.randint(2, 8) if variant == \"carp\" else 0) for k in req}\n    depot = min(range(nv), key=lambda i: math.dist(pts[i], [50.0, 50.0]))\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"req\": req, \"dem\": [dem[k] for k in req], \"depot\": depot,\n            \"cap\": 20 if variant == \"carp\" else 10 ** 6, \"n\": len(req)}\n\n\n@_maker('lop')\ndef _make_lop(variant, n, seed, rng):\n    # 线性排序：权重矩阵，Σ_{i<j} w[π(j)][π(i)] 最大化\n    nn = max(5, min(n, 12))\n    w = [[0 if i == j else rng.randint(1, 20) for j in range(nn)] for i in range(nn)]\n    return {\"variant\": variant, \"w\": w, \"n\": nn}\n\n\n@_maker('sms')\ndef _make_sms(variant, n, seed, rng):\n    # 单机总延误\n    nn = max(5, min(n, 10))\n    p = [rng.randint(2, 12) for _ in range(nn)]\n    d = [rng.randint(8, 30) for _ in range(nn)]\n    return {\"variant\": variant, \"p\": p, \"d\": d, \"n\": nn}\n\n\n@_maker('ctp')\ndef _make_ctp(variant, n, seed, rng):\n    # 课程排课（课程表问题 CTP 的精简版）：n 门课，每门 1–3 节、由某位教师授课、有若干学生；\n    # 另有若干「课程组」（同一届学生要修的几门课），同一组、同一教师的课不能在同一个时段；一周 5 天 × 2 节 = 10 个时段，3 间教室（容量 30 / 45 / 60）\n    nn = max(4, min(n, 14))\n    lec = [rng.randint(1, 3) for _ in range(nn)]\n    teacher = [rng.randrange(max(3, nn // 2)) for _ in range(nn)]\n    size = [rng.randint(20, 60) for _ in range(nn)]\n    groups = [sorted(rng.sample(range(nn), min(3, nn))) for _ in range(max(2, nn // 3))]\n    # 每位教师、每个课程组的总课时都不超过 8（= 时段数的 80%）：否则它们的课根本排不进去，实例就是无解的\n    while True:\n        over = [c for t in set(teacher) for c in range(nn) if teacher[c] == t and sum(lec[x] for x in range(nn) if teacher[x] == t) > 8]\n        over += [c for g in groups for c in g if sum(lec[x] for x in g) > 8]\n        if not over:\n            break\n        c = max(over, key=lambda c: lec[c])\n        lec[c] = max(1, lec[c] - 1)\n    lec_course = [c for c in range(nn) for _ in range(lec[c])]  # 第 k 节课属于哪门课\n    return {\"variant\": variant, \"lec\": lec, \"teacher\": teacher, \"size\": size, \"groups\": groups, \"lec_course\": lec_course,\n            \"days\": 5, \"slots\": 2, \"rooms\": [30, 45, 60], \"n\": len(lec_course), \"n_courses\": nn}\n\n\n# ---- 批 3：选址族 10 变体（2026-09-27）----\n\n@_maker('lap')\ndef _make_lap(variant, n, seed, rng):\n    # 线性指派：n×n 成本矩阵，排列=指派\n    nn = max(6, min(n, 12))\n    c = [[rng.randint(1, 30) for _ in range(nn)] for _ in range(nn)]\n    return {\"variant\": variant, \"c\": c, \"n\": nn}\n\n\n@_maker('qap')\ndef _make_qap(variant, n, seed, rng):\n    # 二次分配：流量×距离双矩阵\n    nn = max(6, min(n, 10))\n    a = [[rng.randint(0, 10) for _ in range(nn)] for _ in range(nn)]\n    b = [[rng.randint(1, 20) for _ in range(nn)] for _ in range(nn)]\n    return {\"variant\": variant, \"a\": a, \"b\": b, \"n\": nn}\n\n\n@_maker('pmedian', 'pcenter')\ndef _make_pmedian_etc2(variant, n, seed, rng):\n    # p-中位/中心：点集 + 前 p 位=设施\n    nn = max(8, min(n, 14))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    return {\"variant\": variant, \"pts\": pts, \"p\": max(2, nn // 4), \"n\": nn}\n\n\n@_maker('cflp')\ndef _make_cflp(variant, n, seed, rng):\n    # 容量设施选址：每个点既是客户（需求 dem）也是候选设施（容量 cap、固定开设费 fc）；容量总和远大于总需求，开多少个由解码决定\n    nn = max(8, min(n, 12))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    dem = [rng.randint(2, 8) for _ in range(nn)]\n    cap = [rng.randint(14, 28) for _ in range(nn)]\n    while sum(cap) < 2 * sum(dem):\n        cap[rng.randrange(nn)] += 4\n    fc = [rng.randint(200, 500) for _ in range(nn)]\n    return {\"variant\": variant, \"pts\": pts, \"cap\": cap, \"dem\": dem, \"fc\": fc, \"n\": nn}\n\n\n@_maker('lrp')\ndef _make_lrp(variant, n, seed, rng):\n    # 选址-路径联合：n 个客户（有需求），从中选 p 个点建仓库；其余客户由最近的仓库用容量受限的车辆配送\n    nn = max(10, min(n, 14))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    dem = [rng.randint(2, 8) for _ in range(nn)]\n    return {\"variant\": variant, \"pts\": pts, \"dem\": dem, \"p\": 2, \"cap\": 20, \"depot_cost\": 150, \"veh_cost\": 25, \"n\": nn}\n\n\n@_maker('tdm')\ndef _make_tdm(variant, n, seed, rng):\n    # 3-维匹配（最大化版）：X、Y、Z 各 q 个元素，三元组 ⊆ X×Y×Z；选尽量多的两两不相交三元组。\n    # 植入一个完美匹配（q 个三元组），所以最优值已知 = q；再加 2q 个随机三元组当干扰。每个三元组存成 3q 列的 0/1 行（与集合打包同构）。\n    q = max(3, min(6, (n + 1) // 2))\n    ys, zs = list(range(q)), list(range(q))\n    rng.shuffle(ys)\n    rng.shuffle(zs)\n    trip = {(i, ys[i], zs[i]) for i in range(q)}\n    while len(trip) < 3 * q:\n        trip.add((rng.randrange(q), rng.randrange(q), rng.randrange(q)))\n    trip = sorted(trip)\n    rng.shuffle(trip)\n    sets = []\n    for (x, y, z) in trip:\n        row = [0] * (3 * q)\n        row[x] = row[q + y] = row[2 * q + z] = 1\n        sets.append(row)\n    return {\"variant\": variant, \"sets\": sets, \"triples\": [list(t) for t in trip], \"q\": q, \"n\": len(sets)}\n\n\n@_maker('ndp')\ndef _make_ndp(variant, n, seed, rng):\n    # 网络设计（连通需求版）：候选边 = 每点连最近的 3 个点，再并入最小生成树的边（保证候选图连通）；建边费用 = 长度；\n    # 3 对需求点必须在买下的边里连通\n    nn = max(8, min(n, 12))\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nn)]\n    E = set()\n    for i in range(nn):\n        for j in sorted((j for j in range(nn) if j != i), key=lambda j: math.dist(pts[i], pts[j]))[:3]:\n            E.add((min(i, j), max(i, j)))\n    par = list(range(nn))\n\n    def find(x):\n        while par[x] != x:\n            par[x] = par[par[x]]\n            x = par[x]\n        return x\n    for (d, a, b) in sorted((math.dist(pts[a], pts[b]), a, b) for a in range(nn) for b in range(a + 1, nn)):\n        ra, rb = find(a), find(b)\n        if ra != rb:\n            par[ra] = rb\n            E.add((a, b))\n    edges = [[a, b, round(math.dist(pts[a], pts[b]))] for (a, b) in sorted(E)]\n    pairs = []\n    while len(pairs) < 3:\n        a, b = rng.sample(range(nn), 2)\n        if (a, b) not in pairs and (b, a) not in pairs:\n            pairs.append((a, b))\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"pairs\": [list(q) for q in pairs], \"n\": len(edges), \"n_pts\": nn}\n\n\n@_maker('freqasg')\ndef _make_freqasg(variant, n, seed, rng):\n    # 频率分配：发射机×频率，距离-冲突罚（着色同型）\n    nn = max(8, min(n, 12))\n    conf = [[1 if i != j and rng.random() < 0.4 else 0 for j in range(nn)] for i in range(nn)]\n    return {\"variant\": variant, \"conf\": conf, \"n\": nn, \"slots\": 6}\n\n# ---- 批 5：黑箱与多目标族 10 变体（2026-09-27，实数向量）----\n\n@_maker('cbbb', 'nbbb', 'lbbb', 'ebbb', 'mmo')\ndef _make_cbbb_etc5(variant, n, seed, rng):\n    # rastrigin 家族（约束/噪声/大规模/昂贵/多模态）\n    nn = 10 if variant == \"lbbb\" else 8\n    return {\"variant\": variant, \"n\": nn}\n\n\n@_maker('blo')\ndef _make_blo(variant, n, seed, rng):\n    # 双层优化的占位地形（8 维）：见 _obj_blo 的说明——它不是真正的嵌套优化\n    return {\"variant\": variant, \"n\": 8}\n\n\n@_maker('ro')\ndef _make_ro(variant, n, seed, rng):\n    # 鲁棒优化（场景法）：8 维 Rastrigin 地形；决策 x 的实际取值会被 8 个已知的扰动场景 δₖ（每个分量 ∈ [−0.3, 0.3]）打偏，\n    # 要在「最差场景」下也好。场景在实例里固定给出\n    nn = 8\n    scen = [[round(rng.uniform(-0.3, 0.3), 4) for _ in range(nn)] for _ in range(8)]\n    return {\"variant\": variant, \"n\": nn, \"scen\": scen}\n\n\n@_maker('dop')\ndef _make_dop(variant, n, seed, rng):\n    return {\"variant\": variant, \"n\": 8}\n\n\n@_maker('ged')\ndef _make_ged(variant, n, seed, rng):\n    # 生成式设计（布局生成的最小模型）：k 个圆形功能块（半径 6–14），要摆进 100×100 的场地，互不重叠、留 2 个单位的间隙；\n    # 其中一部分块对「希望相邻」（任意两块以 0.35 的概率成对）。解 = 每个块的 (x, y)（实数向量，[−5,5] 线性映射到场地内）\n    k = max(5, min(n, 12))\n    r = [rng.randint(6, 14) for _ in range(k)]\n    adj = [[i, j] for i in range(k) for j in range(i + 1, k) if rng.random() < 0.35]\n    return {\"variant\": variant, \"r\": r, \"adj\": adj, \"gap\": 2, \"size\": 100, \"k\": k, \"n\": 2 * k}\n\n\n@_maker('proteinfold')\ndef _make_proteinfold(variant, n, seed, rng):\n    # HP 格点：H/P 序列（方向序解码）\n    nn = max(12, min(n, 20))\n    seq = [\"H\" if rng.random() < 0.45 else \"P\" for _ in range(nn)]\n    return {\"variant\": variant, \"seq\": seq, \"n\": nn}\n\n\n# ---- P 类对照问题与多序列比对（2026-10 重做）----\n\ndef _pc_graph(rng, nn, directed=False):\n    \"\"\"随机连通图：每对点以 0.3 的概率连边，再并入一棵随机生成树保证连通。返回 (pts, 边对集合)。\"\"\"\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nn)]\n    E = set()\n    for i in range(nn):\n        for j in range(i + 1, nn):\n            if rng.random() < 0.3:\n                E.add((i, j))\n    order = list(range(nn))\n    rng.shuffle(order)\n    for k in range(1, nn):\n        a, b = order[k], order[rng.randrange(k)]\n        E.add((min(a, b), max(a, b)))\n    return pts, sorted(E)\n\n\ndef _pc_find(parent, x):\n    while parent[x] != x:\n        parent[x] = parent[parent[x]]\n        x = parent[x]\n    return x\n\n\ndef _opt_mst(nn, edges):\n    par = list(range(nn))\n    opt = 0\n    for a, b, w in sorted(edges, key=lambda e: e[2]):\n        ra, rb = _pc_find(par, a), _pc_find(par, b)\n        if ra != rb:\n            par[ra] = rb\n            opt += w\n    return opt\n\n\ndef _opt_sp(nn, edges, src, dst):\n    dist = [10 ** 9] * nn\n    dist[src] = 0\n    done = [False] * nn\n    for _ in range(nn):\n        u = min((v for v in range(nn) if not done[v]), key=lambda v: dist[v])\n        done[u] = True\n        for a, b, w in edges:\n            if a == u and dist[u] + w < dist[b]:\n                dist[b] = dist[u] + w\n            if b == u and dist[u] + w < dist[a]:\n                dist[a] = dist[u] + w\n    return dist[dst]\n\n\ndef _opt_gmatch(nn, edges):\n    adjw = [[] for _ in range(nn)]\n    for a, b, w in edges:\n        adjw[a].append((b, w))\n        adjw[b].append((a, w))\n    memo = {}\n\n    def best(mask):\n        if mask == (1 << nn) - 1:\n            return 0\n        if mask in memo:\n            return memo[mask]\n        v = next(i for i in range(nn) if not mask >> i & 1)\n        r = best(mask | 1 << v)  # v 不配对\n        for u, w in adjw[v]:\n            if not mask >> u & 1:\n                r = max(r, w + best(mask | 1 << v | 1 << u))\n        memo[mask] = r\n        return r\n    return best(0)\n\n\n@_maker('mst')\ndef _make_mst(variant, n, seed, rng):\n    # 最小生成树：随机连通加权图（权 1–15）。解 = 边的优先序，Kruskal 式解码（按序加边，成环就跳过）；opt = Kruskal 的最优值\n    nn = max(8, min(n, 24))\n    pts, E = _pc_graph(rng, nn)\n    edges = [[a, b, rng.randint(1, 15)] for a, b in E]\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"n\": len(edges), \"n_nodes\": nn, \"opt\": _opt_mst(nn, edges)}\n\n\n@_maker('shortestpath')\ndef _make_shortestpath(variant, n, seed, rng):\n    # 最短路径：随机连通加权图（权 1–15），起点 0、终点 = 离起点跳数最多的点。解 = 每个点的「优先级」（实数向量），解码从起点出发、每步走向优先级最高的未访问邻居，走进死胡同按重罚计；opt = Dijkstra 的最优值\n    nn = max(8, min(n, 24))\n    pts, E = _pc_graph(rng, nn)\n    edges = [[a, b, rng.randint(1, 15)] for a, b in E]\n    hops, q = {0: 0}, [0]  # 终点取离起点「跳数最多」的点（同跳数取最短距离最大者）：不让起点和终点直接相连\n    for u in q:\n        for a, b, _w in edges:\n            for x, y in ((a, b), (b, a)):\n                if x == u and y not in hops:\n                    hops[y] = hops[u] + 1\n                    q.append(y)\n    dst = max(range(1, nn), key=lambda v: (hops[v], _opt_sp(nn, edges, 0, v)))\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"n\": nn, \"src\": 0, \"dst\": dst, \"opt\": _opt_sp(nn, edges, 0, dst)}\n\n\ndef _pc_flow_graph(rng, nn, with_cost):\n    \"\"\"随机有向流网络：源点 0、汇点 n−1；每个有序点对以 0.22 的概率连一条弧，再保证存在一条源→汇的路径。\"\"\"\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nn)]\n    A = set()\n    for i in range(nn):\n        for j in range(nn):\n            if i != j and j != 0 and i != nn - 1 and rng.random() < 0.22:\n                A.add((i, j))\n    mid = list(range(1, nn - 1))\n    rng.shuffle(mid)\n    chain = [0] + mid[:3] + [nn - 1]\n    for a, b in zip(chain, chain[1:]):\n        A.add((a, b))\n    return pts, sorted(A)\n\n\ndef _pc_max_flow(nn, arcs, src, snk, cost=None, want=None):\n    \"\"\"最大流（Edmonds–Karp）；给出 cost 与 want 时改为「最小费用流」（逐次最短增广路，Bellman–Ford），要凑出 want 单位流。返回（流值, 费用）。\n    残量图用「弧 + 反向弧」成对存放（互为 twin），所以相反方向的两条真弧、平行弧都不会互相覆盖。\"\"\"\n    to, cap, cst = [], [], []\n    for k, (a, b, c) in enumerate(arcs):\n        ck = cost[k] if cost else 0\n        to += [b, a]\n        cap += [c, 0]\n        cst += [ck, -ck]\n    frm = [None] * len(to)\n    for k, (a, b, _c) in enumerate(arcs):\n        frm[2 * k], frm[2 * k + 1] = a, b\n    out = [[] for _ in range(nn)]\n    for e in range(len(to)):\n        out[frm[e]].append(e)\n    flow, total = 0, 0\n    while want is None or flow < want:\n        prev_e = {src: None}\n        if cost is None:  # BFS\n            q = [src]\n            for u in q:\n                for e in out[u]:\n                    if cap[e] > 0 and to[e] not in prev_e:\n                        prev_e[to[e]] = e\n                        q.append(to[e])\n        else:  # Bellman–Ford\n            dist = {src: 0}\n            for _ in range(nn):\n                ch = False\n                for e in range(len(to)):\n                    u = frm[e]\n                    if cap[e] > 0 and u in dist and dist[u] + cst[e] < dist.get(to[e], 10 ** 9):\n                        dist[to[e]], prev_e[to[e]] = dist[u] + cst[e], e\n                        ch = True\n                if not ch:\n                    break\n        if snk not in prev_e:\n            break\n        path, v = [], snk\n        while prev_e[v] is not None:\n            e = prev_e[v]\n            path.append(e)\n            v = frm[e]\n        push = min(cap[e] for e in path)\n        if want is not None:\n            push = min(push, want - flow)\n        for e in path:\n            cap[e] -= push\n            cap[e ^ 1] += push\n            total += push * cst[e]\n        flow += push\n    return flow, total\n\n\n@_maker('maxflow')\ndef _make_maxflow(variant, n, seed, rng):\n    # 最大流：随机有向流网络（弧容量 5–20）。解 = 每条弧上的流量（实数向量，[−5,5] 线性映射到 [0, 容量]）；目标 = −源点净流出 + 3 × 各中间点的流量守恒违反量；opt = Edmonds–Karp 的最大流\n    nn = max(8, min(n, 16))\n    pts, A = _pc_flow_graph(rng, nn, False)\n    arcs = [[a, b, rng.randint(5, 20)] for a, b in A]\n    f, _ = _pc_max_flow(nn, arcs, 0, nn - 1)\n    return {\"variant\": variant, \"pts\": pts, \"arcs\": arcs, \"n\": len(arcs), \"n_nodes\": nn, \"src\": 0, \"snk\": nn - 1, \"opt\": f}\n\n\n@_maker('mincostflow')\ndef _make_mincostflow(variant, n, seed, rng):\n    # 最小费用流：同一类流网络（弧容量 5–20、单位费用 1–5）；要从源点送 F 单位到汇点，F = 最大流的 60%。解 = 每条弧上的流量；\n    # 目标 = 总费用 + 60 × (|源点净流出 − F| + 中间点的守恒违反量)；opt = 逐次最短增广路得到的最小费用\n    nn = max(8, min(n, 16))\n    pts, A = _pc_flow_graph(rng, nn, True)\n    arcs = [[a, b, rng.randint(5, 20)] for a, b in A]\n    cost = [rng.randint(1, 5) for _ in arcs]\n    fmax, _ = _pc_max_flow(nn, arcs, 0, nn - 1)\n    F = max(1, int(fmax * 0.6))\n    _f, opt = _pc_max_flow(nn, arcs, 0, nn - 1, cost=cost, want=F)\n    return {\"variant\": variant, \"pts\": pts, \"arcs\": [a + [c] for a, c in zip(arcs, cost)], \"n\": len(arcs), \"n_nodes\": nn,\n            \"src\": 0, \"snk\": nn - 1, \"need\": F, \"opt\": opt}\n\n\n@_maker('gmatch')\ndef _make_gmatch(variant, n, seed, rng):\n    # 一般图最大权匹配：随机连通加权图（权 1–15）。解 = 边的优先序，贪心解码（两端都空闲就取）；opt = 对顶点子集的动态规划（精确）\n    nn = max(8, min(n, 14))\n    pts, E = _pc_graph(rng, nn)\n    edges = [[a, b, rng.randint(1, 15)] for a, b in E]\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"n\": len(edges), \"n_nodes\": nn, \"opt\": _opt_gmatch(nn, edges)}\n\n\n@_maker('topsort')\ndef _make_topsort(variant, n, seed, rng):\n    # 拓扑排序：随机有向无环图——先隐藏一个随机的顶点次序，再按它以 0.6 的概率连「前 → 后」的弧，最后把顶点编号打乱。\n    # 解 = 顶点的排列；目标 = 违反的弧数（排在后面的点指向排在前面的点），0 即合法拓扑序；opt = 0（Kahn 算法线性时间可得）\n    nn = max(8, min(n, 24))\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nn)]  # 先取坐标：不然隐藏次序恰好等于「同种子的第一个随机排列」，随机基线第一步就撞上答案\n    hidden = list(range(nn))\n    rng.shuffle(hidden)\n    arcs = [[hidden[i], hidden[j]] for i in range(nn) for j in range(i + 1, nn) if rng.random() < 0.6]\n    for i in range(nn - 1):  # 保证至少有一条贯穿的链，次序不至于太松\n        if rng.random() < 0.5:\n            a = [hidden[i], hidden[i + 1]]\n            if a not in arcs:\n                arcs.append(a)\n    return {\"variant\": variant, \"pts\": pts, \"arcs\": arcs, \"n\": nn, \"opt\": 0}\n\n\n_MSA_SCORE = {\"match\": 2, \"mismatch\": -1, \"gap\": -2}\n\n\ndef _msa_pair(a, b):\n    if a == \"-\" and b == \"-\":\n        return 0\n    if a == \"-\" or b == \"-\":\n        return _MSA_SCORE[\"gap\"]\n    return _MSA_SCORE[\"match\"] if a == b else _MSA_SCORE[\"mismatch\"]\n\n\ndef _msa_dp(seqs):\n    \"\"\"三条序列的和对（SP）得分的精确最优：三维动态规划（7 种列类型）。\"\"\"\n    A, B, C = seqs\n    la, lb, lc = len(A), len(B), len(C)\n    NEG = -10 ** 9\n    D = {}\n\n    def col(x, y, z):\n        return _msa_pair(x, y) + _msa_pair(x, z) + _msa_pair(y, z)\n    for i in range(la + 1):\n        for j in range(lb + 1):\n            for k in range(lc + 1):\n                if i == j == k == 0:\n                    D[(0, 0, 0)] = 0\n                    continue\n                best = NEG\n                for di in (0, 1):\n                    for dj in (0, 1):\n                        for dk in (0, 1):\n                            if not (di or dj or dk) or i - di < 0 or j - dj < 0 or k - dk < 0:\n                                continue\n                            x = A[i - 1] if di else \"-\"\n                            y = B[j - 1] if dj else \"-\"\n                            z = C[k - 1] if dk else \"-\"\n                            v = D[(i - di, j - dj, k - dk)] + col(x, y, z)\n                            if v > best:\n                                best = v\n                D[(i, j, k)] = best\n    return D[(la, lb, lc)]\n\n\n@_maker('msa')\ndef _make_msa(variant, n, seed, rng):\n    # 多序列比对（3 条合成 DNA 序列）：先随机造一条祖先序列，再各自发生 2 处点突变 + 1–2 处缺失，得到长度略有差别、彼此相似的三条序列。\n    # 解 = 3 × W 个 0/1 位（每条序列一行，1 = 该列放一个残基，0 = 空位），W = 最长序列长度 + 4；目标 = −SP 得分；opt = 三维动态规划的精确最优\n    L0 = max(8, min(n, 14))\n    anc = [rng.choice(\"ACGT\") for _ in range(L0)]\n    seqs = []\n    for _ in range(3):\n        t = list(anc)\n        for _m in range(2):\n            t[rng.randrange(len(t))] = rng.choice(\"ACGT\")\n        for _d in range(rng.randint(1, 2)):\n            del t[rng.randrange(len(t))]\n        seqs.append(\"\".join(t))\n    W = max(len(x) for x in seqs) + 4\n    return {\"variant\": variant, \"seqs\": seqs, \"W\": W, \"n\": 3 * W, \"opt\": _msa_dp(seqs)}\n\n\n# ---- 批 4：图问题族 12 变体（2026-09-27）----\n\n@_maker('vcover', 'domset', 'mclique', 'fvs', 'maxcut', 'gpp')\ndef _make_vcover_etc9(variant, n, seed, rng):\n    # 点边图族：统一图生成\n    nn = max(8, min(n, 12))\n    pts = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(nn)]\n    edges = []\n    for i in range(nn):\n        for j in range(i + 1, nn):\n            if rng.random() < 0.35:\n                edges.append((i, j, rng.randint(1, 15)))\n    return {\"variant\": variant, \"pts\": pts, \"edges\": edges, \"n\": nn}\n\n\n@_maker('setpack', 'hset')\ndef _make_setpack_etc2(variant, n, seed, rng):\n    # 集合族：集合 × 元素 0/1 矩阵。setpack：每一位 = 选不选某个集合（n = 集合数）；hset：每一位 = 选不选某个元素（n = 元素数）\n    ne = max(6, min(n, 14))\n    sets = [[1 if rng.random() < 0.3 else 0 for _ in range(ne)] for _ in range(ne // 2 + 2)]\n    for row in sets:  # 每个集合至少含一个元素（否则击中集无解、打包里它与谁都不冲突）\n        if not any(row):\n            row[rng.randrange(ne)] = 1\n    return {\"variant\": variant, \"sets\": sets, \"n\": len(sets) if variant == \"setpack\" else ne}\n\n\n@_maker('csplogic')\ndef _make_csplogic(variant, n, seed, rng):\n    # 约束满足：变量×值域+约束对\n    nn = max(8, min(n, 10))\n    vals = 4\n    conf = [[1 if i != j and rng.random() < 0.3 else 0 for j in range(nn)] for i in range(nn)]\n    return {\"variant\": variant, \"conf\": conf, \"n\": nn, \"slots\": vals}\n\n\n# ============================================================ 目标函数（每变体一个，签名 fn(self, s)）\n\ndef _vrp_dist(self):\n    \"\"\"仓库到各点、点到点的距离，按实例缓存（目标函数每代被调用几十次）。\"\"\"\n    D = getattr(self, \"_vrpD\", None)\n    if D is None:\n        pts = self.p[\"pts\"]\n        D = self._vrpD = [[math.dist(a, b) for b in pts] for a in pts]\n    return D\n\n\ndef _vrp_free_routes(D, demand, cap, tour):\n    \"\"\"车队不限的最优切分的路线（vrp_split 的无车数上限版本，仅用于展示）。\"\"\"\n    return vrp_split(D, demand, cap, max(1, len(tour)), tour)[1]\n\n\ndef vrp_split(D, demand, cap, m_veh, tour):\n    \"\"\"Prins (2004) 最优切分：把客户的访问序（巨型回路 tour，元素为 pts 下标 1..n）切成至多 m_veh 条\n    容量合法的路线，使总里程最小（分层 DP：f[k][j] = 用 k 条路线服务前 j 个客户的最小里程）。\n    返回 (总里程, 路线列表)；这个访问序切不出合法方案时返回 (None, None)。\"\"\"\n    n = len(tour)\n    INF = float(\"inf\")\n    pre = [0.0] * n  # pre[l] = 沿访问序从第 0 个走到第 l 个的里程\n    for l in range(1, n):\n        pre[l] = pre[l - 1] + D[tour[l - 1]][tour[l]]\n    f = [[INF] * (n + 1) for _ in range(m_veh + 1)]\n    back = [[-1] * (n + 1) for _ in range(m_veh + 1)]\n    f[0][0] = 0.0\n    for k in range(1, m_veh + 1):\n        fk, fp, bk = f[k], f[k - 1], back[k]\n        for j in range(1, n + 1):\n            load = 0\n            best, arg = INF, -1\n            for i in range(j - 1, -1, -1):  # 第 k 条路线服务 tour[i..j-1]\n                load += demand[tour[i]]\n                if load > cap:\n                    break\n                if fp[i] == INF:\n                    continue\n                c = fp[i] + D[0][tour[i]] + (pre[j - 1] - pre[i]) + D[tour[j - 1]][0]\n                if c < best:\n                    best, arg = c, i\n            fk[j], bk[j] = best, arg\n    kbest = min(range(1, m_veh + 1), key=lambda k: f[k][n])\n    if f[kbest][n] == INF:\n        return None, None\n    routes, j, k = [], n, kbest\n    while j > 0:\n        i = back[k][j]\n        routes.append(tour[i:j])\n        j, k = i, k - 1\n    routes.reverse()\n    return f[kbest][n], routes\n\n\ndef _vrp_free_split(D, demand, cap, tour):\n    \"\"\"车队不限的 Prins 切分（O(n·每路客户数)）：只用来给「切不进车队」的访问序算一个有梯度的惩罚。\"\"\"\n    n = len(tour)\n    INF = float(\"inf\")\n    pre = [0.0] * n\n    for l in range(1, n):\n        pre[l] = pre[l - 1] + D[tour[l - 1]][tour[l]]\n    f = [INF] * (n + 1)\n    f[0] = 0.0\n    cnt = [0] * (n + 1)\n    for j in range(1, n + 1):\n        load = 0\n        for i in range(j - 1, -1, -1):\n            load += demand[tour[i]]\n            if load > cap:\n                break\n            c = f[i] + D[0][tour[i]] + (pre[j - 1] - pre[i]) + D[tour[j - 1]][0]\n            if c < f[j]:\n                f[j], cnt[j] = c, cnt[i] + 1\n    return f[n], cnt[n]\n\n\n@_objective('vrp', fidelity=\"standard\",\n            note=\"\")\ndef _obj_vrp(self, s):\n    # 带容量车辆路径 CVRP：s 是客户的访问序（巨型回路），解码 = Prins 最优切分成至多 m_veh 条容量合法的路线，\n    # 目标 = 总里程。访问序切不进车队时，用「不限车队的最优切分里程 + 每多用一辆车 200」作惩罚，保持搜索有梯度。\n    D = _vrp_dist(self)\n    demand, cap, m_veh = self.p[\"demand\"], self.p[\"cap\"], self.p[\"m_veh\"]\n    tour = [x + 1 for x in s]\n    total, _routes = vrp_split(D, demand, cap, m_veh, tour)\n    if total is None:\n        free, used = _vrp_free_split(D, demand, cap, tour)\n        total = free + 200.0 * max(1, used - m_veh)\n    return round(total, 3)\n\n\ndef vrptw_arcs(D, demand, cap, e, l, svc, H, tour):\n    \"\"\"访问序 tour（元素为 pts 下标 1..n）上所有「合法的连续一段」：返回 arcs[i] = [(j, 里程), …]，\n    表示 tour[i:j] 可以由同一辆车服务（容量不超、每个客户在窗口关闭前到达——早到则等到窗口打开、\n    且在仓库关门 H 前回到仓库），里程 = 仓库→…→仓库的行驶距离（等待不计里程）。\n    一段不合法，向右延长也一定不合法（到达只会更晚、载重只会更大、回仓只会更晚——回仓用三角不等式），所以遇到第一个违反就停。\"\"\"\n    n = len(tour)\n    arcs = [[] for _ in range(n)]\n    for i in range(n):\n        load, t, prev, dist = 0, 0.0, 0, 0.0\n        for j in range(i, n):\n            c = tour[j]\n            load += demand[c]\n            if load > cap:\n                break\n            arr = t + D[prev][c]\n            if arr > l[c] + 1e-9:\n                break\n            t = max(arr, e[c]) + svc[c]\n            dist += D[prev][c]\n            prev = c\n            if t + D[c][0] > H + 1e-9:\n                break\n            arcs[i].append((j + 1, dist + D[c][0]))\n    return arcs\n\n\ndef vrptw_split(arcs, n, m_veh):\n    \"\"\"在 vrptw_arcs 给出的合法段上做 Prins 最优切分：至多 m_veh 条路线，总里程最小。\n    返回 (总里程, 路线的 (起, 止) 列表)；这个访问序切不进车队时返回 (None, None)。\"\"\"\n    INF = float(\"inf\")\n    f = [[INF] * (n + 1) for _ in range(m_veh + 1)]\n    back = [[-1] * (n + 1) for _ in range(m_veh + 1)]\n    f[0][0] = 0.0\n    for k in range(1, m_veh + 1):\n        fp, fk, bk = f[k - 1], f[k], back[k]\n        for i in range(n):\n            if fp[i] == INF:\n                continue\n            for j, c in arcs[i]:\n                if fp[i] + c < fk[j]:\n                    fk[j], bk[j] = fp[i] + c, i\n    kbest = min(range(1, m_veh + 1), key=lambda k: f[k][n])\n    if f[kbest][n] == INF:\n        return None, None\n    spans, j, k = [], n, kbest\n    while j > 0:\n        i = back[k][j]\n        spans.append((i, j))\n        j, k = i, k - 1\n    spans.reverse()\n    return f[kbest][n], spans\n\n\ndef vrptw_free_split(arcs, n):\n    \"\"\"车队不限的最优切分（只用来给「切不进车队」的访问序算有梯度的惩罚，以及页面上照样画出路线）：返回 (里程, 路线数, spans)。\"\"\"\n    INF = float(\"inf\")\n    f, cnt, back = [INF] * (n + 1), [0] * (n + 1), [-1] * (n + 1)\n    f[0] = 0.0\n    for i in range(n):\n        if f[i] == INF:\n            continue\n        for j, c in arcs[i]:\n            if f[i] + c < f[j]:\n                f[j], cnt[j], back[j] = f[i] + c, cnt[i] + 1, i\n    if f[n] == INF:\n        return INF, 0, None\n    spans, j = [], n\n    while j > 0:\n        spans.append((back[j], j))\n        j = back[j]\n    spans.reverse()\n    return f[n], cnt[n], spans\n\n\ndef vrpstw_arcs(D, demand, cap, e, l, svc, H, lam, tour):\n    \"\"\"软时间窗版的 vrptw_arcs：晚到不再不可行，而是每晚 1 个单位罚 lam（早到仍要等；回仓晚于 H 同样计罚）。\n    只有容量能让一段不合法（所以遇到超载就停）。arcs[i] = [(j, 里程 + lam × 迟到总量), …]。\"\"\"\n    n = len(tour)\n    arcs = [[] for _ in range(n)]\n    for i in range(n):\n        load, t, prev, dist, late = 0, 0.0, 0, 0.0, 0.0\n        for j in range(i, n):\n            c = tour[j]\n            load += demand[c]\n            if load > cap:\n                break\n            arr = t + D[prev][c]\n            late += max(0.0, arr - l[c])\n            t = max(arr, e[c]) + svc[c]\n            dist += D[prev][c]\n            prev = c\n            end_late = max(0.0, t + D[c][0] - H)\n            arcs[i].append((j + 1, dist + D[c][0] + lam * (late + end_late)))\n    return arcs\n\n\ndef _vrptw_arcs_of(self, s):\n    p = self.p\n    tour = [x + 1 for x in s]\n    if \"lam\" in p:\n        return vrpstw_arcs(_vrp_dist(self), p[\"demand\"], p[\"cap\"], p[\"e\"], p[\"l\"], p[\"svc\"], p[\"l\"][0], p[\"lam\"], tour)\n    return vrptw_arcs(_vrp_dist(self), p[\"demand\"], p[\"cap\"], p[\"e\"], p[\"l\"], p[\"svc\"], p[\"l\"][0], tour)\n\n\n@_objective('vrptw', 'vrpstw', fidelity=\"standard\")\ndef _obj_vrptw(self, s):\n    # 带时间窗的车辆路径 VRPTW（硬时间窗；变体 vrpstw 为软时间窗：晚到不非法、按迟到量罚）：s 是客户的访问序，解码 = 在「合法的连续段」上做 Prins 最优切分，\n    # 至多 m_veh 条路线，目标 = 总里程。切不进车队时：不限车队的最优切分里程 + 每多用一辆车 200（保持搜索有梯度）。\n    arcs = _vrptw_arcs_of(self, s)\n    n = len(s)\n    total, _spans = vrptw_split(arcs, n, self.p[\"m_veh\"])\n    if total is None:\n        free, used, _sp = vrptw_free_split(arcs, n)\n        total = free + 200.0 * max(1, used - self.p[\"m_veh\"])\n    return round(total, 3)\n\n\ndef vrptw_schedule(p, route):\n    \"\"\"一条路线上每个客户的 (到达, 开始服务, 离开) 时刻；等待 = 开始 − 到达。\"\"\"\n    out, t, prev = [], 0.0, 0\n    for c in route:\n        arr = t + math.dist(p[\"pts\"][prev], p[\"pts\"][c])\n        start = max(arr, p[\"e\"][c])\n        t = start + p[\"svc\"][c]\n        out.append([round(arr, 2), round(start, 2), round(t, 2)])\n        prev = c\n    return out\n\n\ndef _mdvrp_groups(self, s):\n    \"\"\"把排列拆成 D 组客户（按分隔符），返回 [第 d 个仓库的客户下标 1..k 列表]。\"\"\"\n    D = self.p[\"D\"]\n    k = self.p[\"n\"] + 1 - D\n    groups, g = [[] for _ in range(D)], 0\n    for v in s:\n        if v >= k:\n            g += 1\n        else:\n            groups[g].append(v + 1)\n    return groups\n\n\ndef _mdvrp_mats(self):\n    \"\"\"每个仓库一份「0 号 = 该仓库、1..k = 客户」的距离矩阵与需求表（直接复用 vrp_split），按实例缓存。\"\"\"\n    cached = getattr(self, \"_mdM\", None)\n    if cached is None:\n        p = self.p\n        D = p[\"D\"]\n        k = p[\"n\"] + 1 - D\n        cust = p[\"pts\"][D:]\n        demand = [0] + p[\"demand\"][D:]\n        mats = []\n        for d in range(D):\n            pts = [p[\"pts\"][d]] + cust\n            mats.append([[math.dist(a, b) for b in pts] for a in pts])\n        cached = self._mdM = (mats, demand)\n    return cached\n\n\ndef mdvrp_split_all(self, s):\n    \"\"\"每个仓库的客户序做 Prins 最优切分（至多 m_dep 条路线）。返回 (总里程, [(仓库, 路线列表, 是否在车队内)])；\n    切不进车队的仓库按「不限车队的最优切分 + 每多一辆车 200」计罚（路线仍照切，页面画得出来）。\"\"\"\n    p = self.p\n    mats, demand = _mdvrp_mats(self)\n    total, parts = 0.0, []\n    for d, tour in enumerate(_mdvrp_groups(self, s)):\n        if not tour:\n            parts.append((d, [], True))\n            continue\n        cost, routes = vrp_split(mats[d], demand, p[\"cap\"], p[\"m_dep\"], tour)\n        within = cost is not None\n        if not within:\n            cost, used = _vrp_free_split(mats[d], demand, p[\"cap\"], tour)\n            cost += 200.0 * max(1, used - p[\"m_dep\"])\n            routes = _vrp_free_routes(mats[d], demand, p[\"cap\"], tour)\n        total += cost\n        parts.append((d, routes, within))\n    return total, parts\n\n\n@_objective('mdvrp', fidelity=\"standard\")\ndef _obj_mdvrp(self, s):\n    # 多车场 VRP：序列里的分隔符把客户分给各个仓库（每个仓库自己的车队与容量），各仓库内部做 Prins 最优切分，目标 = 总里程。\n    # 没有路线时长上限（经典 MDVRP 实例有，这里省略）。\n    return round(mdvrp_split_all(self, s)[0], 3)\n\n\n# ---- 调度类：目标函数与「解长什么样」（2026-10 重做）----\n\ndef _pfsp_times(p, s):\n    \"\"\"置换流水车间的完工时间表：C[k][j] = max(C[k][j−1], C[k−1][j]) + p[k][j]；返回每个作业在每台机器上的 (开始, 结束)。\"\"\"\n    m = len(p)\n    free = [0] * m\n    out = []\n    for j in s:\n        row, prev = [], 0\n        for k in range(m):\n            st = max(free[k], prev)\n            en = st + p[k][j]\n            free[k] = prev = en\n            row.append((st, en))\n        out.append(row)\n    return out\n\n\n@_objective('fss', fidelity=\"standard\")\ndef _obj_fss(self, s):\n    # 置换流水车间（所有机器上作业顺序相同）：最小化完工时间 Cmax\n    p = self.p[\"p\"]\n    free = [0] * len(p)\n    for j in s:\n        prev = 0\n        for k in range(len(p)):\n            prev = free[k] = max(free[k], prev) + p[k][j]\n    return free[-1]\n\n\n@_detail('fss')\ndef _detail_fss(self, s):\n    rows = _pfsp_times(self.p[\"p\"], s)\n    ops = [[j, k, st, en] for j, row in zip(s, rows) for k, (st, en) in enumerate(row)]\n    return {\"ops\": ops, \"makespan\": rows[-1][-1][1], \"lb\": _pfsp_lb(self.p[\"p\"]), \"m\": len(self.p[\"p\"]), \"n_jobs\": len(s)}\n\n\ndef _pfsp_lb(p):\n    \"\"\"经典下界：某台机器上全部作业的总时间，加上它之前最短的前置和之后最短的后继。\"\"\"\n    m, n = len(p), len(p[0])\n    best = 0\n    for k in range(m):\n        head = min(sum(p[q][j] for q in range(k)) for j in range(n)) if k else 0\n        tail = min(sum(p[q][j] for q in range(k + 1, m)) for j in range(n)) if k < m - 1 else 0\n        best = max(best, head + sum(p[k][j] for j in range(n)) + tail)\n    return best\n\n\ndef _shop_schedule(self, s):\n    \"\"\"把排列 s 译成工序时间表，返回 [(作业, 机器, 开始, 结束)]。\n    jss / fjsp：排列元素对作业数取模得到「作业重复序列」（每个作业恰好出现 m 次），第 k 次出现的就是它的第 k 道工序（Bierwirth 1995 的工序编码）；\n      jss 按作业自己的路线定机器，fjsp 在可选机器里挑「做完最早」的；\n    oss：排列元素 = 工序编号 (作业 × m + 机器)，按排列顺序排程；\n    都是半主动调度：工序在「作业就绪」与「机器空闲」的较晚者开始。\"\"\"\n    p = self.p\n    v = self.variant\n    mf, out = {}, []\n    if v == \"oss\":\n        m = p[\"m_mach\"]\n        jr = [0] * p[\"n_jobs\"]\n        for x in s:\n            j, k = divmod(x, m)\n            st = max(jr[j], mf.get(k, 0))\n            en = st + p[\"t\"][j][k]\n            jr[j], mf[k] = en, en\n            out.append((j, k, st, en))\n        return out\n    nj = p[\"n_jobs\"]\n    nxt, jr = [0] * nj, [0] * nj\n    for x in s:\n        j = x % nj\n        op = p[\"jobs\"][j][nxt[j]]\n        nxt[j] += 1\n        if v == \"jss\":\n            k, t = op\n            st = max(jr[j], mf.get(k, 0))\n        else:\n            k, t = min(op, key=lambda kt: (max(jr[j], mf.get(kt[0], 0)) + kt[1], kt[0]))\n            st = max(jr[j], mf.get(k, 0))\n        jr[j], mf[k] = st + t, st + t\n        out.append((j, k, st, st + t))\n    return out\n\n\n@_objective('oss', fidelity=\"standard\")\ndef _obj_oss(self, s):\n    return max(en for (_j, _k, _st, en) in _shop_schedule(self, s))\n\n\n@_objective('jss', fidelity=\"standard\")\ndef _obj_jss(self, s):\n    return max(en for (_j, _k, _st, en) in _shop_schedule(self, s))\n\n\n@_objective('fjsp', fidelity=\"simplified\", note=\"机器不是搜索出来的：每道工序固定挑「做完最早」的机器（常见的解码规则，但会漏掉需要故意选慢机器的最优解）\")\ndef _obj_fjsp(self, s):\n    return max(en for (_j, _k, _st, en) in _shop_schedule(self, s))\n\n\n@_detail('oss', 'jss', 'fjsp')\ndef _detail_shop(self, s):\n    ops = _shop_schedule(self, s)\n    return {\"ops\": [list(o) for o in ops], \"makespan\": max(o[3] for o in ops), \"lb\": self.p.get(\"lb\"), \"m\": self.p[\"m_mach\"], \"n_jobs\": self.p[\"n_jobs\"]}\n\n\ndef _hc_adj(self):\n    adj = getattr(self, \"_hcadj\", None)\n    if adj is None:\n        adj = self._hcadj = {(a, b) for a, b, *_ in self.p[\"edges\"]} | {(b, a) for a, b, *_ in self.p[\"edges\"]}\n    return adj\n\n\n@_objective('hc', fidelity=\"standard\")\ndef _obj_hc(self, s):\n    # 哈密顿回路的优化视角：排列首尾相接，数「不是图中边」的相邻对；0 = 找到了哈密顿回路\n    adj = _hc_adj(self)\n    n = len(s)\n    return sum(1 for i in range(n) if (s[i], s[(i + 1) % n]) not in adj)\n\n\n@_detail('hc')\ndef _detail_hc(self, s):\n    adj = _hc_adj(self)\n    n = len(s)\n    bad = [i for i in range(n) if (s[i], s[(i + 1) % n]) not in adj]\n    return {\"broken\": bad, \"found\": not bad}\n\n\ndef _lpath_walk(self, s):\n    \"\"\"沿排列走：下一个点与当前点相邻就延伸，碰到非边就停。返回（走过的点序列, 累计权重）。\"\"\"\n    w = getattr(self, \"_lpw\", None)\n    if w is None:\n        w = self._lpw = {}\n        for a, b, c in self.p[\"edges\"]:\n            w[(a, b)] = w[(b, a)] = c\n    path, tot = [s[0]], 0\n    for i in range(1, len(s)):\n        c = w.get((s[i - 1], s[i]))\n        if c is None:\n            break\n        path.append(s[i])\n        tot += c\n    return path, tot\n\n\n@_objective('lpath', fidelity=\"standard\")\ndef _obj_lpath(self, s):\n    # 最长（权重最大的）简单路径：沿排列延伸、碰到非边就停，累计权重取负\n    return -_lpath_walk(self, s)[1]\n\n\n@_detail('lpath')\ndef _detail_lpath(self, s):\n    path, tot = _lpath_walk(self, s)\n    return {\"path\": path, \"weight\": tot}\n\n\ndef _carp_sp(self):\n    \"\"\"路网全点对最短路（Floyd–Warshall，按实例缓存）。\"\"\"\n    sp = getattr(self, \"_carpsp\", None)\n    if sp is None:\n        nv = len(self.p[\"pts\"])\n        sp = [[0 if i == j else 10 ** 9 for j in range(nv)] for i in range(nv)]\n        for a, b, c in self.p[\"edges\"]:\n            sp[a][b] = sp[b][a] = min(sp[a][b], c)\n        for k in range(nv):\n            for i in range(nv):\n                for j in range(nv):\n                    if sp[i][k] + sp[k][j] < sp[i][j]:\n                        sp[i][j] = sp[i][k] + sp[k][j]\n        self._carpsp = sp\n    return sp\n\n\ndef _carp_plan(self, s):\n    \"\"\"排列 s = 必需边的服务顺序。每条边走哪个方向：从当前位置出发、先到离得近的那一端（贪心）；\n    再对这条「巨型路线」做容量切分（Ulusoy / Prins 式动态规划：每一段从仓库出发、回仓库，载重 ≤ 容量）。\n    返回（总费用, [每趟的（起点, 终点, 边下标）列表]）。\"\"\"\n    p = self.p\n    sp = _carp_sp(self)\n    dep, cap = p[\"depot\"], p[\"cap\"]\n    ends, seq, cur = [], [], dep\n    for r in s:\n        a, b, c = p[\"edges\"][p[\"req\"][r]]\n        if sp[cur][a] <= sp[cur][b]:\n            u, v = a, b\n        else:\n            u, v = b, a\n        ends.append((u, v, c))\n        seq.append(r)\n        cur = v\n    k = len(seq)\n    INF = float(\"inf\")\n    best, prv = [INF] * (k + 1), [0] * (k + 1)\n    best[0] = 0.0\n    for i in range(k):\n        if best[i] == INF:\n            continue\n        load, cost = 0, 0.0\n        for j in range(i, k):\n            load += p[\"dem\"][seq[j]]\n            if load > cap and j > i:\n                break\n            u, v, c = ends[j]\n            cost += (sp[dep][u] if j == i else sp[ends[j - 1][1]][u]) + c\n            tot = cost + sp[v][dep]\n            if best[i] + tot < best[j + 1]:\n                best[j + 1], prv[j + 1] = best[i] + tot, i\n    trips, j = [], k\n    while j > 0:\n        i = prv[j]\n        trips.append([[ends[t][0], ends[t][1], p[\"req\"][seq[t]]] for t in range(i, j)])\n        j = i\n    return best[k], trips[::-1]\n\n\n@_objective('carp', 'rpostman', fidelity=\"simplified\", note=\"每条边的行走方向由「先到近的一端」的贪心定，不是搜索出来的；路线内顺序就是排列顺序，没有路线内优化\")\ndef _obj_carp(self, s):\n    # 弧路由：必需边的服务序 → 贪心定方向 → 容量切分；费用 = 服务费 + 空驶（最短路）。rpostman 容量无限 = 一条回路\n    return round(_carp_plan(self, s)[0], 3)\n\n\n@_detail('carp', 'rpostman')\ndef _detail_carp(self, s):\n    cost, trips = _carp_plan(self, s)\n    return {\"trips\": trips, \"cost\": round(cost, 3)}\n\n\n@_objective('lop', fidelity=\"standard\")\ndef _obj_lop(self, s):\n    v = self.variant\n    w = self.p[\"w\"]\n    return int(-sum(w[s[j]][s[i]] for i in range(self.n) for j in range(i + 1, self.n)))\n\n\n@_objective('sms', fidelity=\"standard\")\ndef _obj_sms(self, s):\n    v = self.variant\n    p_, d = self.p[\"p\"], self.p[\"d\"]\n    t = 0\n    tot = 0\n    for x in s:\n        t += p_[x]\n        tot += max(0, t - d[x])\n    return tot\n\n\n# ---- 批 2：调度/排课/赛程族 8 变体目标 ----\n\ndef _ctp_plan(self, s):\n    \"\"\"排列 s 是「排课顺序」。逐节课 first-fit：取最早的合法时段（同课程不重复、教师 / 课程组无冲突、教室没满），\n    教室取装得下的最小一间；软代价 = 教室装不下的人数 + 同一天已有这门课的 10；找不到合法时段就记「未排」。\"\"\"\n    p = self.p\n    lc, teacher, size, rooms = p[\"lec_course\"], p[\"teacher\"], p[\"size\"], p[\"rooms\"]\n    P_ = p[\"days\"] * p[\"slots\"]\n    conf = getattr(self, \"_ctpconf\", None)\n    if conf is None:\n        n = p[\"n_courses\"]\n        conf = [[False] * n for _ in range(n)]\n        for a in range(n):\n            for b in range(n):\n                if a != b and teacher[a] == teacher[b]:\n                    conf[a][b] = True\n        for g in p[\"groups\"]:\n            for a in g:\n                for b in g:\n                    if a != b:\n                        conf[a][b] = True\n        self._ctpconf = conf\n    at = [[] for _ in range(P_)]  # 每个时段已排的 (课程, 教室下标)\n    placed, soft, undone = [], 0, 0\n    day_of = {}\n    for k in s:\n        c = lc[k]\n        best = None\n        for t in range(P_):\n            if any(c2 == c or conf[c][c2] for c2, _r in at[t]) or len(at[t]) >= len(rooms):\n                continue\n            used = {r for _c, r in at[t]}\n            free = [r for r in range(len(rooms)) if r not in used]\n            fit = [r for r in free if rooms[r] >= size[c]]\n            r = min(fit, key=lambda r: rooms[r]) if fit else max(free, key=lambda r: rooms[r])\n            cost = max(0, size[c] - rooms[r]) + (10 if (t // p[\"slots\"]) in day_of.get(c, ()) else 0)\n            best = (cost, t, r)  # 首个合法时段（first-fit，图着色式的装配）：排课顺序决定结果，所以值得搜索\n            break\n        if best is None:\n            undone += 1\n            continue\n        cost, t, r = best\n        at[t].append((c, r))\n        day_of.setdefault(c, set()).add(t // p[\"slots\"])\n        placed.append((k, c, t, r))\n        soft += cost\n    return placed, soft, undone\n\n\n@_objective('ctp', fidelity=\"simplified\", note=\"贪心装配而不是对时段 × 教室做搜索；只有教师 / 课程组冲突、教室容量、同日分散三类约束，没有 ITC-2007 的最少上课天数、课程表紧凑度等\")\ndef _obj_ctp(self, s):\n    placed, soft, undone = _ctp_plan(self, s)\n    return soft + 1000 * undone\n\n\n@_detail('ctp')\ndef _detail_ctp(self, s):\n    placed, soft, undone = _ctp_plan(self, s)\n    return {\"placed\": [list(x) for x in placed], \"soft\": soft, \"undone\": undone}\n\n\n# ---- 批 5：黑箱与多目标族 10 变体目标（实数向量）----\n\n@_objective('cbbb', fidelity=\"simplified\", note=\"Rastrigin + 一条线性约束的自拟函数，不是标准约束基准（如 CEC 约束套件）\", encoding=\"real\")\ndef _obj_cbbb(self, s):\n    # 约束黑箱：rastrigin + 线性约束 Σx ≤ 3 罚\n    v = self.variant\n    base = 10 * self.n + sum(x * x - 10 * math.cos(2 * math.pi * x) for x in s)\n    viol = max(0.0, sum(s) - 3.0)\n    return round(base + 500 * viol, 3)\n\n\n@_objective('nbbb', fidelity=\"illustrative\", note=\"「噪声」是确定性伪噪声（同输入同输出），不是真随机噪声\", encoding=\"real\")\ndef _obj_nbbb(self, s):\n    # 噪声黑箱：rastrigin + 确定性伪噪声（同输入同输出，可复现）\n    v = self.variant\n    base = 10 * self.n + sum(x * x - 10 * math.cos(2 * math.pi * x) for x in s)\n    noise = 2.0 * math.sin(13.7 * sum(s)) * math.cos(7.3 * s[0])\n    return round(base + noise, 3)\n\n\n@_objective('lbbb', fidelity=\"illustrative\", note=\"函数是标准的 Rosenbrock，但只有 10 维，并非真正的大规模（通常 ≥1000 维）\", encoding=\"real\")\ndef _obj_lbbb(self, s):\n    # 大规模黑箱：rosenbrock 10 维（经典难收敛谷）\n    v = self.variant\n    return round(sum(100 * (s[i + 1] - s[i] ** 2) ** 2 + (1 - s[i]) ** 2\n                     for i in range(self.n - 1)), 3)\n\n\n@_objective('ebbb', fidelity=\"illustrative\", note=\"只是把迭代数限到 50 代来「模拟」昂贵评估；没有代理模型，也没有评估预算计数\", encoding=\"real\")\ndef _obj_ebbb(self, s):\n    # 昂贵黑箱：与 cbbb 同地形——预算受限（默认 50 代）模拟昂贵评估\n    v = self.variant\n    base = 10 * self.n + sum(x * x - 10 * math.cos(2 * math.pi * x) for x in s)\n    viol = max(0.0, sum(x * x for x in s) - 12.0)\n    return round(base + 500 * viol, 3)\n\n\n@_objective('mmo', fidelity=\"illustrative\", note=\"Rastrigin 地形，目标仍是单一全局最优；没有「同时定位多个峰」的评价\", encoding=\"real\")\ndef _obj_mmo(self, s):\n    # 多模态：rastrigin 地形（指数级局部极小；同时定位多个峰属进阶版）\n    v = self.variant\n    return round(10 * self.n + sum(x * x - 10 * math.cos(2 * math.pi * x) for x in s), 3)\n\n\n@_objective('dop', fidelity=\"illustrative\", note=\"静态双峰（按 x[0] 的符号选地形），目标并不随时间变化\")\ndef _obj_dop(self, s):\n    # 动态优化（教学级静态双峰）：x[0]>0 用 A 地形否则 B\n    v = self.variant\n    if s[0] >= 0:\n        return round(sum((x - 2) ** 2 + 2 for x in s), 3)\n    return round(sum((x + 2) ** 2 + 2 for x in s), 3)\n\n\ndef _ged_pos(self, s):\n    p = self.p\n    out = []\n    for i in range(p[\"k\"]):\n        ri = p[\"r\"][i]\n        span = p[\"size\"] - 2 * ri\n        out.append([ri + min(1.0, max(0.0, (s[2 * i] + 5.0) / 10.0)) * span, ri + min(1.0, max(0.0, (s[2 * i + 1] + 5.0) / 10.0)) * span])\n    return out\n\n\n@_objective('ged', fidelity=\"simplified\", note=\"只有「互不重叠」与「希望相邻」两类规则的圆形块布局，没有采光、动线、结构等真实设计指标；设计空间只有 2k 个坐标\", encoding=\"real\")\ndef _obj_ged(self, s):\n    # 布局生成：重叠量平方 × 5（含 2 个单位的间隙）+ 希望相邻的块之间多出来的距离（紧贴最好）\n    p = self.p\n    pos = _ged_pos(self, s)\n    tot = 0.0\n    for i in range(p[\"k\"]):\n        for j in range(i + 1, p[\"k\"]):\n            d = math.dist(pos[i], pos[j])\n            ov = p[\"r\"][i] + p[\"r\"][j] + p[\"gap\"] - d\n            if ov > 0:\n                tot += 5.0 * ov * ov\n    for i, j in p[\"adj\"]:\n        d = math.dist(pos[i], pos[j])\n        tot += max(0.0, d - (p[\"r\"][i] + p[\"r\"][j] + p[\"gap\"]))\n    return round(tot, 6)\n\n\n@_detail('ged')\ndef _detail_ged(self, s):\n    p = self.p\n    pos = _ged_pos(self, s)\n    overlaps = sum(1 for i in range(p[\"k\"]) for j in range(i + 1, p[\"k\"]) if math.dist(pos[i], pos[j]) < p[\"r\"][i] + p[\"r\"][j])\n    return {\"pos\": [[round(a, 2), round(b, 2)] for a, b in pos], \"overlaps\": overlaps}\n\n\n@_objective('proteinfold', fidelity=\"simplified\", note=\"二维方格 HP 模型 + 绝对方向编码；自交用罚分（每处 4）而不是直接排除；序列是随机的（H 占 45%），不是文献里的标准序列\")\ndef _obj_proteinfold(self, s):\n    # 解 = 长度 n 的排列，第 i 个元素对 4 取模给出第 i 个残基到第 i+1 个残基的方向；\n    # 能量 = −(拓扑 HH 接触数) + 4 × 自交处数。拓扑接触 = 序列上不相邻（|i−j|>1）、格点上相邻的 H–H 对\n    seq = self.p[\"seq\"]\n    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]\n    pos = [(0, 0)]\n    x = y = 0\n    seen = {(0, 0)}\n    clash = 0\n    for i in range(1, len(seq)):\n        dx, dy = dirs[s[(i - 1) % len(s)] % 4]\n        x, y = x + dx, y + dy\n        if (x, y) in seen:\n            clash += 1\n        seen.add((x, y))\n        pos.append((x, y))\n    contacts = 0\n    for i in range(len(seq)):\n        if seq[i] != \"H\":\n            continue\n        for j in range(i + 2, len(seq)):\n            if seq[j] == \"H\" and abs(pos[i][0] - pos[j][0]) + abs(pos[i][1] - pos[j][1]) == 1:\n                contacts += 1\n    return -contacts + 4 * clash\n\n\n@_detail('proteinfold')\ndef _detail_proteinfold(self, s):\n    seq = self.p[\"seq\"]\n    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]\n    pos = [(0, 0)]\n    x = y = 0\n    for i in range(1, len(seq)):\n        dx, dy = dirs[s[(i - 1) % len(s)] % 4]\n        x, y = x + dx, y + dy\n        pos.append((x, y))\n    cnt = {}\n    for q in pos:\n        cnt[q] = cnt.get(q, 0) + 1\n    contacts = [[i, j] for i in range(len(seq)) for j in range(i + 2, len(seq))\n                if seq[i] == \"H\" and seq[j] == \"H\" and abs(pos[i][0] - pos[j][0]) + abs(pos[i][1] - pos[j][1]) == 1]\n    return {\"pos\": [list(q) for q in pos], \"contacts\": contacts, \"clashes\": sum(c - 1 for c in cnt.values() if c > 1)}\n\n\n# ---- P 类对照问题与多序列比对：目标函数与「解长什么样」（2026-10 重做）----\n\ndef _mst_tree(self, s):\n    par = list(range(self.p[\"n_nodes\"]))\n    tree, total = [], 0\n    for k in s:\n        a, b, w = self.p[\"edges\"][k]\n        ra, rb = _pc_find(par, a), _pc_find(par, b)\n        if ra != rb:\n            par[ra] = rb\n            tree.append(k)\n            total += w\n    return tree, total\n\n\n@_objective('mst', fidelity=\"standard\")\ndef _obj_mst(self, s):\n    # Kruskal 式解码：按排列给出的优先序依次加边，成环就跳过——对连通图一定得到生成树；排列恰好是按权升序时就是最优\n    return _mst_tree(self, s)[1]\n\n\n@_detail('mst')\ndef _detail_mst(self, s):\n    tree, total = _mst_tree(self, s)\n    return {\"tree\": tree, \"weight\": total, \"opt\": self.p[\"opt\"]}\n\n\ndef _sp_walk(self, s):\n    \"\"\"从起点出发，每步走向「优先级最高的未访问邻居」；走不动（所有邻居都访问过）就算失败。返回（路径, 长度或 None）。\"\"\"\n    p = self.p\n    nbr = getattr(self, \"_spnbr\", None)\n    if nbr is None:\n        nbr = self._spnbr = [[] for _ in range(p[\"n\"])]\n        for a, b, w in p[\"edges\"]:\n            nbr[a].append((b, w))\n            nbr[b].append((a, w))\n    cur, path, tot, seen = p[\"src\"], [p[\"src\"]], 0, {p[\"src\"]}\n    while cur != p[\"dst\"]:\n        cand = [(s[v], v, w) for v, w in nbr[cur] if v not in seen]\n        if not cand:\n            return path, None\n        _k, v, w = max(cand)\n        tot += w\n        seen.add(v)\n        path.append(v)\n        cur = v\n    return path, tot\n\n\n@_objective('shortestpath', fidelity=\"standard\", encoding=\"real\")\ndef _obj_shortestpath(self, s):\n    # 优先级编码（Gen &amp; Cheng 的路径编码）：解码出的一定是一条简单路径；走进死胡同按 4000 计\n    path, tot = _sp_walk(self, s)\n    return 4000 if tot is None else tot\n\n\n@_detail('shortestpath')\ndef _detail_shortestpath(self, s):\n    path, tot = _sp_walk(self, s)\n    return {\"path\": path, \"length\": tot, \"reached\": tot is not None, \"opt\": self.p[\"opt\"]}\n\n\ndef _flow_state(self, s):\n    \"\"\"把决策向量译成各弧的流量，并算出源点净流出与各中间点的守恒违反量。\"\"\"\n    p = self.p\n    arcs, nn = p[\"arcs\"], p[\"n_nodes\"]\n    x = [min(1.0, max(0.0, (v + 5.0) / 10.0)) * a[2] for v, a in zip(s, arcs)]\n    ex = [0.0] * nn\n    for f, a in zip(x, arcs):\n        ex[a[0]] -= f\n        ex[a[1]] += f\n    out_src = -ex[p[\"src\"]]\n    viol = sum(abs(ex[v]) for v in range(nn) if v not in (p[\"src\"], p[\"snk\"]))\n    return x, out_src, viol\n\n\n@_objective('maxflow', fidelity=\"standard\", encoding=\"real\")\ndef _obj_maxflow(self, s):\n    # 流向量编码：最大化源点净流出，中间点的流量守恒用精确罚函数（权 3 > 1，每违反 1 单位至多多换 1 单位流，不划算）\n    x, out_src, viol = _flow_state(self, s)\n    return round(-out_src + 3.0 * viol, 6)\n\n\n@_objective('mincostflow', fidelity=\"standard\", encoding=\"real\")\ndef _obj_mincostflow(self, s):\n    # 目标 = 总费用 + 60 × (送出量与需求 F 的偏差 + 守恒违反量)：60 大于任何一条源→汇路径的单位费用上界（≤ 5 × (n−1)）\n    p = self.p\n    x, out_src, viol = _flow_state(self, s)\n    cost = sum(f * a[3] for f, a in zip(x, p[\"arcs\"]))\n    return round(cost + 60.0 * (abs(out_src - p[\"need\"]) + viol), 6)\n\n\n@_detail('maxflow', 'mincostflow')\ndef _detail_flow(self, s):\n    x, out_src, viol = _flow_state(self, s)\n    d = {\"flow\": [round(f, 3) for f in x], \"value\": round(out_src, 3), \"violation\": round(viol, 3), \"opt\": self.p[\"opt\"]}\n    if self.variant == \"mincostflow\":\n        d[\"cost\"] = round(sum(f * a[3] for f, a in zip(x, self.p[\"arcs\"])), 3)\n        d[\"need\"] = self.p[\"need\"]\n    return d\n\n\ndef _gm_pick(self, s):\n    used, picked, tot = set(), [], 0\n    for k in s:\n        a, b, w = self.p[\"edges\"][k]\n        if a not in used and b not in used:\n            used.add(a)\n            used.add(b)\n            picked.append(k)\n            tot += w\n    return picked, tot\n\n\n@_objective('gmatch', fidelity=\"standard\")\ndef _obj_gmatch(self, s):\n    # 最大权匹配：按优先序贪心取边（两端都空闲才取）；任何匹配都能写成「它的边在前」的优先序，所以不丢最优解\n    return -_gm_pick(self, s)[1]\n\n\n@_detail('gmatch')\ndef _detail_gmatch(self, s):\n    picked, tot = _gm_pick(self, s)\n    return {\"matched\": picked, \"weight\": tot, \"opt\": self.p[\"opt\"]}\n\n\n@_objective('topsort', fidelity=\"standard\")\ndef _obj_topsort(self, s):\n    # 违反的弧数：弧 a → b 要求 a 排在 b 前面\n    pos = {v: i for i, v in enumerate(s)}\n    return sum(1 for a, b in self.p[\"arcs\"] if pos[a] > pos[b])\n\n\n@_detail('topsort')\ndef _detail_topsort(self, s):\n    pos = {v: i for i, v in enumerate(s)}\n    return {\"order\": list(s), \"backward\": [k for k, (a, b) in enumerate(self.p[\"arcs\"]) if pos[a] > pos[b]]}\n\n\ndef _msa_rows(self, s):\n    \"\"\"每行的 0/1 位决定残基放在哪些列：取前 len 个 1 依次放残基序列；1 不够就把剩下的残基接在最后一个残基后面；行尾补空位到同宽。\"\"\"\n    W, seqs = self.p[\"W\"], self.p[\"seqs\"]\n    rows = []\n    for r, seq in enumerate(seqs):\n        bits = s[r * W:(r + 1) * W]\n        cols = [i for i, b in enumerate(bits) if b][:len(seq)]\n        row = [\"-\"] * W\n        for ch, c in zip(seq, cols):\n            row[c] = ch\n        rest = seq[len(cols):]\n        pos = (cols[-1] + 1) if cols else 0\n        row = row[:pos] + list(rest) + row[pos:] if rest else row\n        rows.append(row)\n    width = max(len(r) for r in rows)\n    return [\"\".join(r) + \"-\" * (width - len(r)) for r in rows]\n\n\ndef _msa_sp(rows):\n    tot = 0\n    for c in range(len(rows[0])):\n        a, b, d = rows[0][c], rows[1][c], rows[2][c]\n        tot += _msa_pair(a, b) + _msa_pair(a, d) + _msa_pair(b, d)\n    return tot\n\n\n@_objective('msa', fidelity=\"simplified\", note=\"只有 3 条合成的短 DNA 序列、线性空位罚分（匹配 +2、错配 −1、残基对空位 −2），没有 BLOSUM 等替换矩阵与仿射空位；解码对位串做了「1 不够就接在后面」的修补\", encoding=\"bits\")\ndef _obj_msa(self, s):\n    # 多序列比对（和对 SP 得分，最大化）：目标 = −SP\n    return -_msa_sp(_msa_rows(self, s))\n\n\n@_detail('msa')\ndef _detail_msa(self, s):\n    rows = _msa_rows(self, s)\n    return {\"rows\": rows, \"sp\": _msa_sp(rows), \"opt\": self.p[\"opt\"]}\n\n\n@_objective('blo', fidelity=\"illustrative\", note=\"上层 Rastrigin + 下层最优响应耦合项的自拟函数，没有真正的嵌套优化\", encoding=\"real\")\ndef _obj_blo(self, s):\n    # 双层优化（教学级）：上层 rastrigin + 下层最优响应耦合项\n    v = self.variant\n    upper = sum(x * x for x in s)\n    lower_resp = sum(10 * math.cos(2 * math.pi * (x * 0.5)) for x in s)\n    return round(upper + abs(lower_resp), 3)\n\n\ndef _ras(x):\n    return 10 * len(x) + sum(v * v - 10 * math.cos(2 * math.pi * v) for v in x)\n\n\n@_objective('ro', fidelity=\"simplified\", note=\"场景是 8 个固定的随机扰动，没有区间不确定集的凸对偶化，也没有「预算化的不确定性」(Bertsimas–Sim)；目标函数是 Rastrigin 这个人造地形\", encoding=\"real\")\ndef _obj_ro(self, s):\n    # 鲁棒优化（场景法）：最差情形目标 = max_k f(x + δₖ)；f 是 Rastrigin\n    return round(max(_ras([a + d for a, d in zip(s, dl)]) for dl in self.p[\"scen\"]), 6)\n\n\n@_detail('ro')\ndef _detail_ro(self, s):\n    vals = [_ras([a + d for a, d in zip(s, dl)]) for dl in self.p[\"scen\"]]\n    return {\"nominal\": round(_ras(s), 4), \"scenarios\": [round(v, 4) for v in vals], \"worst\": round(max(vals), 4)}\n\n\n# ---- 批 3：选址族 10 变体目标 ----\n\n@_objective('lap', fidelity=\"standard\")\ndef _obj_lap(self, s):\n    # 线性指派：Σ c[i][π(i)]\n    v = self.variant\n    c = self.p[\"c\"]\n    return sum(c[i][s[i]] for i in range(self.n))\n\n\n@_objective('qap', fidelity=\"standard\")\ndef _obj_qap(self, s):\n    # 二次分配：ΣΣ 流量 a[i][j] × 距离 b[π(i)][π(j)]\n    v = self.variant\n    a, b = self.p[\"a\"], self.p[\"b\"]\n    return sum(a[i][j] * b[s[i]][s[j]]\n               for i in range(self.n) for j in range(self.n) if i != j)\n\n\n@_objective('pmedian', 'pcenter', fidelity=\"standard\")\ndef _obj_pmedian_etc2(self, s):\n    # 前 p 位=设施；客户→最近设施\n    v = self.variant\n    pts, pfac = self.p[\"pts\"], self.p[\"p\"]\n    fac = s[:pfac]\n    ds = []\n    for i in range(self.n):\n        if i in fac:\n            continue\n        ds.append(min(math.dist(pts[i], pts[f]) for f in fac))\n    if v == \"pmedian\":\n        return round(sum(ds), 3)\n    return round(max(ds) if ds else 0, 3)  # p-中心=minimize 最大距离\n\n\n@_detail('pmedian', 'pcenter')\ndef _detail_pmedian_etc2(self, s):\n    pts, pfac = self.p[\"pts\"], self.p[\"p\"]\n    fac = list(s[:pfac])\n    assign = [min(fac, key=lambda f: (math.dist(pts[i], pts[f]), f)) for i in range(self.n)]\n    return {\"fac\": fac, \"assign\": assign, \"dist\": [round(math.dist(pts[i], pts[assign[i]]), 3) for i in range(self.n)]}\n\n\ndef _cflp_plan(self, s):\n    \"\"\"排列 s 给出开设顺序：先开到容量够覆盖总需求，再按需求从大到小把客户贪心派给「最近且还装得下」的已开设施；\n    派不下就继续按排列顺序多开一个再试。返回（已开设施, {客户: 设施}, 是否全部派完）。\"\"\"\n    pts, cap, dem = self.p[\"pts\"], self.p[\"cap\"], self.p[\"dem\"]\n    n, total = self.n, sum(self.p[\"dem\"])\n    opened, csum, k = [], 0, 0\n    while csum < total and k < n:\n        opened.append(s[k])\n        csum += cap[s[k]]\n        k += 1\n    order = sorted(range(n), key=lambda i: (-dem[i], i))\n    while True:\n        res = {f: cap[f] for f in opened}\n        asg, ok = {}, True\n        for i in order:\n            cands = [f for f in opened if res[f] >= dem[i]]\n            if not cands:\n                ok = False\n                break\n            f = min(cands, key=lambda f: (math.dist(pts[i], pts[f]), f))\n            asg[i] = f\n            res[f] -= dem[i]\n        if ok or k >= n:\n            return opened, asg, ok\n        opened.append(s[k])\n        k += 1\n\n\n@_objective('cflp', fidelity=\"simplified\", note=\"开设顺序由排列给出、开到容量够为止，客户用贪心而不是运输问题派给设施；设施固定费与运输费都是自拟尺度\")\ndef _obj_cflp(self, s):\n    opened, asg, _ok = _cflp_plan(self, s)\n    pts, dem, fc = self.p[\"pts\"], self.p[\"dem\"], self.p[\"fc\"]\n    total = sum(fc[f] for f in opened) + sum(math.dist(pts[i], pts[f]) * dem[i] for i, f in asg.items())\n    return round(total + self.BIG * (self.n - len(asg)), 3)\n\n\n@_detail('cflp')\ndef _detail_cflp(self, s):\n    opened, asg, ok = _cflp_plan(self, s)\n    cap, dem = self.p[\"cap\"], self.p[\"dem\"]\n    load = {f: 0 for f in opened}\n    for i, f in asg.items():\n        load[f] += dem[i]\n    return {\"open\": opened, \"assign\": [asg.get(i, -1) for i in range(self.n)], \"load\": [load.get(f, 0) for f in range(self.n)],\n            \"cap\": cap, \"fixed\": sum(self.p[\"fc\"][f] for f in opened), \"feasible\": ok}\n\n\ndef _lrp_plan(self, s):\n    \"\"\"排列前 p 位 = 仓库；其余客户归最近的仓库，同一仓库的客户按排列顺序依次装车，装不下就换一辆；每辆车从仓库出发、回仓库。\"\"\"\n    pts, dem, cap, p = self.p[\"pts\"], self.p[\"dem\"], self.p[\"cap\"], self.p[\"p\"]\n    depots = list(s[:p])\n    mine = {d: [] for d in depots}\n    for c in s[p:]:\n        mine[min(depots, key=lambda d: (math.dist(pts[c], pts[d]), d))].append(c)\n    trips = []\n    for d in depots:\n        cur, load = [], 0\n        for c in mine[d]:\n            if cur and load + dem[c] > cap:\n                trips.append((d, cur))\n                cur, load = [], 0\n            cur.append(c)\n            load += dem[c]\n        if cur:\n            trips.append((d, cur))\n    length = 0.0\n    for d, cs in trips:\n        path = [d] + cs + [d]\n        length += sum(math.dist(pts[path[i]], pts[path[i + 1]]) for i in range(len(path) - 1))\n    return depots, trips, length\n\n\n@_objective('lrp', fidelity=\"simplified\", note=\"仓库个数固定为 2；客户归最近仓库、按排列顺序装车（不优化每辆车内的路线顺序）；没有仓库容量\")\ndef _obj_lrp(self, s):\n    depots, trips, length = _lrp_plan(self, s)\n    return round(length + self.p[\"depot_cost\"] * len(depots) + self.p[\"veh_cost\"] * len(trips), 3)\n\n\n@_detail('lrp')\ndef _detail_lrp(self, s):\n    depots, trips, length = _lrp_plan(self, s)\n    return {\"depots\": depots, \"trips\": [[d, list(cs)] for d, cs in trips], \"length\": round(length, 3)}\n\n\ndef _ndp_state(self, s):\n    edges, pairs = self.p[\"edges\"], self.p[\"pairs\"]\n    par = list(range(self.p[\"n_pts\"]))\n\n    def find(x):\n        while par[x] != x:\n            par[x] = par[par[x]]\n            x = par[x]\n        return x\n    cost = 0\n    for k, (a, b, w) in enumerate(edges):\n        if s[k]:\n            cost += w\n            ra, rb = find(a), find(b)\n            if ra != rb:\n                par[ra] = rb\n    return cost, [find(a) == find(b) for a, b in pairs]\n\n\n@_objective('ndp', fidelity=\"simplified\", note=\"只要求需求点对连通（斯坦纳森林），没有流量、容量，也没有「固定费 + 单位费」两部分费用\", encoding=\"bits\")\ndef _obj_ndp(self, s):\n    cost, conn = _ndp_state(self, s)\n    return cost + 500 * sum(1 for c in conn if not c)\n\n\n@_detail('ndp')\ndef _detail_ndp(self, s):\n    cost, conn = _ndp_state(self, s)\n    return {\"sel\": [int(x) for x in s], \"cost\": cost, \"connected\": conn, \"violations\": sum(1 for c in conn if not c), \"size\": int(sum(s))}\n\n\n@_objective('tdm', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_tdm(self, s):\n    # 3-维匹配（最大化版）：选尽量多的两两不相交三元组；与集合打包同构（元素被重复占用 × BIG 罚）\n    return _obj_setpack(self, s)\n\n\n@_detail('tdm')\ndef _detail_tdm(self, s):\n    cover = [0] * len(self.p[\"sets\"][0])\n    for i, row in enumerate(self.p[\"sets\"]):\n        if s[i]:\n            for j, e in enumerate(row):\n                if e:\n                    cover[j] += 1\n    return {\"sel\": [int(x) for x in s], \"violations\": sum(c - 1 for c in cover if c > 1), \"size\": int(sum(s)), \"q\": self.p[\"q\"]}\n\n\n@_objective('freqasg', fidelity=\"simplified\", note=\"频率数固定为 6，相邻频率也算冲突；不是通用频率分配\")\ndef _obj_freqasg(self, s):\n    # 频率分配：取模分 6 频率，冲突对罚（同着色）\n    v = self.variant\n    conf, slots = self.p[\"conf\"], self.p[\"slots\"]\n    slot_of = {x: i % slots for i, x in enumerate(s)}\n    viol = sum(conf[a][b] for a in range(self.n) for b in range(a + 1, self.n)\n               if abs(slot_of[a] - slot_of[b]) <= 1)  # 相邻频率也算冲突\n    return self.BIG * viol\n\n\n# ---- 批 4：图问题族 12 变体目标 ----\n\n@_objective('mclique', fidelity=\"standard\")\ndef _obj_mclique(self, s):\n    # 排列序构建团：依次加入与团内全部邻接的点\n    v = self.variant\n    edges, nn = self.p[\"edges\"], self.n\n    adj = {a: set() for a in range(nn)}\n    for (a, b, _) in edges:\n        adj[a].add(b)\n        adj[b].add(a)\n    clique = []\n    for x in s:\n        if all(y in adj[x] for y in clique):\n            clique.append(x)\n    return -len(clique)  # 最大化团大小\n\n\n@_objective('gpp', fidelity=\"standard\")\ndef _obj_gpp(self, s):\n    # 图划分：均衡两块+最小割（与 maxcut 相反目标）\n    v = self.variant\n    side = {x: i % 2 for i, x in enumerate(s)}\n    cut = sum(w for (a, b, w) in self.p[\"edges\"] if side[a] != side[b])\n    bal = abs(sum(1 for x in s if side[x] == 0) - self.n // 2)\n    return cut + 50 * bal\n\n\n@_objective('csplogic', fidelity=\"simplified\", note=\"取模赋值 + 冲突罚，规模与约束类型有限\")\ndef _obj_csplogic(self, s):\n    # 约束满足：取模赋值，冲突罚（同 etp 模式）\n    v = self.variant\n    conf, slots = self.p[\"conf\"], self.p[\"slots\"]\n    slot_of = {x: i % slots for i, x in enumerate(s)}\n    viol = sum(conf[a][b] for a in range(self.n) for b in range(a + 1, self.n)\n               if slot_of[a] == slot_of[b])\n    return self.BIG * viol\n\n\n# ============================================================ 上下文与入口\n\n# ============================================================ 第一梯队新增（2026-10）\n# 每个变体 = 一对 @_maker / @_objective；需要在页面上画出「解长什么样」的变体再登记一个 @_detail。\n\n# ---------------------------------------------------------------- 子集类问题：位向量编码（每一位 = 选 / 不选）\n# 与排列版的区别：k 不再是写死的常数，目标里既有「选了多少」也有「违反了多少」，约束违反用 BIG 罚（BIG 远大于任何可行目标之差）。\n\ndef _es_graph_adj(p):\n    adj = [set() for _ in range(p[\"n\"])]\n    for (a, b, _w) in p[\"edges\"]:\n        adj[a].add(b)\n        adj[b].add(a)\n    return adj\n\n\n@_objective('vcover', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_vcover(self, s):\n    # 顶点覆盖：选尽量少的顶点，使每条边至少有一个端点被选\n    unc = sum(1 for (a, b, _w) in self.p[\"edges\"] if not s[a] and not s[b])\n    return self.BIG * unc + sum(s)\n\n\n@_objective('domset', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_domset(self, s):\n    # 支配集：选尽量少的顶点，使每个顶点要么被选、要么有被选的邻居\n    adj = _es_graph_adj(self.p)\n    und = sum(1 for v in range(self.n) if not s[v] and not any(s[u] for u in adj[v]))\n    return self.BIG * und + sum(s)\n\n\ndef _fvs_cycles(p, removed):\n    \"\"\"删掉 removed 之后剩下的图里「多余的边数」（= 圈秩；0 表示是森林）。\"\"\"\n    parent = list(range(p[\"n\"]))\n\n    def find(x):\n        while parent[x] != x:\n            parent[x] = parent[parent[x]]\n            x = parent[x]\n        return x\n    cyc = 0\n    for (a, b, _w) in p[\"edges\"]:\n        if removed[a] or removed[b]:\n            continue\n        ra, rb = find(a), find(b)\n        if ra == rb:\n            cyc += 1\n        else:\n            parent[ra] = rb\n    return cyc\n\n\n@_objective('fvs', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_fvs(self, s):\n    # 反馈顶点集：删尽量少的顶点，使剩下的图没有环（并查集数「多余的边」）\n    return self.BIG * _fvs_cycles(self.p, s) + sum(s)\n\n\n@_objective('maxcut', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_maxcut(self, s):\n    # 最大割：每个顶点一位 = 在哪一侧（不要求两侧一样大），最大化跨侧边权和（取负）\n    return -sum(w for (a, b, w) in self.p[\"edges\"] if s[a] != s[b])\n\n\n@_objective('setpack', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_setpack(self, s):\n    # 集合打包：选尽量多的两两不相交的集合（每位 = 选不选这个集合）；重叠的元素数 × BIG 罚\n    sets = self.p[\"sets\"]\n    cover = [0] * len(sets[0])\n    for i, row in enumerate(sets):\n        if s[i]:\n            for j, e in enumerate(row):\n                if e:\n                    cover[j] += 1\n    return self.BIG * sum(c - 1 for c in cover if c > 1) - sum(s)\n\n\n@_objective('hset', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_hset(self, s):\n    # 击中集：选尽量少的元素（每位 = 选不选这个元素），使每个集合至少含一个被选元素\n    unh = sum(1 for row in self.p[\"sets\"] if not any(row[j] and s[j] for j in range(self.n)))\n    return self.BIG * unh + sum(s)\n\n\n@_maker('stp')\ndef _make_stp(variant, n, seed, rng):\n    # 斯坦纳树：平面上的点集 + 必需点（terminal）；其余点是可选的中转点（Steiner 点）\n    nn = max(8, min(n, 14))\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(nn)]\n    req = sorted(rng.sample(range(nn), max(3, nn // 3)))\n    return {\"variant\": variant, \"pts\": pts, \"req\": req, \"n\": nn}\n\n\ndef _mst_len(pts, nodes):\n    \"\"\"完全欧氏图上 nodes 的最小生成树长度（Prim）。\"\"\"\n    nodes = list(nodes)\n    if len(nodes) < 2:\n        return 0.0\n    dist = {v: math.dist(pts[nodes[0]], pts[v]) for v in nodes[1:]}\n    total = 0.0\n    while dist:\n        v = min(dist, key=dist.get)\n        total += dist.pop(v)\n        for u in dist:\n            d = math.dist(pts[v], pts[u])\n            if d < dist[u]:\n                dist[u] = d\n    return total\n\n\n@_objective('stp', fidelity=\"standard\", encoding=\"bits\")\ndef _obj_stp(self, s):\n    # 图上的斯坦纳树：必需点一定在树里；每个其余点一位 = 要不要作为中转点；\n    # 目标 = 必需点 ∪ 被选中转点 在完全欧氏图上的最小生成树长度（最优斯坦纳树恰好是某个点子集的最小生成树）\n    req = self.p[\"req\"]\n    nodes = set(req) | {i for i in range(self.n) if s[i]}\n    return round(_mst_len(self.p[\"pts\"], nodes), 3)\n\n\n@_detail('vcover', 'domset', 'fvs', 'maxcut', 'stp')\ndef _detail_graph_bits(self, s):\n    p = self.p\n    if self.variant == \"vcover\":\n        bad = sum(1 for (a, b, _w) in p[\"edges\"] if not s[a] and not s[b])\n    elif self.variant == \"domset\":\n        adj = _es_graph_adj(p)\n        bad = sum(1 for v in range(self.n) if not s[v] and not any(s[u] for u in adj[v]))\n    elif self.variant == \"fvs\":\n        bad = _fvs_cycles(p, s)\n    elif self.variant == \"maxcut\":\n        bad = 0\n    else:\n        bad = 0\n    out = {\"sel\": [int(x) for x in s], \"violations\": bad, \"size\": int(sum(s))}\n    if self.variant == \"maxcut\":\n        out[\"cut\"] = sum(w for (a, b, w) in p[\"edges\"] if s[a] != s[b])\n        out[\"total\"] = sum(w for (_a, _b, w) in p[\"edges\"])\n    if self.variant == \"stp\":\n        nodes = set(p[\"req\"]) | {i for i in range(self.n) if s[i]}\n        out[\"nodes\"] = sorted(nodes)\n        out[\"mst\"] = round(_mst_len(p[\"pts\"], nodes), 3)\n    return out\n\n\n@_detail('setpack', 'hset')\ndef _detail_set_bits(self, s):\n    sets = self.p[\"sets\"]\n    if self.variant == \"setpack\":\n        cover = [0] * len(sets[0])\n        for i, row in enumerate(sets):\n            if s[i]:\n                for j, e in enumerate(row):\n                    if e:\n                        cover[j] += 1\n        bad = sum(c - 1 for c in cover if c > 1)\n    else:\n        bad = sum(1 for row in sets if not any(row[j] and s[j] for j in range(self.n)))\n    return {\"sel\": [int(x) for x in s], \"violations\": bad, \"size\": int(sum(s))}\n\n\n# ---------------------------------------------------------------- 定向运动 OP（2026-10 重建为标准模型）\n\n@_maker('orienteering')\ndef _make_orienteering(variant, n, seed, rng):\n    # 仓库居中 + n 个带收益的点；预算 = 最近邻回路长度的 45%——走不完所有点，必须挑「值得去的」\n    k = max(8, min(n, 20))\n    pts = [[50.0, 50.0]] + [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(k)]\n    gain = [0] + [rng.randint(5, 20) for _ in range(k)]\n    left, cur, tour = set(range(1, k + 1)), 0, 0.0\n    while left:\n        nxt = min(left, key=lambda j: math.dist(pts[cur], pts[j]))\n        tour += math.dist(pts[cur], pts[nxt])\n        left.remove(nxt)\n        cur = nxt\n    tour += math.dist(pts[cur], pts[0])\n    return {\"variant\": variant, \"pts\": pts, \"gain\": gain, \"budget\": round(0.45 * tour, 1), \"n\": k}  # n = 客户数\n\n\ndef _op_route(p, s):\n    \"\"\"按优先序 s 依次访问：该点放得下（去了还能在预算内回仓库）才去，放不下的跳过。\n    任何可行路线都可以写成「它的访问序在前、其余点在后」的优先序，所以这个解码不丢最优解。\"\"\"\n    pts, budget = p[\"pts\"], p[\"budget\"]\n    route, cur, used = [0], 0, 0.0\n    for x in s:\n        j = x + 1\n        d = math.dist(pts[cur], pts[j])\n        if used + d + math.dist(pts[j], pts[0]) <= budget + 1e-9:\n            route.append(j)\n            used += d\n            cur = j\n    used += math.dist(pts[cur], pts[0])\n    route.append(0)\n    return route, used\n\n\n@_objective('orienteering', fidelity=\"standard\",\n            note=\"\")\ndef _obj_orienteering(self, s):\n    # 定向运动：在预算内选点并排路线，最大化收集的收益（取负）；同分时极小的路程项偏好更短的路线\n    route, length = _op_route(self.p, s)\n    return round(-sum(self.p[\"gain\"][j] for j in route) + length / 10000.0, 6)\n\n\n@_detail('orienteering')\ndef _detail_orienteering(self, s):\n    route, length = _op_route(self.p, s)\n    return {\"route\": route, \"score\": sum(self.p[\"gain\"][j] for j in route), \"length\": round(length, 2),\n            \"budget\": self.p[\"budget\"], \"total_gain\": sum(self.p[\"gain\"])}\n\n\n# ---------------------------------------------------------------- 资源受限项目调度 RCPSP（串行调度生成方案）\n\n@_maker('rcpsp')\ndef _make_rcpsp(variant, n, seed, rng):\n    # n 个活动（工期 1~6）、前序关系（只从编号小的指向编号大的，保证无环）、2 种可再生资源\n    k = max(6, min(n, 20))\n    dur = [rng.randint(1, 6) for _ in range(k)]\n    preds = [sorted(rng.sample(range(i), min(i, rng.randint(0, 2)))) if i else [] for i in range(k)]\n    r = [[rng.randint(0, 4) for _ in range(2)] for _ in range(k)]\n    return {\"variant\": variant, \"dur\": dur, \"preds\": preds, \"r\": r, \"caps\": [6, 6], \"n\": k}\n\n\ndef rcpsp_schedule(p, order):\n    \"\"\"串行调度生成方案（serial SGS，RCPSP 最标准的解码）：按优先序依次取「前序都已排好」的第一个活动，\n    排在满足前序与资源上限的最早开工时刻。返回 (开工时间, 完工时间, 工期)。\"\"\"\n    dur, preds, r, caps = p[\"dur\"], p[\"preds\"], p[\"r\"], p[\"caps\"]\n    n, K = len(dur), len(caps)\n    horizon = sum(dur)\n    usage = [[0] * (horizon + 1) for _ in range(K)]\n    start, end = [None] * n, [None] * n\n    todo = list(order)\n    while todo:\n        idx = next(i for i, a in enumerate(todo) if all(start[q] is not None for q in preds[a]))\n        a = todo.pop(idx)\n        t = max((end[q] for q in preds[a]), default=0)\n        while any(usage[k][u] + r[a][k] > caps[k] for k in range(K) for u in range(t, t + dur[a])):\n            t += 1\n        for k in range(K):\n            for u in range(t, t + dur[a]):\n                usage[k][u] += r[a][k]\n        start[a], end[a] = t, t + dur[a]\n    return start, end, max(end)\n\n\n@_objective('rcpsp', fidelity=\"standard\")\ndef _obj_rcpsp(self, s):\n    # 目标 = 项目工期（最后一个活动的完工时刻）。解 = 活动的优先序，解码 = 串行调度生成方案\n    return rcpsp_schedule(self.p, s)[2]\n\n\n@_detail('rcpsp')\ndef _detail_rcpsp(self, s):\n    start, end, mk = rcpsp_schedule(self.p, s)\n    p = self.p\n    n = len(p[\"dur\"])\n    longest = [0] * n  # 关键路径（只看前序、不看资源）= 工期的一个下界\n    for i in range(n):\n        longest[i] = p[\"dur\"][i] + max((longest[q] for q in p[\"preds\"][i]), default=0)\n    res_lb = max(-(-sum(p[\"dur\"][i] * p[\"r\"][i][k] for i in range(n)) // p[\"caps\"][k]) for k in range(len(p[\"caps\"])))\n    return {\"start\": start, \"end\": end, \"makespan\": mk, \"lb\": max(max(longest), res_lb)}\n\n\n# ---------------------------------------------------------------- 非对称旅行商 ATSP\n\n@_maker('atsp')\ndef _make_atsp(variant, n, seed, rng):\n    # 非对称 TSP：去程与回程代价不同（单行线、顺逆风、上下坡）。距离 = 欧氏距离 × 每条有向边各自的随机因子，取整\n    k = max(5, min(n, 30))\n    pts = [[round(rng.uniform(0, 100), 1), round(rng.uniform(0, 100), 1)] for _ in range(k)]\n    d = [[0 if i == j else int(round(math.dist(pts[i], pts[j]) * rng.uniform(0.7, 1.6))) for j in range(k)]\n         for i in range(k)]\n    return {\"variant\": variant, \"pts\": pts, \"d\": d, \"n\": k}  # pts 只用来画图，代价全在矩阵 d 里\n\n\n@_objective('atsp', fidelity=\"standard\")\ndef _obj_atsp(self, s):\n    # 回路总代价：沿访问顺序累加有向边代价 d[i][j]（i→j 与 j→i 可以不同），最后回到起点\n    d = self.p[\"d\"]\n    return sum(d[s[i]][s[(i + 1) % len(s)]] for i in range(len(s)))\n\n\n@_detail('vrptw', 'vrpstw')\ndef _detail_vrptw(self, s):\n    arcs = _vrptw_arcs_of(self, s)\n    n = len(s)\n    tour = [x + 1 for x in s]\n    total, spans = vrptw_split(arcs, n, self.p[\"m_veh\"])\n    within = total is not None\n    if not within:\n        _f, _u, spans = vrptw_free_split(arcs, n)\n    routes = [tour[i:j] for i, j in spans]\n    sched = [vrptw_schedule(self.p, r) for r in routes]\n    wait = sum(a[1] - a[0] for sc in sched for a in sc)\n    out = {\"routes\": routes, \"sched\": sched, \"wait\": round(wait, 2), \"within_fleet\": within}\n    if \"lam\" in self.p:  # 软时间窗：迟到总量（客户窗 + 回仓晚于关门）和里程分开给，目标 = 里程 + lam × 迟到\n        late = sum(max(0.0, a[0] - self.p[\"l\"][c]) for r, sc in zip(routes, sched) for c, a in zip(r, sc))\n        for r, sc in zip(routes, sched):\n            late += max(0.0, sc[-1][2] + math.dist(self.p[\"pts\"][r[-1]], self.p[\"pts\"][0]) - self.p[\"l\"][0])\n        dist = sum(sum(math.dist(self.p[\"pts\"][a], self.p[\"pts\"][b]) for a, b in zip([0] + r, r + [0])) for r in routes)\n        out.update(late=round(late, 2), dist=round(dist, 2))\n    return out\n\n\n@_detail('mdvrp')\ndef _detail_mdvrp(self, s):\n    _tot, parts = mdvrp_split_all(self, s)\n    D = self.p[\"D\"]\n    routes, depot_of = [], []\n    for d, rts, _w in parts:\n        for r in rts:\n            routes.append([D + c - 1 for c in r])  # 1..k → pts 下标（仓库在前）\n            depot_of.append(d)\n    return {\"routes\": routes, \"route_depot\": depot_of, \"within_fleet\": all(w for _d, _r, w in parts),\n            \"per_depot\": [len(r) for _d, r, _w in parts]}\n\n\n@_detail('atsp')\ndef _detail_atsp(self, s):\n    return {\"order\": list(s)}\n\n\n# ---------------------------------------------------------------- 并行机调度 P||Cmax\n\n@_maker('pms')\ndef _make_pms(variant, n, seed, rng):\n    k = max(6, min(n, 40))\n    m = 3 if k <= 16 else (4 if k <= 28 else 5)\n    return {\"variant\": variant, \"p\": [rng.randint(5, 40) for _ in range(k)], \"m_mach\": m, \"n\": k}\n\n\ndef _pms_assign(p, m, order):\n    \"\"\"表调度（list scheduling）：按优先序依次把作业放到当前负载最小的机器。\n    任何最优调度都能表示成某个优先序的表调度，所以搜索优先序就覆盖了全部最优解。\"\"\"\n    loads = [0] * m\n    machines = [[] for _ in range(m)]\n    for j in order:\n        i = loads.index(min(loads))\n        loads[i] += p[j]\n        machines[i].append(j)\n    return loads, machines\n\n\n@_objective('pms', fidelity=\"standard\")\ndef _obj_pms(self, s):\n    # 目标 = 最大完工时间 makespan（Cmax）：最忙那台机器的总加工时间\n    loads, _ = _pms_assign(self.p[\"p\"], self.p[\"m_mach\"], s)\n    return max(loads)\n\n\n@_detail('pms')\ndef _detail_pms(self, s):\n    loads, machines = _pms_assign(self.p[\"p\"], self.p[\"m_mach\"], s)\n    total = sum(self.p[\"p\"])\n    return {\"machines\": machines, \"loads\": loads,\n            \"lb\": max(max(self.p[\"p\"]), -(-total // self.p[\"m_mach\"]))}  # 下界 max(最长作业, ⌈总时间/机器数⌉)\n\n\n# ---------------------------------------------------------------- 数分割\n\n@_maker('numpart')\ndef _make_numpart(variant, n, seed, rng):\n    k = max(6, min(n, 40))\n    return {\"variant\": variant, \"a\": [rng.randint(1, 10000) for _ in range(k)], \"n\": k}\n\n\n@_objective('numpart', fidelity=\"standard\", encoding=\"real\")\ndef _obj_numpart(self, s):\n    # 实数向量 s：s[i] > 0 → 第 i 个数放进集合 A，否则放进 B；目标 = |ΣA − ΣB|（越小越均衡，0 = 完美划分）\n    a = self.p[\"a\"]\n    return abs(sum(a[i] if s[i] > 0 else -a[i] for i in range(len(a))))\n\n\n@_detail('numpart')\ndef _detail_numpart(self, s):\n    a = self.p[\"a\"]\n    side = [1 if s[i] > 0 else 0 for i in range(len(a))]\n    return {\"side\": side, \"sum_a\": sum(a[i] for i in range(len(a)) if side[i]),\n            \"sum_b\": sum(a[i] for i in range(len(a)) if not side[i])}\n\n\n# ---------------------------------------------------------------- k-means 聚类（中心点优化）\n\n@_maker('kmeans')\ndef _make_kmeans(variant, n, seed, rng):\n    # 簇数 k：n ≤ 15 取 3，之后每 10 加 1（最多 6）；每簇约 20 个点，高斯团块\n    k = 3 if n <= 15 else min(6, 2 + n // 10)\n    centers = [[rng.uniform(15, 85), rng.uniform(15, 85)] for _ in range(k)]\n    pts = []\n    for c in centers:\n        sd = rng.uniform(5, 10)\n        pts += [[round(rng.gauss(c[0], sd), 2), round(rng.gauss(c[1], sd), 2)] for _ in range(20)]\n    return {\"variant\": variant, \"pts\": pts, \"k\": k, \"n\": 2 * k}  # n = 决策向量长度 = 2k（k 个中心的 x,y）\n\n\ndef _kmeans_centers(p, s):\n    \"\"\"向量 s ∈ [−5,5]^(2k) → k 个中心：每个坐标按比例映射到数据包围盒里（所以用户的点集不论坐标尺度都能用）。\"\"\"\n    xs = [q[0] for q in p[\"pts\"]]\n    ys = [q[1] for q in p[\"pts\"]]\n    lo, hi = (min(xs), min(ys)), (max(xs), max(ys))\n    out = []\n    for c in range(p[\"k\"]):\n        out.append([lo[0] + (min(5, max(-5, s[2 * c])) + 5) / 10 * (hi[0] - lo[0]),\n                    lo[1] + (min(5, max(-5, s[2 * c + 1])) + 5) / 10 * (hi[1] - lo[1])])\n    return out\n\n\n@_objective('kmeans', fidelity=\"standard\", encoding=\"real\")\ndef _obj_kmeans(self, s):\n    # k-means 的目标：每个点到最近中心的平方距离之和（SSE）。这里直接优化中心位置，不做 Lloyd 迭代\n    cs = _kmeans_centers(self.p, s)\n    return round(sum(min((q[0] - c[0]) ** 2 + (q[1] - c[1]) ** 2 for c in cs) for q in self.p[\"pts\"]), 3)\n\n\n@_detail('kmeans')\ndef _detail_kmeans(self, s):\n    cs = _kmeans_centers(self.p, s)\n    assign = [min(range(len(cs)), key=lambda c: (q[0] - cs[c][0]) ** 2 + (q[1] - cs[c][1]) ** 2)\n              for q in self.p[\"pts\"]]\n    return {\"centers\": [[round(v, 3) for v in c] for c in cs], \"assign\": assign}\n\n\n# ---------------------------------------------------------------- 分数背包（实数向量编码）\n\n@_maker('fkp')\ndef _make_fkp(variant, n, seed, rng):\n    # 分数背包：每个物品可以只取一部分（比例 x∈[0,1]）。物品分布与 0-1 背包页相同：重量 2–60、价值 10–100、容量 = 总重量的 45%\n    nn = max(8, min(n, 60))\n    w = [rng.randint(2, 60) for _ in range(nn)]\n    v = [rng.randint(10, 100) for _ in range(nn)]\n    cap = int(sum(w) * 0.45)\n    lp, rest = 0.0, cap\n    for i in sorted(range(nn), key=lambda i: -v[i] / w[i]):  # 贪心（按价值密度）就是分数背包的精确最优\n        take = min(1.0, rest / w[i])\n        lp += v[i] * take\n        rest -= w[i] * take\n        if rest <= 1e-12:\n            break\n    return {\"variant\": variant, \"w\": w, \"v\": v, \"cap\": cap, \"n\": nn, \"lp\": round(lp, 6)}\n\n\ndef _fkp_x(s):\n    return [min(1.0, max(0.0, (x + 5.0) / 10.0)) for x in s]  # 决策向量 [−5,5] 线性映射成取用比例 [0,1]\n\n\n@_objective('fkp', fidelity=\"standard\", encoding=\"real\")\ndef _obj_fkp(self, s):\n    # 最大化 Σ vᵢxᵢ，s.t. Σ wᵢxᵢ ≤ 容量。用精确罚函数 −价值 + λ·超重，λ = 最大价值密度 + 1：\n    # λ 不小于任何一个物品的价值密度时，罚函数的最优与带约束的最优一致（超重 1 单位至多换来 λ 的收益，永远不划算）\n    x = _fkp_x(s)\n    w, v = self.p[\"w\"], self.p[\"v\"]\n    lam = max(vi / wi for vi, wi in zip(v, w)) + 1.0\n    over = max(0.0, sum(wi * xi for wi, xi in zip(w, x)) - self.p[\"cap\"])\n    return round(-sum(vi * xi for vi, xi in zip(v, x)) + lam * over, 6)\n\n\n@_detail('fkp')\ndef _detail_fkp(self, s):\n    x = _fkp_x(s)\n    w, v = self.p[\"w\"], self.p[\"v\"]\n    return {\"x\": [round(t, 4) for t in x], \"weight\": round(sum(a * b for a, b in zip(w, x)), 4),\n            \"value\": round(sum(a * b for a, b in zip(v, x)), 4), \"lp\": self.p[\"lp\"], \"cap\": self.p[\"cap\"]}\n\n\n# ---------------------------------------------------------------- 工程约束设计（4 个经典算例）\n# 决策向量 s ∈ [−5,5]^n 按比例映射到各变量的取值范围；约束写成无量纲形式 g ≤ 0（g = 实际值/限值 − 1），\n# 违反量按 精确罚函数 f + 1000·f_scale·Σmax(0,g) 计入（权重大于拉格朗日乘子，所以罚函数的最优 = 约束问题的最优）。\n\n_DESIGN = {}\n\n\ndef _design(variant, names, bounds, f_scale, best):\n    def deco(fn):\n        _DESIGN[variant] = {\"names\": names, \"bounds\": bounds, \"f_scale\": f_scale, \"best\": best, \"fn\": fn}\n        return fn\n    return deco\n\n\ndef _design_x(variant, s):\n    b = _DESIGN[variant][\"bounds\"]\n    return [lo + (min(5, max(-5, v)) + 5) / 10 * (hi - lo) for v, (lo, hi) in zip(s, b)]\n\n\ndef _design_eval(variant, s):\n    spec = _DESIGN[variant]\n    x = _design_x(variant, s)\n    f, g = spec[\"fn\"](x)\n    return x, f, g\n\n\n@_design(\"wbeam\", [\"h 焊缝厚度\", \"l 焊缝长度\", \"t 梁高\", \"b 梁宽\"],\n         [(0.1, 2.0), (0.1, 10.0), (0.1, 10.0), (0.1, 2.0)], 1.0, 1.724852)\ndef _wbeam(x):\n    # 焊接梁（Coello 2000）：最小化制造成本；约束 = 剪应力 / 弯曲应力 / 几何 / 挠度 / 屈曲载荷\n    h, l, t, b = x\n    P, L, E, G = 6000.0, 14.0, 30e6, 12e6\n    tau_max, sigma_max, delta_max = 13600.0, 30000.0, 0.25\n    f = 1.10471 * h * h * l + 0.04811 * t * b * (14.0 + l)\n    M = P * (L + l / 2.0)\n    R = math.sqrt(l * l / 4.0 + ((h + t) / 2.0) ** 2)\n    J = 2.0 * (math.sqrt(2.0) * h * l * (l * l / 12.0 + ((h + t) / 2.0) ** 2))\n    t1 = P / (math.sqrt(2.0) * h * l)\n    t2 = M * R / J\n    tau = math.sqrt(t1 * t1 + 2.0 * t1 * t2 * l / (2.0 * R) + t2 * t2)\n    sigma = 6.0 * P * L / (b * t * t)\n    delta = 4.0 * P * L ** 3 / (E * t ** 3 * b)\n    Pc = (4.013 * E * math.sqrt(t * t * b ** 6 / 36.0) / (L * L)) * (1.0 - t / (2.0 * L) * math.sqrt(E / (4.0 * G)))\n    g = [tau / tau_max - 1.0, sigma / sigma_max - 1.0, (h - b) / 2.0,\n         (0.10471 * h * h + 0.04811 * t * b * (14.0 + l) - 5.0) / 5.0, (0.125 - h) / 0.125,\n         delta / delta_max - 1.0, 1.0 - Pc / P]\n    return f, g\n\n\n@_design(\"pvessel\", [\"Ts 筒壁厚\", \"Th 封头厚\", \"R 内半径\", \"L 筒长\"],\n         [(0.0625, 6.1875), (0.0625, 6.1875), (10.0, 200.0), (10.0, 200.0)], 6000.0, 5885.3328)\ndef _pvessel(x):\n    # 压力容器（Sandgren 1990，连续变量版）：最小化材料 + 成型 + 焊接成本\n    Ts, Th, R, L = x\n    f = 0.6224 * Ts * R * L + 1.7781 * Th * R * R + 3.1661 * Ts * Ts * L + 19.84 * Ts * Ts * R\n    g = [(-Ts + 0.0193 * R) / 1.0, (-Th + 0.00954 * R) / 1.0,\n         (-math.pi * R * R * L - 4.0 / 3.0 * math.pi * R ** 3 + 1296000.0) / 1296000.0, (L - 240.0) / 240.0]\n    return f, g\n\n\n@_design(\"tcspring\", [\"d 线径\", \"D 簧圈中径\", \"N 有效圈数\"],\n         [(0.05, 2.0), (0.25, 1.3), (2.0, 15.0)], 0.0127, 0.012665)\ndef _tcspring(x):\n    # 拉压弹簧（Arora 1989）：最小化重量；约束 = 最小挠度 / 剪应力 / 颤振频率 / 外径\n    d, D, N = x\n    f = (N + 2.0) * D * d * d\n    g = [1.0 - D ** 3 * N / (71785.0 * d ** 4),\n         (4.0 * D * D - d * D) / (12566.0 * (D * d ** 3 - d ** 4)) + 1.0 / (5108.0 * d * d) - 1.0,\n         1.0 - 140.45 * d / (D * D * N), (d + D) / 1.5 - 1.0]\n    return f, g\n\n\n@_design(\"reducer\", [\"b 齿宽\", \"m 模数\", \"z 小齿轮齿数\", \"l1 轴1跨距\", \"l2 轴2跨距\", \"d1 轴1直径\", \"d2 轴2直径\"],\n         [(2.6, 3.6), (0.7, 0.8), (17.0, 28.0), (7.3, 8.3), (7.3, 8.3), (2.9, 3.9), (5.0, 5.5)], 3000.0, 2994.4711)\ndef _reducer(x):\n    # 减速器（Golinski）：最小化重量；11 个约束 = 齿弯曲应力 / 接触应力 / 轴挠度 / 轴应力 / 几何\n    b, m, z, l1, l2, d1, d2 = x\n    f = (0.7854 * b * m * m * (3.3333 * z * z + 14.9334 * z - 43.0934)\n         - 1.508 * b * (d1 * d1 + d2 * d2) + 7.4777 * (d1 ** 3 + d2 ** 3) + 0.7854 * (l1 * d1 * d1 + l2 * d2 * d2))\n    g = [27.0 / (b * m * m * z) - 1.0, 397.5 / (b * m * m * z * z) - 1.0,\n         1.93 * l1 ** 3 / (m * d1 ** 4 * z) - 1.0, 1.93 * l2 ** 3 / (m * d2 ** 4 * z) - 1.0,\n         math.sqrt((745.0 * l1 / (m * z)) ** 2 + 16.9e6) / (110.0 * d1 ** 3) - 1.0,\n         math.sqrt((745.0 * l2 / (m * z)) ** 2 + 157.5e6) / (85.0 * d2 ** 3) - 1.0,\n         m * z / 40.0 - 1.0, 5.0 * m / b - 1.0, b / (12.0 * m) - 1.0,\n         (1.5 * d1 + 1.9) / l1 - 1.0, (1.1 * d2 + 1.9) / l2 - 1.0]\n    return f, g\n\n\ndef _obj_design(self, s):\n    x, f, g = _design_eval(self.variant, s)\n    return round(f + 1000.0 * _DESIGN[self.variant][\"f_scale\"] * sum(max(0.0, v) for v in g), 6)\n\n\nfor _v, _note in ((\"wbeam\", \"\"), (\"pvessel\", \"\"), (\"tcspring\", \"\"), (\"reducer\", \"\")):\n    _OBJS[_v] = _obj_design\n    FIDELITY[_v] = {\"level\": \"standard\", \"note\": _note}\n    ENCODING[_v] = \"real\"\n\n\n@_detail('wbeam', 'pvessel', 'tcspring', 'reducer')\ndef _detail_design(self, s):\n    spec = _DESIGN[self.variant]\n    x, f, g = _design_eval(self.variant, s)\n    return {\"names\": spec[\"names\"], \"bounds\": spec[\"bounds\"], \"x\": [round(v, 5) for v in x],\n            \"f\": round(f, 6), \"g\": [round(v, 5) for v in g], \"feasible\": all(v <= 1e-9 for v in g),\n            \"best_known\": spec[\"best\"]}\n\n\ndef _make_design(variant, n, seed, rng):\n    return {\"variant\": variant, \"n\": len(_DESIGN[variant][\"names\"])}\n\n\nfor _v in (\"wbeam\", \"pvessel\", \"tcspring\", \"reducer\"):\n    _MAKERS[_v] = _make_design\n\n\n# ---- 新变体：tools/new_problem.py 把生成的 @_maker / @_objective 追加在这一行之前 ----\n\n\nVARIANTS = tuple(_MAKERS)  # 注册顺序 = 变体清单的唯一来源（必须放在所有 @_maker 登记之后）\nBIT_VARIANTS = tuple(v for v in _OBJS if ENCODING[v] == \"bits\")  # 位向量编码的变体（每位 = 选 / 不选）：由各 @_objective 的 encoding 得出\nVEC_VARIANTS = tuple(v for v in _OBJS if ENCODING[v] == \"real\")  # 实数向量编码的变体（其余为排列编码）\nassert set(ENCODING) == set(_OBJS), \"每个变体都必须有编码（@_objective 默认 perm）\"\nassert set(_MAKERS) == set(_OBJS), \"每个变体必须同时有 maker 与 objective\"\nassert set(FIDELITY) == set(_OBJS), \"每个变体都必须登记保真度\"\n\n\ndef es_make(variant=\"vrp\", n=12, seed=7):\n    \"\"\"实例生成入口：按变体分派到该变体的 @_maker 函数（n 为规模上限，各变体取语义安全子规模）。未知变体返回 None。\"\"\"\n    fn = _MAKERS.get(variant)\n    if fn is None:\n        return None\n    return fn(variant, n, seed, random.Random(seed))\n\n\nclass _ES:\n    \"\"\"entryseq 上下文：排列编码（批 5 黑箱/多目标族为实数向量），变体专属 obj。\"\"\"\n\n    BIG = 4000\n    VEC_VARIANTS = VEC_VARIANTS\n\n    def __init__(self, problem):\n        self.p = problem\n        self.variant = problem[\"variant\"]\n        self.n = problem[\"n\"]\n        self.vec = self.variant in self.VEC_VARIANTS\n        self.bits = self.variant in BIT_VARIANTS\n\n    def random(self, rng):\n        if self.bits:  # 子集类：每位 0/1\n            return [rng.randint(0, 1) for _ in range(self.n)]\n        if self.vec:  # 黑箱/多目标族：实数向量（rastrigin 域 [−5,5]）\n            return [rng.uniform(-5, 5) for _ in range(self.n)]\n        s = list(range(self.n))\n        rng.shuffle(s)\n        return s\n\n    def swap(self, s, rng):\n        if self.bits:  # 位向量邻域 = 翻转一位\n            s = list(s)\n            s[rng.randrange(self.n)] ^= 1\n            return s\n        if self.vec:  # 向量邻域=高斯扰动\n            return [max(-5, min(5, v + rng.gauss(0, 0.5))) for v in s]\n        s = list(s)\n        i, j = rng.randrange(self.n), rng.randrange(self.n)\n        s[i], s[j] = s[j], s[i]\n        return s\n\n    def detail(self, s):\n        \"\"\"页面可视化需要的附加信息（见 @_detail）：由当前最优解推出，随每个状态一起发给页面。\"\"\"\n        fn = _DETAIL.get(self.variant)\n        if fn is not None:\n            return fn(self, s)\n        if self.variant == \"vrp\":\n            return {\"routes\": self.routes(s)}\n        return None\n\n    def routes(self, s):\n        \"\"\"（仅 vrp）把访问序切成路线，返回各路线的 pts 下标列表；切不进车队时按不限车队切（页面仍能画出来）。\"\"\"\n        D = _vrp_dist(self)\n        tour = [x + 1 for x in s]\n        _t, routes = vrp_split(D, self.p[\"demand\"], self.p[\"cap\"], self.p[\"m_veh\"], tour)\n        if routes is None:\n            routes = _vrp_free_routes(D, self.p[\"demand\"], self.p[\"cap\"], tour)\n        return routes\n\n    # ---- 变体目标 ----\n\n    def obj(self, s):\n        \"\"\"变体目标：分派到本文件里该变体的 @_objective 函数。\"\"\"\n        return _OBJS[self.variant](self, s)\n\n\nclass _ESBits(_ES):\n    \"\"\"位向量编码的变体（BIT_VARIANTS）：补上位编码算法要求的协议——value = -obj，repair 恒等，init_pop，polish。\n    只给位向量变体加这些方法：排列变体的 de / gwo / cs 靠「ctx 没有 init_pop」判断自己该走排列分支。\"\"\"\n\n    def value(self, s):\n        return -self.obj(s)\n\n    def repair(self, s):\n        return list(s)\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(x) for x in pop]\n\n    def polish(self, s, rng, moves=10):\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            v = self.value(s)\n            if v >= best:\n                best = v\n            else:\n                s = prev\n        return s\n\n\ndef es_ctx(problem):\n    \"\"\"按变体的编码建上下文。\"\"\"\n    return (_ESBits if problem[\"variant\"] in BIT_VARIANTS else _ES)(problem)\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\n自带问题（Bring Your Own Problem）：用户选一种「解的形状」（编码）+ 写一个目标函数，\n该编码下已有的全部算法内核原样可用。设计与安全边界见 docs/design-bring-your-own-problem.md。\n\n三种编码（= domains 引擎里 custom 域的三个变体）：\n    bits  一串是/否（长度 n）           → 位向量内核（与 QUBO 同一批 21 个算法）\n    perm  一个排序（0..n-1 的排列）      → 排列内核（与装箱/着色同一批 22 个算法）\n    real  一组实数（n 维，统一范围 lo..hi）→ 连续内核（与连续函数同一批 21 个算法）\n\n目标函数（L1 表达式）：Python 表达式的受限子集，用 ast 解析后按白名单检查，**不使用 eval 处理用户原文**——\n没有 import、没有属性访问、没有循环语句、没有字符串，只能做算术、比较、推导式和白名单函数。\n目标函数（L3 本地 Python）：命令行 `--objective-py` 才会打开，浏览器里永远关闭（见 enable_python）。\n\n纯标准库。浏览器里本文件与 domains.py 拼接进同一名字空间（同 entryseq.py 的做法）。\n\"\"\"\nimport ast\nimport difflib\nimport json\nimport math\nimport random\nimport re\nimport time\n\nENCODINGS = (\"bits\", \"perm\", \"real\")\n\nUP_LIMITS = {\n    \"bits\": 1000, \"perm\": 300, \"real\": 100,\n    \"src_chars\": 4000, \"stmts\": 30, \"nodes\": 900,\n    \"data_cells\": 250000,          # 全部数据表的格子总数\n    \"iter_budget\": 2000000,        # 一次评价里推导式最多迭代这么多次\n    \"range_cap\": 1000000,          # 单个 range 的上限\n    \"pow_exp\": 64,                 # 整数幂的指数上限\n    \"int_bits\": 4096,              # 整数乘法 / 乘方结果的位数上限（防止 30 条语句连续平方撑爆内存）\n}\nPENALTY = 1e18                      # 目标函数在某个解上出错 / 非有限时给的惩罚（内部统一按最小化）\n_DRY_RUNS = 30\n\n_PY_ENABLED = False\n\n\ndef enable_python():\n    \"\"\"打开「本地 Python 目标函数」。只有命令行入口会调用；浏览器里的 worker 永远不调用它。\"\"\"\n    global _PY_ENABLED\n    _PY_ENABLED = True\n\n\ndef python_enabled():\n    return _PY_ENABLED\n\n\nclass UPError(ValueError):\n    \"\"\"用户的目标函数 / 数据不合格。msg 里已含行号，可直接展示。\"\"\"\n\n    def __init__(self, path, msg):\n        ValueError.__init__(self, msg)\n        self.path = path\n        self.msg = msg\n\n\nclass _EvalError(Exception):\n    pass\n\n\n# ------------------------------------------------------------------ 白名单\n\ndef _sqrt(v):\n    if v < 0:\n        raise _EvalError(\"sqrt 的参数不能是负数\")\n    return math.sqrt(v)\n\n\ndef _log(v):\n    if v <= 0:\n        raise _EvalError(\"log 的参数必须大于 0\")\n    return math.log(v)\n\n\ndef _exp(v):\n    try:\n        return math.exp(v)\n    except OverflowError:\n        raise _EvalError(\"exp 的结果太大\")\n\n\n_FUNCS = {\n    \"sum\": sum, \"min\": min, \"max\": max, \"abs\": abs, \"len\": len, \"sorted\": sorted,\n    \"round\": round, \"float\": float, \"int\": int, \"any\": any, \"all\": all,\n    \"sqrt\": _sqrt, \"exp\": _exp, \"log\": _log, \"sin\": math.sin, \"cos\": math.cos,\n    \"floor\": math.floor, \"ceil\": math.ceil, \"zip\": zip, \"enumerate\": enumerate,\n    \"range\": None,  # 在 UPObjective 里换成带上限的版本\n}\n_CONSTS = {\"pi\": math.pi, \"e\": math.e, \"True\": True, \"False\": False}\n_RESERVED = set(_FUNCS) | set(_CONSTS) | {\"x\", \"n\", \"objective\", \"lo\", \"hi\"}\n\n_BINOPS = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow)\n_UNOPS = (ast.UAdd, ast.USub, ast.Not)\n_CMPOPS = (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)\n_BOOLOPS = (ast.And, ast.Or)\n\n_NAME_RE = re.compile(r\"^[A-Za-z][A-Za-z0-9_]*$\")\n\n\ndef _suggest(name, names):\n    near = difflib.get_close_matches(name, sorted(names), n=2, cutoff=0.6)\n    return f\"（你是不是想写 {' 或 '.join(near)}？）\" if near else \"\"\n\n\n# ------------------------------------------------------------------ 静态检查\n\nclass _Checker(ast.NodeVisitor):\n    def __init__(self, names):\n        self.scope = [set(names)]\n        self.assigned = []\n        self.nodes = 0\n        self.depth = 0  # 推导式嵌套深度\n\n    def _all(self):\n        out = set()\n        for s in self.scope:\n            out |= s\n        return out\n\n    def fail(self, node, msg):\n        ln = getattr(node, \"lineno\", None)\n        raise UPError(\"objective\", (f\"第 {ln} 行：\" if ln else \"\") + msg)\n\n    def generic_visit(self, node):\n        self.nodes += 1\n        if self.nodes > UP_LIMITS[\"nodes\"]:\n            raise UPError(\"objective\", \"表达式太长太复杂（超过 %d 个语法节点），请拆简单一些\" % UP_LIMITS[\"nodes\"])\n        ast.NodeVisitor.generic_visit(self, node)\n\n    # ---- 语句\n    def visit_Module(self, node):\n        if len(node.body) > UP_LIMITS[\"stmts\"]:\n            raise UPError(\"objective\", \"语句太多（最多 %d 条）\" % UP_LIMITS[\"stmts\"])\n        for i, st in enumerate(node.body):\n            last = i == len(node.body) - 1\n            if isinstance(st, ast.Assign):\n                self.visit(st)\n            elif isinstance(st, ast.Expr) and last:\n                self.visit(st.value)\n                self.assigned.append(\"objective\")\n            else:\n                self.fail(st, \"只允许「名字 = 表达式」的赋值，最后一行可以直接写一个表达式作为目标值\"\n                              \"（不支持 %s）\" % type(st).__name__)\n        if \"objective\" not in self.assigned:\n            raise UPError(\"objective\", \"没有给出目标值：请写 objective = …，或让最后一行就是一个表达式\")\n\n    def visit_Assign(self, node):\n        if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):\n            self.fail(node, \"赋值左边只能是一个名字\")\n        name = node.targets[0].id\n        if name.startswith(\"_\"):\n            self.fail(node, \"名字不能以下划线开头\")\n        if name in _RESERVED - {\"objective\"} or name in self.scope[0] - set(self.assigned) and name != \"objective\":\n            self.fail(node, f\"名字 {name} 已被占用（x、n、数据表名和内置函数不能重新赋值）\")\n        self.visit(node.value)\n        self.assigned.append(name)\n        self.scope[0].add(name)\n\n    # ---- 表达式\n    def visit_Constant(self, node):\n        if isinstance(node.value, bool) or isinstance(node.value, (int, float)):\n            return\n        self.fail(node, \"只允许数字和 True/False（不允许字符串等其它常量）\")\n\n    def visit_Name(self, node):\n        if not isinstance(node.ctx, ast.Load):\n            self.fail(node, \"不允许在表达式里给名字赋值\")\n        if node.id.startswith(\"_\"):\n            self.fail(node, \"名字不能以下划线开头\")\n        if node.id not in self._all():\n            self.fail(node, f\"没有叫 {node.id} 的变量{_suggest(node.id, self._all() - _RESERVED | {'x', 'n'})}。\"\n                            f\"可用：{', '.join(sorted(self._all() - set(_FUNCS) - set(_CONSTS)))}\")\n\n    def visit_BinOp(self, node):\n        if not isinstance(node.op, _BINOPS):\n            self.fail(node, \"不支持这个运算符；可用 + - * / // % **\")\n        self.generic_visit(node)\n\n    def visit_UnaryOp(self, node):\n        if not isinstance(node.op, _UNOPS):\n            self.fail(node, \"不支持这个一元运算符\")\n        self.generic_visit(node)\n\n    def visit_BoolOp(self, node):\n        self.generic_visit(node)\n\n    def visit_Compare(self, node):\n        if not all(isinstance(o, _CMPOPS) for o in node.ops):\n            self.fail(node, \"比较只支持 == != < <= > >=（不支持 in / is）\")\n        self.generic_visit(node)\n\n    def visit_IfExp(self, node):\n        self.generic_visit(node)\n\n    def visit_Subscript(self, node):\n        if not isinstance(node.ctx, ast.Load):\n            self.fail(node, \"不允许对下标赋值（目标函数只能读 x 和数据，不能修改）\")\n        self.generic_visit(node)\n\n    def visit_Slice(self, node):\n        self.generic_visit(node)\n\n    def visit_List(self, node):\n        self.generic_visit(node)\n\n    def visit_Tuple(self, node):\n        self.generic_visit(node)\n\n    def visit_Call(self, node):\n        if not isinstance(node.func, ast.Name) or node.func.id not in _FUNCS:\n            self.fail(node, \"只能调用这些函数：\" + \"、\".join(sorted(_FUNCS)))\n        if node.keywords:\n            self.fail(node, \"函数调用不支持 名字=值 形式的参数\")\n        for a in node.args:\n            if isinstance(a, ast.Starred):\n                self.fail(node, \"不支持 *参数 展开\")\n        self.nodes += 1\n        for a in node.args:\n            self.visit(a)\n\n    def _comp(self, node):\n        # 循环层数 = 推导式嵌套层数 + 同一个推导式里 for 的个数；最多两层（运行期还有迭代预算兜底）\n        levels = len(node.generators)\n        self.depth += levels\n        if self.depth > 2:\n            self.fail(node, \"循环最多嵌套两层（推导式里的每个 for、以及推导式套推导式，都算一层）\")\n        self.scope.append(set())\n        for gen in node.generators:\n            if gen.is_async:\n                self.fail(node, \"不支持 async\")\n            self.visit(gen.iter)\n            tgt = gen.target\n            names = [tgt] if isinstance(tgt, ast.Name) else (list(tgt.elts) if isinstance(tgt, ast.Tuple) else None)\n            if names is None or not all(isinstance(t, ast.Name) for t in names):\n                self.fail(node, \"for 后面只能是名字或名字元组\")\n            for t in names:\n                if t.id.startswith(\"_\") or t.id in _RESERVED:\n                    self.fail(node, f\"循环变量名 {t.id} 不可用\")\n                self.scope[-1].add(t.id)\n            for cond in gen.ifs:\n                self.visit(cond)\n        elts = [node.elt]\n        for e in elts:\n            self.visit(e)\n        self.scope.pop()\n        self.depth -= levels\n\n    def visit_ListComp(self, node):\n        self._comp(node)\n\n    def visit_GeneratorExp(self, node):\n        self._comp(node)\n\n    # 其余一律拒绝：属性访问、lambda、字符串、f-string、字典/集合、walrus、await、yield …\n    def visit_Attribute(self, node):\n        self.fail(node, \"不允许用 .（属性访问）；需要的函数直接写名字，如 sqrt(v)、abs(v)\")\n\n    def visit_Lambda(self, node):\n        self.fail(node, \"不支持 lambda\")\n\n    def visit_JoinedStr(self, node):\n        self.fail(node, \"不支持 f 字符串\")\n\n    def visit_Dict(self, node):\n        self.fail(node, \"不支持字典；数据表请放在数据里，用 名字[下标] 读取\")\n\n    def visit_Set(self, node):\n        self.fail(node, \"不支持集合\")\n\n    def visit_DictComp(self, node):\n        self.fail(node, \"不支持字典推导式\")\n\n    def visit_SetComp(self, node):\n        self.fail(node, \"不支持集合推导式\")\n\n    def visit_NamedExpr(self, node):\n        self.fail(node, \"不支持 :=\")\n\n    def visit_Starred(self, node):\n        self.fail(node, \"不支持 * 展开\")\n\n\nclass _Rewriter(ast.NodeTransformer):\n    \"\"\"检查通过后做运行期加固：整数幂 / 序列重复 / 推导式迭代量计数。\"\"\"\n\n    def visit_BinOp(self, node):\n        self.generic_visit(node)\n        if isinstance(node.op, ast.Pow):\n            return ast.copy_location(ast.Call(ast.Name(\"_pow\", ast.Load()), [node.left, node.right], []), node)\n        if isinstance(node.op, ast.Mult):\n            return ast.copy_location(ast.Call(ast.Name(\"_mul\", ast.Load()), [node.left, node.right], []), node)\n        return node\n\n    def visit_comprehension(self, node):\n        self.generic_visit(node)\n        node.iter = ast.Call(ast.Name(\"_it\", ast.Load()), [node.iter], [])\n        return node\n\n\ndef compile_expression(src, data_names):\n    \"\"\"静态检查 + 加固 + 编译。返回 (code, 赋值过的名字)。不合格抛 UPError（带行号的中文消息）。\"\"\"\n    if not isinstance(src, str) or not src.strip():\n        raise UPError(\"objective\", \"目标函数是空的\")\n    if len(src) > UP_LIMITS[\"src_chars\"]:\n        raise UPError(\"objective\", \"目标函数太长（最多 %d 个字符）\" % UP_LIMITS[\"src_chars\"])\n    try:\n        tree = ast.parse(src, mode=\"exec\")\n    except SyntaxError as e:\n        raise UPError(\"objective\", f\"第 {e.lineno} 行语法错误：{e.msg}\")\n    chk = _Checker(set(data_names) | {\"x\", \"n\"} | set(_FUNCS) | set(_CONSTS))\n    chk.visit(tree)\n    # 最后一行是裸表达式：改写成 objective = <expr>\n    last = tree.body[-1]\n    if isinstance(last, ast.Expr):\n        tree.body[-1] = ast.copy_location(ast.Assign([ast.Name(\"objective\", ast.Store())], last.value), last)\n    tree = _Rewriter().visit(tree)\n    ast.fix_missing_locations(tree)\n    return compile(tree, \"<目标函数>\", \"exec\"), chk.assigned\n\n\n# ------------------------------------------------------------------ 可调用的目标函数\n\nclass UPObjective:\n    \"\"\"f(x) -> float。L1 表达式（默认）或本地 Python 函数（enable_python 之后）。\"\"\"\n\n    def __init__(self, problem):\n        self.n = problem[\"n\"]\n        self.data = problem.get(\"data\", {})\n        self._budget = 0\n        if problem.get(\"objective_python\"):\n            if not _PY_ENABLED:\n                raise UPError(\"objective_python\", \"本地 Python 目标函数只在命令行里可用（--objective-py），浏览器里不开放\")\n            ns = {\"math\": math, \"random\": random}\n            try:\n                exec(compile(problem[\"objective_python\"], \"<objective_python>\", \"exec\"), ns)\n            except Exception as e:  # noqa: BLE001\n                raise UPError(\"objective_python\", f\"{type(e).__name__}: {e}\")\n            if not callable(ns.get(\"objective\")):\n                raise UPError(\"objective_python\", \"代码里需要定义 def objective(x, data): …\")\n            self._pyf = ns[\"objective\"]\n            self._code = None\n            return\n        self._pyf = None\n        self._code, _ = compile_expression(problem.get(\"objective\"), self.data)\n        self._base = dict(self.data)\n        self._base.update(_CONSTS)\n        self._base.update(_FUNCS)\n        self._base[\"n\"] = self.n\n        self._base[\"_pow\"] = self._pow\n        self._base[\"_mul\"] = self._mul\n        self._base[\"_it\"] = self._it\n        self._base[\"range\"] = self._range\n        self._base[\"__builtins__\"] = {}  # 检查过的表达式本来就够不到内置名字；这里再关一道\n\n    # ---- 运行期加固\n    def _pow(self, a, b):\n        if isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):\n            raise _EvalError(\"不能对序列做乘方\")\n        if isinstance(a, int) and isinstance(b, int) and not isinstance(a, bool):\n            if b > UP_LIMITS[\"pow_exp\"] or b < 0:\n                a = float(a)\n        try:\n            r = a ** b\n        except OverflowError:\n            raise _EvalError(\"乘方的结果太大\")\n        except ZeroDivisionError:\n            raise _EvalError(\"0 不能做负数次幂\")\n        if isinstance(r, int) and r.bit_length() > UP_LIMITS[\"int_bits\"]:\n            raise _EvalError(\"整数太大（连续平方 / 乘方会让整数无限膨胀）\")\n        return r\n\n    def _mul(self, a, b):\n        if isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):\n            raise _EvalError(\"不支持用 * 重复序列；请用推导式，如 [0 for i in range(n)]\")\n        if isinstance(a, int) and isinstance(b, int) and a.bit_length() + b.bit_length() > UP_LIMITS[\"int_bits\"]:\n            raise _EvalError(\"整数太大（连续相乘会让整数无限膨胀）\")\n        return a * b\n\n    def _it(self, iterable):\n        for item in iterable:\n            self._budget -= 1\n            if self._budget < 0:\n                raise _EvalError(\"一次评价里循环太多（超过 %d 次迭代），请简化目标函数\" % UP_LIMITS[\"iter_budget\"])\n            yield item\n\n    def _range(self, *args):\n        r = range(*[int(a) for a in args])\n        if len(r) > UP_LIMITS[\"range_cap\"]:\n            raise _EvalError(\"range 太大（最多 %d）\" % UP_LIMITS[\"range_cap\"])\n        return r\n\n    def __call__(self, x):\n        if self._pyf is not None:\n            try:\n                v = self._pyf(x, self.data)\n            except Exception as e:  # noqa: BLE001\n                raise _EvalError(f\"{type(e).__name__}: {e}\")\n        else:\n            env = dict(self._base)\n            env[\"x\"] = x\n            self._budget = UP_LIMITS[\"iter_budget\"]\n            try:\n                exec(self._code, env)\n            except _EvalError:\n                raise\n            except ZeroDivisionError:\n                raise _EvalError(\"除以 0\")\n            except IndexError:\n                raise _EvalError(\"下标越界（x 或数据表的下标超出了长度）\")\n            except (TypeError, ValueError, OverflowError, KeyError) as e:\n                raise _EvalError(f\"{type(e).__name__}: {e}\")\n            v = env.get(\"objective\")\n        if isinstance(v, bool):\n            v = int(v)\n        if not isinstance(v, (int, float)):\n            raise _EvalError(f\"目标值应该是一个数字，算出来的是 {type(v).__name__}\")\n        v = float(v)\n        if not math.isfinite(v):\n            raise _EvalError(\"目标值不是有限的数（nan 或 inf）\")\n        return v\n\n\n# ------------------------------------------------------------------ 编码上下文（与内核约定的协议）\n\nclass _UPBase:\n    def __init__(self, problem):\n        self.problem = problem\n        self.n = problem[\"n\"]\n        self.f = UPObjective(problem)\n        self.sign = -1.0 if problem.get(\"sense\") == \"max\" else 1.0\n        self.best_val = float(\"inf\")   # 内部值（最小化口径）\n        self.best_x = None\n        self.n_err = 0\n        self.first_err = \"\"\n\n    def _score(self, x):\n        try:\n            v = self.sign * self.f(x)\n        except _EvalError as e:\n            self.n_err += 1\n            if not self.first_err:\n                self.first_err = str(e)\n            return PENALTY\n        if v < self.best_val:\n            self.best_val = v\n            self.best_x = list(x)\n        return v\n\n\nclass UPBits(_UPBase):\n    \"\"\"位向量：与 QUBO 上下文同一套协议（obj / value / polish / repair / random / init_pop）。\"\"\"\n\n    def obj(self, s):\n        return self._score(s)\n\n    def value(self, s):\n        return -self.obj(s)\n\n    def polish(self, s, rng, moves=10):\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            v = self.value(s)\n            if v >= best:\n                best = v\n            else:\n                s = prev\n        return s\n\n    def repair(self, s):\n        return list(s)\n\n    def random(self, rng):\n        return [rng.randint(0, 1) for _ in range(self.n)]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\nclass UPPerm(_UPBase):\n    \"\"\"排列：与装箱 / 着色上下文同一套协议（decode / solution / better / diff / random）。\"\"\"\n\n    def decode(self, perm):\n        return (self._score(perm), 0.0)  # 排列内核约定 decode 返回 (主指标, 次级指标) 元组；自定义问题没有次级指标\n\n    def solution(self, perm):\n        return list(perm)\n\n    def better(self, a, b):\n        return a[0] < b[0]\n\n    def diff(self, a, b):\n        return b[0] - a[0]\n\n    def random(self, rng):\n        p = list(range(self.n))\n        rng.shuffle(p)\n        return p\n\n\nclass UPReal(_UPBase):\n    \"\"\"实数向量：与连续函数上下文同一套协议（dim / lo / hi / random / eval / clamp / init_pop）。\"\"\"\n\n    def __init__(self, problem):\n        _UPBase.__init__(self, problem)\n        self.dim = self.n\n        self.lo = float(problem[\"lo\"])\n        self.hi = float(problem[\"hi\"])\n\n    def random(self, rng):\n        return [rng.uniform(self.lo, self.hi) for _ in range(self.dim)]\n\n    def eval(self, x):\n        return self._score(x)\n\n    def clamp(self, x):\n        return [min(self.hi, max(self.lo, v)) for v in x]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.eval(x) for x in pop]\n\n\n_CTX = {\"bits\": UPBits, \"perm\": UPPerm, \"real\": UPReal}\n\n\ndef up_make_ctx(problem):\n    return _CTX[problem[\"variant\"]](problem)\n\n\ndef up_wrap_stream(gen, ctx):\n    \"\"\"把内核吐出的状态整理成页面 / 命令行统一的样子：\n    以评价过的全部点里最好的那个为准（有的内核不把预热 / 初始化阶段评价过的点算进「最优」，上报值就会比实际找到的差）；\n    内部一律最小化，sense=max 时把 best / cur 翻回用户的口径；补上完整的最优解和出错统计。\"\"\"\n    for s in gen:\n        if ctx.best_x is not None and ctx.best_val < s.get(\"best\", float(\"inf\")):\n            s[\"best\"] = ctx.best_val\n        if ctx.sign < 0:\n            for k in (\"best\", \"cur\"):\n                if isinstance(s.get(k), (int, float)):\n                    s[k] = -s[k]\n        if ctx.best_x is not None:\n            s[\"best_sol\"] = list(ctx.best_x)\n        if ctx.n_err:\n            s[\"eval_errors\"] = ctx.n_err\n            s[\"first_error\"] = ctx.first_err\n        yield s\n\n\n# ------------------------------------------------------------------ 校验 / 规整 / 试跑\n\ndef _flat_cells(v, depth=0):\n    if isinstance(v, bool):\n        return None\n    if isinstance(v, (int, float)):\n        return 1 if math.isfinite(v) else None\n    if isinstance(v, list) and depth < 3 and v:\n        total = 0\n        for e in v:\n            c = _flat_cells(e, depth + 1)\n            if c is None:\n                return None\n            total += c\n        return total\n    return None\n\n\ndef up_check(problem, dry_runs=_DRY_RUNS):\n    \"\"\"校验并规整一个自带问题。返回 (规整后的 problem 或 None, errors, warnings, info)，\n    errors / warnings 是 [{\"path\", \"msg\"}]，info 里有试跑测得的单次评价耗时（毫秒）。\"\"\"\n    errors, warnings, info = [], [], {}\n\n    def err(path, msg):\n        errors.append({\"path\": path, \"msg\": msg})\n\n    if not isinstance(problem, dict):\n        err(\"\", \"自带问题应为 JSON 对象（花括号）\")\n        return None, errors, warnings, info\n    variant = problem.get(\"variant\", problem.get(\"encoding\"))\n    if variant not in ENCODINGS:\n        err(\"variant\", f\"需要指定编码 variant：{' / '.join(ENCODINGS)}（bits=是/否，perm=排序，real=实数），收到 {variant!r}\")\n        return None, errors, warnings, info\n    n = problem.get(\"n\")\n    if isinstance(n, float) and n.is_integer():\n        n = int(n)\n    if not isinstance(n, int) or isinstance(n, bool) or n < 2:\n        err(\"n\", f\"n（解的长度 / 维度）应为 ≥ 2 的整数，收到 {n!r}\")\n    elif n > UP_LIMITS[variant]:\n        err(\"n\", f\"{variant} 编码的 n 最多 {UP_LIMITS[variant]}（浏览器内运行的规模上限），收到 {n}\")\n    sense = problem.get(\"sense\", \"min\")\n    if sense not in (\"min\", \"max\"):\n        err(\"sense\", f\"sense 应为 min（越小越好）或 max（越大越好），收到 {sense!r}\")\n    out = {\"variant\": variant, \"n\": n, \"sense\": sense}\n    if variant == \"real\":\n        lo, hi = problem.get(\"lo\"), problem.get(\"hi\")\n        if not all(isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) for v in (lo, hi)):\n            err(\"lo\", \"real 编码需要数值范围 lo 和 hi（所有维度共用）\")\n        elif not lo < hi:\n            err(\"lo\", f\"需要 lo < hi，收到 lo={lo}, hi={hi}\")\n        else:\n            out[\"lo\"], out[\"hi\"] = lo, hi\n    data = problem.get(\"data\", {})\n    clean = {}\n    if not isinstance(data, dict):\n        err(\"data\", \"data 应为对象：数据表名 → 数字或（嵌套）数字数组\")\n    else:\n        cells = 0\n        for k, v in data.items():\n            if not isinstance(k, str) or not _NAME_RE.match(k):\n                err(f\"data.{k}\", \"数据名只能由字母、数字、下划线组成，并以字母开头\")\n            elif k in _RESERVED:\n                err(f\"data.{k}\", f\"数据名 {k} 与内置名字冲突（x / n / lo / hi / objective / 函数名不能用）\")\n            else:\n                c = _flat_cells(v)\n                if c is None:\n                    err(f\"data.{k}\", \"只能是数字，或最多三层嵌套的数字数组（不能有字符串 / null / 空数组 / nan）\")\n                else:\n                    cells += c\n                    clean[k] = v\n        if cells > UP_LIMITS[\"data_cells\"]:\n            err(\"data\", f\"数据总量太大（{cells} 个数，上限 {UP_LIMITS['data_cells']}）\")\n    out[\"data\"] = clean\n    known = {\"variant\", \"encoding\", \"n\", \"sense\", \"lo\", \"hi\", \"data\", \"objective\", \"objective_python\", \"schema\"}\n    for k in problem:\n        if k not in known:\n            warnings.append({\"path\": k, \"msg\": \"未知字段，已忽略\"})\n    if problem.get(\"objective_python\"):\n        out[\"objective_python\"] = problem[\"objective_python\"]\n    else:\n        out[\"objective\"] = problem.get(\"objective\")\n    if errors:\n        return None, errors, warnings, info\n    try:\n        ctx = up_make_ctx(out)\n    except UPError as e:\n        err(e.path, e.msg)\n        return None, errors, warnings, info\n    # ---- 试跑：随机解上求值\n    rng = random.Random(20260711)\n    xs = [ctx.random(rng) for _ in range(dry_runs)]\n    if variant == \"bits\":\n        xs += [[0] * n, [1] * n]\n    vals, bad = [], {}\n    t0 = time.time()\n    for x in xs:\n        try:\n            vals.append(ctx.f(x))\n        except _EvalError as e:\n            bad[str(e)] = bad.get(str(e), 0) + 1\n    per_ms = (time.time() - t0) * 1000.0 / len(xs)\n    info[\"eval_ms\"] = round(per_ms, 4)\n    if bad and not vals:\n        msg, cnt = max(bad.items(), key=lambda kv: kv[1])\n        err(\"objective\", f\"目标函数在所有 {len(xs)} 个随机解上都出错：{msg}\")\n        return None, errors, warnings, info\n    if bad:\n        msg, cnt = max(bad.items(), key=lambda kv: kv[1])\n        warnings.append({\"path\": \"objective\", \"msg\": f\"{len(xs)} 个随机解里有 {sum(bad.values())} 个让目标函数出错（{msg}）；\"\n                                                     f\"运行时这类解会被当作极差的解，但最好在函数里把它们处理掉\"})\n    if len(set(vals)) == 1:\n        err(\"objective\", f\"所有随机解的目标值都一样（{vals[0]}）——没有东西可优化。检查是否漏用了 x，或惩罚项是否压倒了一切\")\n        return None, errors, warnings, info\n    if per_ms > 5:\n        warnings.append({\"path\": \"objective\", \"msg\": f\"每次评价约 {per_ms:.1f} 毫秒；种群类算法每代要评价几十次，\"\n                                                     f\"浏览器里还会慢约 2 倍，建议先把迭代次数调小\"})\n    return out, errors, warnings, info\n\n\ndef up_auto_params(ctx, user_keys):\n    \"\"\"用户的目标函数量级未知，而内核里的温度 t0（模拟退火等）和步长 sigma（连续域）是按内置问题标定的绝对值。\n    这里按随机解上目标值的离散程度 / 取值范围换算；用户显式给了的参数不动。\"\"\"\n    rng = random.Random(97)\n    vals = []\n    for _ in range(24):\n        x = ctx.random(rng)\n        try:\n            vals.append(ctx.sign * ctx.f(x))\n        except _EvalError:\n            pass\n    out = {}\n    if len(vals) >= 2 and \"t0\" not in user_keys:\n        mu = sum(vals) / len(vals)\n        sd = math.sqrt(sum((v - mu) ** 2 for v in vals) / len(vals))\n        if sd > 0:\n            out[\"t0\"] = sd * 0.5\n    if getattr(ctx, \"lo\", None) is not None and \"sigma\" not in user_keys:\n        out[\"sigma\"] = 0.06 * (ctx.hi - ctx.lo)\n    return out\n\n\n# ------------------------------------------------------------------ 内置示例（每种编码一个，也是文档里的范例）\n\ndef up_preset(variant=\"bits\", n=None, seed=7):\n    rng = random.Random(seed)\n    if variant == \"bits\":\n        n = int(n or 30)\n        value = [rng.randint(5, 60) for _ in range(n)]\n        cost = [rng.randint(3, 30) for _ in range(n)]\n        return {\n            \"variant\": \"bits\", \"n\": n, \"sense\": \"max\",\n            \"data\": {\"value\": value, \"cost\": cost, \"budget\": sum(cost) // 3},\n            \"objective\": (\"gain = sum(value[i] * x[i] for i in range(n))\\n\"\n                          \"spend = sum(cost[i] * x[i] for i in range(n))\\n\"\n                          \"objective = gain - 20 * max(0, spend - budget)\"),\n        }\n    if variant == \"perm\":\n        n = int(n or 12)\n        p = [rng.randint(1, 9) for _ in range(n)]\n        total = sum(p)\n        d = [rng.randint(total // 4, total) for _ in range(n)]\n        w = [rng.randint(1, 5) for _ in range(n)]\n        return {\n            \"variant\": \"perm\", \"n\": n, \"sense\": \"min\",\n            \"data\": {\"p\": p, \"d\": d, \"w\": w},\n            \"objective\": (\"sum(w[x[k]] * max(0, sum(p[x[j]] for j in range(k + 1)) - d[x[k]]) \"\n                          \"for k in range(n))\"),\n        }\n    if variant == \"real\":\n        # 曲线拟合：y ≈ a·exp(b·t) + c。x = [a, b, c]，目标 = 平方误差和（真值 a=2, b=-0.7, c=0.5，带一点噪声）\n        t = [round(0.5 * i, 2) for i in range(14)]\n        y = [round(2.0 * math.exp(-0.7 * ti) + 0.5 + rng.uniform(-0.05, 0.05), 4) for ti in t]\n        return {\n            \"variant\": \"real\", \"n\": 3, \"sense\": \"min\", \"lo\": -5, \"hi\": 5,\n            \"data\": {\"t\": t, \"y\": y},\n            \"objective\": \"sum((x[0] * exp(x[1] * t[i]) + x[2] - y[i]) ** 2 for i in range(len(t)))\",\n        }\n    raise ValueError(variant)\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\n连续多目标基准（ZDT / DTLZ）：决策变量是实数向量，目标一律「越小越好」，有解析的真 Pareto 前沿，\n所以能算 IGD（到真前沿的平均距离）和超体积 HV——这是多目标算法比较的标准做法。\n\n与 domains.py 里的「多目标背包」（位编码、最大化、没有真前沿）是两回事，所以单独成域 mocont：\n    变体 zdt1 zdt2 zdt3 zdt4 zdt5（位串）zdt6（双目标）、dtlz1 … dtlz7（三目标）\n    算法 random（随机基线）/ wsga（加权和 GA，对照：非凸前沿会漏）/ nsga2 / moead（Tchebycheff + 差分，Li & Zhang 2009）\n状态里：pop=当代种群的目标值，front=当代非支配解，igd/hv 是当代前沿的指标，best=到当前为止最好的 IGD（只降不升）。\n\n纯标准库。浏览器里本文件与 domains.py 拼进同一名字空间（同 entryseq.py 的做法）：顶层名字不得与其它模块重名。\n参考：Zitzler, Deb & Thiele (2000) Evolutionary Computation 8(2):173-195（ZDT）；\n      Deb, Thiele, Laumanns & Zitzler (2005) 在 Evolutionary Multiobjective Optimization 中（DTLZ）。\n\"\"\"\nimport math\nimport random\n\nMOC_VARIANTS = (\"zdt1\", \"zdt2\", \"zdt3\", \"zdt4\", \"zdt5\", \"zdt6\", \"dtlz1\", \"dtlz2\", \"dtlz3\", \"dtlz4\", \"dtlz5\", \"dtlz6\", \"dtlz7\")\nMOC_BITS = (\"zdt5\",)          # 位串编码的变体（其余都是实数向量）\nMOC_SCALE = {\"zdt5\": [31.0, 10.0]}  # ZDT5 的两个目标量级差很大（f1 在 1..31，f2 在 0.3..10）：MOEA/D 的 Tchebycheff 要先按目标范围归一化；其余变体各目标量级相近，不缩放\nMOC_NFIX = {\"zdt5\": 11}       # 决策变量个数固定的变体：ZDT5 的真前沿 f2 = (n-1)/f1 依赖 n，按论文取 11（第 1 变量 30 位，其余 10 个变量各 5 位）\n\n\n# ------------------------------------------------------------------ 测试函数（最小化）\n\ndef _zdt_g(x):\n    return 1.0 + 9.0 * sum(x[1:]) / (len(x) - 1)\n\n\ndef _f_zdt1(x):\n    g = _zdt_g(x)\n    return [x[0], g * (1.0 - math.sqrt(x[0] / g))]\n\n\ndef _f_zdt2(x):\n    g = _zdt_g(x)\n    return [x[0], g * (1.0 - (x[0] / g) ** 2)]\n\n\ndef _f_zdt3(x):\n    g = _zdt_g(x)\n    r = x[0] / g\n    return [x[0], g * (1.0 - math.sqrt(r) - r * math.sin(10.0 * math.pi * x[0]))]\n\n\ndef _f_zdt4(x):\n    g = 1.0 + 10.0 * (len(x) - 1) + sum(v * v - 10.0 * math.cos(4.0 * math.pi * v) for v in x[1:])\n    return [x[0], g * (1.0 - math.sqrt(x[0] / g))]\n\n\ndef _f_zdt6(x):\n    f1 = 1.0 - math.exp(-4.0 * x[0]) * math.sin(6.0 * math.pi * x[0]) ** 6\n    g = 1.0 + 9.0 * (sum(x[1:]) / (len(x) - 1)) ** 0.25\n    return [f1, g * (1.0 - (f1 / g) ** 2)]\n\n\ndef _f_dtlz1(x):\n    k = len(x) - 2\n    g = 100.0 * (k + sum((v - 0.5) ** 2 - math.cos(20.0 * math.pi * (v - 0.5)) for v in x[2:]))\n    return [0.5 * x[0] * x[1] * (1.0 + g), 0.5 * x[0] * (1.0 - x[1]) * (1.0 + g), 0.5 * (1.0 - x[0]) * (1.0 + g)]\n\n\ndef _f_dtlz2(x):\n    g = sum((v - 0.5) ** 2 for v in x[2:])\n    c = math.pi / 2.0\n    return [(1.0 + g) * math.cos(x[0] * c) * math.cos(x[1] * c),\n            (1.0 + g) * math.cos(x[0] * c) * math.sin(x[1] * c),\n            (1.0 + g) * math.sin(x[0] * c)]\n\n\ndef _f_zdt5(x):\n    \"\"\"ZDT5（位串）：x 是 30 + 5(n-1) 个 0/1。f1 = 1 + 第一段里 1 的个数，g = Σ v(其余各 5 位里 1 的个数)，\n    v(u) = 2 + u（u < 5），v(5) = 1；f2 = g / f1。欺骗性：全 0 的段 v=2 很诱人，最优却是全 1（v=1）。\"\"\"\n    f1 = 1.0 + sum(x[:30])\n    g = 0.0\n    for i in range(30, len(x), 5):\n        u = sum(x[i:i + 5])\n        g += 2.0 + u if u < 5 else 1.0\n    return [f1, g / f1]\n\n\ndef _dtlz_sphere(g, a1, a2):\n    return [(1.0 + g) * math.cos(a1) * math.cos(a2), (1.0 + g) * math.cos(a1) * math.sin(a2), (1.0 + g) * math.sin(a1)]\n\n\ndef _f_dtlz3(x):\n    # g 同 DTLZ1（Rastrigin 式，3^k - 1 个局部前沿），形状同 DTLZ2（球面）\n    k = len(x) - 2\n    g = 100.0 * (k + sum((v - 0.5) ** 2 - math.cos(20.0 * math.pi * (v - 0.5)) for v in x[2:]))\n    c = math.pi / 2.0\n    return _dtlz_sphere(g, x[0] * c, x[1] * c)\n\n\ndef _f_dtlz4(x):\n    # 同 DTLZ2，但 x 被 x^100 压缩：解在目标空间里极不均匀地挤向 f3 = 0 的面（考多样性维护）\n    g = sum((v - 0.5) ** 2 for v in x[2:])\n    c = math.pi / 2.0\n    return _dtlz_sphere(g, (x[0] ** 100) * c, (x[1] ** 100) * c)\n\n\ndef _f_dtlz5(x):\n    # 前沿退化成一条曲线（f1 = f2）：第二个角度由 g 控制，g = 0 时恒为 π/4\n    g = sum((v - 0.5) ** 2 for v in x[2:])\n    t2 = math.pi / (4.0 * (1.0 + g)) * (1.0 + 2.0 * g * x[1])\n    return _dtlz_sphere(g, x[0] * math.pi / 2.0, t2)\n\n\ndef _f_dtlz6(x):\n    # 同 DTLZ5，但 g = Σ x^0.1：g 在 0 附近极其陡，收敛很难\n    g = sum(v ** 0.1 for v in x[2:])\n    t2 = math.pi / (4.0 * (1.0 + g)) * (1.0 + 2.0 * g * x[1])\n    return _dtlz_sphere(g, x[0] * math.pi / 2.0, t2)\n\n\ndef _dtlz7_f3(f1, f2, g):\n    h = 3.0 - sum(f / (1.0 + g) * (1.0 + math.sin(3.0 * math.pi * f)) for f in (f1, f2))\n    return (1.0 + g) * h\n\n\ndef _f_dtlz7(x):\n    k = len(x) - 2\n    g = 1.0 + 9.0 / k * sum(x[2:])\n    return [x[0], x[1], _dtlz7_f3(x[0], x[1], g)]\n\n\n# 变体 → (名称, 目标数, 默认维数, 最小维数, 每维取值范围函数, 目标函数, HV 参考点)\ndef _unit(n):\n    return [(0.0, 1.0)] * n\n\n\ndef _zdt5_bounds(n):\n    return [(0, 1)] * (30 + 5 * (n - 1))\n\n\ndef _zdt4_bounds(n):\n    return [(0.0, 1.0)] + [(-5.0, 5.0)] * (n - 1)\n\n\nMOC_SPEC = {\n    \"zdt1\": (\"ZDT1（凸前沿）\", 2, 30, 2, _unit, _f_zdt1, [1.1, 1.1]),\n    \"zdt2\": (\"ZDT2（非凸前沿）\", 2, 30, 2, _unit, _f_zdt2, [1.1, 1.1]),\n    \"zdt3\": (\"ZDT3（不连续前沿）\", 2, 30, 2, _unit, _f_zdt3, [1.1, 1.1]),\n    \"zdt4\": (\"ZDT4（多峰：21^9 个局部前沿）\", 2, 10, 2, _zdt4_bounds, _f_zdt4, [1.1, 1.1]),\n    \"zdt5\": (\"ZDT5（位串编码的欺骗问题）\", 2, 11, 2, _zdt5_bounds, _f_zdt5, [32.0, 11.0]),\n    \"zdt6\": (\"ZDT6（前沿偏斜、解密度不均）\", 2, 10, 2, _unit, _f_zdt6, [1.1, 1.1]),\n    \"dtlz1\": (\"DTLZ1（三目标线性前沿，多峰）\", 3, 7, 3, _unit, _f_dtlz1, [0.6, 0.6, 0.6]),\n    \"dtlz2\": (\"DTLZ2（三目标球面前沿）\", 3, 12, 3, _unit, _f_dtlz2, [1.1, 1.1, 1.1]),\n    \"dtlz3\": (\"DTLZ3（球面前沿 + 3^k-1 个局部前沿）\", 3, 12, 3, _unit, _f_dtlz3, [1.1, 1.1, 1.1]),\n    \"dtlz4\": (\"DTLZ4（球面前沿，解密度极不均）\", 3, 12, 3, _unit, _f_dtlz4, [1.1, 1.1, 1.1]),\n    \"dtlz5\": (\"DTLZ5（前沿退化成曲线）\", 3, 12, 3, _unit, _f_dtlz5, [1.1, 1.1, 1.1]),\n    \"dtlz6\": (\"DTLZ6（退化曲线 + 难收敛）\", 3, 12, 3, _unit, _f_dtlz6, [1.1, 1.1, 1.1]),\n    \"dtlz7\": (\"DTLZ7（4 块不连通前沿）\", 3, 22, 3, _unit, _f_dtlz7, [1.1, 1.1, 7.0]),\n}\n\n\ndef mc_make(variant=\"zdt1\", n=None, seed=7):\n    \"\"\"实例 = 变体 + 决策变量个数（这些基准函数是确定的，没有随机实例；seed 只给算法用）。\"\"\"\n    if variant not in MOC_SPEC:\n        raise ValueError(variant)\n    _name, m, n_def, n_min, _b, _f, _r = MOC_SPEC[variant]\n    n = n_def if n in (None, \"\") else int(n)\n    if variant in MOC_NFIX:\n        n = MOC_NFIX[variant]\n    return {\"variant\": variant, \"n\": max(n_min, min(n, 100)), \"m\": m}\n\n\nclass MOC:\n    \"\"\"连续多目标上下文。\"\"\"\n\n    def __init__(self, problem):\n        self.variant = problem[\"variant\"]\n        name, self.m, _nd, self.n_min, bfun, self.fn, self.ref = MOC_SPEC[self.variant]\n        self.name = name\n        self.n = problem[\"n\"]\n        self.bounds = bfun(self.n)\n        self.bits = self.variant in MOC_BITS\n        self.scale = MOC_SCALE.get(self.variant, [1.0] * self.m)\n\n    def clamp(self, x):\n        return [min(hi, max(lo, v)) for v, (lo, hi) in zip(x, self.bounds)]\n\n    def random(self, rng):\n        if self.bits:\n            return [rng.randint(0, 1) for _ in self.bounds]\n        return [rng.uniform(lo, hi) for (lo, hi) in self.bounds]\n\n    def f(self, x):\n        return self.fn(x if self.bits else self.clamp(x))\n\n    # ---- 变异 / 交叉：实数编码用 SBX + 多项式变异 / 差分；位串用均匀交叉 + 逐位翻转（概率 1/长度）\n    def cross(self, a, b, rng):\n        if not self.bits:\n            return sbx(a, b, self.bounds, rng)\n        if rng.random() > 0.9:\n            return list(a), list(b)\n        c1, c2 = list(a), list(b)\n        for i in range(len(a)):\n            if rng.random() < 0.5:\n                c1[i], c2[i] = c2[i], c1[i]\n        return c1, c2\n\n    def mutate(self, x, rng):\n        if not self.bits:\n            return poly_mutate(x, self.bounds, rng)\n        pm = 1.0 / len(x)\n        return [1 - v if rng.random() < pm else v for v in x]\n\n    def vary3(self, a, b, c, rng):\n        \"\"\"MOEA/D 的产生子代：实数 = 差分 a + 0.5(b - c)；位串没有差分，改用 a、b 的交叉。\"\"\"\n        if self.bits:\n            return self.cross(a, b, rng)[0]\n        return self.clamp([a[d] + 0.5 * (b[d] - c[d]) for d in range(len(a))])\n\n\n# ------------------------------------------------------------------ 真前沿与指标\n\ndef das_dennis(m, h):\n    pts = []\n\n    def rec(rem, k, cur):\n        if k == m - 1:\n            pts.append([c / h for c in cur + [rem]])\n            return\n        for i in range(rem + 1):\n            rec(rem - i, k + 1, cur + [i])\n    rec(h, 0, [])\n    return pts\n\n\n_FRONT_CACHE = {}\n\n\ndef true_front(variant, count=200):\n    \"\"\"解析真前沿的采样点（用作 IGD 的参考集）。\"\"\"\n    key = (variant, count)\n    if key in _FRONT_CACHE:\n        return _FRONT_CACHE[key]\n    if variant in (\"zdt1\", \"zdt4\"):\n        pts = [[i / (count - 1), 1.0 - math.sqrt(i / (count - 1))] for i in range(count)]\n    elif variant == \"zdt2\":\n        pts = [[i / (count - 1), 1.0 - (i / (count - 1)) ** 2] for i in range(count)]\n    elif variant == \"zdt3\":\n        # 曲线 f2 = 1 - sqrt(f1) - f1·sin(10π f1) 中只有一部分是非支配的（5 段）：密采样后按 f1 升序扫一遍，\n        # 只保留 f2 严格低于此前所有点的那些（O(n)；论文里的 5 段端点由此得到，不手抄常数）\n        dense = [[t / 20000.0, 1.0 - math.sqrt(t / 20000.0) - (t / 20000.0) * math.sin(10.0 * math.pi * t / 20000.0)]\n                 for t in range(20001)]\n        nd, low = [], float(\"inf\")\n        for pt in dense:\n            if pt[1] < low:\n                nd.append(pt)\n                low = pt[1]\n        step = max(1, len(nd) // count)\n        pts = nd[::step]\n    elif variant == \"zdt6\":\n        lo = 0.2807753191\n        pts = [[lo + (1.0 - lo) * i / (count - 1), 1.0 - (lo + (1.0 - lo) * i / (count - 1)) ** 2] for i in range(count)]\n    elif variant == \"zdt5\":\n        pts = [[float(f1), 10.0 / f1] for f1 in range(1, 32)]  # 离散前沿：g = 10 时 f2 = 10 / f1，f1 取 1..31\n    elif variant == \"dtlz1\":\n        pts = [[0.5 * w for w in v] for v in das_dennis(3, 13)]\n    elif variant in (\"dtlz2\", \"dtlz3\", \"dtlz4\"):\n        pts = []\n        for v in das_dennis(3, 13):\n            norm = math.sqrt(sum(w * w for w in v))\n            pts.append([w / norm for w in v])\n    elif variant in (\"dtlz5\", \"dtlz6\"):\n        # g = 0 时 θ2 = π/4：f1 = f2 = cosθ1/√2，f3 = sinθ1，θ1 ∈ [0, π/2]\n        pts = [[math.cos(t) / math.sqrt(2.0), math.cos(t) / math.sqrt(2.0), math.sin(t)]\n               for t in (math.pi / 2.0 * i / (count - 1) for i in range(count))]\n    elif variant == \"dtlz7\":\n        pts = _dtlz7_front(200)\n        step = max(1, len(pts) // count)\n        pts = pts[::step]\n    else:\n        raise ValueError(variant)\n    _FRONT_CACHE[key] = pts\n    return pts\n\n\ndef _dtlz7_front(grid):\n    \"\"\"DTLZ7 的真前沿（g = 1）：曲面 f3 = h(f1, f2) 上的非支配部分。曲面在 (f1, f2) 网格上取点，\n    网格点 (i, j) 被支配 ⇔ 存在 i' ≤ i、j' ≤ j（不同于自己）的点 f3 不比它大；用二维前缀最小值一遍算出，O(grid²)，不必做三维两两比较。\"\"\"\n    key = (\"dtlz7\", \"grid\", grid)\n    if key in _FRONT_CACHE:\n        return _FRONT_CACHE[key]\n    xs = [i / (grid - 1) for i in range(grid)]\n    f3 = [[_dtlz7_f3(a, b, 1.0) for b in xs] for a in xs]\n    INF = float(\"inf\")\n    pm = [[INF] * grid for _ in range(grid)]  # pm[i][j] = min f3 over i' <= i, j' <= j\n    pts = []\n    for i in range(grid):\n        for j in range(grid):\n            up = pm[i - 1][j] if i else INF\n            left = pm[i][j - 1] if j else INF\n            if f3[i][j] < min(up, left):\n                pts.append([xs[i], xs[j], f3[i][j]])\n            pm[i][j] = min(f3[i][j], up, left)\n    pts.sort()\n    _FRONT_CACHE[key] = pts\n    return pts\n\n\ndef dense_front(variant, h=36):\n    \"\"\"三目标真前沿的密采样（只用来算参考超体积；IGD 用较稀的 true_front）。\"\"\"\n    key = (variant, \"dense\", h)\n    if key not in _FRONT_CACHE:\n        pts = []\n        if variant in (\"dtlz5\", \"dtlz6\"):\n            pts = true_front(variant, 400)\n        elif variant == \"dtlz7\":\n            pts = _dtlz7_front(60)\n        else:\n            for v in das_dennis(3, h):\n                if variant == \"dtlz1\":\n                    pts.append([0.5 * w for w in v])\n                else:\n                    norm = math.sqrt(sum(w * w for w in v))\n                    pts.append([w / norm for w in v])\n        _FRONT_CACHE[key] = pts\n    return _FRONT_CACHE[key]\n\n\ndef igd(front, ref_set):\n    \"\"\"IGD：参考集中每个点到「找到的前沿」最近距离的平均值（越小越好；既衡量收敛也衡量铺开）。\"\"\"\n    if not front:\n        return float(\"inf\")\n    return sum(min(math.dist(r, f) for f in front) for r in ref_set) / len(ref_set)\n\n\ndef hypervolume(points, ref):\n    \"\"\"被 points 支配、且在参考点 ref 以内的体积（最小化；2 / 3 目标，维度扫描法）。\"\"\"\n    pts = [p for p in points if all(p[d] < ref[d] for d in range(len(ref)))]\n    if not pts:\n        return 0.0\n    m = len(ref)\n    if m == 1:\n        return ref[0] - min(p[0] for p in pts)\n    if m == 2:\n        pts.sort()\n        vol, best_y = 0.0, ref[1]\n        for x, y in pts:\n            if y < best_y:\n                vol += (ref[0] - x) * (best_y - y)\n                best_y = y\n        return vol\n    pts.sort(key=lambda p: p[-1])  # 按最后一维升序切片\n    vol = 0.0\n    for i, p in enumerate(pts):\n        nxt = pts[i + 1][-1] if i + 1 < len(pts) else ref[-1]\n        if nxt > p[-1]:\n            vol += hypervolume([q[:-1] for q in pts[: i + 1]], ref[:-1]) * (nxt - p[-1])\n    return vol\n\n\n# ------------------------------------------------------------------ 非支配排序与算子（最小化）\n\ndef nd_sort(F):\n    n = len(F)\n    S = [[] for _ in range(n)]\n    cnt = [0] * n\n    fronts = [[]]\n    rank = [0] * n\n    for i in range(n):\n        for j in range(i + 1, n):\n            a, b = F[i], F[j]\n            ab = all(a[d] <= b[d] for d in range(len(a))) and a != b\n            ba = all(b[d] <= a[d] for d in range(len(a))) and a != b\n            if ab:\n                S[i].append(j)\n                cnt[j] += 1\n            elif ba:\n                S[j].append(i)\n                cnt[i] += 1\n    fronts[0] = [i for i in range(n) if cnt[i] == 0]\n    k = 0\n    while fronts[k]:\n        nxt = []\n        for i in fronts[k]:\n            for j in S[i]:\n                cnt[j] -= 1\n                if cnt[j] == 0:\n                    rank[j] = k + 1\n                    nxt.append(j)\n        k += 1\n        fronts.append(nxt)\n    return rank, [f for f in fronts if f]\n\n\ndef crowding(F, idxs):\n    if len(idxs) <= 2:\n        return {i: float(\"inf\") for i in idxs}\n    dist = {i: 0.0 for i in idxs}\n    for d in range(len(F[0])):\n        order = sorted(idxs, key=lambda i: F[i][d])\n        dist[order[0]] = dist[order[-1]] = float(\"inf\")\n        span = F[order[-1]][d] - F[order[0]][d]\n        if span <= 0:\n            continue\n        for k in range(1, len(order) - 1):\n            dist[order[k]] += (F[order[k + 1]][d] - F[order[k - 1]][d]) / span\n    return dist\n\n\ndef sbx(p1, p2, bounds, rng, eta=15.0, pc=0.9):\n    \"\"\"模拟二进制交叉（Deb & Agrawal 1995）。\"\"\"\n    c1, c2 = list(p1), list(p2)\n    if rng.random() > pc:\n        return c1, c2\n    for i, (lo, hi) in enumerate(bounds):\n        if rng.random() > 0.5 or abs(p1[i] - p2[i]) < 1e-14:\n            continue\n        a, b = min(p1[i], p2[i]), max(p1[i], p2[i])\n        u = rng.random()\n        beta = 1.0 + 2.0 * (a - lo) / (b - a)\n        alpha = 2.0 - beta ** -(eta + 1.0)\n        bq = (u * alpha) ** (1.0 / (eta + 1.0)) if u <= 1.0 / alpha else (1.0 / (2.0 - u * alpha)) ** (1.0 / (eta + 1.0))\n        x1 = 0.5 * ((a + b) - bq * (b - a))\n        beta = 1.0 + 2.0 * (hi - b) / (b - a)\n        alpha = 2.0 - beta ** -(eta + 1.0)\n        bq = (u * alpha) ** (1.0 / (eta + 1.0)) if u <= 1.0 / alpha else (1.0 / (2.0 - u * alpha)) ** (1.0 / (eta + 1.0))\n        x2 = 0.5 * ((a + b) + bq * (b - a))\n        x1, x2 = min(hi, max(lo, x1)), min(hi, max(lo, x2))\n        if rng.random() < 0.5:\n            x1, x2 = x2, x1\n        c1[i], c2[i] = x1, x2\n    return c1, c2\n\n\ndef poly_mutate(x, bounds, rng, eta=20.0, pm=None):\n    \"\"\"多项式变异（Deb & Goyal 1996）。\"\"\"\n    n = len(x)\n    pm = 1.0 / n if pm is None else pm\n    y = list(x)\n    for i, (lo, hi) in enumerate(bounds):\n        if rng.random() >= pm:\n            continue\n        u = rng.random()\n        d1, d2 = (y[i] - lo) / (hi - lo), (hi - y[i]) / (hi - lo)\n        if u < 0.5:\n            dq = (2.0 * u + (1.0 - 2.0 * u) * (1.0 - d1) ** (eta + 1.0)) ** (1.0 / (eta + 1.0)) - 1.0\n        else:\n            dq = 1.0 - (2.0 * (1.0 - u) + 2.0 * (u - 0.5) * (1.0 - d2) ** (eta + 1.0)) ** (1.0 / (eta + 1.0))\n        y[i] = min(hi, max(lo, y[i] + dq * (hi - lo)))\n    return y\n\n\n# ------------------------------------------------------------------ 状态\n\nclass _Tracker:\n    def __init__(self, ctx):\n        self.ctx = ctx\n        self.ref_set = true_front(ctx.variant)\n        self.hv_true = hypervolume(true_front(ctx.variant, 1500) if ctx.m == 2 else dense_front(ctx.variant), ctx.ref)\n        self.best_igd = float(\"inf\")\n\n    def state(self, it, pop_F, pop_X):\n        ctx = self.ctx\n        _r, fronts = nd_sort(pop_F)\n        order = sorted(fronts[0], key=lambda i: pop_F[i])\n        front = [pop_F[i] for i in order]\n        cur = igd(front, self.ref_set)\n        self.best_igd = min(self.best_igd, cur)\n        hv = hypervolume(front, ctx.ref)\n        return {\"iter\": it, \"pop\": [list(f) for f in pop_F], \"front\": [list(f) for f in front],\n                \"front_x\": [list(pop_X[i]) for i in order], \"nd\": len(front),\n                \"igd\": round(cur, 6), \"hv\": round(hv, 6), \"hv_ratio\": round(hv / self.hv_true, 4) if self.hv_true else 0.0,\n                \"best\": round(self.best_igd, 6), \"cur\": round(cur, 6)}\n\n\n# ------------------------------------------------------------------ 算法\n\ndef _mc_random(ctx, p, rng):\n    \"\"\"随机基线：每代抽一批随机解，只保留非支配的档案。\"\"\"\n    tr = _Tracker(ctx)\n    arch, arch_x = [], []\n    for it in range(1, p[\"max_iter\"] + 1):\n        new_x = [ctx.random(rng) for _ in range(p[\"n_pop\"])]\n        new = [ctx.f(x) for x in new_x]\n        cand, cand_x = arch + new, arch_x + new_x\n        _r, fr = nd_sort(cand)\n        arch, arch_x = [cand[i] for i in fr[0]], [cand_x[i] for i in fr[0]]\n        if len(arch) > 2 * p[\"n_pop\"]:\n            arch, arch_x = arch[:: 2], arch_x[:: 2]\n        yield tr.state(it, arch + new, arch_x + new_x)\n\n\ndef _mc_wsga(ctx, p, rng):\n    \"\"\"加权和 GA（对照）：每代随机权重把多目标压成一个数，再做单目标选择。\n    经典弱点：种群被拉向权重方向上的某一点，铺不开前沿；非凸前沿段用任何权重都够不到。\"\"\"\n    tr = _Tracker(ctx)\n    n_pop = p[\"n_pop\"]\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    F = [ctx.f(x) for x in pop]\n    for it in range(1, p[\"max_iter\"] + 1):\n        w = [rng.random() for _ in range(ctx.m)]\n        s = sum(w) or 1.0\n        w = [v / s for v in w]\n        sc = [sum(w[d] * f[d] for d in range(ctx.m)) for f in F]\n        new = [list(pop[min(range(n_pop), key=sc.__getitem__)])]\n        while len(new) < n_pop:\n            a = min(rng.sample(range(n_pop), 2), key=sc.__getitem__)\n            b = min(rng.sample(range(n_pop), 2), key=sc.__getitem__)\n            c1, _c2 = ctx.cross(pop[a], pop[b], rng)\n            new.append(ctx.mutate(c1, rng))\n        pop = new\n        F = [ctx.f(x) for x in pop]\n        yield tr.state(it, F, pop)\n\n\ndef _mc_nsga2(ctx, p, rng):\n    \"\"\"NSGA-II（Deb et al. 2002）：非支配排序 + 拥挤度 + 精英保留；实数编码用 SBX + 多项式变异。\"\"\"\n    tr = _Tracker(ctx)\n    n_pop = p[\"n_pop\"]\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    F = [ctx.f(x) for x in pop]\n    rank, fronts = nd_sort(F)\n    cd = {}\n    for fr in fronts:\n        cd.update(crowding(F, fr))\n\n    def tour():\n        a, b = rng.sample(range(n_pop), 2)\n        if rank[a] != rank[b]:\n            return pop[a] if rank[a] < rank[b] else pop[b]\n        return pop[a] if cd[a] >= cd[b] else pop[b]\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        kids = []\n        while len(kids) < n_pop:\n            c1, c2 = ctx.cross(tour(), tour(), rng)\n            kids += [ctx.mutate(c1, rng), ctx.mutate(c2, rng)]\n        kids = kids[:n_pop]\n        KF = [ctx.f(x) for x in kids]\n        union, UF = pop + kids, F + KF\n        _ur, ufronts = nd_sort(UF)\n        sel = []\n        for fr in ufronts:\n            if len(sel) + len(fr) <= n_pop:\n                sel += fr\n            else:\n                c = crowding(UF, fr)\n                sel += sorted(fr, key=lambda i: c[i], reverse=True)[: n_pop - len(sel)]\n                break\n        pop, F = [union[i] for i in sel], [UF[i] for i in sel]\n        rank, fronts = nd_sort(F)\n        cd = {}\n        for fr in fronts:\n            cd.update(crowding(F, fr))\n        yield tr.state(it, F, pop)\n\n\ndef _mc_moead(ctx, p, rng):\n    \"\"\"MOEA/D-DE（Li & Zhang 2009）：把多目标拆成 N 个 Tchebycheff 单目标子问题，每个子问题只与权重相近的邻居交配；\n    变异 = 差分 + 多项式变异（位串编码的 ZDT5 没有差分，改用均匀交叉 + 逐位翻转）。\"\"\"\n    tr = _Tracker(ctx)\n    m = ctx.m\n    if m == 2:\n        n_pop = p[\"n_pop\"]\n        W = [[i / (n_pop - 1), 1.0 - i / (n_pop - 1)] for i in range(n_pop)]\n    else:\n        h = 1\n        while len(das_dennis(m, h + 1)) <= p[\"n_pop\"]:\n            h += 1\n        W = das_dennis(m, h)\n        n_pop = len(W)\n    W = [[max(v, 1e-6) for v in w] for w in W]\n    T = max(3, n_pop // 5)\n    nb = [sorted(range(n_pop), key=lambda j: math.dist(W[i], W[j]))[:T] for i in range(n_pop)]\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    F = [ctx.f(x) for x in pop]\n    z = [min(f[d] for f in F) for d in range(m)]\n\n    def g(f, w):\n        return max(w[d] * abs(f[d] - z[d]) / ctx.scale[d] for d in range(m))\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in rng.sample(range(n_pop), n_pop):\n            pool = nb[i] if rng.random() < 0.9 else list(range(n_pop))\n            r1, r2, r3 = rng.sample(pool, 3) if len(pool) >= 3 else (i, i, i)\n            child = ctx.mutate(ctx.vary3(pop[r1], pop[r2], pop[r3], rng), rng)\n            cf = ctx.f(child)\n            z = [min(z[d], cf[d]) for d in range(m)]\n            replaced = 0\n            for j in rng.sample(pool, len(pool)):\n                if g(cf, W[j]) <= g(F[j], W[j]):\n                    pop[j], F[j] = child, cf\n                    replaced += 1\n                    if replaced >= 2:\n                        break\n        yield tr.state(it, F, pop)\n\n\ndef _pref_point(ctx):\n    \"\"\"偏好范式用的参考点（愿望点）：理想点向真前沿「正中」那个点方向走 85%——略好于前沿、不可达，是 R-NSGA-II 论文里常见的设法。\"\"\"\n    pts = true_front(ctx.variant)\n    m = ctx.m\n    ideal = [min(p[d] for p in pts) for d in range(m)]\n    sc = ctx.scale\n    cen = [sum(p[d] for p in pts) / len(pts) for d in range(m)]\n    mid = min(pts, key=lambda p: sum(((p[d] - cen[d]) / sc[d]) ** 2 for d in range(m)))\n    return [ideal[d] + 0.85 * (mid[d] - ideal[d]) for d in range(m)]\n\n\ndef _mc_ibea(ctx, p, rng):\n    \"\"\"IBEA（Zitzler & Künzli 2004）：用加性 ε 指标直接当适应度——F(x) = Σ_{y≠x} −exp(−I(y,x)/(c·κ))，\n    环境选择反复删掉适应度最差者并更新其余个体的适应度；不用支配排序，也不用拥挤度。\"\"\"\n    tr = _Tracker(ctx)\n    n, m, sc, kappa = p[\"n_pop\"], ctx.m, ctx.scale, 0.05\n    pop = [ctx.random(rng) for _ in range(n)]\n    F = [ctx.f(x) for x in pop]\n\n    def eps_matrix(Fs):\n        k = len(Fs)\n        return [[max((Fs[i][d] - Fs[j][d]) / sc[d] for d in range(m)) for j in range(k)] for i in range(k)]\n\n    def fitness(I, alive):\n        c = max((abs(I[i][j]) for i in alive for j in alive if i != j), default=1.0) or 1.0\n        return c, {i: sum(-math.exp(-I[j][i] / (c * kappa)) for j in alive if j != i) for i in alive}\n\n    _c, fit = fitness(eps_matrix(F), list(range(n)))\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        ids = list(range(n))\n\n        def tour():\n            a, b = rng.sample(ids, 2)\n            return pop[a] if fit[a] >= fit[b] else pop[b]\n        kids = []\n        while len(kids) < n:\n            c1, c2 = ctx.cross(tour(), tour(), rng)\n            kids += [ctx.mutate(c1, rng), ctx.mutate(c2, rng)]\n        kids = kids[:n]\n        union, UF = pop + kids, F + [ctx.f(x) for x in kids]\n        I = eps_matrix(UF)\n        alive = list(range(len(union)))\n        c, ufit = fitness(I, alive)\n        while len(alive) > n:\n            worst = min(alive, key=lambda i: ufit[i])\n            alive.remove(worst)\n            for i in alive:\n                ufit[i] += math.exp(-I[worst][i] / (c * kappa))\n        pop, F = [union[i] for i in alive], [UF[i] for i in alive]\n        fit = {k: ufit[i] for k, i in enumerate(alive)}\n        yield tr.state(it, F, pop)\n\n\ndef _mc_rnsga2(ctx, p, rng):\n    \"\"\"R-NSGA-II（Deb et al. 2006）简化版：NSGA-II 的骨架，但同一前沿内用「到参考点的距离」代替拥挤度，\n    并用 ε-清除避免种群塌成一个点。只追求参考点附近的那一段前沿——所以 IGD（衡量整条前沿）偏大是预期的。\"\"\"\n    tr = _Tracker(ctx)\n    n, m, sc = p[\"n_pop\"], ctx.m, ctx.scale\n    ref = _pref_point(ctx)\n    eps = 0.02\n\n    def dist(f):\n        return math.sqrt(sum(((f[d] - ref[d]) / sc[d]) ** 2 for d in range(m)))\n\n    def clear_order(Fs, ids):\n        rest = sorted(ids, key=lambda i: dist(Fs[i]))\n        out, later = [], []\n        while rest:\n            a = rest.pop(0)\n            out.append(a)\n            keep = []\n            for b in rest:\n                if math.sqrt(sum(((Fs[a][d] - Fs[b][d]) / sc[d]) ** 2 for d in range(m))) < eps:\n                    later.append(b)\n                else:\n                    keep.append(b)\n            rest = keep\n        return out + sorted(later, key=lambda i: dist(Fs[i]))\n\n    pop = [ctx.random(rng) for _ in range(n)]\n    F = [ctx.f(x) for x in pop]\n    rank, _fr = nd_sort(F)\n\n    def emit(it):\n        s = tr.state(it, F, pop)\n        s[\"pref\"] = [round(v, 6) for v in ref]\n        s[\"pref_dist\"] = round(min(dist(f) for f in s[\"front\"]), 6)\n        return s\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        def tour():\n            a, b = rng.sample(range(n), 2)\n            if rank[a] != rank[b]:\n                return pop[a] if rank[a] < rank[b] else pop[b]\n            return pop[a] if dist(F[a]) <= dist(F[b]) else pop[b]\n        kids = []\n        while len(kids) < n:\n            c1, c2 = ctx.cross(tour(), tour(), rng)\n            kids += [ctx.mutate(c1, rng), ctx.mutate(c2, rng)]\n        kids = kids[:n]\n        union, UF = pop + kids, F + [ctx.f(x) for x in kids]\n        _ur, ufronts = nd_sort(UF)\n        sel = []\n        for fr in ufronts:\n            if len(sel) + len(fr) <= n:\n                sel += fr\n            else:\n                sel += clear_order(UF, fr)[: n - len(sel)]\n                break\n        pop, F = [union[i] for i in sel], [UF[i] for i in sel]\n        rank, _fr = nd_sort(F)\n        yield emit(it)\n\n\nMOC_ALGOS = {\n    \"random\": {\"fn\": _mc_random, \"name\": \"随机搜索\", \"category\": \"基线\", \"desc\": \"盲采样 + 非支配档案：所有算法都要显著优于它\", \"tune\": []},\n    \"wsga\": {\"fn\": _mc_wsga, \"name\": \"加权和 GA\", \"category\": \"进化计算\", \"desc\": \"每代随机权重合成单目标（对照：铺不开前沿、漏非凸段）\", \"tune\": []},\n    \"nsga2\": {\"fn\": _mc_nsga2, \"name\": \"NSGA-II\", \"category\": \"进化计算\", \"desc\": \"非支配排序 + 拥挤度，SBX + 多项式变异（Deb 2002）\", \"tune\": []},\n    \"moead\": {\"fn\": _mc_moead, \"name\": \"MOEA/D\", \"category\": \"进化计算\", \"desc\": \"Tchebycheff 分解 + 邻域差分（Li & Zhang 2009）\", \"tune\": []},\n    \"ibea\": {\"fn\": _mc_ibea, \"name\": \"IBEA\", \"category\": \"进化计算\", \"desc\": \"指标法：加性 ε 指标直接当适应度，不用支配排序（Zitzler & Künzli 2004）\", \"tune\": []},\n    \"rnsga2\": {\"fn\": _mc_rnsga2, \"name\": \"R-NSGA-II\", \"category\": \"进化计算\", \"desc\": \"偏好法：给定参考点，同一前沿内按到参考点的距离选择（Deb 等 2006 简化版）；图上的菱形是参考点\", \"tune\": []},\n}\nMOC_DEF = {\"n_pop\": 60, \"max_iter\": 300, \"seed\": 7}\n\n\n# -*- coding: utf-8 -*-\n\"\"\"v0.8 问题域扩展引擎：把元启发式从 TSP 推广到多个问题域。\n\n设计原则（百科全书的骨架）：\n  算法 = 探索/开发机制（与问题无关），问题绑定 = 编码 + 邻域/算子 + 约束处理。\n  本文件为每个问题域提供「域上下文」（编码、评价、修复、polish），算法按统一生成器\n  接口逐代 yield 状态，前端 worker 逐条消费——与 py/solvers.py 的 TSP 体系同构。\n\n三个域（v0.8 简化版，后续逐个加深）：\n  knapsack   0-1 背包      —— 二进制编码 + 贪心修复算子（约束处理入门）\n  continuous 连续函数基准   —— 实数编码，PSO/DE/GWO/WOA/SCA 的「原生域」\n  multiobj   双目标背包     —— NSGA-II：非支配排序 + 拥挤度（多目标入门）\n\n接口：\n  domain_start(domain, problem_json, algo, params_json) -> info json\n  domain_step() -> state json or None\n  domain_list(domain) -> 算法清单（含默认参数）\n  domain_preset(domain, seed, opts_json) -> 预置实例\n\n「真优化」校验铁律与 TSP 侧相同：每个算法都必须有「真实迭代进步」，\n测试里逐个对照随机基线（tests/test_domains.py）。\n\"\"\"\nimport json\nimport math\nimport random\n\n# ---- 算法分类（生成文件 py/taxonomy.py：由 data/families.json + data/algos.json 得出）----\n# 本地正常导入；浏览器构建期拼进同一名字空间，ImportError 分支跳过\ntry:\n    from taxonomy import category_of\nexcept ImportError:\n    pass\n\n# ---- 域引擎组件库（S1-1 组件化：骨架件单一来源 = py/domain_components.py）----\n# 本地/pytest 正常导入；Pyodide 构建期本文件与 domain_components.py 拼进同一名字\n# 空间执行，此 import 抛 ImportError → 跳过（名字已在空间内），两种环境行为一致\ntry:\n    from domain_components import (\n        argbest, bits_flip, bits_mutate, bits_uniform, bump, greedy_replace,\n        pm_insert as _pm_insert, pm_ox as _pm_ox, pm_polish as _pm_polish,\n        pm_swap as _pm_swap,\n    )\nexcept ImportError:\n    pass\n\n# ---- entryseq 词条域（57 变体的实例生成 + 目标函数，一变体一对函数）= py/entryseq.py ----\n# 与上面同一机制：本地正常导入；浏览器构建期拼进同一名字空间，ImportError 分支跳过\ntry:\n    from entryseq import _ES, es_make, es_ctx, FIDELITY, VEC_VARIANTS, BIT_VARIANTS, _DESIGN, _opt_mst, _opt_sp, _opt_gmatch, _pc_max_flow, _msa_dp  # noqa: F401  （不起别名：浏览器里这些模块拼进同一名字空间，别名不会被绑定）\nexcept ImportError:\n    pass\n\n# ---- 自带问题 custom 域（用户给编码 + 目标函数，三种编码复用已有内核）= py/userproblem.py ----\ntry:\n    from userproblem import (up_check, up_make_ctx, up_preset, up_wrap_stream, up_auto_params,  # noqa: F401\n                             ENCODINGS as _UP_ENCODINGS)\nexcept ImportError:\n    pass\n\n# ---- 连续多目标基准 mocont 域（ZDT / DTLZ，有解析真前沿，可算 IGD / HV）= py/mocont.py ----\ntry:\n    from mocont import (MOC, mc_make, MOC_ALGOS, MOC_DEF, MOC_VARIANTS, MOC_SPEC, MOC_NFIX,  # noqa: F401\n                        true_front)  # 不起别名：浏览器拼接环境里别名不会被绑定\nexcept ImportError:\n    pass\n\n# ============================================================\n# 域一：0-1 背包（二进制编码）\n# ============================================================\n\ndef ks_make(n=40, seed=7):\n    \"\"\"随机背包实例：cap 取总重的 45%，保证既装不满也留有取舍。\"\"\"\n    rng = random.Random(seed)\n    items = [(rng.randint(2, 60), rng.randint(10, 100)) for _ in range(n)]\n    cap = int(sum(w for w, _ in items) * 0.45)\n    return {\"n\": n, \"cap\": cap, \"items\": [[w, v] for w, v in items]}\n\n\nclass _KS:\n    \"\"\"背包域上下文：编码=0/1 向量，约束=超重必须修复。\"\"\"\n\n    def __init__(self, problem):\n        self.items = [tuple(x) for x in problem[\"items\"]]\n        self.cap = problem[\"cap\"]\n        self.n = problem[\"n\"]\n\n    def value(self, s):\n        return sum(self.items[i][1] for i in range(self.n) if s[i])\n\n    def weight(self, s):\n        return sum(self.items[i][0] for i in range(self.n) if s[i])\n\n    def repair(self, s):\n        \"\"\"贪心修复：超重时按「单位重量价值最低先扔」，这是约束背包的标准修复算子。\"\"\"\n        s = list(s)\n        total = self.weight(s)\n        if total <= self.cap:\n            return s\n        idx = [i for i in range(self.n) if s[i]]\n        idx.sort(key=lambda i: self.items[i][1] / max(1, self.items[i][0]))\n        for i in idx:\n            if total <= self.cap:\n                break\n            s[i] = 0\n            total -= self.items[i][0]\n        return s\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.5 else 0 for _ in range(self.n)])\n\n    def polish(self, s, rng, moves=10):\n        \"\"\"memetic 组件：随机单比特翻转爬山（小预算，模拟退火内也用）。\"\"\"\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            s2 = self.repair(s)\n            v = self.value(s2)\n            if v >= best:\n                s, best = s2, v\n            else:\n                s = prev\n        return s\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.value(s) for s in pop]\n\n\ndef _ks_random(ctx, p, rng):\n    best, bs = None, None  # 哨兵必须 None：负值景观（如 cmp/ssp 的 -罚）下 -1 会吞掉全部样本\n    for it in range(1, p[\"max_iter\"] + 1):\n        s = ctx.random(rng)\n        v = ctx.value(s)\n        if bs is None or v > best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": bs}\n\n\ndef _ks_hc(ctx, p, rng):\n    s = ctx.random(rng)\n    best, bs = ctx.value(s), list(s)\n    for it in range(1, p[\"max_iter\"] + 1):\n        for _ in range(p[\"tries\"]):\n            i = rng.randrange(ctx.n)\n            cand = list(s)\n            cand[i] ^= 1\n            cand = ctx.repair(cand)\n            v = ctx.value(cand)\n            if v > ctx.value(s):\n                s = cand\n        best, bs = bump(best, bs, ctx.value(s), s)\n        yield {\"iter\": it, \"best\": best, \"cur\": ctx.value(s), \"best_sol\": bs}\n\n\ndef _ks_sa(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.value(s)\n    best, bs = v, list(s)\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        i = rng.randrange(ctx.n)\n        cand = list(s)\n        cand[i] ^= 1\n        cand = ctx.repair(cand)\n        v2 = ctx.value(cand)\n        d = v2 - v\n        if d > 0 or (T > 1e-9 and rng.random() < math.exp(d / T)):\n            s, v = cand, v2\n        best, bs = bump(best, bs, v, s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": bs}\n\n\ndef _ks_ga(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals)\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]  # 精英保留\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            pa, pb = pop[a], pop[b]\n            child = bits_uniform(pa, pb, rng)  # 均匀交叉\n            bits_mutate(child, p[\"pm\"], rng)\n            child = ctx.repair(child)\n            new.append(child)\n        pop = new\n        vals = [ctx.value(s) for s in pop]\n        bi = argbest(vals)\n        best, bs = bump(best, bs, vals[bi], pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\ndef _ks_de(ctx, p, rng):\n    \"\"\"二进制差分：差向量 = r2/r3 不同的位（排列域思想在 0/1 域的等价物）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals)\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(p[\"n_pop\"]):\n            r1, r2, r3 = rng.sample([j for j in range(p[\"n_pop\"]) if j != i], 3)\n            mutant = list(pop[r1])\n            for k in range(ctx.n):\n                if pop[r2][k] != pop[r3][k] and rng.random() < p[\"F\"]:\n                    mutant[k] = pop[r2][k]\n            trial = [mutant[k] if rng.random() < p[\"CR\"] else pop[i][k] for k in range(ctx.n)]\n            trial = ctx.repair(trial)\n            v = ctx.value(trial)\n            if v >= vals[i]:  # DE 贪心选择\n                pop[i], vals[i] = trial, v\n                best, bs = bump(best, bs, v, trial)\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\ndef _ks_ts(ctx, p, rng):\n    \"\"\"禁忌搜索（二进制邻域）：每步在全部单翻转里选最好的非禁忌移动。\"\"\"\n    s = ctx.random(rng)\n    v = ctx.value(s)\n    best, bs = v, list(s)\n    tabu = {}\n    tenure = p[\"tenure\"]\n    for it in range(1, p[\"max_iter\"] + 1):\n        best_move, best_v, best_i = None, -1, -1\n        for i in range(ctx.n):\n            if tabu.get(i, -1) >= it:\n                continue\n            cand = list(s)\n            cand[i] ^= 1\n            cand = ctx.repair(cand)\n            vv = ctx.value(cand)\n            if vv > best_v:\n                best_v, best_move, best_i = vv, cand, i\n        if best_move is None:\n            s = ctx.random(rng)\n            v = ctx.value(s)\n        else:\n            s, v = best_move, best_v\n            tabu[best_i] = it + tenure\n        best, bs = bump(best, bs, v, s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": bs}\n\n\ndef _ks_abc(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    stuck = [0] * p[\"n_pop\"]\n    bi = argbest(vals)\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for phase in range(2):  # 雇佣蜂 + 观察蜂\n            for i in range(p[\"n_pop\"]):\n                k = 1 if rng.random() < 0.8 else 2\n                cand = bits_flip(pop[i], rng, k)\n                cand = ctx.repair(cand)\n                v = ctx.value(cand)\n                if v > vals[i]:\n                    pop[i], vals[i], stuck[i] = cand, v, 0\n                else:\n                    stuck[i] += 1\n            if phase == 1:  # 观察蜂按收益轮盘\n                lo, hi = min(vals), max(vals)\n                w = [(v - lo + 1e-9) for v in vals]\n                tot = sum(w) or 1.0\n                for _ in range(p[\"n_pop\"]):\n                    r, acc = rng.random() * tot, 0.0\n                    for i in range(p[\"n_pop\"]):\n                        acc += w[i]\n                        if acc >= r:\n                            break\n                    cand = bits_flip(pop[i], rng, 1 if rng.random() < 0.8 else 2)\n                    cand = ctx.repair(cand)\n                    v = ctx.value(cand)\n                    if v > vals[i]:\n                        pop[i], vals[i], stuck[i] = cand, v, 0\n        for i in range(p[\"n_pop\"]):  # 侦察蜂\n            if stuck[i] > p[\"limit\"]:\n                pop[i], vals[i], stuck[i] = ctx.random(rng), 0, 0\n                vals[i] = ctx.value(pop[i])\n        bi = argbest(vals)\n        best, bs = bump(best, bs, vals[bi], pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\ndef _ks_woa(ctx, p, rng):\n    \"\"\"二进制鲸鱼：包围 = 按收缩比例抄最优解的位；螺旋 = 抄随机同伴。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals)\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        a = 2.0 * (1 - it / p[\"max_iter\"])  # 线性收缩\n        for i in range(p[\"n_pop\"]):\n            ratio = max(0.1, min(0.9, abs(2 * a * rng.random() - a)))\n            if rng.random() < 0.5:  # 包围：偏向最优\n                src, prob = pop[bi], 1.0 - ratio * 0.5\n                cand = [src[k] if rng.random() < prob else rng.randint(0, 1) for k in range(ctx.n)]\n            else:  # 螺旋：向随机同伴学习\n                src = pop[rng.randrange(p[\"n_pop\"])]\n                cand = [src[k] if rng.random() < 0.5 else pop[i][k] for k in range(ctx.n)]\n            cand = ctx.repair(cand)\n            cand = ctx.polish(cand, rng, 3)\n            v = ctx.value(cand)\n            if greedy_replace(pop, vals, i, cand, v):\n                best, bs = bump(best, bs, v, cand)\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\ndef _ks_gwo(ctx, p, rng):\n    \"\"\"二进制灰狼：α/β/δ 三头狼逐位投票（bGWO 的 majority 思想）+ 递减随机翻转。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    order = sorted(range(p[\"n_pop\"]), key=lambda i: vals[i], reverse=True)\n    al, be, de = pop[order[0]], pop[order[1]], pop[order[2]]\n    best, bs = vals[order[0]], list(pop[order[0]])\n    for it in range(1, p[\"max_iter\"] + 1):\n        a = 2.0 * (1 - it / p[\"max_iter\"])\n        for i in range(p[\"n_pop\"]):\n            cand = []\n            for k in range(ctx.n):\n                votes = al[k] + be[k] + de[k]\n                bit = 1 if votes >= 2 else 0\n                if rng.random() < 0.15 * a:  # 后期随机翻转减少 → 收缩\n                    bit ^= 1\n                cand.append(bit)\n            cand = ctx.repair(cand)\n            cand = ctx.polish(cand, rng, 3)\n            v = ctx.value(cand)\n            if greedy_replace(pop, vals, i, cand, v):\n                best, bs = bump(best, bs, v, cand)\n        order = sorted(range(p[\"n_pop\"]), key=lambda i: vals[i], reverse=True)\n        al, be, de = pop[order[0]], pop[order[1]], pop[order[2]]\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\ndef _ks_cs(ctx, p, rng):\n    \"\"\"布谷鸟（二进制，种群版）：新蛋 = 从最优巢出发做莱维翻转（标准 CS 以 best 为中心）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals)\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(p[\"n_pop\"]):\n            levy = rng.paretovariate(1.5)\n            k = max(1, min(ctx.n - 1, int(ctx.n * 0.12 * levy)))\n            base = pop[bi] if rng.random() < 0.6 else pop[i]  # 偏向最优巢的莱维游走\n            cand = list(base)\n            for _ in range(k):\n                cand[rng.randrange(ctx.n)] ^= 1\n            cand = ctx.repair(cand)\n            v2 = ctx.value(cand)\n            if greedy_replace(pop, vals, i, cand, v2):\n                best, bs = bump(best, bs, v2, cand)\n        for i in range(p[\"n_pop\"]):  # 弃巢重建\n            if rng.random() < p[\"pa\"]:\n                pop[i], vals[i] = ctx.random(rng), 0\n                vals[i] = ctx.value(pop[i])\n        bi = argbest(vals)\n        best, bs = bump(best, bs, vals[bi], pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": max(vals), \"best_sol\": bs}\n\n\n# ============================================================\n# 域二：连续函数基准（实数编码——PSO/DE/GWO/WOA/SCA 的原生域）\n# ============================================================\n\ndef _fn_sphere(x):\n    return sum(v * v for v in x)\n\n\ndef _fn_rosenbrock(x):\n    return sum(100 * (x[i + 1] - x[i] * x[i]) ** 2 + (1 - x[i]) ** 2 for i in range(len(x) - 1))\n\n\ndef _fn_rastrigin(x):\n    return 10 * len(x) + sum(v * v - 10 * math.cos(2 * math.pi * v) for v in x)\n\n\ndef _fn_ackley(x):\n    n = len(x)\n    s1 = sum(v * v for v in x) / n\n    s2 = sum(math.cos(2 * math.pi * v) for v in x) / n\n    return -20 * math.exp(-0.2 * math.sqrt(s1)) - math.exp(s2) + 20 + math.e\n\n\nFUNCS = {\"sphere\": (_fn_sphere, -5.0, 5.0, 0.0),\n         \"rosenbrock\": (_fn_rosenbrock, -2.2, 2.2, 0.0),\n         \"rastrigin\": (_fn_rastrigin, -5.0, 5.0, 0.0),\n         \"ackley\": (_fn_ackley, -5.0, 5.0, 0.0)}\n\n\n# ============================================================\n# H3 期：BBOB 基准套件（COCO, Hansen et al. 2009）子集接入 continuous 域。\n# 仅追加、零修改 FUNCS 字面量——下方 FUNCS.update 注入。选入 6 个无噪可分函数：\n# f1 球（同 sphere）、f2 椭球（条件数 1e6）、f3 雪茄、f4 铁饼、f5 异次幂、\n# f6 尖脊。全部在原点取最优 0、定义域 [-5,5]^d，与既有连续函数口径一致。\n# 编号说明：f1/f2 与 COCO 官方编号一致；f3-f6 为本站教学序，取的是 BBOB\n# 套件真实函数（Bent Cigar/Discus/Different Powers/Sharp Ridge），但非 COCO\n# 官方 f3-f6（separable Rastrigin/Büche-Rastrigin/Linear Slope/Attractive Sector）。\n# ============================================================\n\ndef _fn_bbob_f1(x):\n    return sum(v * v for v in x)\n\n\ndef _fn_bbob_f2(x):\n    d = len(x)\n    if d <= 1:\n        return x[0] * x[0]\n    return sum((10 ** (6.0 * i / (d - 1))) * x[i] * x[i] for i in range(d))\n\n\ndef _fn_bbob_f3(x):  # 雪茄\n    return x[0] * x[0] + 10 ** 6 * sum(v * v for v in x[1:])\n\n\ndef _fn_bbob_f4(x):  # 铁饼\n    return 10 ** 6 * x[0] * x[0] + sum(v * v for v in x[1:])\n\n\ndef _fn_bbob_f5(x):  # 异次幂\n    d = len(x)\n    if d <= 1:\n        return x[0] * x[0]\n    return sum(abs(x[i]) ** (2 + 4.0 * i / (d - 1)) for i in range(d))\n\n\ndef _fn_bbob_f6(x):  # 尖脊\n    return x[0] * x[0] + 100.0 * math.sqrt(sum(v * v for v in x[1:]))\n\n\n# ------------------------------------------------------------------\n# 2026-10 补充的经典连续基准（Jamil & Yang 2013 的全局优化测试函数目录里的标准定义）。\n# 都平移 / 书写成「最优值 = 0」，与既有函数同口径；搜索范围取文献里的通用范围。\n#   griewank       [-600,600]  多峰，峰谷规则、维度越高越平缓\n#   levy           [-10,10]    多峰，最优在 (1,…,1) 而不在原点\n#   schwefel       [-500,500]  欺骗性：次优解离最优解极远（最优在 420.9687 附近，靠近边界）\n#   zakharov       [-5,10]     单峰，变量之间有耦合\n#   dixon_price    [-10,10]    单峰、谷形，最优点各维不同\n#   styblinski_tang [-5,5]     多峰，每一维有两个谷（加常数 39.16617·d 使最优为 0）\n# ------------------------------------------------------------------\n\ndef _fn_griewank(x):\n    return 1.0 + sum(v * v for v in x) / 4000.0 - math.prod(math.cos(v / math.sqrt(i + 1)) for i, v in enumerate(x))\n\n\ndef _fn_levy(x):\n    w = [1.0 + (v - 1.0) / 4.0 for v in x]\n    s = math.sin(math.pi * w[0]) ** 2\n    s += sum((w[i] - 1.0) ** 2 * (1.0 + 10.0 * math.sin(math.pi * w[i] + 1.0) ** 2) for i in range(len(w) - 1))\n    s += (w[-1] - 1.0) ** 2 * (1.0 + math.sin(2.0 * math.pi * w[-1]) ** 2)\n    return s\n\n\ndef _fn_schwefel(x):\n    return 418.9828872724338 * len(x) - sum(v * math.sin(math.sqrt(abs(v))) for v in x)\n\n\ndef _fn_zakharov(x):\n    s = sum(0.5 * (i + 1) * v for i, v in enumerate(x))\n    return sum(v * v for v in x) + s ** 2 + s ** 4\n\n\ndef _fn_dixon_price(x):\n    return (x[0] - 1.0) ** 2 + sum((i + 1) * (2.0 * x[i] ** 2 - x[i - 1]) ** 2 for i in range(1, len(x)))\n\n\ndef _fn_styblinski_tang(x):\n    return 0.5 * sum(v ** 4 - 16.0 * v * v + 5.0 * v for v in x) + 39.16616570377142 * len(x)\n\n\n_NEW_FUNCS = {\"griewank\": (_fn_griewank, -600.0, 600.0, 0.0),\n              \"levy\": (_fn_levy, -10.0, 10.0, 0.0),\n              \"schwefel\": (_fn_schwefel, -500.0, 500.0, 0.0),\n              \"zakharov\": (_fn_zakharov, -5.0, 10.0, 0.0),\n              \"dixon_price\": (_fn_dixon_price, -10.0, 10.0, 0.0),\n              \"styblinski_tang\": (_fn_styblinski_tang, -5.0, 5.0, 0.0)}\n\nFUNCS.update({\n    \"bbob_f1\": (_fn_bbob_f1, -5.0, 5.0, 0.0),\n    \"bbob_f2\": (_fn_bbob_f2, -5.0, 5.0, 0.0),\n    \"bbob_f3\": (_fn_bbob_f3, -5.0, 5.0, 0.0),\n    \"bbob_f4\": (_fn_bbob_f4, -5.0, 5.0, 0.0),\n    \"bbob_f5\": (_fn_bbob_f5, -5.0, 5.0, 0.0),\n    \"bbob_f6\": (_fn_bbob_f6, -5.0, 5.0, 0.0),\n})\nFUNCS.update(_NEW_FUNCS)\n\n\ndef cn_make(fn=\"rastrigin\", dim=2, seed=7):\n    f, lo, hi, opt = FUNCS[fn]\n    return {\"fn\": fn, \"dim\": dim, \"lo\": lo, \"hi\": hi, \"optimum\": opt}\n\n\nclass _CN:\n    def __init__(self, problem):\n        self.f, self.lo, self.hi, _ = FUNCS[problem[\"fn\"]]\n        self.dim = problem[\"dim\"]\n\n    def random(self, rng):\n        return [rng.uniform(self.lo, self.hi) for _ in range(self.dim)]\n\n    def eval(self, x):\n        return self.f(x)\n\n    def clamp(self, x):\n        return [min(self.hi, max(self.lo, v)) for v in x]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.eval(x) for x in pop]\n\n\ndef _cn_state(ctx, it, best, bpos, pop, vals):\n    return {\"iter\": it, \"best\": best, \"gbest_pos\": list(bpos[:2]), \"best_sol\": list(bpos),\n            \"particles\": [list(x[:2]) for x in pop], \"cur\": sum(vals) / len(vals)}\n\n\ndef _sym_eig(A, dim, n_rot=100):\n    \"\"\"对称矩阵 Jacobi 特征分解：返回 (特征值列表, 特征向量阵 B)。\n\n    B 的列是特征向量，满足 A ≈ B·diag(λ)·Bᵀ。用于 CMA-ES 协方差采样\n    （C^{1/2}=B·diag(√λ)·Bᵀ、C^{-1/2}=B·diag(1/√λ)·Bᵀ）。连续域 dim≤~20，\n    每代一次足够快；收敛阈值 1e-12，封顶 n_rot 次旋转保底。\n    \"\"\"\n    a = [row[:] for row in A]\n    V = [[1.0 if i == j else 0.0 for j in range(dim)] for i in range(dim)]\n    for _ in range(n_rot):\n        p, q, mx = 0, 1, 0.0\n        for i in range(dim):\n            for j in range(i + 1, dim):\n                if abs(a[i][j]) > mx:\n                    mx = abs(a[i][j]); p, q = i, j\n        if mx < 1e-12:\n            break\n        app, aqq, apq = a[p][p], a[q][q], a[p][q]\n        th = math.pi / 4 if app == aqq else 0.5 * math.atan2(2.0 * apq, aqq - app)\n        c, s = math.cos(th), math.sin(th)\n        for i in range(dim):\n            if i != p and i != q:\n                aip, aiq = a[i][p], a[i][q]\n                a[i][p] = c * aip - s * aiq\n                a[i][q] = s * aip + c * aiq\n                a[p][i] = a[i][p]\n                a[q][i] = a[i][q]\n        a[p][p] = c * c * app - 2.0 * c * s * apq + s * s * aqq\n        a[q][q] = s * s * app + 2.0 * c * s * apq + c * c * aqq\n        a[p][q] = 0.0\n        a[q][p] = 0.0\n        for i in range(dim):\n            vip, viq = V[i][p], V[i][q]\n            V[i][p] = c * vip - s * viq\n            V[i][q] = s * vip + c * viq\n    return [a[i][i] for i in range(dim)], V\n\n\ndef _cn_random(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(p[\"n_pop\"]):\n            pop[i] = ctx.random(rng)\n            vals[i] = ctx.eval(pop[i])\n            best, bpos = bump(best, bpos, vals[i], pop[i], \"min\")\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_hc(ctx, p, rng):\n    x = ctx.random(rng)\n    best = ctx.eval(x)\n    bpos = list(x)\n    sigma = p[\"sigma\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        cand = ctx.clamp([v + rng.gauss(0, sigma) for v in x])\n        c = ctx.eval(cand)\n        if c <= ctx.eval(x):\n            x = cand\n        if c < best:\n            best, bpos = c, list(cand)\n            stall = 0\n        else:\n            stall += 1\n        # 多起点重启：爬山法困在局部谷时，在历史最优附近随机重撒——\n        # 若原样回到 bpos，贪心下降会沿同一轨迹落回同一个谷（实测教训）\n        if stall >= p[\"restart_at\"]:\n            x = ctx.clamp([b + rng.gauss(0, 0.8) for b in bpos])\n            sigma = max(p[\"sigma\"], 0.4)\n            stall = 0\n        sigma *= 0.995\n        yield {\"iter\": it, \"best\": best, \"gbest_pos\": list(bpos[:2]), \"best_sol\": list(bpos),\n               \"particles\": [list(x[:2])], \"cur\": ctx.eval(x)}\n\n\ndef _cn_sa(ctx, p, rng):\n    x = ctx.random(rng)\n    v = ctx.eval(x)\n    best, bpos = v, list(x)\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    span = ctx.hi - ctx.lo\n    stall = 0\n    boost = 0.0  # 重启时的步长加热（与接受温度解耦——教训：二者耦合会让收尾变粗糙）\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        width = 0.1 * span * max(1.0 - it / p[\"max_iter\"], 0.02) * (1.0 + boost)\n        cand = ctx.clamp([b + rng.gauss(0, width) for b in x])\n        v2 = ctx.eval(cand)\n        d = v2 - v\n        if d < 0 or (T > 1e-12 and rng.random() < math.exp(-d / T)):\n            x, v = cand, v2\n        if v < best:\n            best, bpos = v, list(x)\n            stall = 0\n        else:\n            stall += 1\n        # 重启策略（SA 工程化标准组件）：长期无改进就回到历史最优并重新加热步长，\n        # 避免单链在多峰地形（Rastrigin 类）里永久困死\n        if stall >= p[\"restart_at\"]:\n            x = list(bpos)\n            v = best\n            boost = 1.0\n            stall = 0\n        boost *= 0.9\n        yield {\"iter\": it, \"best\": best, \"gbest_pos\": list(bpos[:2]), \"best_sol\": list(bpos),\n               \"particles\": [list(x[:2])], \"cur\": v}\n\n\ndef _cn_pso(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    vel = [[rng.uniform(-0.5, 0.5) * (ctx.hi - ctx.lo) * 0.1 for _ in range(ctx.dim)] for _ in range(p[\"n_pop\"])]\n    pbest = [list(x) for x in pop]\n    pv = list(vals)\n    bi = argbest(vals, \"min\")\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        w = p[\"w_max\"] - (p[\"w_max\"] - p[\"w_min\"]) * it / p[\"max_iter\"]\n        for i in range(p[\"n_pop\"]):\n            for d in range(ctx.dim):\n                r1, r2 = rng.random(), rng.random()\n                vel[i][d] = (w * vel[i][d] + p[\"c1\"] * r1 * (pbest[i][d] - pop[i][d])\n                             + p[\"c2\"] * r2 * (bpos[d] - pop[i][d]))\n                vel[i][d] = max(-1.0, min(1.0, vel[i][d])) * (ctx.hi - ctx.lo) * 0.2\n            pop[i] = ctx.clamp([pop[i][d] + vel[i][d] for d in range(ctx.dim)])\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < pv[i]:\n                pbest[i], pv[i] = list(pop[i]), vals[i]\n                best, bpos = bump(best, bpos, vals[i], pop[i], \"min\")\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_de(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(p[\"n_pop\"]):\n            r1, r2, r3 = rng.sample([j for j in range(p[\"n_pop\"]) if j != i], 3)\n            F = p[\"F\"] * (0.5 + rng.random())\n            mutant = [pop[r1][d] + F * (pop[r2][d] - pop[r3][d]) for d in range(ctx.dim)]\n            trial = [mutant[d] if rng.random() < p[\"CR\"] else pop[i][d] for d in range(ctx.dim)]\n            trial = ctx.clamp(trial)\n            v = ctx.eval(trial)\n            if v <= vals[i]:\n                pop[i], vals[i] = trial, v\n                best, bpos = bump(best, bpos, v, trial, \"min\")\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_gwo(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    order = sorted(range(p[\"n_pop\"]), key=lambda i: vals[i])\n    al, be, de = list(pop[order[0]]), list(pop[order[1]]), list(pop[order[2]])\n    best, bpos = vals[order[0]], list(pop[order[0]])\n    for it in range(1, p[\"max_iter\"] + 1):\n        a = 2.0 * (1 - it / p[\"max_iter\"])\n        for i in range(p[\"n_pop\"]):\n            # 标准 GWO：Xi = Xleader - A·|C·Xleader - X|，A/C 都是随机系数向量\n            def _upd(leader):\n                A = a * (2 * rng.random() - 1)\n                C = 2 * rng.random()\n                return [leader[d] - A * abs(C * leader[d] - pop[i][d]) for d in range(ctx.dim)]\n            x1, x2, x3 = _upd(al), _upd(be), _upd(de)\n            pop[i] = ctx.clamp([(x1[d] + x2[d] + x3[d]) / 3 for d in range(ctx.dim)])\n            vals[i] = ctx.eval(pop[i])\n            best, bpos = bump(best, bpos, vals[i], pop[i], \"min\")\n        order = sorted(range(p[\"n_pop\"]), key=lambda i: vals[i])\n        al, be, de = list(pop[order[0]]), list(pop[order[1]]), list(pop[order[2]])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_woa(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        a = 2.0 * (1 - it / p[\"max_iter\"])\n        for i in range(p[\"n_pop\"]):\n            r1, r2 = rng.random(), rng.random()\n            A = 2 * a * r1 - a\n            C = 2 * r2\n            if rng.random() < 0.5:\n                if abs(A) < 1:  # 包围猎物\n                    cand = [bpos[d] - A * abs(C * bpos[d] - pop[i][d]) for d in range(ctx.dim)]\n                else:  # 搜索猎物\n                    rand = pop[rng.randrange(p[\"n_pop\"])]\n                    cand = [rand[d] - A * abs(C * rand[d] - pop[i][d]) for d in range(ctx.dim)]\n            else:  # 螺旋更新\n                b, l = 1.0, rng.uniform(-1, 1)\n                cand = [bpos[d] + math.exp(b * l) * math.cos(2 * math.pi * l)\n                        * abs(bpos[d] - pop[i][d]) for d in range(ctx.dim)]\n            pop[i] = ctx.clamp(cand)\n            vals[i] = ctx.eval(pop[i])\n            best, bpos = bump(best, bpos, vals[i], pop[i], \"min\")\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_sca(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1 = p[\"a_max\"] - (p[\"a_max\"]) * it / p[\"max_iter\"]\n        for i in range(p[\"n_pop\"]):\n            r2, r3, r4 = 2 * math.pi * rng.random(), rng.random(), rng.random()\n            step = r1 * math.sin(r2) if r4 < 0.5 else r1 * math.cos(r2)\n            pop[i] = ctx.clamp([pop[i][d] + step * abs(r3 * bpos[d] - pop[i][d]) for d in range(ctx.dim)])\n            vals[i] = ctx.eval(pop[i])\n            best, bpos = bump(best, bpos, vals[i], pop[i], \"min\")\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_cmaes(ctx, p, rng):\n    \"\"\"CMA-ES（Hansen & Ostermeier 2001）：连续域 SOTA 级演化策略——本站主场。\n\n    全协方差矩阵自适应 + 步长 σ 自适应 + 进化路径 pc/ps 全套标准 (μ,λ)-CMA-ES：\n      每代对协方差 C 做 Jacobi 特征分解 → B·diag(√λ)·Bᵀ 采样；\n      选 μ 个精英更新均值、pc、ps、C、σ（秩一 + 秩μ 协方差更新）。\n    与 TSP 侧 separable 版不同，这里是**全协方差**（连续域 dim 小，特征分解不重），\n    正是 CMA-ES 相对 EDA / sep-CMA 的招牌能力：自动学习地形条件数。\n    \"\"\"\n    dim = ctx.dim\n    n_pop = int(p[\"n_pop\"])\n    mu = max(1, n_pop // 2)\n    weights = [math.log(mu + 0.5) - math.log(i + 1) for i in range(mu)]\n    wsum = sum(weights)\n    weights = [w / wsum for w in weights]\n    mueff = (sum(weights)) ** 2 / sum(w * w for w in weights)\n    cc = 4.0 / (dim + 4.0)\n    cs = (mueff + 2.0) / (dim + mueff + 3.0)\n    c1 = 2.0 / ((dim + 1.3) ** 2 + mueff)\n    cmu = min(1.0 - c1, 2.0 * (mueff - 2.0 + 1.0 / mueff) / ((dim + 2.0) ** 2 + mueff))\n    damps = 1.0 + 2.0 * max(0.0, math.sqrt((mueff - 1.0) / (dim + 1.0)) - 1.0) + cs\n    chiN = math.sqrt(dim) * (1.0 - 1.0 / (4.0 * dim) + 1.0 / (21.0 * dim ** 2))\n\n    span = ctx.hi - ctx.lo\n    m = ctx.random(rng)\n    sigma = span / 3.0\n    C = [[1.0 if i == j else 0.0 for j in range(dim)] for i in range(dim)]\n    pc = [0.0] * dim\n    ps = [0.0] * dim\n    best = float(\"inf\")\n    bpos = list(m)\n    eigvals, B = _sym_eig(C, dim)\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        sq = [math.sqrt(max(eigvals[i], 1e-14)) for i in range(dim)]\n        invsq = [1.0 / sq[i] for i in range(dim)]\n        pop, vals = [], []\n        for _k in range(n_pop):\n            z = [rng.gauss(0.0, 1.0) for _ in range(dim)]\n            # y = B·(√λ·(Bᵀ z))\n            vtz = [sum(B[p][i] * z[p] for p in range(dim)) for i in range(dim)]\n            w = [sq[i] * vtz[i] for i in range(dim)]\n            y = [sum(B[i][p] * w[p] for p in range(dim)) for i in range(dim)]\n            x = [m[d] + sigma * y[d] for d in range(dim)]\n            # 边界处理：评价与上报用投影回搜索范围的点 xe；协方差 / 均值的更新仍用未投影的 x（标准做法）。\n            # 此前直接在范围外评价——Schwefel 这类范围外函数值更低的函数上，「最优」跑到了范围外（-1e13）\n            xe = ctx.clamp(x)\n            v = ctx.eval(xe)\n            pop.append(x); vals.append(v)\n            best, bpos = bump(best, bpos, v, xe, \"min\")\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        sel = order[:mu]\n        old_m = m\n        m = [sum(weights[i] * pop[sel[i]][d] for i in range(mu)) for d in range(dim)]\n        ymean = [(m[d] - old_m[d]) / sigma for d in range(dim)]\n        # 步长路径 ps 用 C^{-1/2}\n        vtc = [sum(B[p][i] * ymean[p] for p in range(dim)) for i in range(dim)]\n        w2 = [invsq[i] * vtc[i] for i in range(dim)]\n        cinv = [sum(B[i][p] * w2[p] for p in range(dim)) for i in range(dim)]\n        ps = [(1 - cs) * ps[d] + math.sqrt(cs * (2 - cs) * mueff) * cinv[d] for d in range(dim)]\n        hsig = (math.sqrt(sum(pp * pp for pp in ps)) /\n                math.sqrt(1 - (1 - cs) ** (2 * it)) / chiN) < (1.4 + 2.0 / (dim + 1.0))\n        pc = [(1 - cc) * pc[d] + hsig * math.sqrt(cc * (2 - cc) * mueff) * ymean[d] for d in range(dim)]\n        ci = cmu  # Σweights = 1\n        newC = [[0.0] * dim for _ in range(dim)]\n        for d1 in range(dim):\n            for d2 in range(dim):\n                newC[d1][d2] = (1 - c1 - ci) * C[d1][d2] + c1 * (pc[d1] * pc[d2] + hsig * (2 - hsig) * C[d1][d2])\n        for i in range(mu):\n            yi = [(pop[sel[i]][d] - old_m[d]) / sigma for d in range(dim)]\n            wi = weights[i]\n            for d1 in range(dim):\n                for d2 in range(d1, dim):\n                    newC[d1][d2] += cmu * wi * yi[d1] * yi[d2]\n        for d1 in range(dim):\n            for d2 in range(d1 + 1, dim):\n                newC[d2][d1] = newC[d1][d2]\n        C = newC\n        sigma *= math.exp((cs / damps) * (math.sqrt(sum(pp * pp for pp in ps)) / chiN - 1.0))\n        eigvals, B = _sym_eig(C, dim)\n        cur = sum(vals) / n_pop\n        yield _cn_state(ctx, it, best, bpos, [ctx.clamp(q) for q in pop], vals)\n\n\n# ============================================================\n# 域三：双目标背包（多目标入门）\n# ============================================================\n\ndef mo_make(variant=\"moco\", n=40, seed=7):\n    rng = random.Random(seed)\n    items = []\n    for _ in range(n):\n        w = rng.randint(2, 60)\n        v1 = rng.randint(10, 100)\n        # ★ 两个收益必须独立（甚至部分负相关）：若 v2 由 v1 派生，前沿会退化成\n        #   单点支配——教训来自首次实现，测试 test_multiobj_front_shape 看着它\n        v2 = rng.randint(10, 100)\n        if variant == \"maop\":\n            # 三目标：再加一个独立收益 v3，三目标前沿需 NSGA-II 才能覆盖非凸面\n            v3 = rng.randint(10, 100)\n            items.append([w, v1, v2, v3])\n        else:\n            items.append([w, v1, v2])\n    cap = int(sum(x[0] for x in items) * 0.45)\n    return {\"variant\": variant, \"n\": n, \"cap\": cap, \"items\": items}\n\n\ndef _mo_spea2(ctx, p, rng):\n    \"\"\"SPEA2（Zitzler et al., 2001）：强度 Pareto + 密度截断（经典）。\n    F(i)=R(i)+D(i)；R=支配者强度之和，D=1/(σ^k+2)，archive 超容量按最近邻迭代删除。\"\"\"\n    n_pop, arc_cap = p[\"n_pop\"], p[\"n_pop\"]\n    no = ctx.no\n    pop = ctx.init_pop(p, rng)\n    archive = []\n    for it in range(1, p[\"max_iter\"] + 1):\n        union = list(pop) + list(archive)\n        U = [ctx.fs(x)[:no] for x in union]\n        n = len(union)\n        dom = [[False] * n for _ in range(n)]\n        for a in range(n):\n            for b in range(n):\n                if a != b and all(U[a][k] >= U[b][k] for k in range(no)) \\\n                        and any(U[a][k] > U[b][k] for k in range(no)):\n                    dom[a][b] = True  # a 支配 b\n        S = [sum(dom[a]) for a in range(n)]\n        R = [sum(S[j] for j in range(n) if dom[j][i]) for i in range(n)]\n        kth = int(n ** 0.5)  # 正典 k≈sqrt(n)（终审C #3 修正：原 sqrt(n+arc_cap) 偏大）\n        dist = [[sum((U[a][k2] - U[b][k2]) ** 2 for k2 in range(no)) ** 0.5 for b in range(n)]\n                for a in range(n)]\n        Fit = []\n        for i in range(n):\n            dd = sorted(dist[i])[kth] if len(dist[i]) > kth else max(dist[i])\n            Fit.append(R[i] + 1.0 / (dd + 2.0))\n        nd_idx = [i for i in range(n) if Fit[i] < 1.0]\n        if len(nd_idx) < arc_cap:\n            rest = sorted((i for i in range(n) if Fit[i] >= 1.0), key=lambda i: Fit[i])\n            keep = nd_idx + rest[:arc_cap - len(nd_idx)]\n        else:\n            keep = list(nd_idx)\n            while len(keep) > arc_cap:  # 正典 σ 最近邻迭代删除\n                worst = min(keep, key=lambda i2: min((dist[i2][j2] for j2 in keep if j2 != i2), default=9e9))\n                keep.remove(worst)\n        archive = [union[i] for i in keep]  # archive 存解本体（union 全为解，fs 每代重算）\n        # 新种群：archive 二进制锦标赛（Fit 小优）+ 均匀交叉 + 位变异\n        new_pop = []\n        while len(new_pop) < n_pop:\n            a, b = rng.sample(range(len(archive)), 2) if len(archive) >= 2 else (0, 0)\n            pa = archive[a] if Fit[keep[a]] <= Fit[keep[b]] else archive[b]\n            pb = archive[rng.randrange(len(archive))]\n            c = bits_uniform(pa, pb, rng) if rng.random() < p[\"pc\"] else list(pa)\n            bits_mutate(c, p[\"pm\"], rng)\n            new_pop.append(ctx.repair(c))\n        pop = new_pop\n        # 终审C 修正：yield 必须投影回目标空间（archive 存的是解位串），nd 为真实非支配数\n        AF = [ctx.fs(x)[:no] for x in archive]\n        _, afronts = _mo_nd_sort(AF)\n        yield {\"iter\": it, \"pop\": [list(f) for f in AF[:min(8, len(AF))]],\n               \"front\": [list(f) for f in AF], \"nd\": len(afronts[0])}\n\n\ndef _mo_moead(ctx, p, rng):\n    \"\"\"MOEA-D（Zhang & Li, 2007）：Tchebycheff 分解 + 权重向量邻域 + 理想点追踪。\n    最大化目标的 Tchebycheff：g(x)=max_j w_j·|z*_j − f_j(x)|，z*_j=历史最大 f_j，g 越小越好。\"\"\"\n    n_pop = p[\"n_pop\"]\n    if ctx.no == 2:\n        H = max(1, n_pop - 1)\n        W = [[i / H, 1.0 - i / H] for i in range(H + 1)][:n_pop]  # Das-Dennis 单纯形网格（双目标）\n    else:  # 3+ 目标：随机归一化权重（文献常用变体）\n        W = []\n        for _ in range(n_pop):\n            wv = [rng.random() + 0.05 for _ in range(ctx.no)]\n            sw = sum(wv)\n            W.append([w / sw for w in wv])\n    T = max(2, n_pop // 10)\n    pop = ctx.init_pop(p, rng)\n    F = [ctx.fs(x)[:ctx.no] for x in pop]\n    B = []  # 邻域：权重欧氏最近的 T 个\n    for i in range(n_pop):\n        dists = sorted(range(n_pop), key=lambda j: sum((W[i][k] - W[j][k]) ** 2 for k in range(ctx.no)))\n        B.append(dists[:T])\n    z = [max(f[j] for f in F) for j in range(ctx.no)]  # 理想点（最大化）\n    def _g(w, f):\n        return max(w[k] * abs(z[k] - f[k]) for k in range(ctx.no))\n    for it in range(1, p[\"max_iter\"] + 1):\n        i_sub = it % n_pop\n        pa, pb = (pop[j] for j in rng.sample(B[i_sub], 2))\n        c = bits_uniform(pa, pb, rng) if rng.random() < p[\"pc\"] else list(pa)\n        bits_mutate(c, p[\"pm\"], rng)\n        c = ctx.repair(c)\n        fc = ctx.fs(c)[:ctx.no]\n        for k in range(ctx.no):\n            if fc[k] > z[k]:\n                z[k] = fc[k]\n        for j in B[i_sub]:\n            if _g(W[j], fc) <= _g(W[j], F[j]):\n                pop[j], F[j] = c, list(fc)\n        _, fronts = _mo_nd_sort(F)\n        arch = [F[i] for i in fronts[0]]\n        yield {\"iter\": it, \"pop\": [list(f) for f in F], \"front\": [list(f) for f in arch], \"nd\": len(arch)}\n\n\ndef _mo_nd_sort(F):\n    \"\"\"快速非支配排序（最大化 m 目标，m 任意）。返回 ranks 列表与各层索引。\"\"\"\n    n = len(F)\n    m = len(F[0]) if n else 0\n    S = [[] for _ in range(n)]\n    ndc = [0] * n\n    ranks = [0] * n\n    fronts = [[]]\n    for i in range(n):\n        for j in range(i + 1, n):\n            a, b = F[i], F[j]\n            a_dom = all(a[d] >= b[d] for d in range(m)) and a != b\n            b_dom = all(b[d] >= a[d] for d in range(m)) and a != b\n            if a_dom:\n                S[i].append(j)\n                ndc[j] += 1\n            elif b_dom:\n                S[j].append(i)\n                ndc[i] += 1\n    for i in range(n):\n        if ndc[i] == 0:\n            ranks[i] = 0\n            fronts[0].append(i)\n    k = 0\n    while fronts[k]:\n        nxt = []\n        for i in fronts[k]:\n            for j in S[i]:\n                ndc[j] -= 1\n                if ndc[j] == 0:\n                    ranks[j] = k + 1\n                    nxt.append(j)\n        k += 1\n        fronts.append(nxt)\n    return ranks, [f for f in fronts if f]\n\n\ndef _mo_crowding(F, idxs):\n    m = len(F[0]) if F else 0\n    if len(idxs) <= 2:\n        return {i: float(\"inf\") for i in idxs}\n    dist = {i: 0.0 for i in idxs}\n    for d in range(m):\n        order = sorted(idxs, key=lambda i: F[i][d])\n        dist[order[0]] = dist[order[-1]] = float(\"inf\")\n        lo, hi = F[order[0]][d], F[order[-1]][d]\n        rng_ = hi - lo\n        if rng_ <= 0:\n            continue\n        for k in range(1, len(order) - 1):\n            dist[order[k]] += (F[order[k + 1]][d] - F[order[k - 1]][d]) / rng_\n    return dist\n\n\nclass _MO:\n    \"\"\"多目标背包（variant=moco 双目标 / maop 三目标）：no 自适应目标数，fs 返回 [v1(,v2,v3),w]（末位为约束）。\"\"\"\n\n    def __init__(self, problem):\n        self.items = [tuple(x) for x in problem[\"items\"]]  # (w, v1[, v2, v3])\n        self.cap = problem[\"cap\"]\n        self.n = problem[\"n\"]\n        self.no = len(self.items[0]) - 1  # 目标数自适应：双目标 items 宽 3、三目标宽 4\n\n    def fs(self, s):\n        v1 = v2 = 0\n        w = 0\n        for i in range(self.n):\n            if s[i]:\n                w += self.items[i][0]\n                v1 += self.items[i][1]\n                v2 += self.items[i][2]\n        return [v1, v2, w]\n\n    def repair(self, s):\n        s = list(s)\n        f = self.fs(s)\n        if f[self.no] <= self.cap:\n            return s\n        idx = [i for i in range(self.n) if s[i]]\n        idx.sort(key=lambda i: (self.items[i][1] + self.items[i][2]) / max(1, self.items[i][0]))\n        for i in idx:\n            if self.fs(s)[self.no] <= self.cap:\n                break\n            s[i] = 0\n        return s\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.5 else 0 for _ in range(self.n)])\n\n    def init_pop(self, p, rng):\n        return [self.random(rng) for _ in range(p[\"n_pop\"])]\n\n\nclass _MO3:\n    \"\"\"三目标背包（variant=maop）：目标数 no=3，fs 返回 [v1,v2,v3,w]（w 为约束）。\n    与 _MO 共用全部 _mo_* 内核（已泛化到 m 目标），仅 fs/repair/no 不同。\"\"\"\n    no = 3\n\n    def __init__(self, problem):\n        self.items = [tuple(x) for x in problem[\"items\"]]  # (w, v1, v2, v3)\n        self.cap = problem[\"cap\"]\n        self.n = problem[\"n\"]\n\n    def fs(self, s):\n        v1 = v2 = v3 = 0\n        w = 0\n        for i in range(self.n):\n            if s[i]:\n                w += self.items[i][0]\n                v1 += self.items[i][1]\n                v2 += self.items[i][2]\n                v3 += self.items[i][3]\n        return [v1, v2, v3, w]\n\n    def repair(self, s):\n        s = list(s)\n        f = self.fs(s)\n        if f[self.no] <= self.cap:\n            return s\n        idx = [i for i in range(self.n) if s[i]]\n        idx.sort(key=lambda i: (self.items[i][1] + self.items[i][2] + self.items[i][3]) / max(1, self.items[i][0]))\n        for i in idx:\n            if self.fs(s)[self.no] <= self.cap:\n                break\n            s[i] = 0\n        return s\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.5 else 0 for _ in range(self.n)])\n\n    def init_pop(self, p, rng):\n        return [self.random(rng) for _ in range(p[\"n_pop\"])]\n\n\ndef _mo_states(pop, ctx):\n    F = [ctx.fs(s)[:ctx.no] for s in pop]\n    ranks, fronts = _mo_nd_sort(F)\n    front_pts = sorted((F[i] for i in fronts[0]), key=lambda p: (-p[0], p[1]))\n    return F, ranks, fronts, front_pts\n\n\ndef _mo_random(ctx, p, rng):\n    arch = []\n    for it in range(1, p[\"max_iter\"] + 1):\n        s = ctx.random(rng)\n        f = ctx.fs(s)[:ctx.no]\n        cand = arch + [f]\n        _, fronts = _mo_nd_sort(cand)\n        arch = [cand[i] for i in fronts[0]]\n        if len(arch) > 60:\n            arch = arch[::2]\n        yield {\"iter\": it, \"pop\": [ctx.fs(x)[:ctx.no] for x in [list(s)]], \"front\": [list(f) for f in arch], \"nd\": len(arch)}\n\n\ndef _mo_wsga(ctx, p, rng):\n    \"\"\"加权单目标和 GA（对照：经典加权法会漏掉非凸前沿段）。\"\"\"\n    pop = ctx.init_pop(p, rng)\n    for it in range(1, p[\"max_iter\"] + 1):\n        F = [ctx.fs(s)[:ctx.no] for s in pop]\n        # 加权法对任意 m 目标：随机权重归一化后线性合成（m=2 时退化为原 lam/(1-lam)）\n        lams = [rng.random() for _ in range(ctx.no)]\n        s_ = sum(lams) or 1.0\n        lams = [x / s_ for x in lams]\n        sc = [sum(lams[d] * f[d] for d in range(ctx.no)) for f in F]\n        bi = max(range(len(pop)), key=lambda i: sc[i])\n        new = [list(pop[bi])]\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(len(pop)), 2)\n            child = bits_uniform(pop[a], pop[b], rng)\n            bits_mutate(child, p[\"pm\"], rng)\n            new.append(ctx.repair(child))\n        pop = new\n        F, ranks, fronts, front_pts = _mo_states(pop, ctx)\n        yield {\"iter\": it, \"pop\": F, \"front\": front_pts, \"nd\": len(front_pts)}\n\n\ndef _mo_nsga2(ctx, p, rng):\n    \"\"\"NSGA-II（Deb et al., 2002）：非支配排序 + 拥挤度 + 精英保留。\"\"\"\n    pop = ctx.init_pop(p, rng)\n    for it in range(1, p[\"max_iter\"] + 1):\n        F, ranks, fronts, front_pts = _mo_states(pop, ctx)\n        # 二进制锦标赛（rank 小优先，同 rank 拥挤度大优先）\n        def tour():\n            a, b = rng.sample(range(len(pop)), 2)\n            if ranks[a] != ranks[b]:\n                return pop[a] if ranks[a] < ranks[b] else pop[b]\n            da = _mo_crowding(F, fronts[ranks[a]])[a]\n            db = _mo_crowding(F, fronts[ranks[b]])[b]\n            return pop[a] if da >= db else pop[b]\n\n        child = []\n        while len(child) < p[\"n_pop\"]:\n            pa, pb = tour(), tour()\n            c = bits_uniform(pa, pb, rng) if rng.random() < p[\"pc\"] else list(pa)\n            bits_mutate(c, p[\"pm\"], rng)\n            child.append(ctx.repair(c))\n        # 精英合并\n        union = pop + child\n        UF = [ctx.fs(s)[:ctx.no] for s in union]\n        uranks, ufronts = _mo_nd_sort(UF)\n        new = []\n        for fr in ufronts:\n            if len(new) + len(fr) <= p[\"n_pop\"]:\n                new.extend(union[i] for i in fr)\n            else:\n                cd = _mo_crowding(UF, fr)\n                fr_sorted = sorted(fr, key=lambda i: cd[i], reverse=True)\n                new.extend(union[i] for i in fr_sorted[: p[\"n_pop\"] - len(new)])\n                break\n        pop = new\n        F, ranks, fronts, front_pts = _mo_states(pop, ctx)\n        yield {\"iter\": it, \"pop\": F, \"front\": front_pts, \"nd\": len(front_pts)}\n\n\n# ---- NSGA-III 参考点小生境（Deb & Jain 2014，complete-a-kernels 2026-09-29）----\ndef _das_dennis(no, H):\n    \"\"\"Das-Dennis 单纯形参考点生成：所有非负整数向量 (w1..w_no) 和为 H，归一化到 [0,1]。\"\"\"\n    pts = []\n    def rec(rem, k, cur):\n        if k == no - 1:\n            pts.append([c / H for c in cur + [rem]])\n            return\n        for i in range(rem + 1):\n            rec(rem - i, k + 1, cur + [i])\n    rec(H, 0, [])\n    return pts\n\n\ndef _mo_nsga3(ctx, p, rng):\n    \"\"\"NSGA-III（Deb & Jain 2014）：Das-Dennis 参考点 + 垂直距离关联 + 小生境计数选择。\n    复用 _mo_nd_sort / bits_uniform / bits_mutate。max 目标（复用 _MO/_MO3 ctx）。\"\"\"\n    no = ctx.no\n    n_pop = p[\"n_pop\"]\n    H = 12 if no == 2 else 6\n    R = _das_dennis(no, H)\n    pop = ctx.init_pop(p, rng)\n    for it in range(1, p[\"max_iter\"] + 1):\n        F = [ctx.fs(s)[:no] for s in pop]\n        ranks, fronts = _mo_nd_sort(F)\n        off = []\n        while len(off) < n_pop:\n            a, b = rng.sample(range(len(pop)), 2)\n            pa = pop[a] if ranks[a] < ranks[b] else pop[b]\n            pb = pop[rng.randrange(len(pop))]\n            c = bits_uniform(pa, pb, rng) if rng.random() < p[\"pc\"] else list(pa)\n            bits_mutate(c, p[\"pm\"], rng)\n            off.append(ctx.repair(c))\n        union = pop + off\n        UF = [ctx.fs(s)[:no] for s in union]\n        uranks, ufronts = _mo_nd_sort(UF)\n        zmin = [min(f[j] for f in UF) for j in range(no)]\n        zmax = [max(f[j] for f in UF) for j in range(no)]\n        def normf(f):\n            return [(f[j] - zmin[j]) / (zmax[j] - zmin[j]) if (zmax[j] - zmin[j]) > 1e-9 else 0.0\n                    for j in range(no)]\n        assoc = []\n        for f in UF:\n            fn = normf(f)\n            best_r, best_d = 0, None\n            for ri, r in enumerate(R):\n                dot = sum(fn[d] * r[d] for d in range(no))\n                r2 = sum(x * x for x in r)\n                if r2 < 1e-12:\n                    d = _math.sqrt(sum(x * x for x in fn))\n                else:\n                    proj = dot / r2\n                    d = _math.sqrt(sum((fn[d] - proj * r[d]) ** 2 for d in range(no)))\n                if best_d is None or d < best_d:\n                    best_d, best_r = d, ri\n            assoc.append(best_r)\n        pop_sel = []\n        rho = [0] * len(R)\n        for fr in ufronts:\n            if len(pop_sel) + len(fr) <= n_pop:\n                for i in fr:\n                    pop_sel.append(union[i]); rho[assoc[i]] += 1\n            else:\n                I = [i for i in fr if rho[assoc[i]] == 0]\n                P = [i for i in fr if rho[assoc[i]] > 0]\n                while I and len(pop_sel) < n_pop:\n                    i = I.pop(rng.randrange(len(I)))\n                    if rho[assoc[i]] == 0:\n                        pop_sel.append(union[i]); rho[assoc[i]] += 1\n                    else:\n                        P.append(i)\n                while P and len(pop_sel) < n_pop:\n                    i = P.pop(rng.randrange(len(P)))\n                    pop_sel.append(union[i]); rho[assoc[i]] += 1\n                break\n        pop = pop_sel\n        Fpop = [ctx.fs(s)[:no] for s in pop]\n        _, ffronts = _mo_nd_sort(Fpop)\n        front_pts = sorted((Fpop[i] for i in ffronts[0]), key=lambda q: (-q[0],) + tuple(q[1:]))\n        yield {\"iter\": it, \"pop\": [list(f) for f in Fpop], \"front\": [list(f) for f in front_pts],\n               \"nd\": len(front_pts)}\n\n\n# ============================================================\n# 域四/五：排列域通用算法库（图着色 + 装箱共用）\n# ------------------------------------------------------------\n# 两个域同一个范式：编码 = 排列，解码 = 贪心 First-Fit——\n#   图着色：按排列顺序给顶点分配最小可用颜色（合法着色由构造保证）\n#   装箱：  按排列顺序把物品放进第一个放得下的箱子（FF 装箱）\n# 目标都是「min 主指标 + min 次级指标」字典序：\n#   图着色 (色数 k, Σci²)——色平方和鼓励空出高编号颜色桶（文献标准 tie-break）\n#   装箱   (箱数 b, Σ剩余²)——剩余平方和鼓励箱子塞紧\n# 算法内核因此可以只写一份（_pm_* 前缀），域差异全部压进 ctx——\n# 这正是「算法内核 = 探索/开发机制，问题绑定 = 编码+邻域+约束」骨架的第二次兑现。\n# ============================================================\n\n# _pm_ox / _pm_swap / _pm_insert / _pm_polish 已收编至 py/domain_components.py\n# （S1-1 组件化，import 处以 _pm_* 别名保持调用点不变）\n\n\ndef _pm_random(ctx, p, rng):\n    best, bc = None, None\n    for it in range(1, p[\"max_iter\"] + 1):\n        perm = ctx.random(rng)\n        c = ctx.decode(perm)\n        if bc is None or c < bc:\n            best, bc = perm, c\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_hc(ctx, p, rng):\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    for it in range(1, p[\"max_iter\"] + 1):\n        for _ in range(p[\"tries\"]):\n            # 交换 70% / 插入 30%：FF 类解码器对「块重排」更敏感——\n            # 纯交换在 plateau 上几乎全是等值解，实测会被随机基线反超（教训）\n            cand = _pm_swap(perm, rng) if rng.random() < 0.7 else _pm_insert(perm, rng)\n            cc = ctx.decode(cand)\n            # 平台侧移：等值也接受——FF 解码器的 plateau 巨大，\n            # 严格改进版会卡死在首个局部最优（seed21/42 实测被随机基线反超）\n            if cc <= c:\n                perm, c = cand, cc\n        bc, best = bump(bc, best, c, perm, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_sa(ctx, p, rng):\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        cand = _pm_swap(perm, rng) if rng.random() < 0.7 else _pm_insert(perm, rng)\n        cc = ctx.decode(cand)\n        d = ctx.diff(c, cc)\n        if d < 0 or (T > 1e-12 and rng.random() < math.exp(-d / T)):\n            perm, c = cand, cc\n        if c < bc:\n            best, bc = list(perm), c\n            stall = 0\n        else:\n            stall += 1\n        # 卡死重启（连续域 _cn_sa 同款组件）：回到历史最优 + 扰动 + 小预算下探，\n        # 避免单链在 FF 解码器的巨大 plateau 上永久滞留（实测被随机基线反超的教训）\n        if stall >= p[\"restart_at\"]:\n            perm, c = list(best), bc\n            for _ in range(2):\n                cand = _pm_swap(perm, rng)\n                perm, c = cand, ctx.decode(cand)  # 无条件扰动\n            perm = _pm_polish(ctx, perm, rng, p[\"polish\"])\n            c = ctx.decode(perm)\n            stall = 0\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_ts(ctx, p, rng):\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    tabu = {}\n    tenure, sample = p[\"tenure\"], p[\"ts_sample\"]\n    n = ctx.n\n    for it in range(1, p[\"max_iter\"] + 1):\n        bm, bcc, bkey = None, None, None\n        for _ in range(sample):\n            i, j = sorted(rng.sample(range(n), 2))\n            key = (i, j)\n            cand = list(perm)\n            cand[i], cand[j] = cand[j], cand[i]\n            cc = ctx.decode(cand)\n            # 特赦准则：禁忌移动若刷新历史最优也放行\n            if tabu.get(key, -1) >= it and not (bc is None or cc < bc):\n                continue\n            if bcc is None or cc < bcc:\n                bm, bcc, bkey = cand, cc, key\n        if bm is None:\n            perm = ctx.random(rng)\n            c = ctx.decode(perm)\n        else:\n            perm, c = bm, bcc\n            tabu[bkey] = it + tenure\n        bc, best = bump(bc, best, c, perm, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_ga(ctx, p, rng):\n    pop = [ctx.random(rng) for _ in range(p[\"n_pop\"])]\n    costs = [ctx.decode(x) for x in pop]\n    bi = argbest(costs, \"min\")\n    best, bc = list(pop[bi]), costs[bi]\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]  # 精英保留\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            child = _pm_ox(pop[a], pop[b], rng)\n            if rng.random() < p[\"pm\"]:\n                child = _pm_swap(child, rng)\n            new.append(child)\n        pop = new\n        costs = [ctx.decode(x) for x in pop]\n        bi = argbest(costs, \"min\")\n        # memetic：每代对当代最优做小预算下探\n        cand = _pm_polish(ctx, pop[bi], rng, p[\"polish\"])\n        cc = ctx.decode(cand)\n        if cc < costs[bi]:\n            pop[bi], costs[bi] = cand, cc\n        bc, best = bump(bc, best, costs[bi], pop[bi], \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": min(c[0] for c in costs), \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_de(ctx, p, rng):\n    \"\"\"排列版差分 DE（批 7 续）：三父体逐位差异——r1/r2 不同的位置以 F 概率借 r3 的值，\n    OX 式修复保持排列合法（重复值按序重排）。贪心接受。\"\"\"\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    F = p.get(\"F\", 0.7)\n    n = len(perm)\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1, r2, r3 = rng.sample(range(n), 3)\n        cand = list(perm)\n        for k in range(n):\n            if perm[r1] != perm[r2] and rng.random() < F:\n                # 借 r3 序列该位的值：找到 cand 中该值的位置换到 k\n                val = perm[r3]\n                pos = cand.index(val) if val in cand else k\n                cand[k], cand[pos] = cand[pos], cand[k]\n        cand = _pm_ox_repair(cand, perm)  # OX 式修复：以 perm 为参照保相对序\n        cand = _pm_polish(ctx, cand, rng, 8)  # memetic 打磨（与 gwo 同款补救）\n        cc = ctx.decode(cand)\n        if cc <= c:\n            perm, c = cand, cc\n        bc, best = bump(bc, best, cc, perm, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_ox_repair(child, ref):\n    \"\"\"OX 式修复：child 中缺失的值按 ref 相对序补回（保持排列合法）。\"\"\"\n    present = [v for v in child if v in child[:len(child)]]\n    missing = [v for v in ref if v not in child]\n    seen = set()\n    out = []\n    for v in child:\n        if v not in seen:\n            seen.add(v)\n            out.append(v)\n    return out + [v for v in missing if v not in seen]\n\n\ndef _pm_gwo(ctx, p, rng):\n    \"\"\"排列版灰狼 GWO（批 7 续）：α/β/δ 三狼轮流当 OX 父体——\n    每个个体以 1/3 概率选一头狼做 OX 交叉，贪心接受。\"\"\"\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    pop = [list(perm)]\n    popv = [c]\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: popv[i])\n        wolves = [pop[order[k]] for k in range(min(3, len(pop)))]\n        for i in range(len(pop)):\n            wolf = wolves[rng.randrange(len(wolves))]\n            cand = _pm_ox(pop[i], wolf, rng)\n            cand = _pm_polish(ctx, cand, rng, 8)  # memetic 打磨：OX 后局部搜索（弱 GWO 的补救）\n            cc = ctx.decode(cand)\n            if cc <= popv[i]:\n                pop[i], popv[i] = cand, cc\n            if cc < c:\n                perm, c = list(cand), cc\n        pop.sort(key=lambda x: 0)  # 保序（pop 与 popv 同步）\n        popv = [ctx.decode(x) for x in pop]\n        bc, best = bump(bc, best, c, perm, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_cs(ctx, p, rng):\n    \"\"\"排列版布谷鸟 CS（批 7 续）：莱维 swap 串（幂律步长）+ 弃巢重置（pa 概率换最差）。\"\"\"\n    perm = ctx.random(rng)\n    c = ctx.decode(perm)\n    best, bc = list(perm), c\n    pa = p.get(\"pa\", 0.25)\n    for it in range(1, p[\"max_iter\"] + 1):\n        i = rng.randrange(len(perm))\n        levy = int(rng.paretovariate(1.5))\n        cand = list(perm)\n        for _ in range(min(levy + 1, 8)):\n            cand = _pm_swap(cand, rng) if rng.random() < 0.7 else _pm_insert(cand, rng)\n        cc = ctx.decode(cand)\n        if cc <= c:\n            perm, c = cand, cc\n        if rng.random() < pa:  # 弃巢：重置最差个体\n            perm = ctx.random(rng)\n            c = ctx.decode(perm)\n        bc, best = bump(bc, best, c, perm, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": c[0], \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_abc(ctx, p, rng):\n    pop = [ctx.random(rng) for _ in range(p[\"n_pop\"])]\n    costs = [ctx.decode(x) for x in pop]\n    stuck = [0] * p[\"n_pop\"]\n    bi = argbest(costs, \"min\")\n    best, bc = list(pop[bi]), costs[bi]\n\n    def _learn(i, base):\n        if rng.random() < 0.5:\n            cand = _pm_ox(pop[base], pop[i], rng)  # 向最优学片段\n        else:\n            cand = _pm_swap(pop[i], rng)\n        if rng.random() < 0.3:\n            cand = _pm_insert(cand, rng)\n        cc = ctx.decode(cand)\n        if cc < costs[i]:\n            pop[i], costs[i], stuck[i] = cand, cc, 0\n        else:\n            stuck[i] += 1\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        bi = argbest(costs, \"min\")\n        for i in range(p[\"n_pop\"]):  # 雇佣蜂\n            _learn(i, bi)\n        mains = [c[0] for c in costs]\n        w = [1.0 / (1.0 + m) for m in mains]  # 箱数/色数越小越被跟\n        tot = sum(w)\n        for _ in range(p[\"n_pop\"]):  # 观察蜂（轮盘）\n            r, acc = rng.random() * tot, 0.0\n            for i in range(p[\"n_pop\"]):\n                acc += w[i]\n                if acc >= r:\n                    break\n            _learn(i, bi)\n        for i in range(p[\"n_pop\"]):  # 侦察蜂\n            if stuck[i] > p[\"limit\"]:\n                pop[i] = ctx.random(rng)\n                costs[i] = ctx.decode(pop[i])\n                stuck[i] = 0\n        bi = argbest(costs, \"min\")\n        bc, best = bump(bc, best, costs[bi], pop[bi], \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": min(c[0] for c in costs), \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_woa(ctx, p, rng):\n    pop = [ctx.random(rng) for _ in range(p[\"n_pop\"])]\n    costs = [ctx.decode(x) for x in pop]\n    bi = argbest(costs, \"min\")\n    best, bc = list(pop[bi]), costs[bi]\n    for it in range(1, p[\"max_iter\"] + 1):\n        a = 2.0 * (1 - it / p[\"max_iter\"])\n        for i in range(p[\"n_pop\"]):\n            if rng.random() < 0.5:  # 包围：从最优取片段（收缩逐步聚焦）\n                cand = _pm_ox(pop[bi], pop[i], rng)\n            else:  # 螺旋：从随机同伴取片段\n                cand = _pm_ox(pop[i], pop[rng.randrange(p[\"n_pop\"])], rng)\n            if rng.random() < 0.12 * a + 0.03:  # 后期扰动衰减 → 收缩\n                cand = _pm_swap(cand, rng)\n            cand = _pm_polish(ctx, cand, rng, 3)\n            cc = ctx.decode(cand)\n            if greedy_replace(pop, costs, i, cand, cc, \"min\"):\n                bc, best = bump(bc, best, cc, cand, \"min\")\n        yield {\"iter\": it, \"best\": bc[0], \"cur\": min(c[0] for c in costs), \"tie\": bc[1],\n               \"best_sol\": ctx.solution(best)}\n\n\ndef _pm_registry(tag):\n    \"\"\"两个排列域的算法注册表只差文案，用工厂生成（同内核两域复用的直接证据）。\"\"\"\n    noun = \"色数\" if tag == \"gc\" else \"箱数\"\n    return {\n        \"random\": {\"fn\": _pm_random, \"name\": \"随机搜索\", \"category\": \"基线\",\n                   \"desc\": f\"随机排列 + First-Fit 盲采样基线：一切算法都要显著降低{noun}\", \"tune\": []},\n        \"hc\": {\"fn\": _pm_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\",\n               \"desc\": \"交换邻域贪心（每代 tries 次随机交换）\", \"tune\": [\"tries\"]},\n        \"sa\": {\"fn\": _pm_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\",\n               \"desc\": \"Metropolis 准则接受暂时变差的交换/插入\", \"tune\": [\"t0\", \"decay\"]},\n        \"ts\": {\"fn\": _pm_ts, \"name\": \"禁忌搜索 TS\", \"category\": \"局部搜索\",\n               \"desc\": \"交换禁忌表 + 特赦准则（禁忌但破纪录则放行）\", \"tune\": [\"tenure\"]},\n        \"ga\": {\"fn\": _pm_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\",\n               \"desc\": \"OX 顺序交叉 + 交换变异 + memetic 打磨\", \"tune\": [\"pm\"]},\n        \"abc\": {\"fn\": _pm_abc, \"name\": \"人工蜂群 ABC\", \"category\": \"群体智能\",\n                \"desc\": \"雇佣/观察/侦察三阶段（排列版）\", \"tune\": [\"limit\"]},\n        \"woa\": {\"fn\": _pm_woa, \"name\": \"鲸鱼 WOA\", \"category\": \"群体智能\",\n                \"desc\": \"包围/螺旋 = OX 片段继承（排列版）\", \"tune\": []},\n        # ---- 批 7 续（2026-09-27）：排列域三内核（de/gwo/cs）——用户令稳步扩容 ----\n        \"de\": {\"fn\": _pm_de, \"name\": \"差分 DE\", \"category\": \"进化计算\",\n               \"desc\": \"排列版差分：三父体逐位差异 + OX 修复（swap 组合近似）\", \"tune\": [\"F\"]},\n        \"gwo\": {\"fn\": _pm_gwo, \"name\": \"灰狼 GWO\", \"category\": \"群体智能\",\n                \"desc\": \"三狼 OX 投票（α/β/δ 轮流当父体）\", \"tune\": []},\n        \"cs\": {\"fn\": _pm_cs, \"name\": \"布谷鸟 CS\", \"category\": \"群体智能\",\n               \"desc\": \"莱维 swap 串 + 弃巢重置（排列版）\", \"tune\": [\"pa\"]},\n    }\n\n\n# ============================================================\n# 域四：图着色（排列 + First-Fit 贪心着色）\n# ============================================================\n\ndef gc_make(n=50, seed=7, p=0.5):\n    \"\"\"DSJC 均匀随机图（Graph Coloring 基准标准族）：每对顶点以概率 p 连边。\n    实测教训：随机几何图太「结构化」，随机序 First-Fit 就近乎最优（全员贴底）；\n    DSJC p=0.5 时随机序 FF ≈ 12 色，优化后 10~11 色——优化空间真实存在。\n    布局 = 环形 + 抖动（可视化用，与着色质量无关）。\"\"\"\n    rng = random.Random(seed)\n    edges = [[i, j] for i in range(n) for j in range(i + 1, n) if rng.random() < p]\n    pos = []\n    for i in range(n):\n        ang = 2 * math.pi * i / n\n        pos.append([round(50 + 42 * math.cos(ang) + rng.uniform(-4, 4), 1),\n                    round(50 + 42 * math.sin(ang) + rng.uniform(-4, 4), 1)])\n    return {\"n\": n, \"edges\": edges, \"pos\": pos}\n\n\nclass _GC:\n    \"\"\"图着色域上下文：解码 = 按排列顺序 First-Fit 着色（合法由构造保证）。\"\"\"\n\n    def __init__(self, problem):\n        self.n = problem[\"n\"]\n        self.adj = [[] for _ in range(self.n)]\n        for u, v in problem[\"edges\"]:\n            self.adj[u].append(v)\n            self.adj[v].append(u)\n\n    def color(self, perm):\n        col = [-1] * self.n\n        for v in perm:\n            used = {col[u] for u in self.adj[v] if col[u] >= 0}\n            c = 0\n            while c in used:\n                c += 1\n            col[v] = c\n        return col\n\n    def decode(self, perm):\n        col = self.color(perm)\n        k = max(col) + 1\n        tie = sum(c * c for c in col)  # Σci²：鼓励空出高编号桶\n        return (k, tie)\n\n    def solution(self, perm):\n        return self.color(perm)\n\n    def better(self, a, b):\n        return a < b\n\n    def diff(self, c1, c2):\n        # SA 用标量：任何色数改进压倒一切次级变化（BIG 足够大）\n        return (c2[0] - c1[0]) * 100000 + (c2[1] - c1[1])\n\n    def random(self, rng):\n        p = list(range(self.n))\n        rng.shuffle(p)\n        return p\n\n\n# ============================================================\n# 域五：装箱 Bin Packing（排列 + First-Fit 装箱）\n# ============================================================\n\ndef bp_make(n=40, seed=7):\n    \"\"\"经典半均匀分布：物品重 U[20,100]，容量 150。\n    下界 LB = ⌈Σw/C⌉≈0.4n，FFD 通常 LB+1~2，随机序 FF 差 2~3 箱——\n    优化空间真实存在但不会离谱（教育友好）。\"\"\"\n    rng = random.Random(seed)\n    items = [rng.randint(20, 100) for _ in range(n)]\n    return {\"n\": n, \"cap\": 150, \"items\": items}\n\n\nclass _BP:\n    \"\"\"装箱域上下文：解码 = 按排列顺序 First-Fit 装箱。\"\"\"\n\n    def __init__(self, problem):\n        self.items = list(problem[\"items\"])\n        self.cap = problem[\"cap\"]\n        self.n = problem[\"n\"]\n\n    def pack(self, perm):\n        rem = []  # 每箱剩余容量\n        assign = [0] * self.n\n        for idx in perm:\n            w = self.items[idx]\n            for b in range(len(rem)):\n                if rem[b] >= w:\n                    rem[b] -= w\n                    assign[idx] = b\n                    break\n            else:\n                rem.append(self.cap - w)\n                assign[idx] = len(rem) - 1\n        return assign, rem\n\n    def decode(self, perm):\n        assign, rem = self.pack(perm)\n        tie = sum(r * r for r in rem)  # Σ剩余²：鼓励塞紧\n        return (len(rem), tie)\n\n    def solution(self, perm):\n        return self.pack(perm)[0]\n\n    def better(self, a, b):\n        return a < b\n\n    def diff(self, c1, c2):\n        return (c2[0] - c1[0]) * 1000000 + (c2[1] - c1[1])\n\n    def random(self, rng):\n        p = list(range(self.n))\n        rng.shuffle(p)\n        return p\n\n\n# ============================================================\n# 域：装箱变体家族 bpvar（H3 单域多预设，3 变体）\n# ------------------------------------------------------------\n#   vsbinpack：变尺寸装箱 VSBPP——箱有多种容量/成本档位，目标=开启箱成本之和\n#   binpack2d：二维装箱 2D-BPP——shelf 解码，目标=箱数最少\n#   strippack：条带装箱 SPP——单条带 shelf 解码，目标=总高度最小\n# 编码=排列，复用 _pm_* 排列内核；解码=First-Fit（1D）/shelf（2D）。\n# 目标均 = (主指标, 次级指标) 字典序：1D=(成本,Σ剩余²)；2D=(箱数,Σ余隙²)；\n# 条带=(总高,Σ余隙²)。better/diff 主指标强制优先（BIG 足够大）。\n# ============================================================\n\ndef bpv_make(variant=\"vsbinpack\", n=40, seed=7):\n    rng = random.Random(seed)\n    if variant == \"vsbinpack\":\n        # 变尺寸箱：3 档（容量/成本递增）；物品重 U[20,100]\n        items = [rng.randint(20, 100) for _ in range(n)]\n        bin_types = [[80, 1], [150, 2], [220, 3]]\n        return {\"variant\": variant, \"n\": n, \"items\": items, \"bin_types\": bin_types}\n    # 2D 变体：物品矩形 w×h ∈ [12,42]²\n    items = [[rng.randint(12, 42), rng.randint(12, 42)] for _ in range(n)]\n    if variant == \"binpack2d\":\n        return {\"variant\": variant, \"n\": n, \"items\": items, \"binW\": 70, \"binH\": 70}\n    # strippack：单条带，宽=100，高度最小化\n    return {\"variant\": variant, \"n\": n, \"items\": items, \"stripW\": 100}\n\n\nclass _BPV:\n    \"\"\"装箱变体家族上下文：排列编码 + First-Fit / shelf 解码。\"\"\"\n    BIG = 10 ** 7\n\n    def __init__(self, problem):\n        self.variant = problem[\"variant\"]\n        self.items = problem[\"items\"]\n        self.n = problem[\"n\"]\n        if self.variant == \"vsbinpack\":\n            self.bin_types = problem[\"bin_types\"]\n        elif self.variant == \"binpack2d\":\n            self.W = problem[\"binW\"]\n            self.H = problem[\"binH\"]\n            self.multi = True\n        else:  # strippack\n            self.W = problem[\"stripW\"]\n            self.H = 10 ** 9\n            self.multi = False\n\n    def random(self, rng):\n        p = list(range(self.n))\n        rng.shuffle(p)\n        return p\n\n    # ---- VSBPP：变尺寸箱 First-Fit（开最小能容的档位） ----\n    def _pack_vsb(self, perm):\n        bins = []  # 每箱: [cap_total, remaining, cost, type_idx, [idx...]]\n        boxes = []\n        for idx in perm:\n            w = self.items[idx]\n            placed = False\n            for b in range(len(bins)):\n                cap_tot, rem, cost, ti, pl = bins[b]\n                if rem >= w:\n                    pl.append(idx)\n                    boxes.append({\"i\": idx, \"b\": b, \"w\": w, \"x\": cap_tot - rem})\n                    bins[b][1] -= w\n                    placed = True\n                    break\n            if not placed:\n                chosen = None\n                for ti, (cap, cost) in enumerate(self.bin_types):\n                    if cap >= w:\n                        chosen = ti\n                        break\n                if chosen is None:\n                    chosen = len(self.bin_types) - 1\n                cap, cost = self.bin_types[chosen]\n                bins.append([cap, cap - w, cost, chosen, [idx]])\n                boxes.append({\"i\": idx, \"b\": len(bins) - 1, \"w\": w, \"x\": 0})\n        cost = sum(b[2] for b in bins)\n        return (cost, sum(b[1] * b[1] for b in bins)), boxes, bins\n\n    # ---- 2D shelf 解码（2D-BPP / SPP 共用）：物品按序落入可容 shelf，\n    # shelf 高 = 其内最高物；箱满（纵向超 H）则开新箱（2D）/ 续接 shelf（条带） ----\n    def _pack_shelf(self, perm):\n        bins = []  # 每箱: [shelf...]；shelf=[w_used, height, [(idx,w,h,x)]]\n        boxes = []\n        for idx in perm:\n            w, h = self.items[idx][0], self.items[idx][1]\n            placed = False\n            for bi in range(len(bins)):\n                bin_ = bins[bi]\n                bin_h = sum(s[1] for s in bin_)\n                for si in range(len(bin_)):\n                    sw, sh, its = bin_[si]\n                    new_sh = max(sh, h)\n                    if (self.W - sw) >= w and (bin_h - sh + new_sh) <= self.H:\n                        x = sw\n                        bin_[si][0] = sw + w\n                        bin_[si][1] = new_sh\n                        bin_[si][2].append((idx, w, h, x))\n                        boxes.append({\"i\": idx, \"b\": bi, \"w\": w, \"h\": h, \"x\": x, \"y\": bin_h - sh})\n                        placed = True\n                        break\n                if placed:\n                    break\n            if not placed:\n                new_sh = h\n                put = None\n                for bi in range(len(bins)):\n                    bin_h = sum(s[1] for s in bins[bi])\n                    if bin_h + new_sh <= self.H:\n                        put = bi\n                        break\n                if put is None:\n                    if self.multi:\n                        bins.append([])\n                        put = len(bins) - 1\n                    else:\n                        if not bins:\n                            bins.append([])\n                        put = 0\n                bins[put].append([w, h, [(idx, w, h, 0)]])\n                bin_h0 = sum(s[1] for s in bins[put][:-1])\n                boxes.append({\"i\": idx, \"b\": put, \"w\": w, \"h\": h, \"x\": 0, \"y\": bin_h0})\n        return bins, boxes\n\n    def pack(self, perm):\n        if self.variant == \"vsbinpack\":\n            (cost, tie), boxes, bins = self._pack_vsb(perm)\n            return (cost, tie), boxes, {\"bins\": bins, \"mode\": \"vsb\"}\n        bins, boxes = self._pack_shelf(perm)\n        tie = sum((self.W - sw) * sh for bin_ in bins for sw, sh, _ in bin_)\n        if self.variant == \"binpack2d\":\n            return (len(bins), tie), boxes, {\"bins\": bins, \"mode\": \"2d\"}\n        total_h = sum(sh for bin_ in bins for _, sh, _ in bin_)\n        return (total_h, tie), boxes, {\"bins\": bins, \"mode\": \"strip\", \"H\": total_h}\n\n    def decode(self, perm):\n        c, _, _ = self.pack(perm)\n        return c\n\n    def solution(self, perm):\n        c, boxes, meta = self.pack(perm)\n        if meta[\"mode\"] == \"vsb\":\n            conts = []\n            boxes_out = []\n            rowH = 10\n            for b, (cap, rem, cost, ti, pl) in enumerate(meta[\"bins\"]):\n                conts.append({\"b\": b, \"x\": 0, \"y\": b * (rowH + 2), \"w\": cap, \"h\": rowH,\n                              \"cap\": cap, \"cost\": cost, \"type\": ti})\n                for bx in boxes:\n                    if bx[\"b\"] == b:\n                        boxes_out.append({\"i\": bx[\"i\"], \"b\": b, \"x\": bx[\"x\"],\n                                          \"y\": b * (rowH + 2), \"w\": bx[\"w\"], \"h\": rowH - 1})\n            return {\"variant\": \"vsbinpack\", \"boxes\": boxes_out, \"conts\": conts}\n        # 2D / strip：坐标=问题单位（宽 self.W / 高=各箱叠加）\n        conts = []\n        boxes_out = []\n        yoff = 0\n        for b, bin_ in enumerate(meta[\"bins\"]):\n            bin_h = sum(s[1] for s in bin_)\n            if meta[\"mode\"] == \"2d\":\n                conts.append({\"b\": b, \"x\": 0, \"y\": yoff, \"w\": self.W, \"h\": bin_h})\n            shelf_y = yoff\n            for sw, sh, its in bin_:\n                for (idx, w, h, x) in its:\n                    boxes_out.append({\"i\": idx, \"b\": b, \"x\": x, \"y\": shelf_y, \"w\": w, \"h\": h})\n                shelf_y += sh\n            yoff += bin_h + (6 if meta[\"mode\"] == \"2d\" else 0)\n        if meta[\"mode\"] == \"strip\":\n            conts.append({\"b\": 0, \"x\": 0, \"y\": 0, \"w\": self.W, \"h\": yoff})\n        return {\"variant\": self.variant, \"boxes\": boxes_out, \"conts\": conts}\n\n    def better(self, a, b):\n        return a < b\n\n    def diff(self, c1, c2):\n        return (c2[0] - c1[0]) * self.BIG + (c2[1] - c1[1])\n\n\ndef _bpv_greedy(ctx, p, rng):\n    \"\"\"确定性构造锚点：多组定向序（VSBPP 按重降序/升序选最优；2D/条带按面积/高/宽降序选最优），\n    First-Fit / shelf 解码，作随机基线对照不劣于 best-of-200。\"\"\"\n    if ctx.variant == \"vsbinpack\":\n        items = ctx.items\n        orders = [sorted(range(ctx.n), key=lambda i: -items[i]),\n                  sorted(range(ctx.n), key=lambda i: items[i])]\n    else:\n        items = ctx.items\n        orders = [sorted(range(ctx.n), key=lambda i: -(items[i][0] * items[i][1])),\n                  sorted(range(ctx.n), key=lambda i: -items[i][1]),\n                  sorted(range(ctx.n), key=lambda i: -items[i][0])]\n    best_c, best_perm = None, None\n    for o in orders:\n        c, _, _ = ctx.pack(o)\n        if best_c is None or c < best_c:\n            best_c, best_perm = c, list(o)\n    yield {\"iter\": 1, \"best\": best_c[0], \"cur\": best_c[0], \"tie\": best_c[1],\n           \"best_sol\": ctx.solution(best_perm)}\n\n\n# ============================================================\n# 域六/八/十：二进制编码三域（SCP / QUBO / UFLP）共用 _bin_* 内核\n# ------------------------------------------------------------\n# 同背包域范式：编码=0/1 向量，域差异全部压进 ctx（obj/repair/random）。\n# SAT（域七）也是二进制编码，复用 _bin_* 内核 + 两个正典特化算法\n# （WalkSAT、DPLL 精确锚点）。GAP（域九）是整数向量编码，独立小内核。\n# ============================================================\n\ndef _bin_random(ctx, p, rng):\n    best, bs = None, None\n    for it in range(1, p[\"max_iter\"] + 1):\n        s = ctx.random(rng)\n        v = ctx.obj(s)\n        if bs is None or v < best:\n            best, bs = v, s\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _bin_hc(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    for it in range(1, p[\"max_iter\"] + 1):\n        for _ in range(p[\"tries\"]):\n            cand = bits_flip(s, rng, 1)\n            cand = ctx.repair(cand)\n            cv = ctx.obj(cand)\n            if cv <= v:  # 平台侧移：等值也接受（二进制 plateau 巨大）\n                s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _bin_sa(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        cand = bits_flip(s, rng, 1)\n        cand = ctx.repair(cand)\n        cv = ctx.obj(cand)\n        d = cv - v\n        if d < 0 or (T > 1e-12 and rng.random() < math.exp(-d / T)):\n            s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n            stall = 0\n        else:\n            stall += 1\n        if stall >= p[\"restart_at\"]:  # 卡死重启（连续域同款组件）\n            s, v = list(bs), best\n            s = bits_flip(s, rng, 2)\n            s = ctx.repair(s)\n            v = ctx.obj(s)\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _bin_ts(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    tabu = {}\n    tenure, sample = p[\"tenure\"], p[\"ts_sample\"]\n    n = ctx.n\n    for it in range(1, p[\"max_iter\"] + 1):\n        bm, bv, bi = None, None, -1\n        for _ in range(sample):\n            i = rng.randrange(n)\n            cand = list(s)\n            cand[i] ^= 1\n            cand = ctx.repair(cand)\n            cv = ctx.obj(cand)\n            if tabu.get(i, -1) >= it and not (bv is None or cv < best):\n                continue  # 特赦准则：禁忌但破纪录则放行\n            if bv is None or cv < bv:\n                bm, bv, bi = cand, cv, i\n        if bm is None:\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n        else:\n            s, v = bm, bv\n            tabu[bi] = it + tenure\n        if v < best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _bin_ga(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]  # 精英保留\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            child = bits_uniform(pop[a], pop[b], rng)\n            bits_mutate(child, p[\"pm\"], rng)\n            child = ctx.repair(child)\n            new.append(child)\n        pop = new\n        vals = [ctx.obj(s) for s in pop]\n        bi = argbest(vals, \"min\")\n        if vals[bi] < best:\n            best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": min(vals), \"best_sol\": list(bs)}\n\n\n_BIN_ALGOS = {\n    \"random\": {\"fn\": _bin_random, \"name\": \"随机搜索\", \"category\": \"基线\",\n               \"desc\": \"盲采样基线：一切算法都要显著降低目标\", \"tune\": []},\n    \"hc\": {\"fn\": _bin_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\",\n           \"desc\": \"单比特翻转贪心（平台侧移版）\", \"tune\": [\"tries\"]},\n    \"sa\": {\"fn\": _bin_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\",\n           \"desc\": \"Metropolis 准则 + 卡死重启\", \"tune\": [\"t0\", \"decay\"]},\n    \"ts\": {\"fn\": _bin_ts, \"name\": \"禁忌搜索 TS\", \"category\": \"局部搜索\",\n           \"desc\": \"禁忌表 + 采样邻域 + 特赦准则\", \"tune\": [\"tenure\"]},\n    \"ga\": {\"fn\": _bin_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\",\n           \"desc\": \"均匀交叉 + 位翻转变异 + 精英\", \"tune\": [\"pm\"]},\n}\n\n\n# ---- 交换邻域内核（SCP/UFLP 用）：单比特翻转在「修复式编码」下太粗糙——\n# 关掉一个集合/设施造成巨幅跳变，SA/GA 全部卡死（基准实测教训）。\n# swap = 「关一个 + 开一个」成对移动，Δ 平滑，经典文献邻域。 ----\n\ndef _sw_random(ctx, p, rng):\n    return (yield from _bin_random(ctx, p, rng))\n\n\ndef _sw_hc(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        for _ in range(p[\"tries\"]):\n            cand = ctx.swap(s, rng)\n            cv = ctx.obj(cand)\n            if cv <= v:\n                s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n            stall = 0\n        else:\n            stall += 1\n        if stall >= p[\"restart_at\"]:  # ILS：停滞则全新重启（随机基线=200 次重启，必须同样多起点）\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _sw_sa(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        cand = ctx.swap(s, rng)\n        cv = ctx.obj(cand)\n        d = cv - v\n        if d < 0 or (T > 1e-12 and rng.random() < math.exp(-d / max(T, 1e-9))):\n            s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n            stall = 0\n        else:\n            stall += 1\n        if stall >= p[\"restart_at\"]:  # ILS：从全新随机重启，而非在 best 附近小踢\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _sw_ts(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    tabu = {}\n    tenure, sample = p[\"tenure\"], p[\"ts_sample\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        bm, bv, bkey = None, None, None\n        for _ in range(sample):\n            cand = ctx.swap(s, rng)\n            key = tuple(i for i, b in enumerate(cand) if b != s[i])\n            cv = ctx.obj(cand)\n            if tabu.get(key, -1) >= it and not (bv is None or cv < best):\n                continue\n            if bv is None or cv < bv:\n                bm, bv, bkey = cand, cv, key\n        if bm is None:\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n        else:\n            s, v = bm, bv\n            tabu[bkey] = it + tenure\n        if v < best:\n            best, bs = v, list(s)\n            stall = 0\n        else:\n            stall += 1\n        if stall >= p[\"restart_at\"]:  # ILS：禁忌陷入循环时全新重启\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n            stall = 0\n            tabu = {}\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _sw_ga(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            child = bits_uniform(pop[a], pop[b], rng)\n            bits_mutate(child, p[\"pm\"], rng)\n            child = ctx.repair(child)\n            if rng.random() < 0.5:  # 一半个体再叠一次 swap 局部移动\n                child = ctx.swap(child, rng)\n            new.append(child)\n        pop = new\n        vals = [ctx.obj(s) for s in pop]\n        bi = argbest(vals, \"min\")\n        if vals[bi] < best:\n            best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": min(vals), \"best_sol\": list(bs)}\n\n\ndef _sw_pop(ctx, p, rng):\n    \"\"\"自适应种群组装：ctx 有 init_pop 用之，否则 random×n_pop 组装。\"\"\"\n    if hasattr(ctx, \"init_pop\"):\n        return ctx.init_pop(p, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    return pop, [ctx.obj(x) for x in pop]\n\n\ndef _sw_de(ctx, p, rng):\n    \"\"\"通用差分 DE（批 7 续重写）：值可重复域=标准差分；排列域=swap 组合差分。\"\"\"\n    pop, vals = _sw_pop(ctx, p, rng)\n    F = p.get(\"F\", 0.7)\n    perm_mode = len(set(pop[0])) == len(pop[0])\n    n_dim = len(pop[0])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(len(pop)):\n            idxs = [j for j in range(len(pop)) if j != i]\n            r1, r2, r3 = rng.sample(idxs, 3)\n            if perm_mode:\n                cand = list(pop[i])\n                for k in range(n_dim):\n                    if pop[r1][k] != pop[r2][k] and rng.random() < F:\n                        val = pop[r3][k]\n                        if val in cand:\n                            pos = cand.index(val)\n                            cand[k], cand[pos] = cand[pos], cand[k]\n            else:\n                cand = [max(0, min(ctx.n - 1, int(round(r3v + F * (r1v - r2v)))))\n                        if isinstance(r3v, int) else\n                        max(-5, min(5, r3v + F * (r1v - r2v)))\n                        for r3v, r1v, r2v in zip(pop[r3], pop[r1], pop[r2])]\n            c = ctx.obj(cand)\n            if c <= vals[i]:\n                pop[i], vals[i] = cand, c\n        best, bpos = min(zip(vals, pop))\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bpos), \"cur\": sum(vals) / len(vals)}\n\n\ndef _sw_gwo(ctx, p, rng):\n    \"\"\"通用灰狼 GWO（批 7 续重写）：三狼投票，排列/向量双模式。\"\"\"\n    pop, vals = _sw_pop(ctx, p, rng)\n    perm_mode = len(set(pop[0])) == len(pop[0])\n    n_dim = len(pop[0])\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: vals[i])\n        alpha, beta, delta = pop[order[0]], pop[order[1]], pop[order[2]]\n        for i in range(len(pop)):\n            if perm_mode:\n                cand = list(pop[i])\n                for k in range(n_dim):\n                    lead = rng.choice([alpha, beta, delta])\n                    if lead[k] != cand[k] and rng.random() < 0.6:\n                        if lead[k] in cand:\n                            pos = cand.index(lead[k])\n                            cand[k], cand[pos] = cand[pos], cand[k]\n            else:\n                cand = [max(0, min(ctx.n - 1, int(round((alpha[k] + beta[k] + delta[k]) / 3))))\n                        if isinstance(alpha[k], int) else\n                        max(-5, min(5, (alpha[k] + beta[k] + delta[k]) / 3 + rng.uniform(-1, 1)))\n                        for k in range(n_dim)]\n            c = ctx.obj(cand)\n            if c <= vals[i]:\n                pop[i], vals[i] = cand, c\n        best, bpos = min(zip(vals, pop))\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bpos), \"cur\": sum(vals) / len(vals)}\n\n\ndef _sw_cs(ctx, p, rng):\n    \"\"\"通用布谷鸟 CS（批 7 续重写）：莱维 swap 串+弃巢，域无关。\"\"\"\n    pop, vals = _sw_pop(ctx, p, rng)\n    pa = p.get(\"pa\", 0.25)\n    best, bpos = min(zip(vals, pop))\n    for it in range(1, p[\"max_iter\"] + 1):\n        i = rng.randrange(len(pop))\n        levy = int(rng.paretovariate(1.5))\n        cand = list(pop[i])\n        for _ in range(min(levy + 1, 8)):\n            cand = ctx.swap(cand, rng)\n        c = ctx.obj(cand)\n        if c <= vals[i]:\n            pop[i], vals[i] = cand, c\n        wi = max(range(len(pop)), key=lambda i2: vals[i2])\n        if rng.random() < pa:\n            pop[wi] = ctx.random(rng)\n            vals[wi] = ctx.obj(pop[wi])\n        best, bpos = min(zip(vals, pop))\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bpos), \"cur\": sum(vals) / len(vals)}\n\n\n# ---- M1 sigmoid 位向量适配层（2026-09-27 全矩阵计划）----\nimport math as _math\n\ndef _sig(v):\n    return 1.0 / (1.0 + math.exp(-max(-500, min(500, v))))\n\ndef _bin_rand_pos(rng, n_dim):\n    return [rng.uniform(-4, 4) for _ in range(n_dim)]\n\ndef _bin_decode(v):\n    return [1 if _sig(x) > 0.5 else 0 for x in v]\n\ndef _bin_rep(ctx, b):\n    return ctx.repair(b) if hasattr(ctx, \"repair\") else b\n\ndef _bv_fa(ctx, p, rng):\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    alpha = 0.5\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            j = rng.randrange(n_pop)\n            if vals[j] >= vals[i]: continue\n            for k in range(n_dim):\n                r2 = (pos[i][k] - pos[j][k]) ** 2\n                pos[i][k] += 1.0/(1.0+r2) * (pos[j][k] - pos[i][k]) + alpha * (rng.random()-0.5)\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]: bits[i], vals[i] = b, v\n        best = min(vals)\n        alpha *= 0.97\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals)/len(vals)}\n\ndef _bv_ba(ctx, p, rng):\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    vel = [[0.0]*n_dim for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    gbest = list(bits[vals.index(best)])  # 全局最优位向量（vel 向其收敛）\n    A = [0.9]*n_pop\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            f = 0.2 + 0.8*rng.random()\n            g_real = [4.0 if b == 1 else -4.0 for b in gbest]  # gbest 的实数代理\n            for k in range(n_dim):\n                vel[i][k] += (g_real[k] - pos[i][k]) * f\n                pos[i][k] += vel[i][k]\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v <= vals[i] and rng.random() < A[i]:\n                bits[i], vals[i] = b, v; A[i] *= 0.9\n                if v < best: best, gbest = v, list(b)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals)/len(vals)}\n\ndef _bv_jaya(ctx, p, rng):\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    for it in range(1, p[\"max_iter\"] + 1):\n        best = min(vals)\n        worst = max(vals)\n        bi = vals.index(best); wi = vals.index(worst)\n        b_vec = [4.0 if b==1 else -4.0 for b in bits[bi]]\n        w_vec = [4.0 if w==1 else -4.0 for w in bits[wi]]\n        for i in range(n_pop):\n            for k in range(n_dim):\n                pos[i][k] += rng.random()*(b_vec[k]-abs(pos[i][k])) - rng.random()*(w_vec[k]-abs(pos[i][k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]: bits[i], vals[i] = b, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals)/len(vals)}\n\ndef _bv_tlbo(ctx, p, rng):\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    for it in range(1, p[\"max_iter\"] + 1):\n        best = min(vals)\n        mean = [sum(p_[k] for p_ in pos)/n_pop for k in range(n_dim)]\n        tf = rng.randint(1, 2)\n        bi = vals.index(best)\n        for i in range(n_pop):\n            for k in range(n_dim):\n                pos[i][k] += rng.random()*(bits[bi][k]*4 - tf*mean[k])*0.5\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]: bits[i], vals[i] = b, v\n        idx = list(range(n_pop)); rng.shuffle(idx)\n        for a, b in zip(idx[::2], idx[1::2]):\n            better, worse = (a, b) if vals[a] < vals[b] else (b, a)\n            for k in range(n_dim):\n                pos[worse][k] += rng.random()*(pos[better][k] - pos[worse][k])\n            b2 = _bin_rep(ctx, _bin_decode(pos[worse]))\n            v2 = ctx.obj(b2)\n            if v2 < vals[worse]: bits[worse], vals[worse] = b2, v2\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals)/len(vals)}\n\n\n\n# ---- M1 续批 C：CEM/CMA-ES 分布系二值化 ----\ndef _bv_cem(ctx, p, rng):\n    \"\"\"CEM 位向量版：伯努利分布采样→精英频率回写（Rubinstein 1997 离散原味——位编码上 CEM 天然是伯努利 CEM）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    prob = [0.5] * n_dim  # 每位=1 的伯努利概率\n    best, gbest = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [_bin_rep(ctx, [1 if rng.random() < prob[k] else 0 for k in range(n_dim)])\n               for _ in range(n_pop)]\n        vals = [ctx.obj(b) for b in pop]\n        gen_best, gen_bp = min(zip(vals, pop))\n        if best is None or gen_best < best:\n            best, gbest = gen_best, list(gen_bp)\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 2)]\n        freq = [sum(pop[i][k] for i in elite) / len(elite) for k in range(n_dim)]\n        prob = [0.8 * f + 0.2 * g for f, g in zip(freq, (1.0 if g == 1 else 0.0 for g in gbest))]\n        prob = [min(0.95, max(0.05, x)) for x in prob]  # 防概率塌缩到 0/1\n        if stall >= 25:  # 停滞重启：概率弹回 0.5\n            prob = [0.5] * n_dim\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\ndef _bv_cmaes(ctx, p, rng):\n    \"\"\"CMA-ES 位向量版：对角协方差伯努利近似（简化诚实标注：完整 CMA 矩阵对位编码无意义，\n    保留均值/步长/精英回写骨架，协方差退化为每位独立方差）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    prob = [0.5] * n_dim\n    sigma = 0.3\n    best, gbest = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [_bin_rep(ctx, [1 if rng.random() < min(0.95, max(0.05, prob[k] + rng.gauss(0, sigma))) else 0\n                              for k in range(n_dim)]) for _ in range(n_pop)]\n        vals = [ctx.obj(b) for b in pop]\n        gen_best, gen_bp = min(zip(vals, pop))\n        if best is None or gen_best < best:\n            best, gbest = gen_best, list(gen_bp)\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 4)]\n        freq = [sum(pop[i][k] for i in elite) / len(elite) for k in range(n_dim)]\n        prob = [0.7 * f + 0.3 * (1.0 if g == 1 else 0.0) for f, g in zip(freq, gbest)]\n        prob = [min(0.95, max(0.05, x)) for x in prob]\n        var = sum((f - 0.5) ** 2 for f in freq) / n_dim\n        sigma = max(0.05, min(0.4, sigma * (1.15 if var > 0.05 else 0.92)))  # 步长自适应\n        if stall >= 25:\n            prob = [0.5] * n_dim\n            sigma = 0.3\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\n# ---- M1 续批 B：HS/EO/AO/SMA 二值化 ----\ndef _bv_hs(ctx, p, rng):\n    \"\"\"HS 位向量版：和声记忆考量+音高调整（Geem 2001——HS 本是离散起源算法，位串天然适配）。\"\"\"\n    n_dim = ctx.n\n    hms = p.get(\"n_pop\", 30)\n    hm = [_bin_rep(ctx, [1 if rng.random() < 0.5 else 0 for _ in range(n_dim)]) for _ in range(hms)]\n    hv = [ctx.obj(b) for b in hm]\n    hmcr, par = 0.85, 0.3\n    for it in range(1, p[\"max_iter\"] + 1):\n        cand = []\n        for k in range(n_dim):\n            if rng.random() < hmcr:\n                cand.append(hm[rng.randrange(hms)][k])  # 记忆考量\n            else:\n                cand.append(1 if rng.random() < 0.5 else 0)  # 随机选音\n            if rng.random() < par:\n                cand[-1] ^= 1  # 音高调整=位翻转\n        cand = _bin_rep(ctx, cand)\n        v = ctx.obj(cand)\n        wi = max(range(hms), key=lambda i: hv[i])  # 最差替换\n        if v < hv[wi]:\n            hm[wi], hv[wi] = cand, v\n        best = min(hv)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(hm[hv.index(best)]), \"cur\": sum(hv) / len(hv)}\n\ndef _bv_eo(ctx, p, rng):\n    \"\"\"EO 位向量版：均衡候选（4+1 分割）加权聚合更新（Faramarzi 2020）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    bits = [_bin_rep(ctx, [1 if rng.random() < 0.5 else 0 for _ in range(n_dim)]) for _ in range(n_pop)]\n    vals = [ctx.obj(b) for b in bits]\n    a1, a2 = 1.0, 1.0\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        # 正典平衡池（Faramarzi 2020）：前 4 优 + 均值，等概率 0.2 选一作 Ceq\n        top = [bits[i] for i in order[:4]]\n        c_avg = [sum(t[k] for t in top) / 4.0 for k in range(n_dim)]\n        avg = [1 if c > 0.5 else 0 for c in c_avg]\n        pool = top + [_bin_rep(ctx, avg)]\n        c_eq = pool[rng.randrange(5)]\n        g = [4.0 if b == 1 else -4.0 for b in c_eq]\n        F = a1 * (1 if rng.random() >= 0.5 else -1) * (_math.exp(-rng.random() * 3.0) - 1.0)\n        gcp = 0.5 * rng.random() if rng.random() >= 0.5 else 0.0  # GCP 开关（GP=0.5）\n        for i in range(n_pop):\n            lam = rng.random() * 2.0\n            cand = list(bits[i])  # 在副本上翻转，接受才写回（原先先改 bits[i]，没接受时位向量与 vals 错位）\n            for k in range(n_dim):\n                posv = (4.0 if bits[i][k] == 1 else -4.0)\n                # 正典更新：C = Ceq + (C−Ceq)·F + G/(λV)·(1−F)\n                posv = c_eq[k] + (posv - c_eq[k]) * F + gcp * (g[k] - lam * posv) * (1.0 - F) * 0.3\n                if rng.random() < min(1.0, abs(posv) / 8.0):\n                    cand[k] ^= 1  # sigmoid 概率翻转\n            b = _bin_rep(ctx, cand)\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals) / len(vals)}\n        best = min(vals)\n\ndef _levy_vec(rng, n):\n    \"\"\"Levy 飞行步长向量（Mantegna 简化式，β=1.5, s=0.01——AO/CSO 经典部件）。\"\"\"\n    import math as _mm\n    beta = 1.5\n    sig = (_mm.gamma(1 + beta) * _mm.sin(_mm.pi * beta / 2) /\n           (_mm.gamma((1 + beta) / 2) * beta * 2 ** ((beta - 1) / 2))) ** (1 / beta)\n    u = [rng.gauss(0, sig) for _ in range(n)]\n    v = [rng.gauss(0, 1) for _ in range(n)]\n    return [0.01 * uu / (abs(vv) ** (1 / beta)) for uu, vv in zip(u, v)]\n\ndef _bv_ao(ctx, p, rng):\n    \"\"\"AO 位向量版：经典四阶段（Abualigah 2021）——实值 key 空间更新 + sigmoid 解码。\n    X1=Xbest(1−t/T)+(X_M−Xbest·rand)；X2=Xbest·Levy+X_R+(y−x)·rand（螺旋简化为扰动）；\n    X3=(Xbest−X_M)·α−rand+((UB−LB)·rand+LB)·δ（α=δ=0.1）；X4=QF·Xbest−(G1·X·rand−G2·Xbest)+G3·Levy。\"\"\"\n    n_dim, n_pop = ctx.n, p.get(\"n_pop\", 30)\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best, gk = min(vals), list(pos[vals.index(min(vals))])\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        mean = [sum(pos[i][k] for i in range(n_pop)) / n_pop for k in range(n_dim)]\n        lv = _levy_vec(rng, n_dim)\n        for i in range(n_pop):\n            for k in range(n_dim):\n                if t <= 2.0 / 3.0:\n                    if rng.random() < 0.5:  # 阶段1 扩张探索\n                        pos[i][k] = gk[k] * (1.0 - t) + (mean[k] - gk[k]) * rng.random()\n                    else:  # 阶段2 收缩探索（Levy+螺旋扰动）\n                        pos[i][k] = gk[k] * lv[k] + pos[rng.randrange(n_pop)][k] + rng.gauss(0, 0.3)\n                else:\n                    if rng.random() < 0.5:  # 阶段3 扩张开发（α=δ=0.1）\n                        pos[i][k] = (gk[k] - mean[k]) * 0.1 - rng.random() + 8.0 * rng.random() * 0.1\n                    else:  # 阶段4 收缩开发（QF 收缩+Levy）\n                        qf = 1.0 + t * (2.0 - 1.0)\n                        g3 = rng.random()\n                        pos[i][k] = (qf * gk[k] - (rng.random() * pos[i][k] - rng.random() * gk[k])\n                                     + g3 * lv[k] * 0.3)\n                pos[i][k] = max(-6.0, min(6.0, pos[i][k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n                if v < best:\n                    best, gk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals) / len(vals)}\n\ndef _bv_sma(ctx, p, rng):\n    \"\"\"SMA 位向量版：经典结构（Li 2020）——Xb+vb(W·XA−XB) 位移式 + log 权重 + p=tanh|S−DF| + z=0.03 重置。\"\"\"\n    n_dim, n_pop = ctx.n, p.get(\"n_pop\", 30)\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    gk = list(bits[vals.index(best)])\n    z = 0.03\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        rank_of = [0] * n_pop\n        for r_, idx in enumerate(order):\n            rank_of[idx] = r_\n        bF, wF = vals[order[0]], vals[order[-1]]\n        DF = best\n        a = _math.atanh(max(0.001, 1.0 - t))  # vb ∈ [−a,a]\n        vb = rng.uniform(-a, a)\n        vc = rng.uniform(-(1.0 - t), 1.0 - t)\n        span = max(1e-12, bF - wF)\n        for i in range(n_pop):\n            lg = _math.log(abs(bF - vals[i]) / span + 1.0)\n            W = (1 + rng.random() * lg) if rank_of[i] < n_pop // 2 else (1 - rng.random() * lg)\n            p_i = _math.tanh(abs(vals[i] - DF))\n            r = rng.random()\n            if r < z:  # 包裹食物：随机重置\n                pos[i] = [_bin_rand_pos(rng, n_dim)[k] for k in range(n_dim)]\n            elif r < p_i:  # 逼近食物：Xb + vb·(W·XA − XB)\n                ia, ib = rng.randrange(n_pop), rng.randrange(n_pop)\n                for k in range(n_dim):\n                    pos[i][k] = max(-6.0, min(6.0,\n                        pos[order[0]][k] + vb * (W * pos[ia][k] - pos[ib][k])))\n            else:  # 振荡：vc·X\n                for k in range(n_dim):\n                    pos[i][k] = max(-6.0, min(6.0, vc * pos[i][k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n                if v < best:\n                    best, gk = v, list(b)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gk), \"cur\": sum(vals) / len(vals)}\n\ndef _pk_decode(key):\n    return sorted(range(len(key)), key=lambda k: key[k])\n\ndef _pk_sol(ctx, perm):\n    \"\"\"best_sol 归一化：_GC/_BP 有 solution（可视化信息），_ES 直接用排列。\"\"\"\n    return ctx.solution(perm) if hasattr(ctx, \"solution\") else perm\n\ndef _pk_val(v):\n    \"\"\"cost 归一化：_GC/_BP 返回 tuple、_ES 返回标量——统一取标量分量。\"\"\"\n    return v[0] if isinstance(v, tuple) else v\n\ndef _pk_tie(v):\n    return v[1] if isinstance(v, tuple) and len(v) > 1 else 0\n\ndef _pk_cost(ctx, key):\n    perm = _pk_decode(key)\n    if hasattr(ctx, \"decode\"):  # _GC/_BP 协议：decode 返回 cost 元组\n        return ctx.decode(perm)\n    return ctx.obj(perm)  # _ES 协议：obj 直接评估排列\n\ndef _pk_pso(ctx, p, rng):\n    \"\"\"PSO 排列版：随机键 + 速度-位置（Bean 1994 桥接）。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    pb, pv = [list(k) for k in pos], list(vals)\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            for k in range(n_dim):\n                r1, r2 = rng.random(), rng.random()\n                vel[i][k] = 0.7 * vel[i][k] + 1.5 * r1 * (pb[i][k] - pos[i][k]) + 1.5 * r2 * (bk[k] - pos[i][k])\n                pos[i][k] += vel[i][k]\n            v = _pk_cost(ctx, pos[i])\n            if v <= pv[i]:\n                pb[i], pv[i] = list(pos[i]), v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(pv[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_sca(ctx, p, rng):\n    \"\"\"SCA 排列版：随机键 + 正弦余弦更新。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1 = 2.0 - 2.0 * it / p[\"max_iter\"]\n        for i in range(n_pop):\n            r2, r3, r4 = 6.28318 * rng.random(), 2.0 * rng.random(), rng.random()\n            for k in range(n_dim):\n                step = r1 * (_math.sin(r2) if r4 < 0.5 else _math.cos(r2)) * abs(r3 * bk[k] - pos[i][k])\n                pos[i][k] = pos[i][k] + step\n            v = _pk_cost(ctx, pos[i])\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_mfo(ctx, p, rng):\n    \"\"\"MFO 排列版：随机键 + 蛾焰螺旋。\"\"\"\n    import math as _m\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        flame_num = int(round(n_pop - (n_pop - 1) * it / p[\"max_iter\"]))  # 正典多焰递减\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        flames = [list(pos[oi]) for oi in order]\n        t_min = -1.0 + it * (-1.0 / p[\"max_iter\"])\n        for i in range(n_pop):\n            flame = flames[min(i, flame_num - 1)]\n            t = rng.uniform(t_min, 1.0)\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                d = abs(flame[k] - pos[i][k])\n                cand[k] = d * _m.exp(t) * _m.cos(6.28318 * t) + flame[k]\n            v = _pk_cost(ctx, cand)\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        bk = pos[vals.index(best)]\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_eo(ctx, p, rng):\n    \"\"\"EO 排列版：随机键 + 均衡候选聚合（前 4 优均值）。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        # 正典平衡池：前 4 优 + 均值，等概率选一\n        pool = [pos[order[j]] for j in range(min(4, n_pop))]\n        if n_pop >= 4:\n            pool.append([sum(pos[order[j]][k] for j in range(4)) / 4.0 for k in range(n_dim)])\n        c_eq = pool[rng.randrange(len(pool))]\n        F = (1 if rng.random() >= 0.5 else -1) * (_math.exp(-rng.random() * 3.0) - 1.0)\n        gcp = 0.5 * rng.random() if rng.random() >= 0.5 else 0.0  # GCP 开关\n        for i in range(n_pop):\n            lam = rng.random() * 2.0\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                # 正典更新：C = Ceq + (C−Ceq)·F + G/(λV)·(1−F)\n                cand[k] = c_eq[k] + (pos[i][k] - c_eq[k]) * F + gcp * (c_eq[k] - lam * pos[i][k]) * (1.0 - F) * 0.3\n            v = _pk_cost(ctx, cand)\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        bk = pos[vals.index(best)]\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_ao(ctx, p, rng):\n    \"\"\"AO 排列版：随机键 + 经典四阶段（Abualigah 2021）。\"\"\"\n    n_dim = len(ctx.random(rng))\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        mean = [sum(pos[i][k] for i in range(n_pop)) / n_pop for k in range(n_dim)]\n        lv = _levy_vec(rng, n_dim)\n        for i in range(n_pop):\n            for k in range(n_dim):\n                if t <= 2.0 / 3.0:\n                    if rng.random() < 0.5:\n                        pos[i][k] = bk[k] * (1.0 - t) + (mean[k] - bk[k]) * rng.random()\n                    else:\n                        pos[i][k] = bk[k] * lv[k] + pos[rng.randrange(n_pop)][k] + rng.gauss(0, 0.3)\n                else:\n                    if rng.random() < 0.5:\n                        pos[i][k] = (bk[k] - mean[k]) * 0.1 - rng.random() + 2.0 * rng.random() * 0.1\n                    else:\n                        qf = 1.0 + t\n                        pos[i][k] = (qf * bk[k] - (rng.random() * pos[i][k] - rng.random() * bk[k])\n                                     + rng.random() * lv[k] * 0.3)\n            v = _pk_cost(ctx, pos[i])\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_sma(ctx, p, rng):\n    \"\"\"SMA 排列版：随机键 + 经典结构（Li 2020）。\"\"\"\n    n_dim = len(ctx.random(rng))\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    z = 0.03\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        rank_of = [0] * n_pop\n        for r_, idx in enumerate(order):\n            rank_of[idx] = r_\n        bF = vals[order[0]][0] if isinstance(vals[order[0]], tuple) else vals[order[0]]\n        wF = vals[order[-1]][0] if isinstance(vals[order[-1]], tuple) else vals[order[-1]]\n        DF = best[0] if isinstance(best, tuple) else best\n        a = _math.atanh(max(0.001, 1.0 - t))\n        vb = rng.uniform(-a, a)\n        vc = rng.uniform(-(1.0 - t), 1.0 - t)\n        span = max(1e-12, bF - wF)\n        for i in range(n_pop):\n            vi = vals[i][0] if isinstance(vals[i], tuple) else vals[i]\n            lg = _math.log(abs(bF - vi) / span + 1.0) if bF != wF else 0.0\n            W = (1 + rng.random() * lg) if rank_of[i] < n_pop // 2 else (1 - rng.random() * lg)\n            p_i = _math.tanh(abs(vi - DF))\n            r = rng.random()\n            if r < z:\n                pos[i] = [rng.uniform(-1, 1) for _ in range(n_dim)]\n            elif r < p_i:\n                ia, ib = rng.randrange(n_pop), rng.randrange(n_pop)\n                for k in range(n_dim):\n                    pos[i][k] = bk[k] + vb * (W * pos[ia][k] - pos[ib][k])\n            else:\n                for k in range(n_dim):\n                    pos[i][k] = vc * pos[i][k]\n            v = _pk_cost(ctx, pos[i])\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_fa(ctx, p, rng):\n    \"\"\"FA 排列版：随机键 + 亮度吸引（更亮=目标更优者吸引）。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    alpha = 0.5\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            j = rng.randrange(n_pop)\n            if vals[j] >= vals[i]:\n                continue\n            for k in range(n_dim):\n                r2 = (pos[i][k] - pos[j][k]) ** 2\n                pos[i][k] += 1.0 / (1.0 + r2) * (pos[j][k] - pos[i][k]) + alpha * (rng.random() - 0.5)\n            v = _pk_cost(ctx, pos[i])\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        alpha *= 0.97\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_ba(ctx, p, rng):\n    \"\"\"BA 排列版：随机键 + 频率调谐 + 响度衰减。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    A = [0.9] * n_pop\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            f = 0.2 + 0.8 * rng.random()\n            for k in range(n_dim):\n                vel[i][k] += (bk[k] - pos[i][k]) * f\n                pos[i][k] += vel[i][k]\n            v = _pk_cost(ctx, pos[i])\n            if v <= vals[i] and rng.random() < A[i]:\n                vals[i] = v\n                A[i] *= 0.9\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_jaya(ctx, p, rng):\n    \"\"\"Jaya 排列版：随机键 + 向 best 靠拢、远离 worst。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        bi = vals.index(min(vals))\n        wi = vals.index(max(vals))\n        for i in range(n_pop):\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[bi][k] - abs(pos[i][k])) - rng.random() * (pos[wi][k] - abs(pos[i][k]))\n            v = _pk_cost(ctx, cand)\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        bk = pos[vals.index(best)]\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_tlbo(ctx, p, rng):\n    \"\"\"TLBO 排列版：随机键 + 教师/学习两阶段。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(-1, 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [_pk_cost(ctx, k) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        bi = vals.index(min(vals))\n        mean = [sum(pos[i][k] for i in range(n_pop)) / n_pop for k in range(n_dim)]\n        tf = rng.randint(1, 2)\n        for i in range(n_pop):\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[bi][k] - tf * mean[k])\n            v = _pk_cost(ctx, cand)\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        idx = list(range(n_pop))\n        rng.shuffle(idx)\n        for a, b in zip(idx[::2], idx[1::2]):\n            better, worse = (a, b) if vals[a] < vals[b] else (b, a)\n            cand = list(pos[worse])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[better][k] - pos[worse][k])\n            v = _pk_cost(ctx, cand)\n            if v <= vals[worse]:\n                pos[worse], vals[worse] = cand, v\n        best = min(vals)\n        bk = pos[vals.index(best)]\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_cem(ctx, p, rng):\n    \"\"\"CEM 排列版：随机键 + 精英均值回写 + 停滞重启。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    mu = [0.0] * n_dim\n    sd = [1.0] * n_dim\n    best, bk = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [[rng.gauss(mu[k], sd[k]) for k in range(n_dim)] for _ in range(n_pop)]\n        vals = [_pk_cost(ctx, k) for k in pop]\n        gb, gi = min(vals), vals.index(min(vals))\n        if best is None or gb < best:\n            best, bk = gb, list(pop[gi])\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 2)]\n        mu = [sum(pop[i][k] for i in elite) / len(elite) * 0.8 + (bk[k] * 0.2) for k in range(n_dim)]\n        sd = [max(0.05, (max(pop[i][k] for i in elite) - min(pop[i][k] for i in elite)) / 2) for k in range(n_dim)]\n        if stall >= 25:\n            sd = [1.0] * n_dim\n            stall = 0\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\ndef _pk_cmaes(ctx, p, rng):\n    \"\"\"CMA-ES 排列版：随机键 + 对角步长自适应（诚实简化）。\"\"\"\n    n_dim, n_pop = len(ctx.random(rng)), p.get(\"n_pop\", 30)\n    mu = [0.0] * n_dim\n    sigma = 0.5\n    best, bk = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [[mu[k] + rng.gauss(0, sigma) for k in range(n_dim)] for _ in range(n_pop)]\n        vals = [_pk_cost(ctx, k) for k in pop]\n        gb, gi = min(vals), vals.index(min(vals))\n        if best is None or gb < best:\n            best, bk = gb, list(pop[gi])\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 4)]\n        mu = [sum(pop[i][k] for i in elite) / len(elite) for k in range(n_dim)]\n        sigma = max(0.05, min(1.0, sigma * 0.95))\n        if stall >= 25:\n            mu = [0.0] * n_dim\n            sigma = 0.5\n            stall = 0\n        yield {\"iter\": it, \"best\": _pk_val(best), \"cur\": _pk_val(vals[0]), \"tie\": _pk_tie(best),\n               \"best_sol\": _pk_sol(ctx, _pk_decode(bk))}\n\n# ---- M3 指派适配层：实值位置 → round+clamp(0..na-1)（值可重复的指派向量）----\ndef _as_range(ctx, rng):\n    ref = ctx.random(rng)\n    na = getattr(ctx, \"n_a\", None)\n    if na is None:\n        na = (max(ref) + 1) if ref else 2\n    return len(ref), na\n\ndef _as_dec(ctx, pos, na):\n    return [max(0, min(na - 1, int(round(v)))) for v in pos]\n\ndef _as_pso(ctx, p, rng):\n    \"\"\"PSO 指派版：实值位置 + round-clamp 解码。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    pb, pv = [list(k) for k in pos], list(vals)\n    best = min(vals)\n    bk = list(pos[vals.index(best)])\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            for k in range(n_dim):\n                r1, r2 = rng.random(), rng.random()\n                vel[i][k] = 0.7 * vel[i][k] + 1.5 * r1 * (pb[i][k] - pos[i][k]) + 1.5 * r2 * (bk[k] - pos[i][k])\n                pos[i][k] += vel[i][k]\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= pv[i]:\n                pb[i], pv[i] = list(pos[i]), v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_sca(ctx, p, rng):\n    \"\"\"SCA 指派版：正弦余弦更新 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    best = min(vals)\n    bk = list(pos[vals.index(best)])\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1 = 2.0 - 2.0 * it / p[\"max_iter\"]\n        for i in range(n_pop):\n            r2, r3, r4 = 6.28318 * rng.random(), 2.0 * rng.random(), rng.random()\n            for k in range(n_dim):\n                step = r1 * (_math.sin(r2) if r4 < 0.5 else _math.cos(r2)) * abs(r3 * bk[k] - pos[i][k])\n                pos[i][k] = pos[i][k] + step\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_mfo(ctx, p, rng):\n    \"\"\"MFO 指派版：蛾焰螺旋 + round-clamp。\"\"\"\n    import math as _m\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        flame_num = int(round(n_pop - (n_pop - 1) * it / p[\"max_iter\"]))  # 正典多焰递减\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        flames = [list(pos[oi]) for oi in order]\n        t_min = -1.0 + it * (-1.0 / p[\"max_iter\"])\n        for i in range(n_pop):\n            flame = flames[min(i, flame_num - 1)]\n            t = rng.uniform(t_min, 1.0)\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                d = abs(flame[k] - pos[i][k])\n                cand[k] = d * _m.exp(t) * _m.cos(6.28318 * t) + flame[k]\n            v = ctx.obj(_as_dec(ctx, cand, na))\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, pos[vals.index(best)], na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_eo(ctx, p, rng):\n    \"\"\"EO 指派版：均衡候选聚合 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        # 正典平衡池：前 4 优 + 均值，等概率选一\n        pool = [pos[order[j]] for j in range(min(4, n_pop))]\n        if n_pop >= 4:\n            pool.append([sum(pos[order[j]][k] for j in range(4)) / 4.0 for k in range(n_dim)])\n        c_eq = pool[rng.randrange(len(pool))]\n        F = (1 if rng.random() >= 0.5 else -1) * (_math.exp(-rng.random() * 3.0) - 1.0)\n        gcp = 0.5 * rng.random() if rng.random() >= 0.5 else 0.0  # GCP 开关\n        for i in range(n_pop):\n            lam = rng.random() * 2.0\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] = c_eq[k] + (pos[i][k] - c_eq[k]) * F + gcp * (c_eq[k] - lam * pos[i][k]) * (1.0 - F) * 0.3\n            v = ctx.obj(_as_dec(ctx, cand, na))\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, pos[vals.index(best)], na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_ao(ctx, p, rng):\n    \"\"\"AO 指派版：经典四阶段 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    best, bk = min(vals), list(pos[vals.index(min(vals))])\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        mean = [sum(pos[i][k] for i in range(n_pop)) / n_pop for k in range(n_dim)]\n        lv = _levy_vec(rng, n_dim)\n        for i in range(n_pop):\n            for k in range(n_dim):\n                if t <= 2.0 / 3.0:\n                    if rng.random() < 0.5:\n                        pos[i][k] = bk[k] * (1.0 - t) + (mean[k] - bk[k]) * rng.random()\n                    else:\n                        pos[i][k] = bk[k] * lv[k] + pos[rng.randrange(n_pop)][k] + rng.gauss(0, 0.3)\n                else:\n                    if rng.random() < 0.5:\n                        pos[i][k] = (bk[k] - mean[k]) * 0.1 - rng.random() + (na - 1) * rng.random() * 0.1\n                    else:\n                        qf = 1.0 + t\n                        pos[i][k] = (qf * bk[k] - (rng.random() * pos[i][k] - rng.random() * bk[k])\n                                     + rng.random() * lv[k] * 0.3)\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_sma(ctx, p, rng):\n    \"\"\"SMA 指派版：经典结构 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    best = min(vals)\n    bk = list(pos[vals.index(best)])\n    z = 0.03\n    for it in range(1, p[\"max_iter\"] + 1):\n        t = it / p[\"max_iter\"]\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        rank_of = [0] * n_pop\n        for r_, idx in enumerate(order):\n            rank_of[idx] = r_\n        bF, wF = vals[order[0]], vals[order[-1]]\n        DF = best\n        a = _math.atanh(max(0.001, 1.0 - t))\n        vb = rng.uniform(-a, a)\n        vc = rng.uniform(-(1.0 - t), 1.0 - t)\n        span = max(1e-12, bF - wF)\n        for i in range(n_pop):\n            lg = _math.log(abs(bF - vals[i]) / span + 1.0)\n            W = (1 + rng.random() * lg) if rank_of[i] < n_pop // 2 else (1 - rng.random() * lg)\n            p_i = _math.tanh(abs(vals[i] - DF))\n            r = rng.random()\n            if r < z:\n                pos[i] = [rng.uniform(0, na - 1) for _ in range(n_dim)]\n            elif r < p_i:\n                ia, ib = rng.randrange(n_pop), rng.randrange(n_pop)\n                for k in range(n_dim):\n                    pos[i][k] = bk[k] + vb * (W * pos[ia][k] - pos[ib][k])\n            else:\n                for k in range(n_dim):\n                    pos[i][k] = vc * pos[i][k]\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_fa(ctx, p, rng):\n    \"\"\"FA 指派版：亮度吸引 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    best = min(vals)\n    bk = list(pos[vals.index(best)])\n    alpha = 0.5\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            j = rng.randrange(n_pop)\n            if vals[j] >= vals[i]:\n                continue\n            for k in range(n_dim):\n                r2 = (pos[i][k] - pos[j][k]) ** 2\n                pos[i][k] += 1.0 / (1.0 + r2) * (pos[j][k] - pos[i][k]) + alpha * (rng.random() - 0.5)\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= vals[i]:\n                vals[i] = v\n                if v < best:\n                    best, bk = v, list(pos[i])\n        alpha *= 0.97\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_ba(ctx, p, rng):\n    \"\"\"BA 指派版：频率调谐 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    best = min(vals)\n    bk = list(pos[vals.index(best)])\n    A = [0.9] * n_pop\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            f = 0.2 + 0.8 * rng.random()\n            for k in range(n_dim):\n                vel[i][k] += (bk[k] - pos[i][k]) * f\n                pos[i][k] += vel[i][k]\n            v = ctx.obj(_as_dec(ctx, pos[i], na))\n            if v <= vals[i] and rng.random() < A[i]:\n                vals[i] = v\n                A[i] *= 0.9\n                if v < best:\n                    best, bk = v, list(pos[i])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, bk, na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_jaya(ctx, p, rng):\n    \"\"\"Jaya 指派版：向优避劣 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        bi, wi = vals.index(min(vals)), vals.index(max(vals))\n        for i in range(n_pop):\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[bi][k] - abs(pos[i][k])) - rng.random() * (pos[wi][k] - abs(pos[i][k]))\n            v = ctx.obj(_as_dec(ctx, cand, na))\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, pos[vals.index(best)], na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_tlbo(ctx, p, rng):\n    \"\"\"TLBO 指派版：教师/学习 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    pos = [[rng.uniform(0, na - 1) for _ in range(n_dim)] for _ in range(n_pop)]\n    vals = [ctx.obj(_as_dec(ctx, k, na)) for k in pos]\n    for it in range(1, p[\"max_iter\"] + 1):\n        bi = vals.index(min(vals))\n        mean = [sum(pos[i][k] for i in range(n_pop)) / n_pop for k in range(n_dim)]\n        tf = rng.randint(1, 2)\n        for i in range(n_pop):\n            cand = list(pos[i])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[bi][k] - tf * mean[k])\n            v = ctx.obj(_as_dec(ctx, cand, na))\n            if v <= vals[i]:\n                pos[i], vals[i] = cand, v\n        idx = list(range(n_pop))\n        rng.shuffle(idx)\n        for a, b in zip(idx[::2], idx[1::2]):\n            better, worse = (a, b) if vals[a] < vals[b] else (b, a)\n            cand = list(pos[worse])  # 在副本上更新，贪心接受才写回（否则没接受时位置与值错位）\n            for k in range(n_dim):\n                cand[k] += rng.random() * (pos[better][k] - pos[worse][k])\n            v = ctx.obj(_as_dec(ctx, cand, na))\n            if v <= vals[worse]:\n                pos[worse], vals[worse] = cand, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": _as_dec(ctx, pos[vals.index(best)], na), \"cur\": sum(vals) / len(vals)}\n\ndef _as_cem(ctx, p, rng):\n    \"\"\"CEM 指派版：精英均值回写 + 停滞重启 + round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    mu = [(na - 1) / 2.0] * n_dim\n    sd = [na / 3.0] * n_dim\n    best, bk = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [[rng.gauss(mu[k], max(0.02, sd[k])) for k in range(n_dim)] for _ in range(n_pop)]\n        dec = [_as_dec(ctx, x, na) for x in pop]\n        vals = [ctx.obj(x) for x in dec]\n        gb, gi = min(vals), vals.index(min(vals))\n        if best is None or gb < best:\n            best, bk = gb, list(dec[gi])\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 2)]\n        mu = [sum(pop[i][k] for i in elite) / len(elite) * 0.8 + bk[k] * 0.2 for k in range(n_dim)]\n        sd = [max(0.05, (max(pop[i][k] for i in elite) - min(pop[i][k] for i in elite)) / 2) for k in range(n_dim)]\n        if stall >= 25:\n            sd = [na / 3.0] * n_dim\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bk), \"cur\": sum(vals) / len(vals)}\n\ndef _as_cmaes(ctx, p, rng):\n    \"\"\"CMA-ES 指派版：对角步长自适应（诚实简化）+ round-clamp。\"\"\"\n    n_dim, na = _as_range(ctx, rng)\n    n_pop = p.get(\"n_pop\", 30)\n    mu = [(na - 1) / 2.0] * n_dim\n    sigma = na / 4.0\n    best, bk = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [[mu[k] + rng.gauss(0, sigma) for k in range(n_dim)] for _ in range(n_pop)]\n        dec = [_as_dec(ctx, x, na) for x in pop]\n        vals = [ctx.obj(x) for x in dec]\n        gb, gi = min(vals), vals.index(min(vals))\n        if best is None or gb < best:\n            best, bk = gb, list(dec[gi])\n            stall = 0\n        else:\n            stall += 1\n        elite = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 4)]\n        mu = [sum(pop[i][k] for i in elite) / len(elite) for k in range(n_dim)]\n        sigma = max(0.05, sigma * 0.95)\n        if stall >= 25:\n            mu = [(na - 1) / 2.0] * n_dim\n            sigma = na / 4.0\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bk), \"cur\": sum(vals) / len(vals)}\n\n# ---- M1 续批 A：连续系二值化（sigmoid 通用模式，全部 min 协议）----\ndef _bv_pso(ctx, p, rng):\n    \"\"\"PSO 位向量版：速度-位置 + sigmoid 映射（Kennedy & Eberhart 1997 原型）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    gbest = list(bits[vals.index(best)])\n    pbest = [list(b) for b in bits]\n    pval = list(vals)\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n_pop):\n            for k in range(n_dim):\n                r1, r2 = rng.random(), rng.random()\n                pg = 4.0 if pbest[i][k] == 1 else -4.0\n                gg = 4.0 if gbest[k] == 1 else -4.0\n                vel[i][k] = 0.5 * vel[i][k] + 1.5 * r1 * (pg - pos[i][k]) + 1.5 * r2 * (gg - pos[i][k])\n                pos[i][k] = max(-6.0, min(6.0, pos[i][k] + vel[i][k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < pval[i]:\n                pbest[i], pval[i] = list(b), v\n                if v < best:\n                    best, gbest = v, list(b)\n            elif v < vals[i]:\n                bits[i], vals[i] = b, v\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\ndef _bv_sca(ctx, p, rng):\n    \"\"\"SCA 位向量版：正弦余弦更新规则 + sigmoid 映射（Mirjalili 2016）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    gbest = list(bits[vals.index(best)])\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1 = 2.0 - 2.0 * it / p[\"max_iter\"]  # 线性递减 [2,0]\n        for i in range(n_pop):\n            r2, r3, r4 = 6.28318 * rng.random(), 2.0 * rng.random(), rng.random()\n            for k in range(n_dim):\n                g = 4.0 if gbest[k] == 1 else -4.0\n                # 标准 SCA（Mirjalili 2016）：r4 切换 sin/cos，r3 为目的地权重\n                step = r1 * (_math.sin(r2) if r4 < 0.5 else _math.cos(r2)) * abs(r3 * g - pos[i][k])\n                pos[i][k] = max(-6.0, min(6.0, pos[i][k] + step))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n                if v < best:\n                    best, gbest = v, list(b)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\ndef _bv_mfo(ctx, p, rng):\n    \"\"\"MFO 位向量版：蛾焰螺旋 + sigmoid 映射（Mirjalili 2015）。\"\"\"\n    import math as _m\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    for it in range(1, p[\"max_iter\"] + 1):\n        flame_num = int(round(n_pop - (n_pop - 1) * it / p[\"max_iter\"]))  # 正典多焰递减\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        flames = [[4.0 if b == 1 else -4.0 for b in bits[oi]] for oi in order]\n        t_dec = -1.0 + it * (-1.0 / p[\"max_iter\"])  # [0,-1] 线性递减\n        for i in range(n_pop):\n            flame = flames[min(i, flame_num - 1)]  # 前 flame_num 对号入座，其余逼近末焰\n            t = rng.uniform(t_dec, 1.0)\n            for k in range(n_dim):\n                dist = abs(flame[k] - pos[i][k])\n                pos[i][k] = max(-6.0, min(6.0,\n                    dist * _m.exp(1.0 * t) * _m.cos(2 * 3.14159 * t) + flame[k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n        best = min(vals)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bits[vals.index(best)]), \"cur\": sum(vals) / len(vals)}\n\ndef _bv_gsa(ctx, p, rng):\n    \"\"\"GSA 位向量版：引力加速 + sigmoid 映射（Rashedi 2009）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    vel = [[0.0] * n_dim for _ in range(n_pop)]\n    bits = [_bin_rep(ctx, _bin_decode(v)) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals)\n    gbest = list(bits[vals.index(best)])\n    G0 = 1.0\n    for it in range(1, p[\"max_iter\"] + 1):\n        G = G0 * (1.0 - it / (p[\"max_iter\"] + 1)) ** 2\n        worst = max(vals)\n        m = [max(0.0, (worst - v) / max(1e-12, worst - min(vals))) for v in vals]\n        mt = sum(m) or 1.0\n        m = [x / mt for x in m]\n        for i in range(n_pop):\n            for k in range(n_dim):\n                f = sum(m[j] * rng.random() * (pos[j][k] - pos[i][k]) / (abs(pos[j][k] - pos[i][k]) + 0.05)\n                        for j in range(n_pop) if j != i)\n                vel[i][k] = 0.7 * vel[i][k] + f * G\n                pos[i][k] = max(-6.0, min(6.0, pos[i][k] + vel[i][k]))\n            b = _bin_rep(ctx, _bin_decode(pos[i]))\n            v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n                if v < best:\n                    best, gbest = v, list(b)\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\n# ---- QUBO/SAT 温度适配层（complete-a-kernels 2026-09-29）----\ndef _qb_sca(ctx, p, rng):\n    \"\"\"qubo 温度适配 SCA：软阈值 sigmoid 解码(T=1.6)+gbest 每代 5 次位翻抛光。\n    针对 QUBO 大范围负目标 sigmoid 系探索不足（原 _bv_sca 严口径负 -386 vs -404）。\n    min 域（obj=二次型能量）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    T = 1.6\n    def decode(v):\n        return _bin_rep(ctx, [1 if _sig(x / T) > 0.5 else 0 for x in v])\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [decode(v) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    best = min(vals); gbest = list(bits[vals.index(best)])\n    for it in range(1, p[\"max_iter\"] + 1):\n        r1 = 2.0 - 2.0 * it / p[\"max_iter\"]\n        for i in range(n_pop):\n            r2, r3, r4 = 6.28318 * rng.random(), 2.0 * rng.random(), rng.random()\n            for k in range(n_dim):\n                g = 4.0 if gbest[k] == 1 else -4.0\n                step = r1 * (_math.sin(r2) if r4 < 0.5 else _math.cos(r2)) * abs(r3 * g - pos[i][k])\n                pos[i][k] = max(-6.0, min(6.0, pos[i][k] + step))\n            b = decode(pos[i]); v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n                if v < best:\n                    best, gbest = v, list(b)\n        for _ in range(5):\n            k = rng.randrange(n_dim); nb = list(gbest); nb[k] ^= 1; nb = _bin_rep(ctx, nb)\n            nv = ctx.obj(nb)\n            if nv < best:\n                best, gbest = nv, nb\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\n\ndef _sat_mfo(ctx, p, rng):\n    \"\"\"sat 温度适配 MFO：软阈值 sigmoid 解码(T=1.5)+gbest 每代 6 次位翻抛光。\n    替代原 _bv_mfo（sat 严口径负 8 vs 7）。min 域（obj=未满足子句数）。\"\"\"\n    n_pop, n_dim = p.get(\"n_pop\", 30), ctx.n\n    T = 1.5\n    def decode(v):\n        return _bin_rep(ctx, [1 if _sig(x / T) > 0.5 else 0 for x in v])\n    pos = [_bin_rand_pos(rng, n_dim) for _ in range(n_pop)]\n    bits = [decode(v) for v in pos]\n    vals = [ctx.obj(b) for b in bits]\n    for it in range(1, p[\"max_iter\"] + 1):\n        flame_num = int(round(n_pop - (n_pop - 1) * it / p[\"max_iter\"]))\n        order = sorted(range(n_pop), key=lambda i: vals[i])\n        flames = [[4.0 if b == 1 else -4.0 for b in bits[oi]] for oi in order]\n        t_dec = -1.0 + it * (-1.0 / p[\"max_iter\"])\n        for i in range(n_pop):\n            flame = flames[min(i, flame_num - 1)]\n            t = rng.uniform(t_dec, 1.0)\n            for k in range(n_dim):\n                dist = abs(flame[k] - pos[i][k])\n                pos[i][k] = max(-6.0, min(6.0, dist * _math.exp(1.0 * t) * _math.cos(2 * 3.14159 * t) + flame[k]))\n            b = decode(pos[i]); v = ctx.obj(b)\n            if v < vals[i]:\n                bits[i], vals[i] = b, v\n        bi = vals.index(min(vals)); best = vals[bi]; gbest = list(bits[bi])\n        for _ in range(6):\n            k = rng.randrange(n_dim); nb = list(gbest); nb[k] ^= 1; nb = _bin_rep(ctx, nb)\n            nv = ctx.obj(nb)\n            if nv < best:\n                best, gbest = nv, nb\n                bits[bi], vals[bi] = nb, nv  # 抛光的改进要写回种群，否则下一代 min(vals) 把它丢了，上报的最优会变差\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(gbest), \"cur\": sum(vals) / len(vals)}\n\n\n_SW_ALGOS = {\n    \"random\": {\"fn\": _sw_random, \"name\": \"随机搜索\", \"category\": \"基线\",\n               \"desc\": \"盲采样基线：一切算法都要显著降低目标\", \"tune\": []},\n    \"hc\": {\"fn\": _sw_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\",\n           \"desc\": \"「关一开一」交换邻域贪心（修复式编码的标准邻域）\", \"tune\": [\"tries\"]},\n    \"sa\": {\"fn\": _sw_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\",\n           \"desc\": \"交换移动 + Metropolis 准则 + 卡死重启\", \"tune\": [\"t0\", \"decay\"]},\n    \"ts\": {\"fn\": _sw_ts, \"name\": \"禁忌搜索 TS\", \"category\": \"局部搜索\",\n           \"desc\": \"交换禁忌表 + 采样邻域 + 特赦准则\", \"tune\": [\"tenure\"]},\n    \"ga\": {\"fn\": _sw_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\",\n           \"desc\": \"均匀交叉 + 变异 + 叠交换局部移动（memetic）\", \"tune\": [\"pm\"]},\n        # ---- M1 sigmoid 位向量适配（2026-09-27 全矩阵计划）----\n        \"bv_fa\": {\"fn\": _bv_fa, \"name\": \"萤火虫 FA（位）\", \"category\": \"群体智能\",\n                  \"desc\": \"sigmoid 映射二值化\", \"tune\": []},\n        \"bv_ba\": {\"fn\": _bv_ba, \"name\": \"蝙蝠 BA（位）\", \"category\": \"群体智能\",\n                  \"desc\": \"频率调谐+sigmoid 映射\", \"tune\": []},\n        \"bv_jaya\": {\"fn\": _bv_jaya, \"name\": \"Jaya（位）\", \"category\": \"群体智能\",\n                    \"desc\": \"向 best 靠拢+远离 worst\", \"tune\": []},\n        \"bv_tlbo\": {\"fn\": _bv_tlbo, \"name\": \"TLBO（位）\", \"category\": \"人类与社会启发\",\n                    \"desc\": \"教师/学习 sigmoid 映射\", \"tune\": []},\n        # ---- M1 续批 A：连续系二值化（sigmoid 通用模式）----\n        \"bv_pso\": {\"fn\": _bv_pso, \"name\": \"粒子群 PSO（位）\", \"category\": \"群体智能\",\n                   \"desc\": \"速度-位置+sigmoid（Kennedy & Eberhart 1997 原型）\", \"tune\": []},\n        \"bv_sca\": {\"fn\": _bv_sca, \"name\": \"正弦余弦 SCA（位）\", \"category\": \"群体智能\",\n                   \"desc\": \"正弦余弦更新+sigmoid（Mirjalili 2016）\", \"tune\": []},\n        \"bv_mfo\": {\"fn\": _bv_mfo, \"name\": \"蛾焰 MFO（位）\", \"category\": \"群体智能\",\n                   \"desc\": \"经典多焰递减螺旋+sigmoid（Mirjalili 2015，flame 数 n_pop→1）\", \"tune\": []},\n        # ---- M1 续批 B ----\n\n        \"bv_eo\": {\"fn\": _bv_eo, \"name\": \"均衡 EO（位）\", \"category\": \"物理定律\",\n                  \"desc\": \"均衡候选加权聚合+sigmoid（Faramarzi 2020）\", \"tune\": []},\n        \"bv_ao\": {\"fn\": _bv_ao, \"name\": \"天鹰 AO（位）\", \"category\": \"群体智能\",\n                  \"desc\": \"经典四阶段：X1 均值扩张/X2 Levy 收缩探索/X3 α-δ 开发/X4 QF 收缩（Abualigah 2021，文献核对修正）\", \"tune\": []},\n        \"bv_sma\": {\"fn\": _bv_sma, \"name\": \"黏菌 SMA（位）\", \"category\": \"群体智能\",\n                   \"desc\": \"经典位移式 Xb+vb(W·XA−XB)+log 权重+p=tanh 阈值（Li 2020，文献核对修正）\", \"tune\": []},        # ---- M1 续批 C ----\n        \"bv_cem\": {\"fn\": _bv_cem, \"name\": \"交叉熵 CEM（位）\", \"category\": \"进化计算\",\n                   \"desc\": \"伯努利 CEM：精英频率回写+best 锚定+停滞重启（Rubinstein 1997）\", \"tune\": []},\n        \"bv_cmaes\": {\"fn\": _bv_cmaes, \"name\": \"CMA-ES（位·对角近似）\", \"category\": \"进化计算\",\n                     \"desc\": \"对角协方差伯努利近似（诚实简化：完整 CMA 矩阵对位编码无意义）\", \"tune\": []},\n\n}\n\n\n# ---- 连续域内核补全（2026-10）：此前只在 TSP 上有的算法，按原论文写成连续版 ----\n# 每个内核只写一遍（连续形式、原论文公式），再经 56_generic_bridges.py 的通用适配器接到位向量 / 排列 / 指派向量问题上。\n# 约定同其它 _cn_*：上下文 ctx 提供 dim / lo / hi / random / clamp / eval / init_pop；每代 yield _cn_state；\n# 上报「历史最优」（只降不升），评价过的每个点都参与最优追踪。\n\n\ndef _lv_step(rng, n, beta=1.5):\n    \"\"\"Lévy 飞行步长（Mantegna 算法，β = 1.5），不带缩放系数。\"\"\"\n    sig = (math.gamma(1 + beta) * math.sin(math.pi * beta / 2)\n           / (math.gamma((1 + beta) / 2) * beta * 2 ** ((beta - 1) / 2))) ** (1 / beta)\n    return [rng.gauss(0, sig) / (abs(rng.gauss(0, 1)) ** (1 / beta) + 1e-300) for _ in range(n)]\n\n\ndef _cn_best0(vals, pop):\n    bi = min(range(len(vals)), key=vals.__getitem__)\n    return vals[bi], list(pop[bi])\n\n\ndef _cn_hho(ctx, p, rng):\n    \"\"\"哈里斯鹰 HHO（Heidari et al. 2019）：逃逸能量 E = 2E0(1 − t/T) 在探索（|E| ≥ 1）与四种围捕之间切换——\n    软围攻、硬围攻、带 Lévy 俯冲的软 / 硬围攻（俯冲只在变好时接受）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        xm = [sum(x[d] for x in pop) / n for d in range(D)]\n        for i in range(n):\n            x = pop[i]\n            E = 2 * (2 * rng.random() - 1) * (1 - it / T)\n            if abs(E) >= 1:  # 探索\n                if rng.random() >= 0.5:\n                    xr = pop[rng.randrange(n)]\n                    cand = [xr[d] - rng.random() * abs(xr[d] - 2 * rng.random() * x[d]) for d in range(D)]\n                else:\n                    cand = [(bpos[d] - xm[d]) - rng.random() * (ctx.lo + rng.random() * (ctx.hi - ctx.lo)) for d in range(D)]\n                pop[i] = ctx.clamp(cand)\n                vals[i] = ctx.eval(pop[i])\n            else:\n                r, J = rng.random(), 2 * (1 - rng.random())\n                if r >= 0.5:\n                    if abs(E) >= 0.5:  # 软围攻\n                        cand = [(bpos[d] - x[d]) - E * abs(J * bpos[d] - x[d]) for d in range(D)]\n                    else:  # 硬围攻\n                        cand = [bpos[d] - E * abs(bpos[d] - x[d]) for d in range(D)]\n                    pop[i] = ctx.clamp(cand)\n                    vals[i] = ctx.eval(pop[i])\n                else:  # 带渐进快速俯冲的围攻：Y 与 Y + S·LF 里挑变好的\n                    ref = x if abs(E) >= 0.5 else xm\n                    y = ctx.clamp([bpos[d] - E * abs(J * bpos[d] - ref[d]) for d in range(D)])\n                    fy = ctx.eval(y)\n                    if fy < vals[i]:\n                        pop[i], vals[i] = y, fy\n                    else:\n                        lf = _lv_step(rng, D)\n                        z = ctx.clamp([y[d] + rng.random() * lf[d] * 0.01 for d in range(D)])\n                        fz = ctx.eval(z)\n                        if fz < vals[i]:\n                            pop[i], vals[i] = z, fz\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_ssa(ctx, p, rng):\n    \"\"\"麻雀搜索 SSA（Xue & Shen 2020）：发现者（20%）按 exp(−i/(αT)) 收缩或高斯扰动；加入者追随最优发现者，\n    排名靠后的饿着飞向别处；警戒者（10%）遇险时向最优靠拢或向最差反方向逃。更新取贪心。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    n_prod, n_scout, ST = max(1, int(0.2 * n)), max(1, int(0.1 * n)), 0.8\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        order = sorted(range(n), key=vals.__getitem__)\n        pop, vals = [pop[i] for i in order], [vals[i] for i in order]\n        worst = list(pop[-1])\n        fw = vals[-1]\n        new = [None] * n\n        for i in range(n_prod):  # 发现者\n            if rng.random() < ST:\n                a = rng.random() or 1e-12\n                new[i] = [pop[i][d] * math.exp(-(i + 1) / (a * T)) for d in range(D)]\n            else:\n                q = rng.gauss(0, 1)\n                new[i] = [pop[i][d] + q for d in range(D)]\n            new[i] = ctx.clamp(new[i])\n        fv = [ctx.eval(new[i]) for i in range(n_prod)]\n        for i in range(n_prod):\n            if fv[i] < vals[i]:\n                pop[i], vals[i] = new[i], fv[i]\n        xp = list(pop[min(range(n_prod), key=vals.__getitem__)])\n        for i in range(n_prod, n):  # 加入者\n            if i + 1 > n / 2:\n                q = rng.gauss(0, 1)\n                cand = [q * math.exp((worst[d] - pop[i][d]) / ((i + 1) ** 2)) for d in range(D)]\n            else:\n                sign = [rng.choice((-1, 1)) for _ in range(D)]\n                cand = [xp[d] + abs(pop[i][d] - xp[d]) * sign[d] / D for d in range(D)]\n            cand = ctx.clamp(cand)\n            fc = ctx.eval(cand)\n            if fc < vals[i]:\n                pop[i], vals[i] = cand, fc\n        gbest, fg = list(pop[0]), vals[0]\n        for i in rng.sample(range(n), n_scout):  # 警戒者\n            if vals[i] > fg:\n                cand = [gbest[d] + rng.gauss(0, 1) * abs(pop[i][d] - gbest[d]) for d in range(D)]\n            else:\n                k = rng.uniform(-1, 1)\n                cand = [pop[i][d] + k * abs(pop[i][d] - worst[d]) / ((vals[i] - fw) + 1e-50) for d in range(D)]\n            cand = ctx.clamp(cand)\n            fc = ctx.eval(cand)\n            if fc < vals[i]:\n                pop[i], vals[i] = cand, fc\n        cb, cp = _cn_best0(vals, pop)\n        if cb < best:\n            best, bpos = cb, cp\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_alo(ctx, p, rng):\n    \"\"\"蚁狮优化 ALO（Mirjalili 2015）：蚂蚁围绕「轮盘赌选中的蚁狮」与「精英蚁狮」各做一次随机游走（游走范围随迭代收缩），\n    位置取两者平均；蚂蚁比蚁狮好就取代它（蚁狮 + 蚂蚁合并后留最好的 n 只）。\"\"\"\n    lions, lv = ctx.init_pop(p, rng)\n    n, D, T = len(lions), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(lv, lions)\n    walk_len = max(10, min(T, 100))\n    for it in range(1, T + 1):\n        w = 2 if it > 0.1 * T else 1\n        for thr, wv in ((0.5, 3), (0.75, 4), (0.9, 5), (0.95, 6)):\n            if it > thr * T:\n                w = wv\n        ratio = (10 ** w) * it / T\n        lo_t, hi_t = ctx.lo / ratio, ctx.hi / ratio\n        worst_v = max(lv)\n        wts = [worst_v - v + 1e-12 for v in lv]  # 轮盘赌权重：越好越大\n        tot = sum(wts)\n\n        def walk(center, k):\n            c = lo_t + center[k] if rng.random() < 0.5 else -lo_t + center[k]\n            d = hi_t + center[k] if rng.random() < 0.5 else -hi_t + center[k]\n            s, xs = 0.0, []\n            for _ in range(walk_len):\n                s += 1.0 if rng.random() > 0.5 else -1.0\n                xs.append(s)\n            a, b = min(xs), max(xs)\n            pick = xs[min(len(xs) - 1, int(it / T * len(xs)))]\n            return (pick - a) * (d - c) / (b - a) + c if b > a else c\n\n        ants, av = [], []\n        for _ in range(n):\n            r, acc, sel = rng.random() * tot, 0.0, n - 1\n            for j in range(n):\n                acc += wts[j]\n                if acc >= r:\n                    sel = j\n                    break\n            ra = [walk(lions[sel], k) for k in range(D)]\n            re = [walk(bpos, k) for k in range(D)]\n            a = ctx.clamp([(ra[k] + re[k]) / 2 for k in range(D)])\n            ants.append(a)\n            av.append(ctx.eval(a))\n        allp, allv = lions + ants, lv + av\n        order = sorted(range(2 * n), key=allv.__getitem__)[:n]\n        lions, lv = [allp[i] for i in order], [allv[i] for i in order]\n        if lv[0] < best:\n            best, bpos = lv[0], list(lions[0])\n        lions[0], lv[0] = list(bpos), best  # 精英永远留在蚁狮里\n        yield _cn_state(ctx, it, best, bpos, ants, av)\n\n\ndef _cn_boa(ctx, p, rng):\n    \"\"\"蝴蝶优化 BOA（Arora & Singh 2019）：香味 f = c·I^a（I 取归一化后的刺激强度，越好越大；c 随迭代增大），\n    以概率 p = 0.8 全局搜索 x + (r²·g* − x)·f，否则局部搜索 x + (r²·x_j − x_k)·f。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n    c, a, switch = 0.01, 0.1, 0.8\n    for it in range(1, T + 1):\n        lo_v, hi_v = min(vals), max(vals)\n        span = (hi_v - lo_v) or 1.0\n        for i in range(n):\n            inten = (hi_v - vals[i]) / span + 1e-12\n            fr = c * (inten ** a)\n            r = rng.random()\n            if rng.random() < switch:\n                cand = [pop[i][d] + (r * r * bpos[d] - pop[i][d]) * fr for d in range(D)]\n            else:\n                j, k = rng.randrange(n), rng.randrange(n)\n                cand = [pop[i][d] + (r * r * pop[j][d] - pop[k][d]) * fr for d in range(D)]\n            pop[i] = ctx.clamp(cand)\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        c = c + 0.025 / (c * T)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_salp(ctx, p, rng):\n    \"\"\"樽海鞘群 SSA-Salp（Mirjalili et al. 2017）：前一半是领导者，围绕食物（当前最优）按 c1 = 2e^{−(4t/T)²} 步长搜索；\n    其余是追随者，取与前一只位置的平均。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        c1 = 2 * math.exp(-((4 * it / T) ** 2))\n        for i in range(n):\n            if i < n / 2:\n                cand = []\n                for d in range(D):\n                    step = c1 * ((ctx.hi - ctx.lo) * rng.random() + ctx.lo)\n                    cand.append(bpos[d] + step if rng.random() >= 0.5 else bpos[d] - step)\n            else:\n                cand = [(pop[i][d] + pop[i - 1][d]) / 2 for d in range(D)]\n            pop[i] = ctx.clamp(cand)\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_fpa(ctx, p, rng):\n    \"\"\"花朵授粉 FPA（Yang 2012）：以概率 0.8 做全局授粉 x + γ·L(λ)·(g* − x)（Lévy 飞行，γ = 0.1，λ = 1.5），\n    否则局部授粉 x + ε(x_j − x_k)；新位置更好才替换。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        for i in range(n):\n            if rng.random() < 0.8:\n                lv = _lv_step(rng, D)\n                cand = [pop[i][d] + 0.1 * lv[d] * (bpos[d] - pop[i][d]) for d in range(D)]\n            else:\n                j, k = rng.randrange(n), rng.randrange(n)\n                e = rng.random()\n                cand = [pop[i][d] + e * (pop[j][d] - pop[k][d]) for d in range(D)]\n            cand = ctx.clamp(cand)\n            fc = ctx.eval(cand)\n            if fc < vals[i]:\n                pop[i], vals[i] = cand, fc\n                if fc < best:\n                    best, bpos = fc, list(cand)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_da(ctx, p, rng):\n    \"\"\"蜻蜓算法 DA（Mirjalili 2016）：分离 / 对齐 / 凝聚 / 觅食 / 避敌五种行为加权，权重与邻域半径随迭代变化；\n    没有邻居时做 Lévy 随机游走。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    rng_ = ctx.hi - ctx.lo\n    vmax = rng_ / 10.0\n    vel = [[0.0] * D for _ in range(n)]\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        r = rng_ / 4 + rng_ * 2 * it / T\n        w = 0.9 - it * 0.5 / T\n        my_c = 0.1 - it * (0.1 / (T / 2)) if it <= T / 2 else 0.0\n        s, a, c, f, e = 2 * rng.random() * my_c, 2 * rng.random() * my_c, 2 * rng.random() * my_c, 2 * rng.random(), my_c\n        if it > 3 * T / 4:\n            e = 0.0\n        wi = max(range(n), key=vals.__getitem__)\n        enemy = list(pop[wi])\n        for i in range(n):\n            nb = [j for j in range(n) if j != i and all(abs(pop[j][d] - pop[i][d]) <= r for d in range(D))]\n            if nb:\n                S = [-sum(pop[i][d] - pop[j][d] for j in nb) for d in range(D)]\n                A = [sum(vel[j][d] for j in nb) / len(nb) for d in range(D)]\n                C = [sum(pop[j][d] for j in nb) / len(nb) - pop[i][d] for d in range(D)]\n                F = [bpos[d] - pop[i][d] for d in range(D)]\n                E = [enemy[d] + pop[i][d] for d in range(D)]\n                for d in range(D):\n                    v = s * S[d] + a * A[d] + c * C[d] + f * F[d] + e * E[d] + w * vel[i][d]\n                    vel[i][d] = max(-vmax, min(vmax, v))\n                cand = [pop[i][d] + vel[i][d] for d in range(D)]\n            else:\n                lv = _lv_step(rng, D)\n                cand = [pop[i][d] + lv[d] * pop[i][d] for d in range(D)]\n                vel[i] = [0.0] * D\n            pop[i] = ctx.clamp(cand)\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_mpa(ctx, p, rng):\n    \"\"\"海洋掠食者 MPA（Faramarzi et al. 2020）：按迭代三等分——高速比（猎物布朗运动）、单位速度比（一半 Lévy 一半布朗）、\n    低速比（掠食者 Lévy）；精英矩阵 + 记忆保存 + FADs 效应（涡流 / 鱼聚集装置，概率 0.2）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n    P, FADs = 0.5, 0.2\n    for it in range(1, T + 1):\n        CF = (1 - it / T) ** (2 * it / T)\n        elite = list(bpos)\n        old_pop, old_vals = [list(x) for x in pop], list(vals)\n        for i in range(n):\n            RB = [rng.gauss(0, 1) for _ in range(D)]\n            RL = [0.05 * v for v in _lv_step(rng, D)]\n            R = [rng.random() for _ in range(D)]\n            x = pop[i]\n            if it < T / 3:\n                cand = [x[d] + P * R[d] * (RB[d] * (elite[d] - RB[d] * x[d])) for d in range(D)]\n            elif it < 2 * T / 3:\n                if i < n / 2:\n                    cand = [x[d] + P * R[d] * (RL[d] * (elite[d] - RL[d] * x[d])) for d in range(D)]\n                else:\n                    cand = [elite[d] + P * CF * (RB[d] * (RB[d] * elite[d] - x[d])) for d in range(D)]\n            else:\n                cand = [elite[d] + P * CF * (RL[d] * (RL[d] * elite[d] - x[d])) for d in range(D)]\n            pop[i] = ctx.clamp(cand)\n            vals[i] = ctx.eval(pop[i])\n        for i in range(n):  # 记忆保存\n            if vals[i] > old_vals[i]:\n                pop[i], vals[i] = old_pop[i], old_vals[i]\n        cb, cp = _cn_best0(vals, pop)\n        if cb < best:\n            best, bpos = cb, cp\n        old_pop, old_vals = [list(x) for x in pop], list(vals)\n        if rng.random() < FADs:  # FADs 效应\n            for i in range(n):\n                cand = [pop[i][d] + CF * (ctx.lo + rng.random() * (ctx.hi - ctx.lo)) * (1.0 if rng.random() < FADs else 0.0)\n                        for d in range(D)]\n                pop[i] = ctx.clamp(cand)\n                vals[i] = ctx.eval(pop[i])\n        else:\n            r = rng.random()\n            for i in range(n):\n                j, k = rng.randrange(n), rng.randrange(n)\n                pop[i] = ctx.clamp([pop[i][d] + (FADs * (1 - r) + r) * (pop[j][d] - pop[k][d]) for d in range(D)])\n                vals[i] = ctx.eval(pop[i])\n        for i in range(n):\n            if vals[i] > old_vals[i]:\n                pop[i], vals[i] = old_pop[i], old_vals[i]\n        cb, cp = _cn_best0(vals, pop)\n        if cb < best:\n            best, bpos = cb, cp\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_cscrow(ctx, p, rng):\n    \"\"\"乌鸦搜索 CSA（Askarzadeh 2016）：每只乌鸦记着自己的最好藏食点；跟踪另一只乌鸦——对方没发觉（概率 1 − AP）就飞向它的藏食点，\n    否则随机飞到别处；藏食点只在变好时更新。AP = 0.1，飞行长度 fl = 2。\"\"\"\n    mem, mv = ctx.init_pop(p, rng)\n    n, D, T = len(mem), ctx.dim, p[\"max_iter\"]\n    pos = [list(x) for x in mem]\n    best, bpos = _cn_best0(mv, mem)\n    AP, fl = 0.1, 2.0\n    for it in range(1, T + 1):\n        for i in range(n):\n            j = rng.randrange(n)\n            while j == i and n > 1:\n                j = rng.randrange(n)\n            if rng.random() >= AP:\n                r = rng.random()\n                cand = [pos[i][d] + r * fl * (mem[j][d] - pos[i][d]) for d in range(D)]\n            else:\n                cand = ctx.random(rng)\n            pos[i] = ctx.clamp(cand)\n            fv = ctx.eval(pos[i])\n            if fv < mv[i]:\n                mem[i], mv[i] = list(pos[i]), fv\n                if fv < best:\n                    best, bpos = fv, list(pos[i])\n        yield _cn_state(ctx, it, best, bpos, pos, mv)\n# ---- 连续域内核补全（2026-10）第二批：磷虾、细菌、鱼群、烟花、帝国、蛙跳、共生、生物地理、克隆选择 ----\n# 约定同 54_cn_kernels_swarm.py。\n\n\ndef _cn_kh(ctx, p, rng):\n    \"\"\"磷虾群 KH（Gandomi & Alavi 2012）：每只磷虾的速度 = 诱导运动 N（邻居吸引 + 全局最优）+ 觅食运动 F（食物中心 + 自身历史最优）\n    + 随机扩散 D；位置步长 Δt = C_t·Σ(UB − LB)；再做一次与随机磷虾的交叉（概率 Cr = 0.2·K̂_{i,best}）。\n    食物中心用 1/K 加权，K 取平移后的正适应度（目标可为负）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    Nmax, Vf, Dmax, Ct = 0.01, 0.02, 0.005, 0.5\n    dt = Ct * D * (ctx.hi - ctx.lo)\n    N_old = [[0.0] * D for _ in range(n)]\n    F_old = [[0.0] * D for _ in range(n)]\n    pbest = [list(x) for x in pop]\n    pbv = list(vals)\n    best, bpos = _cn_best0(vals, pop)\n    eps = 1e-12\n\n    def khat(a, b, kb, kw):\n        return (a - b) / ((kw - kb) or eps)\n\n    def xhat(xi, xj):\n        dist = math.sqrt(sum((xj[d] - xi[d]) ** 2 for d in range(D))) + eps\n        return [(xj[d] - xi[d]) / dist for d in range(D)]\n\n    for it in range(1, T + 1):\n        kb, kw = min(vals), max(vals)\n        ib = vals.index(kb)\n        shift = [v - kb + 1e-9 for v in vals]\n        wsum = sum(1.0 / s for s in shift)\n        food = [sum(pop[i][d] / shift[i] for i in range(n)) / wsum for d in range(D)]\n        food = ctx.clamp(food)\n        kfood = ctx.eval(food)\n        if kfood < best:\n            best, bpos = kfood, list(food)\n        w = 0.1 + 0.8 * (1 - it / T)\n        cbest = 2 * (rng.random() + it / T)\n        cfood = 2 * (1 - it / T)\n        new = []\n        for i in range(n):\n            ds = sum(math.sqrt(sum((pop[i][d] - pop[j][d]) ** 2 for d in range(D))) for j in range(n)) / (5 * n) + eps\n            a_loc = [0.0] * D\n            for j in range(n):\n                if j == i:\n                    continue\n                dij = math.sqrt(sum((pop[i][d] - pop[j][d]) ** 2 for d in range(D)))\n                if dij < ds:\n                    kh_, xh = khat(vals[i], vals[j], kb, kw), xhat(pop[i], pop[j])\n                    for d in range(D):\n                        a_loc[d] += kh_ * xh[d]\n            kt, xt = khat(vals[i], kb, kb, kw), xhat(pop[i], pop[ib])\n            a_tar = [cbest * kt * xt[d] for d in range(D)]\n            Ni = [Nmax * (a_loc[d] + a_tar[d]) + w * N_old[i][d] for d in range(D)]\n            kf, xf = khat(vals[i], kfood, kb, kw), xhat(pop[i], food)\n            kp, xp = khat(vals[i], pbv[i], kb, kw), xhat(pop[i], pbest[i])\n            Fi = [Vf * (cfood * kf * xf[d] + kp * xp[d]) + w * F_old[i][d] for d in range(D)]\n            Di = [Dmax * (1 - it / T) * rng.uniform(-1, 1) for _ in range(D)]\n            N_old[i], F_old[i] = Ni, Fi\n            x = [pop[i][d] + dt * (Ni[d] + Fi[d] + Di[d]) for d in range(D)]\n            cr = 0.2 * abs(khat(vals[i], kb, kb, kw))  # 越差的磷虾越爱交叉\n            if rng.random() < cr:\n                m = pop[rng.randrange(n)]\n                x = [m[d] if rng.random() < 0.5 else x[d] for d in range(D)]\n            new.append(ctx.clamp(x))\n        for i in range(n):\n            pop[i] = new[i]\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < pbv[i]:\n                pbest[i], pbv[i] = list(pop[i]), vals[i]\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_bfo(ctx, p, rng):\n    \"\"\"细菌觅食 BFO（Passino 2002）：趋化（翻转 + 沿同方向游动，只要变好就继续，至多 Ns 步）、细菌间吸引 / 排斥（J_cc）、\n    每 Nc 代繁殖（健康度前一半各分裂一个，淘汰后一半）、每 Nre 次繁殖做一次消除—扩散（概率 ped 随机迁移）。\n    一次「迭代」= 全部细菌各做一次趋化步。\"\"\"\n    pop, J = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    Nc, Ns, Nre, ped = 10, 4, 4, 0.25\n    C = 0.05 * (ctx.hi - ctx.lo)  # 趋化步长（原论文里是自由参数）：取搜索范围的 5%——0.1 在多峰函数上对随机搜索几乎没有优势\n    d_att, w_att, h_rep, w_rep = 0.1, 0.2, 0.1, 10.0\n    health = [0.0] * n\n    best, bpos = _cn_best0(J, pop)\n\n    def jcc(x):\n        s = 0.0\n        for y in pop:\n            sq = sum((x[d] - y[d]) ** 2 for d in range(D))\n            s += -d_att * math.exp(-w_att * sq) + h_rep * math.exp(-w_rep * sq)\n        return s\n\n    for it in range(1, T + 1):\n        for i in range(n):\n            delta = [rng.uniform(-1, 1) for _ in range(D)]\n            nrm = math.sqrt(sum(v * v for v in delta)) or 1.0\n            direction = [v / nrm for v in delta]\n            cur = J[i] + jcc(pop[i])\n            health[i] += J[i]\n            for _ in range(Ns + 1):\n                cand = ctx.clamp([pop[i][d] + C * direction[d] for d in range(D)])\n                fc = ctx.eval(cand)\n                if fc < best:\n                    best, bpos = fc, list(cand)\n                new_cost = fc + jcc(cand)\n                if new_cost < cur:\n                    pop[i], J[i], cur = cand, fc, new_cost\n                    health[i] += fc\n                else:\n                    break\n        if it % Nc == 0:  # 繁殖：健康度（累计代价）低的一半各复制一份，取代高的一半\n            order = sorted(range(n), key=health.__getitem__)\n            half = n // 2\n            keep = order[:half]\n            pop = [list(pop[i]) for i in keep] + [list(pop[i]) for i in keep] + ([list(pop[order[0]])] if n % 2 else [])\n            J = [J[i] for i in keep] + [J[i] for i in keep] + ([J[order[0]]] if n % 2 else [])\n            health = [0.0] * n\n        if it % (Nc * Nre) == 0:  # 消除—扩散\n            for i in range(n):\n                if rng.random() < ped:\n                    pop[i] = ctx.random(rng)\n                    J[i] = ctx.eval(pop[i])\n                    if J[i] < best:\n                        best, bpos = J[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, J)\n\n\ndef _cn_afsa(ctx, p, rng):\n    \"\"\"人工鱼群 AFSA（李晓磊 2002）：每条鱼在视野内先试聚群、追尾（拥挤度 δ = 0.618 内且更优才执行），都不行就觅食\n    （最多 try_number 次试探），再不行随机游动；聚群与追尾都满足时取更优者。视野与步长随迭代缩小。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    span = ctx.hi - ctx.lo\n    delta, tries = 0.618, 3\n    best, bpos = _cn_best0(vals, pop)\n\n    def dist(a, b):\n        return math.sqrt(sum((a[d] - b[d]) ** 2 for d in range(D)))\n\n    def move(x, target, step):\n        dd = dist(x, target) or 1.0\n        return ctx.clamp([x[d] + rng.random() * step * (target[d] - x[d]) / dd for d in range(D)])\n\n    for it in range(1, T + 1):\n        shrink = 1 - 0.9 * it / T\n        visual = 0.5 * span * math.sqrt(D) * shrink\n        step = 0.15 * span * shrink\n        for i in range(n):\n            x, fx = pop[i], vals[i]\n            nbr = [j for j in range(n) if j != i and dist(x, pop[j]) < visual]\n            cand, fcand = None, None\n            if nbr:\n                center = [sum(pop[j][d] for j in nbr) / len(nbr) for d in range(D)]\n                fc = ctx.eval(ctx.clamp(center))\n                if fc < fx and len(nbr) / n < delta:  # 聚群\n                    cand = move(x, center, step)\n                    fcand = ctx.eval(cand)\n                jb = min(nbr, key=vals.__getitem__)\n                if vals[jb] < fx and len(nbr) / n < delta:  # 追尾\n                    c2 = move(x, pop[jb], step)\n                    f2 = ctx.eval(c2)\n                    if fcand is None or f2 < fcand:\n                        cand, fcand = c2, f2\n            if cand is None:  # 觅食\n                for _ in range(tries):\n                    probe = ctx.clamp([x[d] + rng.uniform(-1, 1) * visual for d in range(D)])\n                    fp = ctx.eval(probe)\n                    if fp < fx:\n                        cand = move(x, probe, step)\n                        fcand = ctx.eval(cand)\n                        break\n                if cand is None:  # 随机游动\n                    cand = ctx.clamp([x[d] + rng.uniform(-1, 1) * step for d in range(D)])\n                    fcand = ctx.eval(cand)\n            if fcand < fx:\n                pop[i], vals[i] = cand, fcand\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_fwa(ctx, p, rng):\n    \"\"\"烟花算法 FWA（Tan & Zhu 2010）：好烟花爆炸得密而范围小，差烟花炸得稀而范围大；爆炸火花在随机若干维上平移 ±A，\n    高斯火花在随机若干维上乘 N(1, 1)；最优烟花直接保留，其余按「到其它候选的距离」轮盘赌选择。\"\"\"\n    n_fw = max(3, min(8, p.get(\"n_pop\", 30) // 6))\n    m_total, a_, b_, A_hat, m_hat = n_fw * 8, 0.04, 0.8, 0.2 * (ctx.hi - ctx.lo), max(2, n_fw)\n    D, T = ctx.dim, p[\"max_iter\"]\n    fw = [ctx.random(rng) for _ in range(n_fw)]\n    fv = [ctx.eval(x) for x in fw]\n    best, bpos = _cn_best0(fv, fw)\n    eps = 1e-12\n\n    def fold(x):  # 越界映射回区间\n        span = ctx.hi - ctx.lo\n        return [ctx.lo + abs(v - ctx.lo) % span if (v < ctx.lo or v > ctx.hi) else v for v in x]\n\n    for it in range(1, T + 1):\n        ymin, ymax = min(fv), max(fv)\n        s_den = sum(ymax - f for f in fv) + eps\n        a_den = sum(f - ymin for f in fv) + eps\n        cand, cv = [], []\n        for i in range(n_fw):\n            s_i = max(round(a_ * m_total), min(round(b_ * m_total), round(m_total * (ymax - fv[i] + eps) / s_den)))\n            amp = A_hat * (fv[i] - ymin + eps) / a_den\n            for _ in range(int(s_i)):\n                x = list(fw[i])\n                for d in rng.sample(range(D), max(1, round(D * rng.random()))):\n                    x[d] += rng.uniform(-amp, amp)\n                x = ctx.clamp(fold(x))\n                cand.append(x)\n                cv.append(ctx.eval(x))\n        for _ in range(m_hat):  # 高斯火花\n            x = list(fw[rng.randrange(n_fw)])\n            g = rng.gauss(1, 1)\n            for d in rng.sample(range(D), max(1, round(D * rng.random()))):\n                x[d] *= g\n            x = ctx.clamp(fold(x))\n            cand.append(x)\n            cv.append(ctx.eval(x))\n        allx, allv = fw + cand, fv + cv\n        bi = min(range(len(allv)), key=allv.__getitem__)\n        if allv[bi] < best:\n            best, bpos = allv[bi], list(allx[bi])\n        chosen = [bi]\n        pool = [k for k in range(len(allx)) if k != bi]\n        if pool:\n            dist = [sum(math.sqrt(sum((allx[k][d] - allx[j][d]) ** 2 for d in range(D))) for j in range(len(allx))) for k in pool]\n            tot = sum(dist) or 1.0\n            for _ in range(n_fw - 1):\n                if not pool:\n                    break\n                r, acc, pick = rng.random() * tot, 0.0, len(pool) - 1\n                for idx, dv in enumerate(dist):\n                    acc += dv\n                    if acc >= r:\n                        pick = idx\n                        break\n                chosen.append(pool[pick])\n        fw = [list(allx[k]) for k in chosen][:n_fw]\n        fv = [allv[k] for k in chosen][:n_fw]\n        while len(fw) < n_fw:\n            fw.append(list(bpos))\n            fv.append(best)\n        yield _cn_state(ctx, it, best, bpos, allx, allv)\n\n\ndef _cn_ica(ctx, p, rng):\n    \"\"\"帝国竞争 ICA（Atashpaz-Gargari & Lucas 2007）：最好的几个国家当帝国主义者，其余殖民地按势力分配；\n    殖民地同化（向帝国主义者移动 β·U(0,1)·距离，β = 2）、革命（少数维随机重置）、比帝国主义者强就互换；\n    每代让最弱帝国的最弱殖民地被势力最强的帝国抢走，殖民地耗尽的帝国灭亡。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    n_imp = max(2, min(6, n // 6))\n    xi, beta, p_rev = 0.1, 2.0, 0.1\n    order = sorted(range(n), key=vals.__getitem__)\n    pop, vals = [pop[i] for i in order], [vals[i] for i in order]\n    imps = list(range(n_imp))\n    cols = list(range(n_imp, n))\n    worst_imp = max(vals[:n_imp])\n    power = [worst_imp - vals[i] + 1e-12 for i in imps]\n    tot = sum(power)\n    emp = {k: [] for k in imps}\n    rest = list(cols)\n    for k in imps[:-1]:\n        cnt = int(round(power[k] / tot * len(cols)))\n        emp[k] = rest[:cnt]\n        rest = rest[cnt:]\n    emp[imps[-1]] = rest\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        for k in list(emp):\n            for ci in range(len(emp[k])):\n                c = emp[k][ci]\n                x = [pop[c][d] + beta * rng.random() * (pop[k][d] - pop[c][d]) for d in range(D)]\n                if rng.random() < p_rev:  # 革命\n                    for d in rng.sample(range(D), max(1, D // 5)):\n                        x[d] = rng.uniform(ctx.lo, ctx.hi)\n                pop[c] = ctx.clamp(x)\n                vals[c] = ctx.eval(pop[c])\n                if vals[c] < best:\n                    best, bpos = vals[c], list(pop[c])\n                if vals[c] < vals[k]:  # 殖民地比帝国主义者强：互换\n                    pop[c], pop[k] = pop[k], pop[c]\n                    vals[c], vals[k] = vals[k], vals[c]\n        if len(emp) > 1:  # 帝国竞争\n            tc = {k: vals[k] + xi * (sum(vals[c] for c in emp[k]) / len(emp[k]) if emp[k] else 0.0) for k in emp}\n            wk = max(emp, key=lambda k: tc[k])\n            if emp[wk]:\n                weak_col = max(emp[wk], key=vals.__getitem__)\n                tmax = max(tc.values())\n                ntc = {k: tmax - tc[k] + 1e-12 for k in emp}\n                s = sum(ntc.values())\n                r, acc, win = rng.random() * s, 0.0, None\n                for k in emp:\n                    acc += ntc[k]\n                    if acc >= r:\n                        win = k\n                        break\n                win = win if win is not None else min(emp, key=lambda k: tc[k])\n                emp[wk].remove(weak_col)\n                emp[win].append(weak_col)\n            if not emp[wk] and len(emp) > 1:  # 灭亡：帝国主义者并入赢家\n                winner = min((k for k in emp if k != wk), key=lambda k: tc[k])\n                emp[winner].append(wk)\n                del emp[wk]\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_sfla(ctx, p, rng):\n    \"\"\"混合蛙跳 SFLA（Eusuff & Lansey 2003）：蛙群按适应度排序后轮流分进 m 个模因组；组内取一个子模因组，\n    最差的蛙向组内最好的蛙跳（步长 U(0,1)·(Pb − Pw)，不超过 Smax），不行就向全局最好跳，再不行就随机重生；组内演化 Ne 次后整体重新洗牌。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    m = max(2, min(6, n // 5))\n    Ne, smax = 3, 0.5 * (ctx.hi - ctx.lo)\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        order = sorted(range(n), key=vals.__getitem__)\n        groups = [order[g::m] for g in range(m)]\n        for grp in groups:\n            q = max(2, (len(grp) + 1) // 2)\n            for _ in range(Ne):\n                # 三角形概率选 q 只组成子模因组（排名靠前的被选中概率大）\n                weights = [2.0 * (len(grp) + 1 - (r + 1)) / (len(grp) * (len(grp) + 1)) for r in range(len(grp))]\n                sub = set()\n                guard = 0\n                while len(sub) < min(q, len(grp)) and guard < 50:\n                    guard += 1\n                    r, acc = rng.random(), 0.0\n                    for idx, w_ in enumerate(weights):\n                        acc += w_\n                        if acc >= r:\n                            sub.add(grp[idx])\n                            break\n                sub = sorted(sub, key=vals.__getitem__)\n                pb, pw = sub[0], sub[-1]\n                for ref in (pb, order[0], None):\n                    if ref is None:\n                        new = ctx.random(rng)\n                    else:\n                        new = ctx.clamp([pop[pw][d] + max(-smax, min(smax, rng.random() * (pop[ref][d] - pop[pw][d]))) for d in range(D)])\n                    fn_ = ctx.eval(new)\n                    if fn_ < best:\n                        best, bpos = fn_, list(new)\n                    if fn_ < vals[pw] or ref is None:\n                        pop[pw], vals[pw] = new, fn_\n                        break\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_sos(ctx, p, rng):\n    \"\"\"共生生物搜索 SOS（Cheng & Prayogo 2014）：每个生物依次经历互利（两者都向最优靠拢，受互利向量 MV 与受益因子 BF 影响）、\n    偏利（向最优与随机伙伴的差学习）、寄生（拷贝自己并随机改几维，若比随机宿主强就取代它）三个阶段，更新都取贪心。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    best, bpos = _cn_best0(vals, pop)\n\n    def accept(i, cand):\n        nonlocal best, bpos\n        cand = ctx.clamp(cand)\n        fc = ctx.eval(cand)\n        if fc < vals[i]:\n            pop[i], vals[i] = cand, fc\n            if fc < best:\n                best, bpos = fc, list(cand)\n\n    for it in range(1, T + 1):\n        for i in range(n):\n            j = rng.randrange(n)\n            while j == i and n > 1:\n                j = rng.randrange(n)\n            mv = [(pop[i][d] + pop[j][d]) / 2 for d in range(D)]  # 互利\n            bf1, bf2 = rng.choice((1, 2)), rng.choice((1, 2))\n            accept(i, [pop[i][d] + rng.random() * (bpos[d] - mv[d] * bf1) for d in range(D)])\n            accept(j, [pop[j][d] + rng.random() * (bpos[d] - mv[d] * bf2) for d in range(D)])\n            j = rng.randrange(n)\n            while j == i and n > 1:\n                j = rng.randrange(n)\n            accept(i, [pop[i][d] + rng.uniform(-1, 1) * (bpos[d] - pop[j][d]) for d in range(D)])  # 偏利\n            j = rng.randrange(n)\n            while j == i and n > 1:\n                j = rng.randrange(n)\n            para = list(pop[i])  # 寄生\n            for d in range(D):\n                if rng.random() < 0.5:\n                    para[d] = rng.uniform(ctx.lo, ctx.hi)\n            accept(j, para)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_bbo(ctx, p, rng):\n    \"\"\"生物地理学优化 BBO（Simon 2008）：栖息地按适应度排序，物种数越多（越好）迁出率 μ 越高、迁入率 λ 越低；\n    每个特征以 λ 的概率从按 μ 轮盘赌选出的栖息地迁入，再以小概率变异；保留 2 个精英。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    n_elite, p_mut = 2, 0.01\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        order = sorted(range(n), key=vals.__getitem__)\n        pop, vals = [pop[i] for i in order], [vals[i] for i in order]\n        elite = [(list(pop[k]), vals[k]) for k in range(n_elite)]\n        mu = [(n - k) / n for k in range(n)]  # 排名 k（0 = 最好）\n        lam = [1 - m for m in mu]\n        mu_sum = sum(mu)\n        new = [list(x) for x in pop]\n        for i in range(n):\n            for d in range(D):\n                if rng.random() < lam[i]:\n                    r, acc, src = rng.random() * mu_sum, 0.0, n - 1\n                    for j in range(n):\n                        acc += mu[j]\n                        if acc >= r:\n                            src = j\n                            break\n                    new[i][d] = pop[src][d]\n                if rng.random() < p_mut:\n                    new[i][d] = rng.uniform(ctx.lo, ctx.hi)\n        for i in range(n):\n            pop[i] = ctx.clamp(new[i])\n            vals[i] = ctx.eval(pop[i])\n            if vals[i] < best:\n                best, bpos = vals[i], list(pop[i])\n        worst = sorted(range(n), key=vals.__getitem__, reverse=True)[:n_elite]\n        for slot, (ex, ev) in zip(worst, elite):  # 精英替换最差\n            pop[slot], vals[slot] = ex, ev\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_ais(ctx, p, rng):\n    \"\"\"克隆选择 CLONALG（de Castro & Von Zuben 2002）：取亲和度（目标值）最好的一半抗体，按排名克隆（越好克隆越多），\n    高频变异的幅度与亲和度成反比（亲和度越高变得越少），克隆里最好的取代原抗体；每代用新随机抗体替换最差的 20%（受体编辑）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    n, D, T = len(pop), ctx.dim, p[\"max_iter\"]\n    n_sel, beta, rho, n_new = max(2, n // 2), 0.3, 3.0, max(1, int(0.2 * n))\n    span = ctx.hi - ctx.lo\n    best, bpos = _cn_best0(vals, pop)\n    for it in range(1, T + 1):\n        order = sorted(range(n), key=vals.__getitem__)\n        pop, vals = [pop[i] for i in order], [vals[i] for i in order]\n        lo_v, hi_v = vals[0], vals[-1]\n        rngv = (hi_v - lo_v) or 1.0\n        for r in range(n_sel):\n            n_clone = max(1, int(round(beta * n / (r + 1))))\n            aff = 1.0 - (vals[r] - lo_v) / rngv  # 归一化亲和度，1 = 最好\n            sigma = math.exp(-rho * aff) * 0.3 * span\n            bc, bv = None, vals[r]\n            for _ in range(n_clone):\n                c = ctx.clamp([pop[r][d] + rng.gauss(0, sigma) for d in range(D)])\n                fc = ctx.eval(c)\n                if fc < bv:\n                    bc, bv = c, fc\n            if bc is not None:\n                pop[r], vals[r] = bc, bv\n                if bv < best:\n                    best, bpos = bv, list(bc)\n        for k in range(n - n_new, n):  # 受体编辑\n            pop[k] = ctx.random(rng)\n            vals[k] = ctx.eval(pop[k])\n            if vals[k] < best:\n                best, bpos = vals[k], list(pop[k])\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n# ---- 通用编码适配器（2026-10）：任何「连续内核」都能解位向量 / 排列 / 指派向量问题 ----\n# 此前每个算法在每种编码上各写一份（bv_* / pk_* / as_* 各约 25 行，逻辑几乎重复）。\n# 这里反过来：算法只写一遍连续版，由「视图」把离散问题包成连续域上下文——\n#   位向量 bits     实数位置经 sigmoid > 0.5 取 0/1（并修复），评价 ctx.obj\n#   排列   perm     实数位置当作随机键（Bean 1994），按键排序得到排列\n#   指派   assign   实数位置四舍五入并截断到 0..n_a-1\n# 视图自己追踪评价过的最优点：上报的 best 一定等于上报的 best_sol 的目标值（tests/test_consistency.py 的不变式）。\n\n\nclass _DiscView:\n    def __init__(self, ctx, mode, rng):\n        self._c = ctx\n        self.mode = mode\n        ref = ctx.random(rng)\n        self.dim = self.n = len(ref)\n        if mode == \"assign\":\n            na = getattr(ctx, \"n_a\", None)\n            self.na = int(na) if na is not None else (max(ref) + 1 if ref else 2)\n            self.lo, self.hi = 0.0, float(max(1, self.na - 1))\n        else:\n            self.lo, self.hi = -4.0, 4.0\n        self.best_val, self.best_tie, self.best_sol, self.best_x = float(\"inf\"), 0.0, None, None\n\n    def random(self, rng):\n        return [rng.uniform(self.lo, self.hi) for _ in range(self.dim)]\n\n    def clamp(self, x):\n        return [min(self.hi, max(self.lo, v)) for v in x]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(int(p.get(\"n_pop\", 30)))]\n        return pop, [self.eval(x) for x in pop]\n\n    def _decode(self, x):\n        if self.mode == \"bits\":\n            return _bin_rep(self._c, _bin_decode(x))\n        if self.mode == \"perm\":\n            return _pk_decode(x)\n        return _as_dec(self._c, x, self.na)\n\n    def eval(self, x):\n        sol = self._decode(x)\n        if self.mode == \"perm\" and hasattr(self._c, \"decode\"):  # 图着色 / 装箱：decode 返回 (主目标, 次级打破平局项)\n            raw = self._c.decode(sol)\n        else:\n            raw = self._c.obj(sol)\n        val, tie = (raw[0], raw[1] if len(raw) > 1 else 0.0) if isinstance(raw, tuple) else (raw, 0.0)\n        if (val, tie) < (self.best_val, self.best_tie):\n            self.best_val, self.best_tie, self.best_x = val, tie, list(x)\n            self.best_sol = _pk_sol(self._c, sol) if self.mode == \"perm\" else sol\n        return val + 1e-6 * tie\n\n    def state(self, st):\n        out = {\"iter\": st[\"iter\"], \"best\": self.best_val, \"cur\": st.get(\"cur\", self.best_val), \"best_sol\": self.best_sol}\n        if self.best_tie:\n            out[\"tie\"] = self.best_tie\n        return out\n\n\ndef _bridge(cn_fn, mode, tag):\n    \"\"\"连续内核 → 某种编码的离散内核。tag 用来给函数起个可读的名字。\"\"\"\n    def kernel(ctx, p, rng):\n        view = _DiscView(ctx, mode, rng)\n        q = dict(p)\n        q.setdefault(\"n_pop\", 30)\n        for st in cn_fn(view, q, rng):\n            yield view.state(st)\n    kernel.__name__ = f\"_{tag}_{cn_fn.__name__[4:]}\"\n    return kernel\n\n\n# 新补全的连续内核：键 → (连续内核, 名称, 一句话说明)\n_NEW_CN = {\n    \"hho\": (_cn_hho, \"哈里斯鹰 HHO\", \"逃逸能量切换探索与四种围捕（Heidari 2019）；在最优点恰在原点的函数上有「中心偏好」\"),\n    \"ssa\": (_cn_ssa, \"麻雀搜索 SSA\", \"发现者 / 加入者 / 警戒者三角色（Xue & Shen 2020）；有中心偏好\"),\n    \"alo\": (_cn_alo, \"蚁狮优化 ALO\", \"蚂蚁围绕蚁狮与精英做随机游走，范围随迭代收缩（Mirjalili 2015）\"),\n    \"boa\": (_cn_boa, \"蝴蝶优化 BOA\", \"香味感知 + 全局 / 局部切换（Arora & Singh 2019）\"),\n    \"salp\": (_cn_salp, \"樽海鞘群 Salp\", \"领导者绕食物搜索、追随者链式跟随（Mirjalili 2017）\"),\n    \"fpa\": (_cn_fpa, \"花朵授粉 FPA\", \"Lévy 全局授粉 + 局部授粉（Yang 2012）\"),\n    \"da\": (_cn_da, \"蜻蜓 DA\", \"分离 / 对齐 / 凝聚 / 觅食 / 避敌五种行为加权（Mirjalili 2016）\"),\n    \"mpa\": (_cn_mpa, \"海洋掠食者 MPA\", \"三阶段速度比 + FADs 效应（Faramarzi 2020）\"),\n    \"cscrow\": (_cn_cscrow, \"乌鸦搜索 CSA\", \"跟踪他人藏食点 + 感知概率（Askarzadeh 2016）\"),\n    \"kh\": (_cn_kh, \"磷虾群 KH\", \"诱导 / 觅食 / 扩散三种运动 + 交叉（Gandomi & Alavi 2012）\"),\n    \"bfo\": (_cn_bfo, \"细菌觅食 BFO\", \"趋化 / 繁殖 / 消除—扩散（Passino 2002）\"),\n    \"afsa\": (_cn_afsa, \"人工鱼群 AFSA\", \"觅食 / 聚群 / 追尾 / 随机四种行为（李晓磊 2002）\"),\n    \"fwa\": (_cn_fwa, \"烟花算法 FWA\", \"爆炸火花 + 高斯火花 + 距离轮盘选择（Tan & Zhu 2010）\"),\n    \"ica\": (_cn_ica, \"帝国竞争 ICA\", \"同化 / 革命 / 帝国竞争（Atashpaz-Gargari & Lucas 2007）\"),\n    \"sfla\": (_cn_sfla, \"混合蛙跳 SFLA\", \"模因分组局部演化 + 整体洗牌（Eusuff & Lansey 2003）\"),\n    \"sos\": (_cn_sos, \"共生搜索 SOS\", \"互利 / 偏利 / 寄生三相（Cheng & Prayogo 2014）；有中心偏好\"),\n    \"bbo\": (_cn_bbo, \"生物地理 BBO\", \"迁入 / 迁出率接力 + 变异（Simon 2008）\"),\n    \"ais\": (_cn_ais, \"克隆选择 AIS\", \"克隆扩增 + 与亲和度成反比的高频变异（de Castro & Von Zuben 2002）\"),\n}\n# ---- 通用「离散 / 局部搜索系」内核（2026-10）：ILS、VNS、ACO、GRASP 只写一遍 ----\n# 各问题域对「评价」和「邻居」的接口并不统一（obj / value / decode / eval；有的有 swap，有的没有）。\n# _MinView 把任何域整理成最小接口：random / fix（修复）/ obj（越小越好的标量）/ swap（邻居），并自己追踪评价过的最优解：\n# 上报的 best 一定等于上报的 best_sol 的目标值。max 协议的域（只有 value）在视图里取负，yield 时再还原符号。\n\n\nclass _MinView:\n    def __init__(self, ctx, rng):\n        self._c = ctx\n        ref = ctx.random(rng)\n        self.n = len(ref)\n        if sorted(ref) == list(range(len(ref))):\n            self.kind = \"perm\"\n        elif hasattr(ctx, \"n_a\") or (all(isinstance(v, int) for v in ref) and not all(v in (0, 1) for v in ref)):\n            self.kind = \"assign\"\n            self.na = int(getattr(ctx, \"n_a\", 0) or (max(ref) + 1))\n        elif all(v in (0, 1) for v in ref):\n            self.kind = \"bits\"\n        else:\n            self.kind = \"real\"\n            self.lo, self.hi = getattr(ctx, \"lo\", -5.0), getattr(ctx, \"hi\", 5.0)\n        self.sign = 1\n        if hasattr(ctx, \"decode\"):\n            self._f = ctx.decode\n        elif hasattr(ctx, \"obj\"):\n            self._f = ctx.obj\n        elif hasattr(ctx, \"eval\"):\n            self._f = ctx.eval\n        else:\n            self._f, self.sign = (lambda s: -ctx.value(s)), -1\n        self.best_val, self.best_tie, self.best_sol = float(\"inf\"), 0.0, None\n        self.last = None\n\n    def random(self, rng):\n        return self.fix(self._c.random(rng))\n\n    def fix(self, s):\n        if self.kind in (\"bits\", \"assign\") and hasattr(self._c, \"repair\"):\n            return self._c.repair(s)\n        return s\n\n    def obj(self, s):\n        self.last = s\n        raw = self._f(s)\n        val, tie = (raw[0], raw[1] if len(raw) > 1 else 0.0) if isinstance(raw, tuple) else (raw, 0.0)\n        if (val, tie) < (self.best_val, self.best_tie):\n            self.best_val, self.best_tie = val, tie\n            self.best_sol = self._c.solution(s) if (self.kind == \"perm\" and hasattr(self._c, \"solution\")) else list(s)\n        return val + 1e-6 * tie\n\n    def swap(self, s, rng):\n        s = list(s)\n        if self.kind == \"perm\":\n            i, j = rng.sample(range(self.n), 2)\n            if rng.random() < 0.5:\n                s[i], s[j] = s[j], s[i]\n            else:\n                v = s.pop(i)\n                s.insert(j, v)\n            return s\n        if self.kind == \"bits\":\n            s[rng.randrange(self.n)] ^= 1\n            return self.fix(s)\n        if self.kind == \"assign\":\n            s[rng.randrange(self.n)] = rng.randrange(self.na)\n            return self.fix(s)\n        k = rng.randrange(self.n)\n        s[k] = min(self.hi, max(self.lo, s[k] + rng.gauss(0, 0.3 * (self.hi - self.lo) / 5)))\n        return s\n\n    def state(self, st):\n        out = {\"iter\": st[\"iter\"], \"best\": self.sign * self.best_val, \"cur\": st.get(\"cur\", self.sign * self.best_val),\n               \"best_sol\": self.best_sol}\n        if self.best_tie:\n            out[\"tie\"] = self.best_tie\n        if self.kind == \"real\" and self.best_sol:  # 连续域的页面按前两维画点：补上它读的字段\n            out[\"gbest_pos\"] = list(self.best_sol[:2])\n            out[\"particles\"] = [list((self.last or self.best_sol)[:2])]\n        return out\n\n\ndef _viewed(kernel, tag):\n    def wrapped(ctx, p, rng):\n        view = _MinView(ctx, rng)\n        q = dict(p)\n        q.setdefault(\"n_pop\", 30)\n        for st in kernel(view, q, rng):\n            yield view.state(st)\n    wrapped.__name__ = tag\n    return wrapped\n\n\ndef _mv_descent(view, s, v, rng, max_fail):\n    \"\"\"采样式一阶下降：连续 max_fail 个随机邻居都没变好就停（不枚举整个邻域——评价次数可控）。\"\"\"\n    fails = 0\n    while fails < max_fail:\n        nb = view.swap(s, rng)\n        nv = view.obj(nb)\n        if nv < v:\n            s, v, fails = nb, nv, 0\n        else:\n            fails += 1\n    return s, v\n\n\ndef _mv_ils(view, p, rng):\n    \"\"\"迭代局部搜索 ILS（Lourenço, Martin & Stützle 2003）：扰动（随机移动若干步）→ 下降到局部最优 → 不比当前差就接受。\"\"\"\n    s = view.random(rng)\n    v = view.obj(s)\n    s, v = _mv_descent(view, s, v, rng, 10)\n    kick = max(2, min(view.n // 4, 6))\n    for it in range(1, p[\"max_iter\"] + 1):\n        cand = s\n        for _ in range(kick):\n            cand = view.swap(cand, rng)\n        cv = view.obj(cand)\n        cand, cv = _mv_descent(view, cand, cv, rng, 10)\n        if cv <= v:\n            s, v = cand, cv\n        yield {\"iter\": it, \"cur\": v * view.sign}\n\n\ndef _mv_vns(view, p, rng):\n    \"\"\"变邻域搜索 VNS（Mladenović & Hansen 1997）：第 k 个邻域 = 随机移动 k 步；摇动 → 下降，变好就回到 k = 1，否则换更大的邻域。\"\"\"\n    s = view.random(rng)\n    v = view.obj(s)\n    k, kmax = 1, 5\n    for it in range(1, p[\"max_iter\"] + 1):\n        cand = s\n        for _ in range(k):\n            cand = view.swap(cand, rng)\n        cv = view.obj(cand)\n        cand, cv = _mv_descent(view, cand, cv, rng, 8)\n        if cv < v:\n            s, v, k = cand, cv, 1\n        else:\n            k = k + 1 if k < kmax else 1\n        yield {\"iter\": it, \"cur\": v * view.sign}\n\n\ndef _mv_aco(view, p, rng):\n    \"\"\"蚁群优化（排序式 Ant System，Bullnheimer et al. 1999；信息素带上下界，Stützle & Hoos 2000）。\n    每只蚂蚁在「决策图」上逐步选：排列 = 每个位置选一个还没用过的元素；位向量 = 每位选 0 / 1；指派 = 每个任务选一个代理；\n    信息素 τ 对应决策（位置 → 元素 / 位 → 取值 / 任务 → 代理）；每代按排名给前 w 只蚂蚁的路径加信息素，历史最优额外加权。\n    没有问题专属的启发式信息——只靠信息素，所以对任意目标函数都能用。\"\"\"\n    n = view.n\n    m = int(p.get(\"n_pop\", 30))\n    if view.kind == \"perm\":\n        tau = [[1.0] * n for _ in range(n)]\n    elif view.kind == \"bits\":\n        tau = [[1.0, 1.0] for _ in range(n)]\n    else:\n        tau = [[1.0] * view.na for _ in range(n)]\n    rho, w, t_min, t_max = 0.1, min(6, m), 0.05, 20.0\n    gbest, gv = None, float(\"inf\")\n\n    def pick(weights, rng):\n        tot = sum(weights)\n        r, acc = rng.random() * tot, 0.0\n        for idx, wv in enumerate(weights):\n            acc += wv\n            if acc >= r:\n                return idx\n        return len(weights) - 1\n\n    def construct():\n        if view.kind == \"perm\":\n            left = list(range(n))\n            sol = [0] * n\n            for pos in rng.sample(range(n), n):\n                idx = pick([tau[pos][it_] for it_ in left], rng)\n                sol[pos] = left.pop(idx)\n            return sol, [(pos, sol[pos]) for pos in range(n)]\n        if view.kind == \"bits\":\n            sol = [pick(tau[i], rng) for i in range(n)]\n        else:\n            sol = [pick(tau[i], rng) for i in range(n)]\n        return view.fix(sol), None\n\n    for it in range(1, p[\"max_iter\"] + 1):\n        ants = []\n        for _ in range(m):\n            sol, path = construct()\n            ants.append((view.obj(sol), sol, path))\n        ants.sort(key=lambda a: a[0])\n        if ants[0][0] < gv:\n            gv, gbest = ants[0][0], (ants[0][1])\n        for row in tau:\n            for k in range(len(row)):\n                row[k] = max(t_min, row[k] * (1 - rho))\n        for r in range(w):\n            val, sol, path = ants[r]\n            dep = (w - r) / w\n            for i in range(n):\n                tau[i][sol[i]] = min(t_max, tau[i][sol[i]] + dep)\n        for i in range(n):\n            tau[i][gbest[i]] = min(t_max, tau[i][gbest[i]] + 1.0)\n        yield {\"iter\": it, \"cur\": sum(a[0] for a in ants) / m * view.sign}\n\n\ndef _mv_grasp(view, p, rng):\n    \"\"\"GRASP（Feo & Resende 1989），位向量版：贪心随机构造——从全 0 出发，每步在随机抽样的几个候选「加入某项」里按\n    边际收益建受限候选表（RCL，α = 0.3），随机选一个加入，直到没有候选能再改进；然后做 1-翻转下降。\n    候选抽样（而不是枚举全部）让每次构造的评价次数可控。\"\"\"\n    n = view.n\n    cand_n, alpha = min(8, n), 0.3\n    for it in range(1, p[\"max_iter\"] + 1):\n        s = view.fix([0] * n)\n        v = view.obj(s)\n        steps = 0\n        while steps < n // 2 + 2:\n            steps += 1\n            opts = []\n            for i in rng.sample(range(n), cand_n):\n                if s[i] == 0:\n                    t = list(s)\n                    t[i] = 1\n                    t = view.fix(t)\n                    opts.append((view.obj(t), t))\n            if not opts:\n                continue\n            opts.sort(key=lambda o: o[0])\n            lo_, hi_ = opts[0][0], opts[-1][0]\n            rcl = [o for o in opts if o[0] <= lo_ + alpha * (hi_ - lo_)]\n            pick_v, pick_t = rng.choice(rcl)\n            if pick_v >= v:\n                break\n            s, v = pick_t, pick_v\n        s, v = _mv_descent(view, s, v, rng, 10)\n        yield {\"iter\": it, \"cur\": v * view.sign}\n\n\n# 新补全的离散 / 局部搜索系内核：键 → (内核, 名称, 一句话说明, 适用的编码)\n_NEW_GENERIC = {\n    \"ils\": (_mv_ils, \"迭代局部搜索 ILS\", \"扰动 → 采样下降 → 不变差就接受（Lourenço 等 2003）\", (\"perm\", \"bits\", \"assign\", \"real\")),\n    \"vns\": (_mv_vns, \"变邻域搜索 VNS\", \"第 k 个邻域 = 随机移动 k 步，变好回 k = 1（Mladenović & Hansen 1997）\", (\"perm\", \"bits\", \"assign\", \"real\")),\n    \"aco\": (_mv_aco, \"蚁群 ACO\", \"排序式 Ant System + 信息素上下界，决策图上逐步构造（只靠信息素，无专属启发式）\", (\"perm\", \"bits\", \"assign\")),\n    \"grasp\": (_mv_grasp, \"GRASP\", \"抽样候选的贪心随机构造 + 1-翻转下降（Feo & Resende 1989）\", (\"bits\",)),\n}\n# ============================================================\n# 域六：集合覆盖 SCP（0-1 编码 + 覆盖修复）\n# ============================================================\n\ndef sc_make(n_el=80, m=50, seed=7):\n    \"\"\"随机 SCP 实例：每集合以 ~25% 概率覆盖每个元素（成本 5-60）。\n    保证全覆盖（每个元素至少入一个集合）——修复算子才有正确性前提。\n    参数标定（bench 实测）：重叠冗余 + 成本方差给搜索留足空间——\n    随机修复基线 ~120，swap 局部搜索 ~88，Chvátal 贪心 ~99。\"\"\"\n    rng = random.Random(seed)\n    sets = [[1 if rng.random() < 0.25 else 0 for _ in range(n_el)] for _ in range(m)]\n    for e in range(n_el):  # 全覆盖修补\n        if not any(s[e] for s in sets):\n            sets[rng.randrange(m)][e] = 1\n    costs = [rng.randint(5, 60) for _ in range(m)]\n    return {\"n_el\": n_el, \"m\": m, \"sets\": sets, \"costs\": costs}\n\n\nclass _SC:\n    \"\"\"SCP 域上下文：编码=集合开关向量；不可行（有未覆盖元素）用 BIG 罚。\"\"\"\n    BIG = 1000\n\n    def __init__(self, problem):\n        self.n_el = problem[\"n_el\"]\n        self.m = problem[\"m\"]\n        self.sets = problem[\"sets\"]\n        self.costs = problem[\"costs\"]\n        self.n = self.m\n        # 位掩码：每个集合覆盖的元素压成一个整数。覆盖判断从「元素×集合」次 Python 循环降到「集合」次整数或运算——\n        # 500×500 的实例上单次评价快两个数量级，结果与逐格判断完全相同（黄金快照核对过）\n        self._mask = [sum(1 << e for e in range(self.n_el) if row[e]) for row in self.sets]\n        self._full = (1 << self.n_el) - 1\n\n    def cost(self, s):\n        return sum(self.costs[i] for i in range(self.m) if s[i])\n\n    def _covered(self, s):\n        c = 0\n        for i, mk in enumerate(self._mask):\n            if s[i]:\n                c |= mk\n        return c\n\n    def uncovered(self, s):\n        return bin(self._full & ~self._covered(s)).count(\"1\")  # 不用 int.bit_count：命令行支持 Python 3.8\n\n    def obj(self, s):\n        return self.cost(s) + self.BIG * self.uncovered(s)\n\n\n    # ---- 位编码族复用桥（2026-09-27 ROADMAP 批 7）：_KS max 内核在本 min 域的桥 ----\n    def value(self, s):\n        return -self.obj(s)  # max 协议桥：obj 越小 = value 越大\n\n    def polish(self, s, rng, moves=10):\n        \"\"\"memetic 位翻转爬山（value 协议）。\"\"\"\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            s = self.repair(s)\n            v = self.value(s)\n            if v >= best:\n                s, best = s2 if False else s, v\n            else:\n                s = prev\n        return s\n\n    def repair(self, s):\n        s = list(s)\n        cov = self._covered(s)\n        while self._full & ~cov:  # 贪心补覆盖：新覆盖/成本 比最高者\n            best_i, best_r = None, -1.0\n            for i in range(self.m):\n                if s[i]:\n                    continue\n                new = bin(self._mask[i] & ~cov).count(\"1\")\n                if new == 0:\n                    continue\n                r = new / self.costs[i]\n                if r > best_r:\n                    best_i, best_r = i, r\n            if best_i is None:\n                break\n            s[best_i] = 1\n            cov |= self._mask[best_i]\n        for i in range(self.m):  # 去冗余：删掉后仍全覆盖才删\n            if s[i]:\n                s[i] = 0\n                if self.uncovered(s) > 0:\n                    s[i] = 1\n        return s\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.3 else 0 for _ in range(self.m)])\n\n    def swap(self, s, rng):\n        \"\"\"关一个随机已选集合 + 开一个随机未选集合，再修复——Δ 平滑的成对移动。\"\"\"\n        cand = list(s)\n        on = [i for i in range(self.m) if cand[i]]\n        off = [i for i in range(self.m) if not cand[i]]\n        if on:\n            cand[rng.choice(on)] = 0\n        if off:\n            cand[rng.choice(off)] = 1\n        return self.repair(cand)\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\ndef _sc_greedy(ctx, p, rng):\n    \"\"\"贪心 ln n 锚点（Chvátal 1979）：一次构造，之后持平——确定性对照。\"\"\"\n    s = [0] * ctx.m\n    cov = [0] * ctx.n_el\n    left = ctx.n_el\n    while left > 0:\n        best_i, best_r = None, -1.0\n        for i in range(ctx.m):\n            if s[i]:\n                continue\n            new = sum(1 for e in range(ctx.n_el) if ctx.sets[i][e] and not cov[e])\n            if new == 0:\n                continue\n            r = new / ctx.costs[i]\n            if r > best_r:\n                best_i, best_r = i, r\n        s[best_i] = 1\n        for e in range(ctx.n_el):\n            if ctx.sets[best_i][e] and not cov[e]:\n                cov[e] = 1\n                left -= 1\n    v = ctx.cost(s)\n    for it in range(1, p[\"max_iter\"] + 1):\n        yield {\"iter\": it, \"best\": v, \"cur\": v, \"best_sol\": list(s)}\n\n\n# ============================================================\n# 域七：SAT / MAX-SAT（二进制编码 + WalkSAT + DPLL 精确锚点）\n# ============================================================\n\ndef sat_make(n_vars=30, ratio=4.26, seed=7):\n    \"\"\"随机 3-CNF：ratio=子句/变量。4.26≈相变点（教学甜点：SAT 页常可满足，\n    MAX-SAT 页用 ratio 5.2 生成多为不可满足式——最小化未满足子句数）。\"\"\"\n    rng = random.Random(seed)\n    n_clauses = int(n_vars * ratio)\n    clauses = []\n    for _ in range(n_clauses):\n        lits = []\n        used = set()\n        while len(lits) < 3:\n            v = rng.randrange(n_vars)\n            if v in used:\n                continue\n            used.add(v)\n            lits.append(v + 1 if rng.random() < 0.5 else -(v + 1))\n        clauses.append(lits)\n    return {\"n_vars\": n_vars, \"clauses\": clauses}\n\n\nclass _SAT:\n    \"\"\"SAT 域上下文：编码=真值赋值向量；目标=未满足子句数（min）。\"\"\"\n\n    def __init__(self, problem):\n        self.n = problem[\"n_vars\"]\n        self.clauses = problem[\"clauses\"]\n\n    def unsat(self, s):\n        u = 0\n        for cl in self.clauses:\n            ok = False\n            for lit in cl:\n                v = abs(lit) - 1\n                if s[v] == (1 if lit > 0 else 0):\n                    ok = True\n                    break\n            if not ok:\n                u += 1\n        return u\n\n    def obj(self, s):\n        return self.unsat(s)\n\n\n    # ---- 位编码族复用桥（2026-09-27 ROADMAP 批 7）：_KS max 内核在本 min 域的桥 ----\n    def value(self, s):\n        return -self.obj(s)  # max 协议桥：obj 越小 = value 越大\n\n    def polish(self, s, rng, moves=10):\n        \"\"\"memetic 位翻转爬山（value 协议）。\"\"\"\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            s = self.repair(s)\n            v = self.value(s)\n            if v >= best:\n                s, best = s2 if False else s, v\n            else:\n                s = prev\n        return s\n\n    def repair(self, s):\n        return list(s)  # 无约束：任何赋值都合法\n\n    def random(self, rng):\n        return [rng.randint(0, 1) for _ in range(self.n)]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\ndef _sat_walksat(ctx, p, rng):\n    \"\"\"WalkSAT（Schöning 1999 精神）：随机取未满足子句，以概率 p 翻转其中随机\n    变量，否则翻转「使未满足数降幅最大」的变量——纯本地操作，无种群。\"\"\"\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    wp = p[\"walk_p\"]\n    last_it = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        if v == 0:\n            break  # 已满足：提前收工（SAT 页常态），后面补齐曲线长度\n        unsat = [cl for cl in ctx.clauses\n                 if all(s[abs(l) - 1] != (1 if l > 0 else 0) for l in cl)]\n        cl = unsat[rng.randrange(len(unsat))]\n        if rng.random() < wp:\n            lit = cl[rng.randrange(len(cl))]\n            s[abs(lit) - 1] ^= 1\n        else:\n            best_lit, best_u = None, None\n            for lit in cl:\n                s[abs(lit) - 1] ^= 1\n                u = ctx.obj(s)\n                s[abs(lit) - 1] ^= 1\n                if best_u is None or u < best_u:\n                    best_lit, best_u = lit, u\n            s[abs(best_lit) - 1] ^= 1\n        v = ctx.obj(s)\n        if v < best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n        last_it = it\n    for it2 in range(last_it + 1, p[\"max_iter\"] + 1):  # 补齐：保证曲线恰为 max_iter 个状态\n        yield {\"iter\": it2, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _sat_dpll(ctx, p, rng):\n    \"\"\"DPLL 精确锚点（单位传播 + 分裂）：首个迭代即给出真值最优（SAT 页=0）。\n    确定性算法：与随机种子无关——这就是「精确对照」的教学点。\"\"\"\n    n, clauses = ctx.n, ctx.clauses\n    assign = [None] * n\n\n    def dpll(cl, asg):\n        # 单位传播：仅当子句「尚未满足」且只剩一个未赋值文字时才传播\n        while True:\n            prog = False\n            for c in cl:\n                if any(asg[abs(l) - 1] == (1 if l > 0 else 0)\n                       for l in c if asg[abs(l) - 1] is not None):\n                    continue  # 子句已满足：不能据此传播\n                un = [l for l in c if asg[abs(l) - 1] is None]\n                if not un:\n                    return None  # 全赋值且无真文字：冲突\n                if len(un) == 1:\n                    l = un[0]\n                    v = abs(l) - 1\n                    val = 1 if l > 0 else 0\n                    if asg[v] is not None and asg[v] != val:\n                        return None  # 两个单位子句互相矛盾\n                    asg[v] = val\n                    prog = True\n            if not prog:\n                break\n        if all(any(asg[abs(l) - 1] == (1 if l > 0 else 0) for l in c)\n               for c in cl):\n            return asg\n        v = next((i for i in range(n) if asg[i] is None), None)\n        if v is None:\n            return None\n        for val in (1, 0):\n            asg2 = list(asg)\n            asg2[v] = val\n            r = dpll(cl, asg2)\n            if r is not None:\n                return r\n        return None\n\n    sol = dpll(clauses, assign)\n    if sol is None:\n        # 不可满足（MAX-SAT 页常态）：退化为确定性的最速下降 MAX-SAT 兜底，\n        # 让锚点至少是一个合理的局部最优，而不是全 0 赋值\n        sol = [0] * n\n        v = ctx.obj(sol)\n        improved = True\n        while improved:\n            improved = False\n            for i in range(n):\n                sol[i] ^= 1\n                nv = ctx.obj(sol)\n                if nv < v:\n                    v = nv\n                    improved = True\n                else:\n                    sol[i] ^= 1\n    u = ctx.obj(sol)\n    for it in range(1, p[\"max_iter\"] + 1):\n        yield {\"iter\": it, \"best\": u, \"cur\": u, \"best_sol\": list(sol)}\n\n\n_SAT_ALGOS = dict(_BIN_ALGOS, **{\n    \"walksat\": {\"fn\": _sat_walksat, \"name\": \"WalkSAT\", \"category\": \"局部搜索\",\n                \"desc\": \"未满足子句内随机/贪心翻转变量（Schöning 系）\", \"tune\": [\"walk_p\"]},\n    \"dpll\": {\"fn\": _sat_dpll, \"name\": \"DPLL 精确\", \"category\": \"精确算法\",\n             \"desc\": \"单位传播 + 分裂的完备精确解（确定性锚点）\", \"tune\": []},\n})\n\n\n# ============================================================\n# 域八：QUBO（二进制二次型，min x'Qx）\n# ============================================================\n\ndef qb_make(n=30, seed=7):\n    \"\"\"随机 QUBO：对角线 -20~60，非对角 ±15（对称）。总有平凡界，实例无约束。\"\"\"\n    rng = random.Random(seed)\n    Q = [[0] * n for _ in range(n)]\n    for i in range(n):\n        Q[i][i] = rng.randint(-20, 60)\n        for j in range(i + 1, n):\n            v = rng.randint(-15, 15)\n            Q[i][j] = v\n            Q[j][i] = v\n    return {\"n\": n, \"Q\": Q}\n\n\nclass _QB:\n    def __init__(self, problem):\n        self.n = problem[\"n\"]\n        self.Q = problem[\"Q\"]\n\n    def obj(self, s):\n        Q = self.Q\n        return sum(Q[i][j] * s[i] * s[j] for i in range(self.n) for j in range(self.n))\n\n\n    # ---- 位编码族复用桥（2026-09-27 ROADMAP 批 7）：_KS max 内核在本 min 域的桥 ----\n    def value(self, s):\n        return -self.obj(s)  # max 协议桥：obj 越小 = value 越大\n\n    def polish(self, s, rng, moves=10):\n        \"\"\"memetic 位翻转爬山（value 协议）。\"\"\"\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            s = self.repair(s)\n            v = self.value(s)\n            if v >= best:\n                s, best = s2 if False else s, v\n            else:\n                s = prev\n        return s\n\n    def repair(self, s):\n        return list(s)\n\n    def random(self, rng):\n        return [rng.randint(0, 1) for _ in range(self.n)]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\n# ============================================================\n# 域九：广义指派 GAP（整数向量编码：任务→代理）\n# ============================================================\n\ndef gap_make(n_a=8, n_j=25, seed=7):\n    \"\"\"随机 GAP：成本 5-40、资源 5-25；代理容量 = 该行资源总和 × 0.65\n    （保证贪心可行且容量有约束力）。\"\"\"\n    rng = random.Random(seed)\n    c = [[rng.randint(5, 40) for _ in range(n_j)] for _ in range(n_a)]\n    r = [[rng.randint(5, 25) for _ in range(n_j)] for _ in range(n_a)]\n    cap = [int(sum(row) * 0.65) for row in r]\n    return {\"n_a\": n_a, \"n_j\": n_j, \"c\": c, \"r\": r, \"cap\": cap}\n\n\nclass _GAP:\n    \"\"\"GAP 域上下文：编码=任务→代理向量；超载用 BIG 罚 + 修复算子。\"\"\"\n    BIG = 1000\n\n    def __init__(self, problem):\n        self.n_a = problem[\"n_a\"]\n        self.n_j = problem[\"n_j\"]\n        self.c = problem[\"c\"]\n        self.r = problem[\"r\"]\n        self.cap = problem[\"cap\"]\n        self.n = self.n_j\n\n    def cost(self, s):\n        return sum(self.c[s[j]][j] for j in range(self.n_j))\n\n    def overflow(self, s):\n        load = [0] * self.n_a\n        for j in range(self.n_j):\n            load[s[j]] += self.r[s[j]][j]\n        return sum(max(0, load[a] - self.cap[a]) for a in range(self.n_a))\n\n    def clamp(self, s):\n        na = self.p[\"n_a\"] if \"n_a\" in self.p else self.n\n        return [max(0, min(na - 1, int(round(v)))) % na if \"n_a\" in self.p else int(v) % na for v in s]\n\n    def swap(self, s, rng):\n        s = list(s)\n        a, b = rng.randrange(len(s)), rng.randrange(len(s))\n        s[a], s[b] = s[b], s[a]\n        return s\n\n    def obj(self, s):\n        return self.cost(s) + self.BIG * self.overflow(s)\n\n    def repair(self, s):\n        s = list(s)\n        while self.overflow(s) > 0:\n            load = [0] * self.n_a\n            for j in range(self.n_j):\n                load[s[j]] += self.r[s[j]][j]\n            over = max(range(self.n_a), key=lambda a: load[a] - self.cap[a])\n            jobs = [j for j in range(self.n_j) if s[j] == over]\n            if not jobs:\n                break\n            j = jobs[0]\n            best_a, best_o = None, None\n            for a in range(self.n_a):\n                if a == over:\n                    continue\n                s[j] = a\n                o = self.overflow(s)\n                if best_o is None or o < best_o:\n                    best_a, best_o = a, o\n            s[j] = best_a\n        return s\n\n    def random(self, rng):\n        return self.repair([rng.randrange(self.n_a) for _ in range(self.n_j)])\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\ndef _gap_random(ctx, p, rng):\n    best, bs = None, None\n    for it in range(1, p[\"max_iter\"] + 1):\n        s = ctx.random(rng)\n        v = ctx.obj(s)\n        if bs is None or v < best:\n            best, bs = v, s\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _gap_hc(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    for it in range(1, p[\"max_iter\"] + 1):\n        for _ in range(p[\"tries\"]):\n            cand = list(s)\n            cand[rng.randrange(ctx.n_j)] = rng.randrange(ctx.n_a)\n            cand = ctx.repair(cand)\n            cv = ctx.obj(cand)\n            if cv <= v:\n                s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _gap_sa(ctx, p, rng):\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    t0, decay = p[\"t0\"], p[\"decay\"]\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        T = t0 * (decay ** it)\n        cand = list(s)\n        cand[rng.randrange(ctx.n_j)] = rng.randrange(ctx.n_a)\n        cand = ctx.repair(cand)\n        cv = ctx.obj(cand)\n        d = cv - v\n        if d < 0 or (T > 1e-12 and rng.random() < math.exp(-d / T)):\n            s, v = cand, cv\n        if v < best:\n            best, bs = v, list(s)\n            stall = 0\n        else:\n            stall += 1\n        if stall >= p[\"restart_at\"]:  # ILS：罚函数景观下单链易卡，停滞即全新重启\n            s = ctx.random(rng)\n            v = ctx.obj(s)\n            stall = 0\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\ndef _gap_ga(ctx, p, rng):\n    pop, vals = ctx.init_pop(p, rng)\n    bi = argbest(vals, \"min\")\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            child = [pop[a][j] if rng.random() < 0.5 else pop[b][j] for j in range(ctx.n_j)]\n            for _ in range(2):\n                child[rng.randrange(ctx.n_j)] = rng.randrange(ctx.n_a)\n            child = ctx.repair(child)\n            new.append(child)\n        pop = new\n        vals = [ctx.obj(s) for s in pop]\n        bi = argbest(vals, \"min\")\n        if vals[bi] < best:\n            best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": min(vals), \"best_sol\": list(bs)}\n\n\n_GAP_ALGOS = {\n    \"random\": {\"fn\": _gap_random, \"name\": \"随机搜索\", \"category\": \"基线\",\n               \"desc\": \"盲指派基线：一切算法都要显著降低总成本\", \"tune\": []},\n    \"hc\": {\"fn\": _gap_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\",\n           \"desc\": \"单任务改派贪心（容量修复后评价）\", \"tune\": [\"tries\"]},\n    \"sa\": {\"fn\": _gap_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\",\n           \"desc\": \"改派移动 + Metropolis 准则\", \"tune\": [\"t0\", \"decay\"]},\n    \"ga\": {\"fn\": _gap_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\",\n           \"desc\": \"整数均匀交叉 + 改派变异 + 修复\", \"tune\": []},\n}\n\n\n# ============================================================\n# 域十：无容量设施选址 UFLP（开-关向量 + 最近设施指派）\n# ============================================================\n\ndef uf_make(n_f=15, n_c=45, seed=7):\n    \"\"\"随机 UFLP：固定成本 80-200；每个客户只有 3 个「偏好设施」指派成本\n    低（5-15），其余 50-120——开哪些设施产生组合耦合，盲采样吃亏、\n    局部搜索系统占优（bench 实测：random ~1354，swap-HC ~1173，局部最优 ~1129）。\n    平面坐标供可视化。\"\"\"\n    rng = random.Random(seed)\n    f_cost = [rng.randint(80, 200) for _ in range(n_f)]\n    c_cost = [[rng.randint(50, 120) for _ in range(n_c)] for _ in range(n_f)]\n    for j in range(n_c):\n        for a in rng.sample(range(n_f), 3):\n            c_cost[a][j] = rng.randint(5, 15)\n    pos_f = [[round(rng.uniform(5, 95), 1), round(rng.uniform(5, 95), 1)] for _ in range(n_f)]\n    pos_c = [[round(rng.uniform(5, 95), 1), round(rng.uniform(5, 95), 1)] for _ in range(n_c)]\n    return {\"n_f\": n_f, \"n_c\": n_c, \"f_cost\": f_cost, \"c_cost\": c_cost,\n            \"pos_f\": pos_f, \"pos_c\": pos_c}\n\n\nclass _UF:\n    \"\"\"UFLP 域上下文：编码=设施开关向量；指派=每个客户选 cheapest open。\"\"\"\n\n    def __init__(self, problem):\n        self.n_f = problem[\"n_f\"]\n        self.n_c = problem[\"n_c\"]\n        self.f_cost = problem[\"f_cost\"]\n        self.c_cost = problem[\"c_cost\"]\n        self.n = self.n_f\n\n    def assign(self, s):\n        return [min((a for a in range(self.n_f) if s[a]),\n                    key=lambda a: self.c_cost[a][j]) for j in range(self.n_c)]\n\n    def obj(self, s):\n        if not any(s):\n            return 10 ** 9\n        a = self.assign(s)\n        return (sum(self.f_cost[i] for i in range(self.n_f) if s[i])\n                + sum(self.c_cost[a[j]][j] for j in range(self.n_c)))\n\n    # ---- 位编码协议桥（批 7 续）：_KS max 内核在本 min 域的 value/polish ----\n    def value(self, s):\n        return -self.obj(s)\n\n    def polish(self, s, rng, moves=10):\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            k = rng.randrange(self.n)\n            s[k] ^= 1\n            s = self.repair(s)\n            v = self.value(s)\n            if v >= best:\n                best, s = v, s\n            else:\n                s = prev\n        return s\n\n    def repair(self, s):\n        s = list(s)\n        if not any(s):\n            s[min(range(self.n_f), key=lambda i: self.f_cost[i])] = 1\n        return s\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.4 else 0 for _ in range(self.n_f)])\n\n    def swap(self, s, rng):\n        \"\"\"关一个随机已开设施 + 开一个随机未开设施——UFLP 标准交换邻域。\"\"\"\n        cand = list(s)\n        on = [i for i in range(self.n_f) if cand[i]]\n        off = [i for i in range(self.n_f) if not cand[i]]\n        if on:\n            cand[rng.choice(on)] = 0\n        if off:\n            cand[rng.choice(off)] = 1\n        return self.repair(cand)\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\n# ---- UFLP 专属局部搜索内核（complete-a-kernels 2026-09-29）----\ndef _uf_local(ctx, p, rng):\n    \"\"\"UFLP 专属局部搜索内核：单设施随机一阶改进（达局部最优）+ 关一开一交换（0.6 概率）\n    + 停滞重启（restart_at=25）。修复 UFLP「设施+服务」复合目标卡坏局部最优\n    （_KS 贪心桥 3616 vs random 1338 失效）。min 域（obj=设施开费+客户指派费）。\"\"\"\n    s = ctx.random(rng)\n    best = ctx.obj(s)\n    stall = 0\n    restart_at = 25\n    for it in range(1, p[\"max_iter\"] + 1):\n        improved = True\n        while improved:\n            improved = False\n            order = list(range(ctx.n_f)); rng.shuffle(order)\n            for i in order:\n                cand = list(s); cand[i] ^= 1; cand = ctx.repair(cand)\n                v = ctx.obj(cand)\n                if v < best:\n                    s, best = cand, v; improved = True; break\n        if rng.random() < 0.6:\n            cand = ctx.swap(s, rng)\n            v = ctx.obj(cand)\n            if v < best:\n                s, best = cand, v; stall = 0\n            else:\n                stall += 1\n        else:\n            stall += 1\n        if stall >= restart_at:\n            s = ctx.random(rng); best = ctx.obj(s); stall = 0\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(s), \"cur\": ctx.obj(s)}\n\n\ndef _uf_greedy(ctx, p, rng):\n    \"\"\"贪心锚点：add+drop 双向局部搜索 + swap 抛光（从空集起，确定性对照）。\n    纯 add/drop 在偏好结构实例上会卡在差局部最优（seed21 实测输给随机基线），\n    加一轮「关一开一」交换抛光后与 swap 内核的局部最优同品质。\"\"\"\n    s = [0] * ctx.n_f\n    s[min(range(ctx.n_f), key=lambda i: ctx.f_cost[i])] = 1\n    improved = True\n    while improved:\n        improved = False\n        base = ctx.obj(s)\n        for i in range(ctx.n_f):\n            s[i] ^= 1\n            v = ctx.obj(s)\n            if v < base:\n                base = v\n                improved = True\n            else:\n                s[i] ^= 1\n    # swap 抛光：add/drop 局部最优再经「关一开一」成对移动改进\n    improved = True\n    while improved:\n        improved = False\n        base = ctx.obj(s)\n        for i in range(ctx.n_f):\n            if not s[i]:\n                continue\n            for j in range(ctx.n_f):\n                if s[j]:\n                    continue\n                s[i] = 0\n                s[j] = 1\n                v = ctx.obj(s)\n                if v < base:\n                    base = v\n                    improved = True\n                    break\n                s[i] = 1\n                s[j] = 0\n            else:\n                continue\n            break\n    v = ctx.obj(s)\n    for it in range(1, p[\"max_iter\"] + 1):\n        yield {\"iter\": it, \"best\": v, \"cur\": v, \"best_sol\": list(s)}\n\n\n_UF_ALGOS = dict(_SW_ALGOS, **{\n    \"greedy\": {\"fn\": _uf_greedy, \"name\": \"贪心锚点\", \"category\": \"构造启发\",\n               \"desc\": \"add+drop 双向局部搜索到局部最优（确定性对照）\", \"tune\": []},\n})\n\n\n# ============================================================\n# 域十一：背包家族变体 kpvar（10 变体单域多预设，H 期）\n# 编码按变体分派：bkp/ukp/cmp=复制展开 0-1 位；mkpm=类 GAP 指派编码\n# （x[i]∈{0..m}，0=不取）；mckp=k*r one-hot 位；其余=0-1 位。\n# 内核全复用 _BIN/_GAP 系 + 变体 repair/目标。\n# ============================================================\n\ndef kpv_make(variant=\"ssp\", n=40, seed=7, k=None, r=None):\n    rng = random.Random(seed)\n    if variant == \"cmp\":  # 找零：币值 expanded 成枚，目标金额 T\n        denoms = [1, 2, 5, 10, 20, 50]\n        T = rng.randint(120, 200)\n        items = [[d, 1] for d in denoms for _ in range(min(T // d, 8))]\n        return {\"variant\": variant, \"denoms\": denoms, \"T\": T,\n                \"items\": items, \"cap\": T}\n    # 价值型变体复用背包枢纽 ks_make 的标定分布（w 2-60 / v 10-100 / cap 45%），\n    # 45 个 _KS 内核在该分布上已通过「全算法赢随机」标定\n    base = ks_make(n=n, seed=seed)\n    w = [x[0] for x in base[\"items\"]]\n    v = [x[1] for x in base[\"items\"]]\n    cap = base[\"cap\"]\n    if variant == \"mkpm\":  # 多背包：m 个包，指派编码（0=不取）；松容量（合计 74%）保证指派算法赢随机\n        return {\"variant\": variant, \"n\": n, \"w\": w, \"v\": v, \"m\": 3,\n                \"caps\": [int(sum(w) * f) for f in (0.30, 0.22, 0.22)]}\n    if variant == \"mckp\":  # 多选择：k 类 × r 件，每类至多一件\n        # 修1（2026-09-27 用户反馈）：k/r 支持预设与自定义直接指定，默认 n/4 类 × 4 件\n        # （n=48 → 12 类 × 4 件，与历史默认一致）；自定义字段与预设标签同格式\n        k = int(k) if k else max(2, n // 4)\n        r = int(r) if r else 4\n        w2 = [[rng.randint(8, 40) for _ in range(r)] for _ in range(k)]\n        v2 = [[rng.randint(8, 55) for _ in range(r)] for _ in range(k)]\n        return {\"variant\": variant, \"k\": k, \"r\": r, \"w2\": w2, \"v2\": v2,\n                \"cap\": int(sum(max(row) for row in w2) * 0.5)}\n    if variant == \"dkp\":  # 折扣背包 DCKP（Guldan 2007；Rong 等 2012）：每组 3 个候选 = 物品 A、物品 B、捆绑 A+B（重量打 75 折）；每组至多选一个\n        k = max(2, n // 2)\n        w2, v2 = [], []\n        for g in range(k):\n            wa, wb, va, vb = w[2 * g], w[2 * g + 1], v[2 * g], v[2 * g + 1]\n            w2.append([wa, wb, int(round(0.75 * (wa + wb)))])\n            v2.append([va, vb, va + vb])\n        return {\"variant\": variant, \"k\": k, \"r\": 3, \"w2\": w2, \"v2\": v2, \"cap\": int(sum(row[2] for row in w2) * 0.5)}\n    if variant == \"bkp\":  # 有界：每件上限 b[i]，复制展开\n        b = [rng.randint(2, 4) for _ in range(n)]\n        items = [[w[i], v[i]] for i in range(n) for _ in range(b[i])]\n        return {\"variant\": variant, \"b\": b, \"items\": items, \"cap\": cap}\n    if variant == \"ukp\":  # 无界：每件最多 3 份（容量截断；份数过大会出现等值高原，单链算法困死）\n        items = [[w[i], v[i]] for i in range(n) for _ in range(min(3, cap // w[i]))]\n        return {\"variant\": variant, \"items\": items, \"cap\": cap}\n    prob = {\"variant\": variant, \"n\": n, \"w\": w, \"v\": v, \"cap\": cap}\n    if variant == \"mdkp\":  # 多维背包：3 个资源维度，每个物品在每个维度各有独立的重量；每个维度的容量 = 该维度总重量的 45%\n        W = [list(w)] + [[rng.randint(2, 60) for _ in range(n)] for _ in range(2)]\n        prob[\"W\"] = W\n        prob[\"caps\"] = [int(sum(row) * 0.45) for row in W]\n    elif variant == \"qkp\":  # 二次利润：Q 对称非负\n        Q = [[0] * n for _ in range(n)]\n        for i in range(n):\n            for j in range(i + 1, n):\n                Q[i][j] = Q[j][i] = rng.randint(0, 8)\n        prob[\"Q\"] = Q\n    elif variant == \"ssp\":\n        prob[\"target\"] = cap\n    # fractional：与普通 0-1 同实例（LP 上界由前端现算）\n    return prob\n\n\nclass _KPV:\n    \"\"\"背包变体位编码 ctx（fractional/bkp/ukp/cmp/mdkp/dkp/qkp/ssp）。\n    cmp=min 枚数+BIG*|Σ-T|；ssp=min |Σw-T|（配精确 DP 锚点）；\n    价值型=min -value + BIG*超载罚。repair 恒保持可行性。\"\"\"\n    BIG = 10000\n\n    def __init__(self, prob):\n        self.prob = prob\n        self.vt = prob[\"variant\"]\n        if \"items\" in prob:\n            self.items = [tuple(x) for x in prob[\"items\"]]\n            self.w = [x[0] for x in self.items]\n            self.v = [x[1] for x in self.items]\n            self.n = len(self.items)\n        else:\n            self.w, self.v = prob[\"w\"], prob[\"v\"]\n            self.n = prob[\"n\"]\n        self.cap = prob[\"cap\"]\n\n    # ---- _BIN 内核接口 ----\n    def random(self, rng):\n        s = [rng.randint(0, 1) for _ in range(self.n)]\n        # 有容量约束的变体：随机起点先修复（否则 GA 初代全是 BIG 罚个体，梯度消失）\n        return s if self.vt in (\"cmp\", \"ssp\") else self.repair(s)\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n    # ---- 变体语义 ----\n    def eff_w(self, s):\n        return list(self.w)\n\n    def mdkp_loads(self, s):\n        caps = self.prob[\"caps\"]\n        W = self.prob[\"W\"]\n        return [sum(W[d][i] for i in range(self.n) if s[i]) for d in range(len(caps))], caps\n\n    def value(self, s):\n        val = sum(self.v[i] for i in range(self.n) if s[i])\n        if self.vt == \"qkp\":\n            Q = self.prob[\"Q\"]\n            val += sum(Q[i][j] for i in range(self.n) if s[i]\n                       for j in range(i + 1, self.n) if s[j])\n        return val\n\n    def obj(self, s):\n        if self.vt == \"cmp\":\n            total = sum(self.w[i] for i in range(self.n) if s[i])\n            return sum(s) + self.BIG * abs(total - self.prob[\"T\"])\n        if self.vt == \"ssp\":\n            return abs(sum(self.w[i] for i in range(self.n) if s[i]) - self.prob[\"target\"])\n        if self.vt == \"mdkp\":\n            load, caps = self.mdkp_loads(s)\n            over = sum(max(0, load[d] - caps[d]) for d in range(len(caps)))\n        else:\n            ew = self.eff_w(s)\n            over = sum(ew[i] for i in range(self.n) if s[i]) - self.cap\n        return -self.value(s) + self.BIG * max(0, over)\n\n    def repair(self, s):\n        s = list(s)\n        if self.vt in (\"cmp\", \"ssp\"):\n            return s  # 无容量约束（偏离目标由目标函数自身罚）\n        if self.vt == \"mdkp\":\n            load, caps = self.mdkp_loads(s)\n            W = self.prob[\"W\"]\n            while any(load[d] > caps[d] for d in range(len(caps))):\n                on = [i for i in range(self.n) if s[i]]\n                # 去「价值 / 维度压力加权重量」最小项（= 压力加权密度最低）\n                drop = min(on, key=lambda i: self.v[i] / max(1, sum(\n                    max(0, load[d] - caps[d]) * W[d][i] for d in range(len(caps)))))\n                s[drop] = 0\n                load, caps = self.mdkp_loads(s)\n            return s\n        while True:\n            ew = self.eff_w(s)\n            if sum(ew[i] for i in range(self.n) if s[i]) <= self.cap:\n                return s\n            on = [i for i in range(self.n) if s[i]]\n            drop = min(on, key=lambda i: self.v[i] / max(1, ew[i]))  # 去价值密度最低项\n            s[drop] = 0\n\n\nclass _MCKP:\n    \"\"\"多选择背包 one-hot 位编码（k 类 × r 件拍平，每类至多一件）。\"\"\"\n    BIG = 10000\n\n    def __init__(self, prob):\n        self.prob = prob\n        self.k, self.r = prob[\"k\"], prob[\"r\"]\n        self.n = self.k * self.r\n        self.cap = prob[\"cap\"]\n        self.w = [prob[\"w2\"][c][j] for c in range(self.k) for j in range(self.r)]\n        self.v = [prob[\"v2\"][c][j] for c in range(self.k) for j in range(self.r)]\n\n    def random(self, rng):\n        return [rng.randint(0, 1) for _ in range(self.n)]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n    def obj(self, s):\n        if any(sum(s[c * self.r:(c + 1) * self.r]) > 1 for c in range(self.k)):\n            return self.BIG  # one-hot 违约重罚（repair 后实际不可达）\n        val = sum(self.v[i] for i in range(self.n) if s[i])\n        over = sum(self.w[i] for i in range(self.n) if s[i]) - self.cap\n        return -val + self.BIG * max(0, over)\n\n    def repair(self, s):\n        s = list(s)\n        for c in range(self.k):  # 每类只留密度最高的一件\n            on = [i for i in range(c * self.r, (c + 1) * self.r) if s[i]]\n            if len(on) > 1:\n                best = max(on, key=lambda i: self.v[i] / max(1, self.w[i]))\n                for i in on:\n                    s[i] = 1 if i == best else 0\n        while sum(self.w[i] for i in range(self.n) if s[i]) > self.cap:\n            on = [i for i in range(self.n) if s[i]]\n            drop = min(on, key=lambda i: self.v[i] / max(1, self.w[i]))\n            s[drop] = 0\n        return s\n\n\nclass _MKPM:\n    \"\"\"多背包指派编码：x[i] ∈ {0..m}，0=不取，j=放包 j。接口对齐 _gap_* 内核\n    （n_j/n_a/random/repair/obj/init_pop），big-val + BIG*超载罚。\"\"\"\n    BIG = 10000\n\n    def __init__(self, prob):\n        self.prob = prob\n        self.n_j = prob[\"n\"]\n        self.n_a = prob[\"m\"]\n        self.w, self.v = prob[\"w\"], prob[\"v\"]\n        self.caps = prob[\"caps\"]\n        self.cap = sum(self.caps)  # 兼容面\n        self.n = self.n_j\n\n    def loads(self, x):\n        load = [0] * self.n_a\n        for i in range(self.n_j):\n            if x[i]:\n                load[x[i] - 1] += self.w[i]\n        return load\n\n    def overflow(self, x):\n        load = self.loads(x)\n        return sum(max(0, load[a] - self.caps[a]) for a in range(self.n_a))\n\n    def obj(self, x):\n        val = sum(self.v[i] for i in range(self.n_j) if x[i])\n        return -val + self.BIG * self.overflow(x)\n\n    def repair(self, x):\n        x = list(x)\n        for _ in range(3 * self.n_j):  # 先迁移：超载包最差密度项 → slack 最大包\n            load = self.loads(x)\n            over_a = [a for a in range(self.n_a) if load[a] > self.caps[a]]\n            if not over_a:\n                return x\n            worst, worst_key = None, None\n            for i in range(self.n_j):\n                if x[i] and (x[i] - 1) in over_a:\n                    key = self.v[i] / max(1, self.w[i])\n                    if worst_key is None or key < worst_key:\n                        worst, worst_key = i, key\n            if worst is None:\n                break\n            tgt = [a for a in range(self.n_a) if a != x[worst] - 1]\n            best_a = max(tgt, key=lambda a: self.caps[a] - load[a])\n            x[worst] = best_a + 1 if self.caps[best_a] - load[best_a] >= self.w[worst] else 0\n        # 兜底：仍超载则直接丢最差密度项（必终止）\n        load = self.loads(x)\n        for a in range(self.n_a):\n            while load[a] > self.caps[a]:\n                on = [i for i in range(self.n_j) if x[i] == a + 1]\n                drop = min(on, key=lambda i: self.v[i] / max(1, self.w[i]))\n                x[drop] = 0\n                load = self.loads(x)\n        return x\n\n    def random(self, rng):\n        return self.repair([rng.randint(0, self.n_a) for _ in range(self.n_j)])\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\nclass _KPVMaxWrap:\n    \"\"\"把 min-sense 位编码 ctx（_KPV/_MCKP）包装成 _KS 内核期望的 max-value 接口\n    （value/polish/memetic 组件），背包家族变体因此直接复用背包域全部 10 个内核。\"\"\"\n    BIG = 10000\n\n    def __init__(self, ctx):\n        self._ctx = ctx\n        self.prob = ctx.prob\n        self.n = ctx.n\n        self.cap = ctx.cap\n        self.w = ctx.w\n        self.v = ctx.v\n\n    def value(self, s):\n        return -self._ctx.obj(s)\n\n    def obj(self, s):\n        return self._ctx.obj(s)\n\n    def repair(self, s):\n        return self._ctx.repair(s)\n\n    def random(self, rng):\n        return self._ctx.random(rng)\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.value(s) for s in pop]\n\n    def polish(self, s, rng, moves=10):\n        \"\"\"memetic 组件：随机单比特翻转爬山（小预算）。\"\"\"\n        s = list(s)\n        best = self.value(s)\n        for _ in range(moves):\n            prev = list(s)\n            i = rng.randrange(self.n)\n            s[i] ^= 1\n            s2 = self.repair(s)\n            v = self.value(s2)\n            if v >= best:\n                s, best = s2, v\n            else:\n                s = prev\n        return s\n\n\ndef _es_stream(gen, ctx):\n    \"\"\"entryseq 词条：把「当前最优解长什么样」（vrp 的各条路线、pms 的机器分配、聚类的中心……）并进每个状态，\n    页面据此作图，不在前端重算目标函数。\"\"\"\n    for st in gen:\n        if getattr(ctx, \"best_x\", None) is not None:\n            # 连续内核的状态只带前两维、而且有的内核不把热启动 / 初始化阶段评价过的点算进「最优」（如 CEM 的预热采样）：\n            # 这里统一以评价过的全部点里最好的那个为准——上报的最优值 = 它的目标值，best_sol = 它本身\n            if ctx.best_val < st.get(\"best\", float(\"inf\")):\n                st[\"best\"] = ctx.best_val\n            if st.get(\"best\") == ctx.best_val or \"best_sol\" not in st:\n                st[\"best_sol\"] = list(ctx.best_x)\n        if isinstance(st.get(\"best_sol\"), list) and len(st[\"best_sol\"]) == ctx.n:\n            extra = ctx.detail(st[\"best_sol\"])\n            if extra:\n                st.update(extra)\n        yield st\n\n\ndef _neg_stream(gen):\n    \"\"\"_KS 内核流是 max-sense（value）；kpvar 全站 min-sense 口径，取负转发。\"\"\"\n    for st in gen:\n        st = dict(st)\n        st[\"best\"] = -st[\"best\"]\n        st[\"cur\"] = -st[\"cur\"]\n        yield st\n\n\ndef _kpv_ssp_dp(ctx, p, rng):\n    \"\"\"子集和精确锚点：DP 求 reach 集合带父指针回溯，最优 |Σw-T|（一次出解）。\"\"\"\n    w, T = ctx.w, ctx.prob[\"target\"]\n    parent = {0: None}\n    reach = [0]\n    for i, wi in enumerate(w):\n        for s in list(reach):\n            ns = s + wi\n            if ns not in parent:\n                parent[ns] = (s, i)\n                reach.append(ns)\n    best_sum = min(reach, key=lambda s: abs(s - T))\n    sol = [0] * len(w)\n    s = best_sum\n    while parent[s] is not None:\n        s0, i = parent[s]\n        sol[i] = 1\n        s = s0\n    best = abs(best_sum - T)\n    yield {\"iter\": 1, \"best\": best, \"cur\": best, \"best_sol\": sol}\n\n\ndef _kpv_greedy(ctx, p, rng):\n    \"\"\"密度贪心锚点（价值型变体共用）：按 v/w 降序装到不可行为止。\"\"\"\n    n = ctx.n\n    if isinstance(ctx, _MKPM):\n        order = sorted(range(n), key=lambda i: ctx.v[i] / ctx.w[i], reverse=True)\n        x = [0] * n\n        load = [0] * ctx.n_a\n        for i in order:\n            for a in range(ctx.n_a):\n                if load[a] + ctx.w[i] <= ctx.caps[a]:\n                    x[i] = a + 1\n                    load[a] += ctx.w[i]\n                    break\n    elif isinstance(ctx, _MCKP):\n        # 每类先锁定密度最高的一件，再全局降序装\n        best = [max(range(c * ctx.r, (c + 1) * ctx.r),\n                    key=lambda i: ctx.v[i] / ctx.w[i]) for c in range(ctx.k)]\n        order = sorted(best, key=lambda i: ctx.v[i] / ctx.w[i], reverse=True)\n        s = [0] * n\n        total = 0\n        for i in order:\n            if total + ctx.w[i] <= ctx.cap:\n                s[i] = 1\n                total += ctx.w[i]\n        x = s\n    elif getattr(ctx, \"vt\", None) == \"mdkp\":\n        # 多维背包：按「价值 / 各维相对占用之和」降序，每一维都装得下才取\n        W, caps = ctx.prob[\"W\"], ctx.prob[\"caps\"]\n        order = sorted(range(n), key=lambda i: ctx.v[i] / max(1e-9, sum(W[d][i] / caps[d] for d in range(len(caps)))), reverse=True)\n        s = [0] * n\n        load = [0] * len(caps)\n        for i in order:\n            if all(load[d] + W[d][i] <= caps[d] for d in range(len(caps))):\n                s[i] = 1\n                for d in range(len(caps)):\n                    load[d] += W[d][i]\n        x = s\n    else:\n        order = sorted(range(n), key=lambda i: ctx.v[i] / ctx.w[i], reverse=True)\n        s = [0] * n\n        total = 0\n        for i in order:\n            if total + ctx.w[i] <= ctx.cap:\n                s[i] = 1\n                total += ctx.w[i]\n        x = s\n    best = ctx.obj(x)\n    yield {\"iter\": 1, \"best\": best, \"cur\": best, \"best_sol\": list(x)}\n\n\ndef _kpv_cmp_dp(ctx, p, rng):\n    \"\"\"找零精确锚点：min-coin DP（dp[x]=凑 x 的最少枚数），在 |Σ-T| 罚下取最优可达和。\"\"\"\n    denoms = sorted(ctx.prob[\"denoms\"])\n    T = ctx.prob[\"T\"]\n    INF = float(\"inf\")\n    maxs = T + max(denoms)\n    dp = [INF] * (maxs + 1)\n    dp[0] = 0\n    for x in range(1, maxs + 1):\n        for d in denoms:\n            if d <= x and dp[x - d] + 1 < dp[x]:\n                dp[x] = dp[x - d] + 1\n    reach = [x for x in range(maxs + 1) if dp[x] < INF]\n    best_x = min(reach, key=lambda x: dp[x] + ctx.BIG * abs(x - T))\n    sol = [0] * ctx.n\n    x = best_x\n    while x > 0:\n        for d in denoms:\n            if d <= x and dp[x] == dp[x - d] + 1:\n                for i in range(ctx.n):  # 定位一枚未用的 d\n                    if ctx.w[i] == d and not sol[i]:\n                        sol[i] = 1\n                        break\n                x -= d\n                break\n    best = dp[best_x] + ctx.BIG * abs(best_x - T)\n    yield {\"iter\": 1, \"best\": best, \"cur\": best, \"best_sol\": sol}\n\n\n# ============================================================\n# 域：着色家族 gcvar（H2 单域多预设：列表/预染/边/全/MIS 五变体）\n# 排列编码变体（listcolor/precolor/edgecolor/totalcolor）复用 _pm_* 排列内核；\n# mis 用 0/1 位串编码，复用 _bin_* 位串内核（禁改现有图着色/装箱内核）。\n# ============================================================\n\ndef _graph_adj(edges, n):\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n        adj[v].append(u)\n    return adj\n\n\ndef _greedy_ff_color(adj, rng):\n    \"\"\"随机序 First-Fit 正常着色，返回合法 col 数组。\"\"\"\n    n = len(adj)\n    order = list(range(n))\n    rng.shuffle(order)\n    col = [-1] * n\n    for v in order:\n        used = {col[u] for u in adj[v] if col[u] >= 0}\n        c = 0\n        while c in used:\n            c += 1\n        col[v] = c\n    return col\n\n\ndef _list_colorable(adj, lists, rng):\n    \"\"\"随机试若干排列的 FF-list 解码，能得 0 冲突即视为列表可着色。\"\"\"\n    n = len(adj)\n    for _ in range(16):\n        perm = list(range(n))\n        rng.shuffle(perm)\n        col = [-1] * n\n        ok = True\n        for v in perm:\n            used = {col[u] for u in adj[v] if col[u] >= 0}\n            cand = [c for c in lists[v] if c not in used]\n            if not cand:\n                ok = False\n                break\n            col[v] = min(cand)\n        if ok:\n            return True\n    return False\n\n\ndef gcv_make(variant=\"listcolor\", n=40, seed=7, p=0.5):\n    \"\"\"着色家族实例生成：先生成 DSJC 随机图 G（环形布局），再按变体加约束/变换。\n    listcolor=每顶点候选色列表（删 1-2 色，校验可着色）；precolor=先合法着色再固定 20-30%；\n    edgecolor=线图 L(G)；totalcolor=全图 T(G)；mis=同图（位串编码，见 _MIS）。\"\"\"\n    rng = random.Random(seed)\n    edges = [[i, j] for i in range(n) for j in range(i + 1, n) if rng.random() < p]\n    pos = []\n    for i in range(n):\n        ang = 2 * math.pi * i / n\n        pos.append([round(50 + 42 * math.cos(ang) + rng.uniform(-4, 4), 1),\n                    round(50 + 42 * math.sin(ang) + rng.uniform(-4, 4), 1)])\n    adj = _graph_adj(edges, n)\n    prob = {\"variant\": variant, \"n\": n, \"edges\": edges, \"pos\": pos, \"p\": p}\n    if variant == \"listcolor\":\n        # 候选色列表：调色板 K = max_degree + 3（宽松但保留约束感）；每顶点删 1-2 色。\n        # 生成后校验列表可着色（随机若干排列 FF-list 能得 0 冲突），不可着色则重试删色。\n        K = max((len(a) for a in adj), default=0) + 3\n        for _ in range(60):\n            lists = []\n            for i in range(n):\n                allc = list(range(K))\n                rm = rng.sample(allc, min(rng.randint(1, 2), K - 2))\n                lists.append(sorted(set(allc) - set(rm)))\n            if _list_colorable(adj, lists, rng):\n                prob[\"lists\"] = lists\n                prob[\"K\"] = K\n                break\n        else:\n            lists = [list(range(K))[:-1] for _ in range(n)]\n            prob[\"lists\"] = lists\n            prob[\"K\"] = K\n    elif variant == \"precolor\":\n        # 先合法着色再固定 20-30% 顶点\n        col = _greedy_ff_color(adj, rng)\n        K = max(col) + 1\n        nfix = int(n * rng.uniform(0.2, 0.3))\n        fix = [-1] * n\n        for i in rng.sample(range(n), nfix):\n            fix[i] = col[i]\n        prob[\"precol\"] = fix\n        prob[\"K\"] = K\n    elif variant == \"edgecolor\":\n        # 线图变换 L(G)：G 的边→L(G) 顶点，相邻边对（共享顶点）→L(G) 边\n        m = len(edges)\n        lad = [[] for _ in range(m)]\n        for a in range(m):\n            u1, v1 = edges[a]\n            for b in range(m):\n                if a == b:\n                    continue\n                u2, v2 = edges[b]\n                if u1 in (u2, v2) or v1 in (u2, v2):\n                    lad[a].append(b)\n        prob[\"ladj\"] = lad\n        prob[\"m\"] = m\n    elif variant == \"totalcolor\":\n        # 全图 T(G)：顶点+边元素，邻接=顶-顶/边-边/顶-边关联\n        m = len(edges)\n        N = n + m\n        tad = [[] for _ in range(N)]\n        for u, v in edges:\n            tad[u].append(v)\n            tad[v].append(u)\n        for a in range(m):\n            u1, v1 = edges[a]\n            for b in range(m):\n                if a == b:\n                    continue\n                u2, v2 = edges[b]\n                if u1 in (u2, v2) or v1 in (u2, v2):\n                    tad[n + a].append(n + b)\n            tad[u1].append(n + a)\n            tad[n + a].append(u1)\n            tad[v1].append(n + a)\n            tad[n + a].append(v1)\n        prob[\"tadj\"] = tad\n        prob[\"nV\"] = n\n        prob[\"m\"] = m\n        prob[\"N\"] = N\n    # mis 同图实例，无额外约束（位串编码，见 _MIS）\n    return prob\n\n\nclass _GCV:\n    \"\"\"着色家族排列编码 ctx（listcolor/precolor/edgecolor/totalcolor）。\n    解码 = 按排列顺序给元素分配最小可用颜色（listcolor 限列表 / precolor 锁预染 /\n    edgecolor/totalcolor 走线图/全图邻接）。obj = (色数 k, 冲突数, Σci²)。\"\"\"\n    BIG = 100000\n\n    def __init__(self, problem):\n        vt = problem[\"variant\"]\n        if vt == \"edgecolor\":\n            self.N = problem[\"m\"]\n            self.elem_adj = [list(a) for a in problem[\"ladj\"]]\n            self.lists = None\n            self.fixed = [-1] * self.N\n        elif vt == \"totalcolor\":\n            self.N = problem[\"N\"]\n            self.elem_adj = [list(a) for a in problem[\"tadj\"]]\n            self.lists = None\n            self.fixed = [-1] * self.N\n        else:\n            self.N = problem[\"n\"]\n            self.elem_adj = _graph_adj(problem[\"edges\"], self.N)\n            self.lists = problem.get(\"lists\")\n            self.fixed = problem.get(\"precol\") or [-1] * self.N\n        self.n = self.N  # _pm_ts 等内核用 ctx.n\n\n    def _color(self, perm):\n        N = self.N\n        col = [-1] * N\n        # 预染顶点必须最先上色：否则非预染顶点若先于其预染邻居被处理，\n        # 会因「只规避已上色邻居」而误取预染色，造成冲突（precolor 必现）。\n        for e in range(N):\n            if self.fixed[e] >= 0:\n                col[e] = self.fixed[e]\n        for e in perm:\n            if self.fixed[e] >= 0:\n                continue\n            used = {col[x] for x in self.elem_adj[e] if col[x] >= 0}\n            if self.lists is not None:\n                cand = [c for c in self.lists[e] if c not in used]\n                col[e] = min(cand) if cand else min(self.lists[e])\n            else:\n                c = 0\n                while c in used:\n                    c += 1\n                col[e] = c\n        return col\n\n    def decode(self, perm):\n        col = self._color(perm)\n        conf = 0\n        for e in range(self.N):\n            ce = col[e]\n            for x in self.elem_adj[e]:\n                if x > e and col[x] == ce:\n                    conf += 1\n        k = (max(col) + 1) if self.N else 0\n        tie = sum(c * c for c in col)\n        return (k, conf, tie)\n\n    def solution(self, perm):\n        return self._color(perm)\n\n    def better(self, a, b):\n        # 合法性（conf=0）优先于色数：着色演示必须展示合法着色，非法着色\n        # （预染冲突 / 列表死胡同）即使色数更少也不算优。同合法下最小化色数 k，再 Σci²。\n        return (a[1] > 0, a[0], a[2]) < (b[1] > 0, b[0], b[2])\n\n    def diff(self, c1, c2):\n        return (((c2[1] > 0) - (c1[1] > 0)) * 10 ** 9\n                + (c2[0] - c1[0]) * 1000\n                + (c2[2] - c1[2]))\n\n    def random(self, rng):\n        p = list(range(self.N))\n        rng.shuffle(p)\n        return p\n\n\ndef _gcv_greedy(ctx, p, rng):\n    \"\"\"多起点 First-Fit 贪心（构造式锚点，确定性）：在度降序、度升序与若干随机序中取最优着色。\n    列表/预染/线图/全图统一走解码；覆盖足够序空间，作为对照基线不劣于纯随机 best-of-200。\"\"\"\n    orderings = [sorted(range(ctx.N), key=lambda e: -len(ctx.elem_adj[e])),\n                 sorted(range(ctx.N), key=lambda e: len(ctx.elem_adj[e]))]\n    for _ in range(200):\n        o = list(range(ctx.N))\n        rng.shuffle(o)\n        orderings.append(o)\n    best_c, best_perm = None, None\n    for o in orderings:\n        c = ctx.decode(o)\n        if best_c is None or c < best_c:\n            best_c, best_perm = c, list(o)\n    yield {\"iter\": 1, \"best\": best_c[0], \"cur\": best_c[0], \"tie\": best_c[1],\n           \"best_sol\": ctx.solution(best_perm)}\n\n\nclass _MIS:\n    \"\"\"MIS 最大独立集：0/1 位串编码，obj = -|S| + BIG*冲突（repair 后恒 0 冲突）。复用 _bin_* 位串内核。\"\"\"\n    BIG = 10000\n\n    def __init__(self, problem):\n        self.n = problem[\"n\"]\n        self.adj = _graph_adj(problem[\"edges\"], self.n)\n\n    def obj(self, s):\n        size = sum(s)\n        conf = 0\n        for u in range(self.n):\n            if s[u]:\n                for v in self.adj[u]:\n                    if v > u and s[v]:\n                        conf += 1\n        return -size + self.BIG * conf\n\n    def repair(self, s):\n        s = list(s)\n        while True:\n            bad = None\n            for u in range(self.n):\n                if not s[u]:\n                    continue\n                for v in self.adj[u]:\n                    if v > u and s[v]:\n                        bad = u if len(self.adj[u]) >= len(self.adj[v]) else v\n                        break\n                if bad is not None:\n                    break\n            if bad is None:\n                return s\n            s[bad] = 0\n\n    def random(self, rng):\n        return self.repair([1 if rng.random() < 0.5 else 0 for _ in range(self.n)])\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.obj(s) for s in pop]\n\n\ndef _mis_greedy(ctx, p, rng):\n    \"\"\"度升序贪心（确定性锚点）：度小者优先入集，与已选顶点相邻则跳过。\"\"\"\n    order = sorted(range(ctx.n), key=lambda i: len(ctx.adj[i]))\n    s = [0] * ctx.n\n    taken = set()\n    for i in order:\n        if not any(nei in taken for nei in ctx.adj[i]):\n            s[i] = 1\n            taken.add(i)\n    best = ctx.obj(s)\n    yield {\"iter\": 1, \"best\": best, \"cur\": best, \"best_sol\": list(s)}\n\n\n# ============================================================\n# 注册表与统一接口\n# ============================================================\n\n_KS_ALGOS = {\n    \"random\": {\"fn\": _ks_random, \"name\": \"随机搜索\", \"category\": \"基线\", \"desc\": \"盲采样基线：一切算法都要显著赢它\", \"tune\": []},\n    \"hc\": {\"fn\": _ks_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\", \"desc\": \"单比特翻转贪心\", \"tune\": [\"tries\"]},\n    \"sa\": {\"fn\": _ks_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\", \"desc\": \"Metropolis 准则允许暂时变差\", \"tune\": [\"t0\", \"decay\"]},\n    \"ga\": {\"fn\": _ks_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\", \"desc\": \"均匀交叉 + 位翻转变异 + 精英\", \"tune\": [\"pm\"]},\n    \"de\": {\"fn\": _ks_de, \"name\": \"二进制差分 DE\", \"category\": \"进化计算\", \"desc\": \"差向量 = r2/r3 不同的位\", \"tune\": [\"F\", \"CR\"]},\n    \"ts\": {\"fn\": _ks_ts, \"name\": \"禁忌搜索 TS\", \"category\": \"局部搜索\", \"desc\": \"禁忌表 + 全邻域选优\", \"tune\": [\"tenure\"]},\n    \"abc\": {\"fn\": _ks_abc, \"name\": \"人工蜂群 ABC\", \"category\": \"群体智能\", \"desc\": \"雇佣/观察/侦察三阶段\", \"tune\": [\"limit\"]},\n    \"woa\": {\"fn\": _ks_woa, \"name\": \"鲸鱼 WOA\", \"category\": \"群体智能\", \"desc\": \"包围/螺旋二值化\", \"tune\": []},\n    \"gwo\": {\"fn\": _ks_gwo, \"name\": \"灰狼 GWO\", \"category\": \"群体智能\", \"desc\": \"α/β/δ 逐位投票（bGWO）\", \"tune\": []},\n    \"cs\": {\"fn\": _ks_cs, \"name\": \"布谷鸟 CS\", \"category\": \"群体智能\", \"desc\": \"莱维翻转 + 弃巢\", \"tune\": [\"pa\"]},\n}\n\n\n# ---- 连续域扩容批 1（2026-09-27 ROADMAP 批 1：正典连续公式，连续域原生）----\n\ndef _cn_fa(ctx, p, rng):\n    \"\"\"萤火虫 FA（Yang 2008）连续经典：亮度=1/(1+目标)，向更亮者移动 β=1/(1+r²) + α 扰动衰减。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    best, bpos = min(zip(vals, pop))\n    alpha = 0.6\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: vals[i])\n        bi = order[0]\n        for i in range(len(pop)):\n            j = order[rng.randrange(max(1, order.index(i)))] if order.index(i) > 0 else bi\n            r2 = sum((a - b) ** 2 for a, b in zip(pop[i], pop[j]))\n            beta = 1.0 / (1.0 + r2)\n            pop[i] = ctx.clamp([a + beta * (b - a) + alpha * (rng.random() - 0.5)\n                                for a, b in zip(pop[i], pop[j])])\n            vals[i] = ctx.eval(pop[i])\n        cb, cp = min(zip(vals, pop))\n        if cb < best:  # 上报历史最优：只降不升（原先每代取当代种群的最优，会变差）\n            best, bpos = cb, list(cp)\n        alpha *= 0.97\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_ba(ctx, p, rng):\n    \"\"\"蝙蝠 BA（Yang 2010）连续经典：频率调谐 + 响度/脉冲率自适应衰减。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    best, bpos = min(zip(vals, pop))\n    n = len(pop)\n    vel = [[0.0] * ctx.dim for _ in range(n)]\n    A = [0.9] * n\n    r0 = [0.5] * n\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(n):\n            f = 0.2 + 0.8 * rng.random()\n            vel[i] = [v + (x - b) * f for v, x, b in zip(vel[i], pop[i], bpos)]\n            cand = ctx.clamp([x + v for x, v in zip(pop[i], vel[i])])\n            if rng.random() > r0[i]:\n                cand = ctx.clamp([b + 0.08 * (ctx.hi - ctx.lo) * rng.gauss(0, 1) for b in bpos])\n            c = ctx.eval(cand)\n            if c <= vals[i] and rng.random() < A[i]:\n                pop[i], vals[i] = cand, c\n                A[i] *= 0.9\n                r0[i] = r0[i] * (1 - math.exp(-0.9 * it))\n            if c < best:\n                best, bpos = c, list(cand)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_jaya(ctx, p, rng):\n    \"\"\"Jaya（Rao 2016）连续经典：x' = x + r1·(best − |x|) − r2·(worst − |x|)，零专属参数。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    for it in range(1, p[\"max_iter\"] + 1):\n        best, bpos = min(zip(vals, pop))\n        worst, wpos = max(zip(vals, pop))\n        # Rao 2016 原式：Best/Worst = 全局最好/最差解的对应维值\n        for i in range(len(pop)):\n            cand = ctx.clamp([\n                x + rng.random() * (b - abs(x)) - rng.random() * (w - abs(x))\n                for x, b, w in zip(pop[i], bpos, wpos)])\n            c = ctx.eval(cand)\n            # 本站变体：贪心准入——远离 worst 项在收敛后期会把好解推离最优（连续域实测发散）\n            if c < vals[i]:\n                pop[i], vals[i] = cand, c\n        best, bpos = min(zip(vals, pop))\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_gsa(ctx, p, rng):\n    \"\"\"引力搜索 GSA（Rashedi 2009）连续经典：质量=归一化适应度，引力加速度驱动速度-位置。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    G0 = 1.0  # G0=100 时初代加速度 ~230/维，纯暴力随机游走\n    span = ctx.hi - ctx.lo\n    vel = [[(b - x) * 0.1 for x, b in zip(x0, min(zip(vals, pop))[1])] for x0 in pop]\n    best, bpos = min(zip(vals, pop))\n    for it in range(1, p[\"max_iter\"] + 1):\n        lo_v, hi_v = min(vals), max(vals)\n        span = max(1e-12, hi_v - lo_v)\n        m = [(hi_v - v) / span + 1e-9 for v in vals]\n        ms = sum(m)\n        m = [x / ms for x in m]\n        G = G0 * math.exp(-3.0 * it / p[\"max_iter\"])  # 衰减放缓：快衰减 30 代内引力场消失\n        new = []\n        for i in range(len(pop)):\n            ax = [0.0] * ctx.dim\n            for j in range(len(pop)):\n                if j == i:\n                    continue\n                d = max(1e-9, math.dist(pop[i], pop[j]))\n                for k in range(ctx.dim):\n                    ax[k] += G * m[j] * (pop[j][k] - pop[i][k]) / d\n            # 原文速度累积：v = rand·v + a；位置 = 位置 + v\n            vel[i] = [max(-span, min(span, 0.7 * rng.random() * v + a))\n                      for v, a in zip(vel[i], ax)]  # 速度阻尼+限幅：无界速度 200 代发散\n            new.append(ctx.clamp([x + v for x, v in zip(pop[i], vel[i])]))\n        pop = new\n        vals = [ctx.eval(x) for x in pop]\n        cb, cp = min(zip(vals, pop))\n        if cb < best:  # 上报历史最优：只降不升（原先每代取当代种群的最优，会变差）\n            best, bpos = cb, list(cp)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_mfo(ctx, p, rng):\n    \"\"\"蛾焰 MFO（Mirjalili 2015）连续经典：螺旋飞行绕火焰，焰数逐代递减。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    flames, fvals = list(pop), list(vals)\n    best, bpos = min(zip(fvals, flames))\n    N = len(pop)\n    b = 1.0\n    for it in range(1, p[\"max_iter\"] + 1):\n        fn = max(1, round(N - it * (N - 1) / p[\"max_iter\"]))\n        for i in range(N):\n            fl = flames[i % len(flames)]\n            t = rng.uniform(-1.0, 1.0)\n            Dv = math.dist(pop[i], fl)  # 到火焰的距离（整体，非逐维）\n            pop[i] = ctx.clamp([\n                Dv * math.exp(b * t) * math.cos(2 * math.pi * t) + f for f in fl])\n            vals[i] = ctx.eval(pop[i])\n        # 火焰表更新：pop ∪ 旧 flames 取 top fn（原文标准——不是每代直接砍表）\n        cand = pop + flames\n        cvals = vals + fvals\n        order = sorted(range(len(cand)), key=lambda i: cvals[i])[:fn]\n        flames = [cand[i] for i in order]\n        fvals = [cvals[i] for i in order]\n        best, bpos = min(zip(fvals, flames))\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_tlbo(ctx, p, rng):\n    \"\"\"教与学 TLBO（Rao 2011）连续经典：教师阶段向最优-均值靠拢，学习阶段两两互学。零专属参数。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    for it in range(1, p[\"max_iter\"] + 1):\n        best, bpos = min(zip(vals, pop))\n        mean = [sum(x[k] for x in pop) / len(pop) for k in range(ctx.dim)]\n        for i in range(len(pop)):\n            tf = rng.randint(1, 2)\n            cand = ctx.clamp([x + rng.random() * (b - tf * m)\n                              for x, b, m in zip(pop[i], bpos, mean)])\n            c = ctx.eval(cand)\n            if c < vals[i]:\n                pop[i], vals[i] = cand, c\n        idx = list(range(len(pop)))\n        rng.shuffle(idx)\n        for a, b in zip(idx[::2], idx[1::2]):\n            better, worse = (a, b) if vals[a] < vals[b] else (b, a)\n            cand = ctx.clamp([x + rng.random() * (px - qx)\n                              for x, px, qx in zip(pop[worse], pop[better], pop[worse])])\n            c = ctx.eval(cand)\n            if c < vals[worse]:\n                pop[worse], vals[worse] = cand, c\n        best, bpos = min(zip(vals, pop))\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\n\n\n# ---- 连续域扩容批 2 ----\n\ndef _cn_hs(ctx, p, rng):\n    \"\"\"和声搜索 HS（Geem 2001）连续经典：HMCR 记忆/音高调整/随机三路即兴，新和声替换最差。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    hmcr = 0.95\n    bw0 = 0.5 * (ctx.hi - ctx.lo)  # 带宽加大+逐代收缩（固定窄带宽 30 代出不了活）\n    best, bpos = min(zip(vals, pop))\n    for it in range(1, p[\"max_iter\"] + 1):\n        cand = []\n        for k in range(ctx.dim):\n            bw = bw0 * (1.0 - 0.8 * it / p[\"max_iter\"])  # 每维先算带宽（作用域修正）\n            if rng.random() < hmcr:\n                v = pop[rng.randrange(len(pop))][k]\n                if rng.random() < 0.3:\n                    v += rng.uniform(-bw, bw)\n            else:\n                v = rng.uniform(ctx.lo, ctx.hi)\n            cand.append(v)\n        cand = ctx.clamp(cand)\n        c = ctx.eval(cand)\n        wi = max(range(len(pop)), key=lambda i: vals[i])\n        if c < vals[wi]:\n            pop[wi], vals[wi] = cand, c\n        # 每代再即兴 4 次（单和声版本 200 代也慢——HS 文献常用多和声并行）\n        for _ in range(4):\n            cand = []\n            for k in range(ctx.dim):\n                if rng.random() < hmcr:\n                    v = pop[rng.randrange(len(pop))][k]\n                    if rng.random() < 0.3:\n                        bw = bw0 * (1.0 - 0.8 * it / p[\"max_iter\"])\n                        v += rng.uniform(-bw, bw)\n                else:\n                    v = rng.uniform(ctx.lo, ctx.hi)\n                cand.append(v)\n            cand = ctx.clamp(cand)\n            c2 = ctx.eval(cand)\n            wi2 = max(range(len(pop)), key=lambda i: vals[i])\n            if c2 < vals[wi2]:\n                pop[wi2], vals[wi2] = cand, c2\n        best, bpos = min(zip(vals, pop))\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_abc(ctx, p, rng):\n    \"\"\"人工蜂群 ABC（Karaboga 2005）连续经典：雇佣蜂邻域觅食、观察蜂轮盘跟随、侦察蜂弃巢重置。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    best, bpos = min(zip(vals, pop))\n    limit = 20\n    fail = [0] * len(pop)\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(len(pop)):  # 雇佣蜂\n            k = rng.randrange(len(pop))\n            while k == i:\n                k = rng.randrange(len(pop))\n            phi = rng.uniform(-1.0, 1.0)\n            cand = ctx.clamp([x + phi * (x - pop[k][j]) for j, (x, ) in enumerate([(v,) for v in pop[i]])])\n            c = ctx.eval(cand)\n            if c < vals[i]:\n                pop[i], vals[i] = cand, c\n                fail[i] = 0\n            else:\n                fail[i] += 1\n        # Karaboga 的标准适应度：f ≥ 0 时 1/(1+f)，f < 0 时 1+|f|（原先只写了前一半，目标值 ≤ −1 时权重为负，\n        # 轮盘直接抛 ValueError——自带问题 / 允许负目标的变体上 ABC 会崩）\n        fit = [1.0 / (1.0 + v) if v >= 0 else 1.0 + abs(v) for v in vals]\n        fs = sum(fit)\n        for _ in range(len(pop)):  # 观察蜂（轮盘）\n            i = rng.choices(range(len(pop)), weights=fit)[0]\n            k = rng.randrange(len(pop))\n            while k == i:\n                k = rng.randrange(len(pop))\n            phi = rng.uniform(-1.0, 1.0)\n            cand = ctx.clamp([x + phi * (x - pop[k][j]) for j, x in enumerate(pop[i])])\n            c = ctx.eval(cand)\n            if c < vals[i]:\n                pop[i], vals[i] = cand, c\n                fail[i] = 0\n            else:\n                fail[i] += 1\n        wi = max(range(len(pop)), key=lambda i: fail[i])  # 侦察蜂\n        if fail[wi] >= limit:\n            pop[wi] = ctx.random(rng)\n            vals[wi] = ctx.eval(pop[wi])\n            fail[wi] = 0\n        cb, cp = min(zip(vals, pop))\n        if cb < best:  # 历史最优单独记着：侦察蜂弃巢可能正好重置掉当前最好的那只（最久没改进的往往就是它），不能因此丢解\n            best, bpos = cb, list(cp)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_eo(ctx, p, rng):\n    \"\"\"均衡优化 EO（Faramarzi 2020）连续经典：均衡池 4 最优+1 平均，指数生成率 F 控制收束。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    a = 2.0\n    best, bpos = min(zip(vals, pop))\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: vals[i])\n        pool = [pop[i] for i in order[:4]]\n        avg = [sum(x[k] for x in pool) / 4 for k in range(ctx.dim)]\n        pool.append(avg)\n        lam = 2.0 * rng.uniform(0, 1)\n        F = max(0.0, min(1.0, math.exp(-a * it / p[\"max_iter\"])))  # 生成率∈[0,1]：>1 会把 (x−ceq) 外推爆炸\n        for i in range(len(pop)):\n            ceq = pool[rng.randrange(len(pool))]\n            G = [(rng.random() - 0.5) * 2.0 * (1.0 - 0.7 * it / p[\"max_iter\"])\n                 for _ in range(ctx.dim)]  # G 对称化+幅度随迭代衰减：对称但收束\n            pop[i] = ctx.clamp([\n                ceq[k] + (x - ceq[k]) * F + G[k] * (1 - F) for k, x in enumerate(pop[i])])\n            vals[i] = ctx.eval(pop[i])\n        cb, cp = min(zip(vals, pop))\n        if cb < best:  # 上报历史最优：只降不升（原先每代取当代种群的最优，会变差）\n            best, bpos = cb, list(cp)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_ao(ctx, p, rng):\n    \"\"\"天鹰 AO（Abualigah 2021）连续经典：四阶段按 t/T 三等分硬切换（广域/轮廓/定向/精修）。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    best, bpos = min(zip(vals, pop))\n    T = p[\"max_iter\"]\n    for it in range(1, T + 1):\n        stage = 0 if it / T < 1 / 3 else (1 if it / T < 2 / 3 else 2)\n        for i in range(len(pop)):\n            r1, r2 = rng.random(), rng.random()\n            if stage == 0:  # 广域勘探：围绕 best 展开采样\n                cand = ctx.clamp([b * (1 - r1) + x * r2 for x, b in zip(pop[i], bpos)])\n            elif stage == 1:  # 轮廓勘探：Levy 式跳跃\n                levy = math.exp(rng.uniform(-2, 2)) * math.cos(2 * math.pi * rng.random())\n                cand = ctx.clamp([x + levy * (b - x) * r1 for x, b in zip(pop[i], bpos)])\n            else:  # 定向开发+精修：向 best 收缩\n                cand = ctx.clamp([b * (1 - r1) + x * r1 * 0.5 + rng.gauss(0, 0.05)\n                                  for x, b in zip(pop[i], bpos)])\n            c = ctx.eval(cand)\n            if c < vals[i]:\n                pop[i], vals[i] = cand, c\n            if c < best:\n                best, bpos = c, list(cand)\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\ndef _cn_cem(ctx, p, rng):\n    \"\"\"交叉熵 CEM（Rubinstein 1997）连续经典：高斯分布采样→精英回写 mean/std。\n    修复（2026-09-27）：① best 跨代保持 ② mean 向 best-so-far 锚定防漂移\n    ③ 停滞重启（std 弹回 1/2 初始值）——多峰 rastrigin 的分布重启机制。\"\"\"\n    n_pop = p[\"n_pop\"]\n    warm = [ctx.random(rng) for _ in range(30)]\n    mean = list(min(warm, key=ctx.eval))\n    std0 = [(ctx.hi - ctx.lo) / 3] * ctx.dim\n    std = list(std0)\n    best, bpos = None, None\n    stall = 0\n    for it in range(1, p[\"max_iter\"] + 1):\n        pop = [ctx.clamp([rng.gauss(mean[k], max(std[k], 1e-6)) for k in range(ctx.dim)])\n               for _ in range(n_pop)]\n        vals = [ctx.eval(x) for x in pop]\n        # best 跨代保持\n        gen_best, gen_bp = min(zip(vals, pop))\n        if best is None or gen_best < best:\n            best, bpos = gen_best, list(gen_bp)\n            stall = 0\n        else:\n            stall += 1\n        order = sorted(range(n_pop), key=lambda i: vals[i])[:max(2, n_pop // 2)]\n        elite = [pop[i] for i in order]\n        new_mean = [sum(x[k] for x in elite) / len(elite) for k in range(ctx.dim)]\n        # mean 向 best-so-far 锚定 20%（防精英均值漂移）\n        mean = [0.8 * nm + 0.2 * bp for nm, bp in zip(new_mean, bpos)]\n        std = [max((max(x[k] for x in elite) - min(x[k] for x in elite)) / 2,\n                   0.01 * (ctx.hi - ctx.lo)) for k in range(ctx.dim)]\n        # 停滞重启：连续 30 代无改进 → std 弹回 1/2 初始（分布重启）\n        if stall >= 30:\n            std = [s0 / 2 for s0 in std0]\n            stall = 0\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\n\ndef _cn_sma(ctx, p, rng):\n    \"\"\"黏菌 SMA（Li 2020）连续经典：权重 W 按适应度排序对数化，vb/vc 双系数调度探索-开发。\"\"\"\n    pop, vals = ctx.init_pop(p, rng)\n    best, bpos = min(zip(vals, pop))\n    vb, vc = 1.0, 1.0\n    z = 0.05\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: vals[i])\n        worst, bestv = vals[order[-1]], vals[order[0]]\n        span = max(1e-12, worst - bestv)\n        W = []\n        for rank, idx in enumerate(order):\n            ratio = (worst - vals[idx]) / span\n            W.append(1.0 + rng.random() * math.log(ratio + 1.0) if rank < len(order) // 2\n                     else 1.0 - rng.random() * math.log(ratio + 1.0))\n        for i in range(len(pop)):\n            r = rng.random()\n            if r < z:\n                pop[i] = ctx.random(rng)\n            elif r < 0.5 + z / 2:\n                j = order[rng.randrange(max(1, len(order) // 2))]\n                pop[i] = ctx.clamp([x + vb * rng.random() * (W[j] * a - b)\n                                    for x, a, b in zip(pop[i], pop[j], pop[order[-1]])])\n            else:\n                pop[i] = ctx.clamp([vc * x for x in pop[i]])\n            vals[i] = ctx.eval(pop[i])\n        cb, cp = min(zip(vals, pop))\n        if cb < best:  # 上报历史最优：只降不升（原先每代取当代种群的最优，会变差）\n            best, bpos = cb, list(cp)\n        vb *= math.exp(-2 * it / p[\"max_iter\"])\n        vc = 1 - it / p[\"max_iter\"]\n        yield _cn_state(ctx, it, best, bpos, pop, vals)\n\n\n_CN_ALGOS = {\n    \"random\": {\"fn\": _cn_random, \"name\": \"随机搜索\", \"category\": \"基线\", \"desc\": \"盲采样基线\", \"tune\": []},\n    \"hc\": {\"fn\": _cn_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\", \"desc\": \"高斯步长贪心 + 多起点重启\", \"tune\": [\"sigma\", \"restart_at\"]},\n    \"sa\": {\"fn\": _cn_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\", \"desc\": \"连续域 Metropolis + 卡死重启\", \"tune\": [\"t0\", \"decay\", \"restart_at\"]},\n    \"pso\": {\"fn\": _cn_pso, \"name\": \"粒子群 PSO\", \"category\": \"群体智能\", \"desc\": \"原生域！速度-位置公式原样\", \"tune\": [\"w_max\", \"w_min\", \"c1\", \"c2\"]},\n    \"de\": {\"fn\": _cn_de, \"name\": \"差分进化 DE\", \"category\": \"进化计算\", \"desc\": \"原生域！差向量实数运算\", \"tune\": [\"F\", \"CR\"]},\n    \"gwo\": {\"fn\": _cn_gwo, \"name\": \"灰狼 GWO\", \"category\": \"群体智能\", \"desc\": \"原生域！三狼包围\", \"tune\": []},\n    \"woa\": {\"fn\": _cn_woa, \"name\": \"鲸鱼 WOA\", \"category\": \"群体智能\", \"desc\": \"原生域！包围/螺旋\", \"tune\": []},\n    \"sca\": {\"fn\": _cn_sca, \"name\": \"正弦余弦 SCA\", \"category\": \"数学启发\", \"desc\": \"原生域！三角振荡包围\", \"tune\": [\"a_max\"]},\n    \"cmaes\": {\"fn\": _cn_cmaes, \"name\": \"协方差自适应 CMA-ES\", \"category\": \"进化计算\", \"desc\": \"原生域！全协方差自适应 + σ/进化路径（连续域 SOTA）\", \"tune\": []},\n    # ---- 连续域扩容（2026-09-27 ROADMAP 批 1：12 个正典连续公式）----\n    \"fa\": {\"fn\": _cn_fa, \"name\": \"萤火虫 FA\", \"category\": \"群体智能\", \"desc\": \"原生域！亮度吸引 + 距离衰减 + α 扰动衰减\", \"tune\": []},\n    \"ba\": {\"fn\": _cn_ba, \"name\": \"蝙蝠 BA\", \"category\": \"群体智能\", \"desc\": \"原生域！频率调谐 + 响度/脉冲率自适应\", \"tune\": []},\n    \"jaya\": {\"fn\": _cn_jaya, \"name\": \"Jaya 算法 JAYA\", \"category\": \"群体智能\", \"desc\": \"原生域！向最优+远离最劣，零专属参数\", \"tune\": []},\n    \"gsa\": {\"fn\": _cn_gsa, \"name\": \"引力搜索 GSA\", \"category\": \"物理启发\", \"desc\": \"原生域！质量=归一化适应度，引力驱动（速度阻尼版）\", \"tune\": []},\n    \"mfo\": {\"fn\": _cn_mfo, \"name\": \"蛾焰 MFO\", \"category\": \"群体智能\", \"desc\": \"原生域！螺旋飞行绕火焰，焰数递减\", \"tune\": []},\n    \"tlbo\": {\"fn\": _cn_tlbo, \"name\": \"教与学 TLBO\", \"category\": \"人类与社会启发\", \"desc\": \"原生域！教师/学习两阶段，零专属参数\", \"tune\": []},\n    \"hs\": {\"fn\": _cn_hs, \"name\": \"和声搜索 HS\", \"category\": \"音乐启发\", \"desc\": \"原生域！HMCR 三路即兴，多和声并行\", \"tune\": []},\n    \"abc\": {\"fn\": _cn_abc, \"name\": \"人工蜂群 ABC\", \"category\": \"群体智能\", \"desc\": \"原生域！雇佣/观察/侦察三蜂协作\", \"tune\": []},\n    \"eo\": {\"fn\": _cn_eo, \"name\": \"均衡优化 EO\", \"category\": \"物理启发\", \"desc\": \"原生域！均衡池 4+1 + 生成率 clamp[0,1]\", \"tune\": []},\n    \"ao\": {\"fn\": _cn_ao, \"name\": \"天鹰 AO\", \"category\": \"群体智能\", \"desc\": \"原生域！四阶段三等分硬切换调度\", \"tune\": []},\n    \"cem\": {\"fn\": _cn_cem, \"name\": \"交叉熵 CEM\", \"category\": \"进化计算\", \"desc\": \"原生域！EDA 源头：热启动+分布收缩采样→精英回写\", \"tune\": []},\n    \"sma\": {\"fn\": _cn_sma, \"name\": \"黏菌 SMA\", \"category\": \"物理启发\", \"desc\": \"原生域！权重对数化 + vb/vc 调度\", \"tune\": []},\n}\n_MO_ALGOS = {\n    \"random\": {\"fn\": _mo_random, \"name\": \"随机搜索\", \"category\": \"基线\", \"desc\": \"非支配档案累积基线\", \"tune\": []},\n    \"wsga\": {\"fn\": _mo_wsga, \"name\": \"加权 GA\", \"category\": \"进化计算\", \"desc\": \"每代随机权重合成单目标（会漏非凸段）\", \"tune\": [\"pm\"]},\n    \"nsga2\": {\"fn\": _mo_nsga2, \"name\": \"NSGA-II\", \"category\": \"进化计算\", \"desc\": \"非支配排序 + 拥挤度（Deb 2002，引用数万）\", \"tune\": [\"pc\"]},\n    \"moead\": {\"fn\": _mo_moead, \"name\": \"MOEA-D（分解）\", \"category\": \"进化计算\",\n              \"desc\": \"Tchebycheff 分解+权重邻域+理想点追踪（Zhang & Li 2007，经典）\", \"tune\": []},\n    \"spea2\": {\"fn\": _mo_spea2, \"name\": \"SPEA2（强度Pareto）\", \"category\": \"进化计算\",\n              \"desc\": \"强度Pareto 适应度+密度截断 archive（Zitzler 2001，经典）\", \"tune\": []},\n}\n\n_GC_ALGOS = _pm_registry(\"gc\")\n_BP_ALGOS = _pm_registry(\"bp\")\n_SC_ALGOS = dict(_SW_ALGOS, **{\n    \"greedy\": {\"fn\": _sc_greedy, \"name\": \"贪心 ln n\", \"category\": \"构造启发\",\n               \"desc\": \"Chvátal 1979：每次选 新覆盖/成本 比最高集合（近似保证 ln n）\", \"tune\": []},\n})\n\n# ---- H 期 kpvar（背包家族 10 变体）注册表：位编码变体复用 _KS 全套内核\n# （max-sense 包装器），mkpm 复用 _GAP 指派内核；ssp/cmp 各挂专属精确 DP 锚点。 ----\n_KS_FNS = frozenset(a[\"fn\"] for a in _KS_ALGOS.values())\n_KPV_ALGOS = dict(_KS_ALGOS, **{\n    \"greedy\": {\"fn\": _kpv_greedy, \"name\": \"密度贪心\", \"category\": \"构造启发\",\n               \"desc\": \"按价值/重量比降序装入（确定性对照）\", \"tune\": []},\n})\n_SSP_ALGOS = dict(_KS_ALGOS, **{\n    \"ssp_dp\": {\"fn\": _kpv_ssp_dp, \"name\": \"精确 DP\", \"category\": \"构造启发\",\n               \"desc\": \"子集和伪多项式精确算法：reach 集合 DP + 回溯（SSP 专属锚点）\",\n               \"tune\": []},\n})\n_CMP_ALGOS = dict(_KS_ALGOS, **{\n    \"cmp_dp\": {\"fn\": _kpv_cmp_dp, \"name\": \"精确 DP\", \"category\": \"构造启发\",\n               \"desc\": \"找零伪多项式精确算法：min-coin DP + 回溯（Change-Making 专属锚点）\",\n               \"tune\": []},\n})\n_MKPM_ALGOS = dict(_GAP_ALGOS, **{\n    \"greedy\": {\"fn\": _kpv_greedy, \"name\": \"密度贪心\", \"category\": \"构造启发\",\n               \"desc\": \"全局密度降序，能放则放（确定性对照）\", \"tune\": []},\n})\n_MCKP_ALGOS = dict(_KS_ALGOS, **{\n    \"greedy\": {\"fn\": _kpv_greedy, \"name\": \"密度贪心\", \"category\": \"构造启发\",\n               \"desc\": \"每类选密度最高件，全局降序装入（确定性对照）\", \"tune\": []},\n})\n# kpvar 全算法并集（_DOMAINS 注册用；实际可用集按变体在 domain_list/domain_start 分派）\n_KPVAR_ALGOS = dict(_KS_ALGOS, **_GAP_ALGOS,\n                    greedy=_KPV_ALGOS[\"greedy\"],\n                    ssp_dp=_SSP_ALGOS[\"ssp_dp\"], cmp_dp=_CMP_ALGOS[\"cmp_dp\"])\n\n_KS_DEF = {\"n_pop\": 30, \"pm\": 0.04, \"F\": 0.7, \"CR\": 0.6, \"t0\": 8.0, \"decay\": 0.985,\n           \"tries\": 20, \"tenure\": 8, \"limit\": 12, \"pa\": 0.25, \"max_iter\": 200, \"seed\": 7}\n_CN_DEF = {\"n_pop\": 30, \"sigma\": 0.6, \"t0\": 10.0, \"decay\": 0.98, \"w_max\": 0.9, \"w_min\": 0.4,\n           \"c1\": 1.5, \"c2\": 1.5, \"F\": 0.7, \"CR\": 0.9, \"a_max\": 2.0, \"restart_at\": 25,\n           \"max_iter\": 200, \"seed\": 7}\n_MO_DEF = {\"n_pop\": 40, \"pc\": 0.9, \"pm\": 0.04, \"max_iter\": 150, \"seed\": 7}\n_GC_DEF = {\"n_pop\": 30, \"pm\": 0.3, \"t0\": 800.0, \"decay\": 0.985, \"tries\": 40, \"tenure\": 10,\n           \"ts_sample\": 120, \"limit\": 14, \"pa\": 0.25, \"polish\": 8, \"restart_at\": 25,\n           \"max_iter\": 200, \"seed\": 7}\n# gcvar 复用图着色内核，但 edgecolor/totalcolor 经线图/全图变换后 N 暴涨到 ~400，\n# ts_sample=120 会让 TS 在 O(N²) 解码下卡死浏览器/测试；gcvar 单独降到 36（与 N 解耦）。\n_GCVAR_DEF = dict(_GC_DEF, ts_sample=36)\n_BP_DEF = dict(_GC_DEF, t0=4000.0, decay=0.99, restart_at=12, polish=40)\n# 注：温度/重启节奏/下探预算按「参数种子=实例种子」（页面真实语义）标定：\n# 随机基线 = best-of-200 偶有运气样本，SA 单链必须靠高频重启+强下探追平（5/5 胜随机）\n\n_BIN_DEF = {\"n_pop\": 30, \"pm\": 0.04, \"t0\": 30.0, \"decay\": 0.98, \"tries\": 20,\n            \"tenure\": 8, \"ts_sample\": 40, \"restart_at\": 25, \"max_iter\": 200, \"seed\": 7,\n            \"walk_p\": 0.45}\n_SC_DEF = dict(_BIN_DEF)\n_SAT_DEF = dict(_BIN_DEF, t0=3.0)\n_QB_DEF = dict(_BIN_DEF, t0=120.0)\n_GAP_DEF = dict(_BIN_DEF, t0=25.0, decay=0.97)  # 标定：t0=60 冷得太慢，100 代内摸不到低温区\n_UF_DEF = dict(_BIN_DEF, t0=400.0)\n\n# ---- H2 期 gcvar（着色家族 5 变体）注册表：4 个排列变体复用 _pm_* 内核 + 度序贪心锚点；\n# mis 复用 _bin_* 位串内核 + 度升序贪心锚点。 ----\n_GCV_ALGOS = dict(_pm_registry(\"gc\"), **{\n    \"greedy\": {\"fn\": _gcv_greedy, \"name\": \"度序贪心\", \"category\": \"构造启发\",\n               \"desc\": \"顶点按度数降序 First-Fit 着色（确定性对照）\", \"tune\": []},\n})\n_MIS_ALGOS = dict(_BIN_ALGOS, **{\n    \"greedy\": {\"fn\": _mis_greedy, \"name\": \"度升序贪心（MIS）\", \"category\": \"构造启发\",\n               \"desc\": \"度小者优先入集，冲突即跳过（确定性对照）\", \"tune\": []},\n})\n_GCVAR_ALGOS = dict(_GCV_ALGOS, **{k: v for k, v in _MIS_ALGOS.items() if k not in _GCV_ALGOS})\n\n# ---- H3 期 bpvar（装箱变体家族 3 变体）注册表：复用 _pm_* 排列内核 + 构造贪心锚点。 ----\n_BPVAR_ALGOS = dict(_pm_registry(\"bp\"), **{\n    \"greedy\": {\"fn\": _bpv_greedy, \"name\": \"构造贪心\", \"category\": \"构造启发\",\n               \"desc\": \"定向序 First-Fit（VSBPP 最差适应；2D/条带面积降序 shelf）确定性对照\", \"tune\": []},\n})\n# 装箱 FF 解码器 plateau 巨大，沿用 binpack 标定（t0=4000/decay=0.99/高频重启）；\n# ts_sample 降到 60（2D 解码比 1D 贵，n=40 仍远快于 gcvar 的 N~400 变换）\n_BPVAR_DEF = dict(_BP_DEF, ts_sample=60)\n\n\n\n# ============================================================\n# 域十二：原子词条实例域 entryseq（2026-09-27 解冻令首批——用户令「词条都要有实例」）\n# 原子架构：零新内核——直接复用 _SW 共享内核（random/hc/sa/ts/ga），\n# 本域只提供「问题原子」：es_make 实例 + _ES 上下文（obj/swap/random）。\n# 9 变体=旅行商下拉的 9 个词条（VRP/HC/LP/LOP/SMS/FSS/JSS/OSS/RCPSP），\n# 统一排列编码，变体专属 cost 解码；调度类解码为教学级简化（页面已注明）。\n# ============================================================\n\n_ES_DEF = {\"max_iter\": 200, \"tries\": 48, \"t0\": 4000.0, \"decay\": 0.90,\n           \"tenure\": 10, \"restart_at\": 30, \"pm\": 0.06, \"seed\": 7}  # t0 与 BIG 罚同量级：罚悬崖上低温 SA 会卡局部\n\n\n\n\n\n\n_ES_ALGOS = dict(_SW_ALGOS, **{\n    \"greedy\": {\"fn\": _sw_random, \"name\": \"随机基线\", \"category\": \"基线\",\n               \"desc\": \"盲采样对照——各算法必须显著优于它（「真优化」校验锚点）\", \"tune\": []},\n})\n\n\n# ---- 位编码族原子复用（2026-09-27 ROADMAP 批 7）：de/abc/woa/gwo/cs 内核零适配直拉 ----\nclass _ValueView:\n    \"\"\"把 min 域上下文（init_pop 给 obj）转成 _KS 内核期望的 max-value 视图：init_pop 给 value = -obj。\n    其余属性原样转发。没有这一层时，初始种群的值是 obj、之后每次评价的值是 -obj，两者混着比较——\n    内核实际在最大化代价，却把 -代价 当作「更好」上报（集合覆盖里出现负成本）。\"\"\"\n\n    def __init__(self, ctx):\n        self._c = ctx\n\n    def __getattr__(self, name):\n        return getattr(self._c, name)\n\n    def init_pop(self, p, rng):\n        pop = [self._c.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self._c.value(s) for s in pop]\n\n\ndef _minify(ks_fn):\n    \"\"\"_KS max 内核 → min 域包装：yield 时 best/cur 取负，统一 min 协议。\"\"\"\n    def wrapped(ctx, p, rng):\n        for st in ks_fn(_ValueView(ctx), p, rng):\n            st[\"best\"] = -st[\"best\"]\n            st[\"cur\"] = -st[\"cur\"]\n            yield st\n    wrapped.__name__ = ks_fn.__name__ + \"_min\"\n    return wrapped\n\n# def 合并：三域 def 缺 _KS 系键（F/CR/limit/pa/tenure 等）——补齐防 KeyError\nfor _def in (_SC_DEF, _SAT_DEF, _QB_DEF):\n    _def.update({k: v for k, v in _KS_DEF.items() if k not in _def})\n# 这 5 个内核全部 ctx 协议形式（_ks_* 系），_SC/_SAT/_QB 上下文天然兼容（_SW 同协议已在跑）\n_SC_ALGOS.update({\n        k: {\"fn\": _minify(_KS_ALGOS[k][\"fn\"]), \"name\": _KS_ALGOS[k][\"name\"],\n            \"category\": _KS_ALGOS[k][\"category\"], \"desc\": _KS_ALGOS[k][\"desc\"],\n            \"tune\": _KS_ALGOS[k][\"tune\"]}\n        for k in (\"de\", \"abc\", \"woa\", \"gwo\", \"cs\")})\n_SAT_ALGOS.update({\n        k: {\"fn\": _minify(_KS_ALGOS[k][\"fn\"]), \"name\": _KS_ALGOS[k][\"name\"],\n            \"category\": _KS_ALGOS[k][\"category\"], \"desc\": _KS_ALGOS[k][\"desc\"],\n            \"tune\": _KS_ALGOS[k][\"tune\"]}\n        for k in (\"de\", \"abc\", \"woa\", \"gwo\", \"cs\")})\n_BIN_ALGOS.update({\n        k: {\"fn\": _minify(_KS_ALGOS[k][\"fn\"]), \"name\": _KS_ALGOS[k][\"name\"],\n            \"category\": _KS_ALGOS[k][\"category\"], \"desc\": _KS_ALGOS[k][\"desc\"],\n            \"tune\": _KS_ALGOS[k][\"tune\"]}\n        for k in (\"de\", \"abc\", \"woa\", \"gwo\", \"cs\")})  # qubo 域直接引用 _BIN_ALGOS\n\n# ---- M1 位向量 bv 内核全位域挂载（2026-09-27 全矩阵计划）----\n# bv_fa/bv_ba/bv_jaya/bv_tlbo（sigmoid 二值化，min 协议）挂 sat/qubo；setcover 经 dict(_SW_ALGOS) 自动获得\ndef _bv_reg():\n    return {k: {\"fn\": getattr(__import__(__name__), f\"_bv_{sfx}\"),\n                \"name\": nm, \"category\": \"群体智能\" if sfx in (\"fa\", \"ba\") else (\"群体智能\" if sfx == \"jaya\" else \"人类与社会启发\"),\n                \"desc\": ds, \"tune\": []}\n            for k, sfx, nm, ds in (\n                (\"bv_fa\", \"fa\", \"萤火虫 FA（位）\", \"sigmoid 映射二值化（Kennedy & Eberhart 1997 模式）\"),\n                (\"bv_ba\", \"ba\", \"蝙蝠 BA（位）\", \"频率调谐+sigmoid 映射二值化\"),\n                (\"bv_jaya\", \"jaya\", \"Jaya（位）\", \"向 best 靠拢+远离 worst（sigmoid）\"),\n                (\"bv_tlbo\", \"tlbo\", \"TLBO（位）\", \"教师/学习 sigmoid 映射（零专属参数）\"),\n                (\"bv_pso\", \"pso\", \"粒子群 PSO（位）\", \"速度-位置+sigmoid（Kennedy & Eberhart 1997 原型）\"),\n                (\"bv_sca\", \"sca\", \"正弦余弦 SCA（位）\", \"经典 sin/cos 更新（r4 切换，Mirjalili 2016，文献核对修正）\"),\n                (\"bv_mfo\", \"mfo\", \"蛾焰 MFO（位）\", \"经典多焰递减螺旋+sigmoid（Mirjalili 2015，flame 数 n_pop→1）\"),\n                # bv_gsa/bv_hs 撤下（2026-09-28 门裁定）：GSA 引力项在离散翻转语境退化、\n                # HS 记忆考量 50 代收敛不足——各 3-4 域连随机最优都未赢，系统性失效\n\n                (\"bv_eo\", \"eo\", \"均衡 EO（位）\", \"经典平衡池 5 候选等概率选一+F 项+GCP 开关（Faramarzi 2020，文献核对修正）\"),\n                (\"bv_ao\", \"ao\", \"天鹰 AO（位）\", \"经典四阶段：X1 均值扩张/X2 Levy 收缩探索/X3 α-δ 开发/X4 QF 收缩（Abualigah 2021，文献核对修正）\"),\n                (\"bv_sma\", \"sma\", \"黏菌 SMA（位）\", \"经典位移式 Xb+vb(W·XA−XB)+log 权重+p=tanh 阈值（Li 2020，文献核对修正）\"),\n                (\"bv_cem\", \"cem\", \"交叉熵 CEM（位）\", \"伯努利 CEM 精英频率回写（Rubinstein 1997）\"),\n                (\"bv_cmaes\", \"cmaes\", \"CMA-ES（位·对角近似）\", \"对角协方差伯努利近似（诚实简化）\"))}\n# ---- M1 max 域包装：bv min 内核 → knapsack/kpvar（max 协议）----\n# ctx.obj 代理取负（内核内部 min 比较对齐），yield 时 best/cur 还原正号\ndef _maximize(bv_fn):\n    def wrapped(ctx, p, rng):\n        raw_eval = ctx.obj if hasattr(ctx, \"obj\") else ctx.value  # _KS 系接口名=value\n        class _MaxView:\n            def __init__(self, c, ev):\n                self._c = c\n                self._ev = ev\n                self.n = c.n\n            def obj(self, s):\n                return -self._ev(s)\n            def __getattr__(self, name):\n                return getattr(self._c, name)\n        for st in bv_fn(_MaxView(ctx, raw_eval), p, rng):\n            st[\"best\"] = -st[\"best\"]\n            st[\"cur\"] = -st[\"cur\"]\n            yield st\n    wrapped.__name__ = bv_fn.__name__ + \"_max\"\n    return wrapped\n\n_bv_full = _bv_reg()\nfor _bk, _bv_entry in _bv_full.items():\n    _KS_ALGOS[_bk] = {\"fn\": _maximize(_bv_entry[\"fn\"]), \"name\": _bv_entry[\"name\"] + \"（max）\",\n                      \"category\": _bv_entry[\"category\"], \"desc\": _bv_entry[\"desc\"] + \"；max 域经 obj 取负代理适配\",\n                      \"tune\": []}\n# kpvar 变体：_KPV ctx 是 min 语义（obj=-value+罚）——挂原生 min bv（非 max 包装）；\n# mckp(one-hot 无 repair)/mkpm(0..m 指派非二值) 编码不适配位向量 sigmoid——不挂（诚实）\n_KPV_ALGOS.update(_bv_reg())\n_KPV_ALGOS.pop(\"bv_sma\")  # qkp 变体撤下 bv_sma（2026-09-28 严口径门）：-2026 vs 随机最优 -2058，其他位域均过门\n_SSP_ALGOS.update(_bv_reg())\n_CMP_ALGOS.update(_bv_reg())\n_CMP_ALGOS.pop(\"bv_tlbo\")  # cmp 撤下 bv_tlbo：教师阶段推力致解码越界（BIG 罚主导=不可行解），其余变体均过门\n_CMP_ALGOS.pop(\"bv_mfo\")  # cmp 撤下 bv_mfo：蛾焰螺旋致超载（20016 vs 随机最优 20，BIG 罚主导）\n_KPVAR_ALGOS.update(_bv_reg())  # 并集清单（实际分派按 _kpvar_reg）\n\n_SAT_ALGOS.update(_bv_reg())\n_BIN_ALGOS.update(_bv_reg())\n_BIN_ALGOS.pop(\"bv_ba\")  # qubo 撤下 bv_ba：BA 響度接受准则在 qubo 大范围负目标上 50 代探索不足（-263 vs 基线 -280），setcover/uflp/sat 均强\n_BIN_ALGOS.pop(\"bv_fa\")  # qubo 撤下 bv_fa（监督复核 2026-09-27）：同族 seed 口径下 -295 vs 随机最优 -404（连最差 -348 未赢），与 bv_ba 同源探索不足；多 seed [-295,-567,-663] 仅 1/3 稳赢，seed 高度敏感\n# qubo 单域撤下（2026-09-28 严口径门）：sca -386 vs 随机最优 -404 探索不足 -> 用 _qb_sca 温度适配层替之；\n# mfo/eo 经 M4 文献核对修正后已过门（mfo -555/eo -564 vs -404）-> 下方逐域回挂块重新接入\n_BIN_ALGOS.pop(\"bv_sca\")\n# 弱内核诚实标注（监督复核 WEAK 项：非假跑、边际通过——页面 desc 可见）\n_UF_ALGOS.update(_bv_reg())  # uflp min 域（_SW 协议路线已通，bv 同理）\n_SC_ALGOS[\"bv_tlbo\"][\"desc\"] += \"；弱内核（本域仅边际优于随机）\"\n_SAT_ALGOS[\"bv_ba\"][\"desc\"] += \"；弱内核（本域仅边际优于随机）\"\n_SAT_ALGOS.pop(\"bv_mfo\")  # sat 撤下 bv_mfo（2026-09-28 终门）：8 vs 随机最优 7 严口径未赢——统一标准不保留严口径负格\n\n# ---- complete-a-kernels 2026-09-29：严口径门回挂（逐域，不过门不挂） ----\n# 实测（同族 3-seed 随机基线取最优，200 代）：\n#   bv_gsa PASS: qubo(-549) sat(6) uflp(1147) knapsack(1604,max) kpvar(ssp/fractional/ukp/bkp/qkp/mdkp/dkp)\n#   bv_gsa FAIL: setcover(159 vs 115)→不挂；cmp(19 vs 16)→不挂；mckp 走独立 _MCKP_ALGOS→安全\n#   bv_hs  PASS: sat(6) knapsack(1501,max) kpvar(ssp/fractional/ukp/bkp/qkp/mdkp/dkp)\n#   bv_hs  FAIL: qubo(-338) uflp(1314) cmp(19 vs 16)→不挂\n#   bv_mfo PASS: qubo(-555) cmp(12 vs 16, 3-seed min 严口径边际)→回挂；sat 用 _sat_mfo 适配层替原 _bv_mfo\n#   bv_eo  PASS: qubo(-564)→回挂\n#   _qb_sca(温度适配) PASS: qubo(-788)→回挂；_sat_mfo(温度适配) PASS: sat(5)→回挂\n#   _uf_local(UFLP 专属) PASS: uflp(1166 vs 1249)→回挂\n#   _mo_nsga3 PASS: moco 前沿真·非支配(nd=40)+覆盖 8≥nsga2 7；maop 三目标非支配(nd=40)\n# 原撤下原因（GSA 引力退化/HS 收敛不足）经 M4 文献核对 + 实测已不成立：现有 _bv_gsa(正典 Rashedi 2009 GSA)/\n#   _bv_hs(正典 Geem 2001 HS) 在目标域过严口径门，故按域逐挂（不绕 _bv_reg 全局以防污染失败域）。\n_bv_gsa_e = {\"fn\": _bv_gsa, \"name\": \"引力 GSA（位）\", \"category\": \"群体智能\",\n            \"desc\": \"经典引力搜索：质量加权吸引+sigmoid 映射（Rashedi 2009，文献核对修正）\", \"tune\": []}\n_bv_hs_e = {\"fn\": _bv_hs, \"name\": \"和声 HS（位）\", \"category\": \"群体智能\",\n           \"desc\": \"经典和声搜索：HMCR 记忆考量+PAR 音高调整（Geem 2001，文献核对修正）\", \"tune\": []}\n# 位编码 min 域：原生 min 内核直挂（kpvar 价值变体 ctx 为 min 语义）\nfor _reg in (_KPV_ALGOS, _SSP_ALGOS, _KPVAR_ALGOS):\n    _reg[\"bv_gsa\"] = dict(_bv_gsa_e)\n    _reg[\"bv_hs\"] = dict(_bv_hs_e)\n_SAT_ALGOS[\"bv_gsa\"] = dict(_bv_gsa_e)\n_SAT_ALGOS[\"bv_hs\"] = dict(_bv_hs_e)\n_UF_ALGOS[\"bv_gsa\"] = dict(_bv_gsa_e)            # uflp min；bv_hs 在 uflp FAIL 不挂\n_UF_ALGOS[\"uf_local\"] = {\"fn\": _uf_local, \"name\": \"UFLP 局部搜索\", \"category\": \"局部搜索\",\n                         \"desc\": \"单设施随机一阶改进+关一开一交换(0.6)+停滞重启：修复 UFLP 复合目标卡坏局部最优\", \"tune\": []}\n# knapsack 是 max 域：经 obj 取负代理适配（_maximize）\n_KS_ALGOS[\"bv_gsa\"] = {\"fn\": _maximize(_bv_gsa), \"name\": \"引力 GSA（位·max）\", \"category\": \"群体智能\",\n                      \"desc\": \"经典 GSA（Rashedi 2009），max 域经 obj 取负代理适配\", \"tune\": []}\n_KS_ALGOS[\"bv_hs\"] = {\"fn\": _maximize(_bv_hs), \"name\": \"和声 HS（位·max）\", \"category\": \"群体智能\",\n                     \"desc\": \"经典 HS（Geem 2001），max 域经 obj 取负代理适配\", \"tune\": []}\n# qubo 大范围负目标：bv_mfo/bv_eo 经 M4 修正已过门（下方 _BIN_ALGOS 已保留）；bv_gsa 原生过门；_qb_sca 温度适配层补 sca 缺口\n_BIN_ALGOS[\"bv_mfo\"] = _bv_reg()[\"bv_mfo\"]\n_BIN_ALGOS[\"bv_eo\"] = _bv_reg()[\"bv_eo\"]\n_BIN_ALGOS[\"bv_gsa\"] = dict(_bv_gsa_e)\n_BIN_ALGOS[\"qb_sca\"] = {\"fn\": _qb_sca, \"name\": \"SCA（位·温度适配）\", \"category\": \"群体智能\",\n                        \"desc\": \"软阈值 sigmoid 解码(T=1.6)+gbest 位翻抛光，针对 QUBO 大范围负目标（Mirjalili 2016 适配）\", \"tune\": []}\n# sat：原 _bv_mfo 严口径负（8 vs 7），用 _sat_mfo 温度适配层替之\n_SAT_ALGOS[\"sat_mfo\"] = {\"fn\": _sat_mfo, \"name\": \"MFO（位·温度适配）\", \"category\": \"群体智能\",\n                         \"desc\": \"软阈值 sigmoid 解码(T=1.5)+gbest 位翻抛光，SAT 专属适配（Mirjalili 2015 适配）\", \"tune\": []}\n# cmp：bv_mfo 经 M4 修正 3-seed 严口径过门（12 vs 16，边际→弱内核标注）；bv_gsa/bv_hs 在 cmp FAIL 不挂\n_CMP_ALGOS[\"bv_mfo\"] = _bv_reg()[\"bv_mfo\"]\n_CMP_ALGOS[\"bv_mfo\"][\"desc\"] += \"；弱内核（cmp 变体仅边际优于随机，3-seed 严口径过门）\"\n# 多目标：NSGA-III 参考点小生境（Deb 2014 正典）\n_MO_ALGOS[\"nsga3\"] = {\"fn\": _mo_nsga3, \"name\": \"NSGA-III\", \"category\": \"进化计算\",\n                      \"desc\": \"Das-Dennis 参考点+垂直距离关联+小生境计数选择（Deb & Jain 2014 经典）\", \"tune\": [\"pc\"]}\n\n\n# ---- uflp 位编码接入（批 7 续）：_KS 内核直拉（同位编码族模式，_UF 已有 value/polish 桥） ----\n# TODO 批 3 修：uflp 的 _KS 内核贪心卡坏局部最优（3616 vs random 1338）——\n# _UF.value=−obj 桥方向正确但 KS 贪心在 uflp 的「设施+服务」复合目标上失效，\n# 需要 uflp 专属内核或换 HC/SA 路线。桥代码保留（_UF.value/polish 已在）。\n# gap 域接入（批 7 续）：_GAP 有 obj/repair/swap ✓，de/gwo 向量分支需整数 clamp ✓\n_GAP_ALGOS.update({\n    k: {\"fn\": fn, \"name\": nm, \"category\": cat, \"desc\": ds, \"tune\": tn}\n    for k, (fn, nm, cat, ds, tn) in {\n        \"gwo\": (_sw_gwo, \"灰狼 GWO\", \"群体智能\", \"三狼指派投票（排列自适应）\", []),\n        \"cs\": (_sw_cs, \"布谷鸟 CS\", \"群体智能\", \"莱维 swap 串+弃巢（域无关）\", [\"pa\"]),\n    }.items()})  # de 的向量差分对整数指派产生 float——跳过（需 round 适配，批 3+）\n_UF_DEF.update({k: v for k, v in _KS_DEF.items() if k not in _UF_DEF})  # 补 F/CR/limit/pa 等键\n\n# ---- 批 7 续（2026-09-27）：entryseq/gap 域接 de/gwo/cs（_ES 协议 min 直配 ✓） ----\n_ES_ALGOS.update({k: {\"fn\": getattr(__import__(__name__), f\"_sw_{k}\"),\n                      \"name\": nm, \"category\": cat, \"desc\": ds, \"tune\": tn}\n                  for k, nm, cat, ds, tn in (\n    (\"de\", \"差分 DE\", \"进化计算\", \"自适应双模式差分（排列=swap 组合/向量=标准差分）\", [\"F\"]),\n    (\"gwo\", \"灰狼 GWO\", \"群体智能\", \"三狼投票自适应（排列/向量双模）\", []),\n    (\"cs\", \"布谷鸟 CS\", \"群体智能\", \"莱维 swap 串+弃巢（域无关）\", [\"pa\"]))})\n_GAP_ALGOS.update({k: {\"fn\": getattr(__import__(__name__), f\"_sw_{k}\"),\n                       \"name\": nm, \"category\": cat, \"desc\": ds, \"tune\": tn}\n                   for k, nm, cat, ds, tn in (\n    (\"gwo\", \"灰狼 GWO\", \"群体智能\", \"三狼指派投票（整数自适应）\", []),\n    (\"cs\", \"布谷鸟 CS\", \"群体智能\", \"莱维 swap 串+弃巢（域无关）\", [\"pa\"]))})\n\n\n# ---- M2 排列域挂载（2026-09-28）：随机键桥接的连续系内核，一次挂载全域共享 ----\n_PK_ALGOS = {k: {\"fn\": getattr(__import__(__name__), \"_\" + k), \"name\": nm, \"category\": cat, \"desc\": ds, \"tune\": []}\n             for k, nm, cat, ds in (\n    (\"pk_pso\", \"粒子群 PSO（排列）\", \"群体智能\", \"随机键+速度位置（Bean 1994）\"),\n    (\"pk_sca\", \"正弦余弦 SCA（排列）\", \"群体智能\", \"随机键+正弦余弦更新\"),\n    (\"pk_mfo\", \"蛾焰 MFO（排列）\", \"群体智能\", \"随机键+经典多焰递减螺旋（Mirjalili 2015）\"),\n    (\"pk_eo\", \"均衡 EO（排列）\", \"物理定律\", \"随机键+经典平衡池（Faramarzi 2020 核对修正）\"),\n    (\"pk_ao\", \"天鹰 AO（排列）\", \"群体智能\", \"随机键+经典四阶段（Abualigah 2021 核对修正）\"),\n    (\"pk_sma\", \"黏菌 SMA（排列）\", \"群体智能\", \"随机键+经典位移式（Li 2020 核对修正）\"),\n    (\"pk_fa\", \"萤火虫 FA（排列）\", \"群体智能\", \"随机键+亮度吸引\"),\n    (\"pk_ba\", \"蝙蝠 BA（排列）\", \"群体智能\", \"随机键+频率调谐\"),\n    (\"pk_jaya\", \"Jaya（排列）\", \"群体智能\", \"随机键+向优避劣\"),\n    (\"pk_tlbo\", \"TLBO（排列）\", \"人类与社会启发\", \"随机键+教师/学习\"),\n    (\"pk_cem\", \"交叉熵 CEM（排列）\", \"进化计算\", \"随机键+精英均值回写+停滞重启\"),\n    (\"pk_cmaes\", \"CMA-ES（排列·对角近似）\", \"进化计算\", \"随机键+对角步长自适应（诚实简化）\"))}\nfor _reg in (_GC_ALGOS, _GCV_ALGOS, _BP_ALGOS, _BPVAR_ALGOS):\n    _reg.update(_PK_ALGOS)\nif \"_GCVAR_ALGOS\" in dir() or True:\n    try:\n        _GCVAR_ALGOS.update(_PK_ALGOS)  # 并级注册表（domain_start 预检用）\n    except NameError:\n        pass\n_MIS_ALGOS.update(_bv_reg())  # mis 位串变体：挂位向量 bv 系（位编码天然适配，非排列）\ntry:\n    _GCVAR_ALGOS.update(_bv_reg())  # 并级也挂 bv（domain_start 预检走并级，mis 变体分派用 _MIS_ALGOS）\nexcept NameError:\n    pass\nfor _reg_es in (_ES_ALGOS,):\n    _reg_es.update(_PK_ALGOS)  # entryseq 排列变体挂随机键 pk 系（位/向量变体已有 bv 系）\n# vrp 变体撤下 pk_sma（2026-09-28 严口径门）：994.79 vs 随机最优 959.98——Levy 大步在 VRP 路径域发散（sms 变体 12/12 过门）\n\n\n# ---- entryseq：三种编码各配一套算法（2026-10 重做，取代此前「撤下」的补丁）----\n# 此前 entryseq 把所有变体当排列用，再靠撤下清单掩盖不适用的组合：ga / ts 继承自位向量内核而全部崩溃；\n# bv_*（位向量）与 pk_*（排列的随机键桥接）被无差别地挂在实数向量变体上，把 0/1 或 0..n-1 当作实数向量喂给目标函数——\n# 能跑、不报错，但结果没有意义。现在每种编码只配适用的算法：\n#   排列变体      random / hc / sa / de / gwo / cs（排列·向量双模）+ 新写的排列 ga / ts + pk_* 随机键系\n#   位向量变体    与 QUBO 同一批位向量算法（含 ga / ts / bv_*）\n#   实数向量变体  与连续函数同一批连续算法（pso / de / cmaes / …）\n# 排列变体的算法集：去掉位向量 bv_*（把 0/1 当排列喂给目标函数，结果没有意义）和「greedy」\n# （那个键指向的就是随机基线 _sw_random，与 random 重复，名字还误导）\n_ES_PERM_ALGOS = {k: v for k, v in _ES_ALGOS.items() if not k.startswith(\"bv_\") and k != \"greedy\"}\n\n\ndef _es_tournament(vals, rng, k=3):\n    return min(rng.sample(range(len(vals)), min(k, len(vals))), key=vals.__getitem__)\n\n\ndef _es_ga(ctx, p, rng):\n    \"\"\"排列版遗传算法：锦标赛选择 + OX 顺序交叉 + 交换/插入变异 + 精英保留。\"\"\"\n    n_pop = int(p.get(\"n_pop\", 30))\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    vals = [ctx.obj(x) for x in pop]\n    bi = min(range(n_pop), key=vals.__getitem__)\n    best, bs = vals[bi], list(pop[bi])\n    k_mut = max(1, round(p.get(\"pm\", 0.06) * ctx.n))\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(bs)]\n        while len(new) < n_pop:\n            a, b = _es_tournament(vals, rng), _es_tournament(vals, rng)\n            child = _pm_ox(pop[a], pop[b], rng) if rng.random() < 0.9 else list(pop[a])\n            if rng.random() < 0.5:\n                for _ in range(k_mut):\n                    child = _pm_swap(child, rng) if rng.random() < 0.5 else _pm_insert(child, rng)\n            new.append(child)\n        pop = new\n        vals = [ctx.obj(x) for x in pop]\n        bi = min(range(n_pop), key=vals.__getitem__)\n        if vals[bi] < best:\n            best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": sum(vals) / n_pop, \"best_sol\": list(bs)}\n\n\ndef _es_ts(ctx, p, rng):\n    \"\"\"排列版禁忌搜索：每步在 tries 个随机交换里取最好的非禁忌移动；刚交换过的位置对在 tenure 步内禁忌，\n    但比历史最优还好的移动可以破禁（aspiration）。\"\"\"\n    n = ctx.n\n    s = ctx.random(rng)\n    v = ctx.obj(s)\n    best, bs = v, list(s)\n    tabu = {}\n    for it in range(1, p[\"max_iter\"] + 1):\n        pick = None\n        for _ in range(int(p.get(\"tries\", 48))):\n            i, j = sorted(rng.sample(range(n), 2))\n            t = list(s)\n            t[i], t[j] = t[j], t[i]\n            tv = ctx.obj(t)\n            if tabu.get((i, j), 0) >= it and tv >= best:\n                continue\n            if pick is None or tv < pick[0]:\n                pick = (tv, t, (i, j))\n        if pick is None:  # 采样到的移动全被禁忌：随机扰动一下\n            s = ctx.swap(s, rng)\n            v = ctx.obj(s)\n        else:\n            v, s, mv = pick\n            tabu[mv] = it + int(p.get(\"tenure\", 10)) + rng.randrange(3)\n        if v < best:\n            best, bs = v, list(s)\n        yield {\"iter\": it, \"best\": best, \"cur\": v, \"best_sol\": list(bs)}\n\n\n_ES_PERM_ALGOS.update({\n    \"ga\": {\"fn\": _es_ga, \"name\": \"遗传算法 GA（排列）\", \"category\": \"进化计算\",\n           \"desc\": \"锦标赛选择 + OX 顺序交叉 + 交换/插入变异 + 精英保留\", \"tune\": [\"pm\"]},\n    \"ts\": {\"fn\": _es_ts, \"name\": \"禁忌搜索 TS（排列）\", \"category\": \"局部搜索\",\n           \"desc\": \"随机交换邻域取最好非禁忌移动，禁忌位置对，破禁准则\", \"tune\": [\"tenure\"]},\n})\n\n\nclass _ESVecCN:\n    \"\"\"entryseq 实数向量变体 → 连续域算法期望的上下文（dim / lo / hi / eval / clamp / random / init_pop）。\n    同时记下评价过的最优点，好让状态里带上完整的 best_sol。\"\"\"\n\n    def __init__(self, es):\n        self._es = es\n        self.variant, self.p, self.n, self.vec = es.variant, es.p, es.n, True\n        self.dim, self.lo, self.hi = es.n, -5.0, 5.0\n        self.best_val, self.best_x = float(\"inf\"), None\n\n    def random(self, rng):\n        return [rng.uniform(self.lo, self.hi) for _ in range(self.dim)]\n\n    def eval(self, x):\n        v = self._es.obj(x)\n        if v < self.best_val:\n            self.best_val, self.best_x = v, list(x)\n        return v\n\n    obj = eval\n\n    def clamp(self, x):\n        return [min(self.hi, max(self.lo, v)) for v in x]\n\n    def init_pop(self, p, rng):\n        pop = [self.random(rng) for _ in range(p[\"n_pop\"])]\n        return pop, [self.eval(x) for x in pop]\n\n    def detail(self, s):\n        return self._es.detail(s)\n\n\n_ES_BIT_DEF = dict(_QB_DEF, t0=3.0)  # _QB_DEF 已补齐 F / CR / limit / pa 等位编码算法要的键  # 子集类目标的可行差距是个位数，罚项 BIG 远大于它：温度取个位数\n_ES_ALGOS_ALL = {}\nfor _reg_x in (_ES_PERM_ALGOS, _BIN_ALGOS, _CN_ALGOS):\n    for _k_x, _v_x in _reg_x.items():\n        _ES_ALGOS_ALL.setdefault(_k_x, _v_x)\n\n\ndef _es_registry(variant):\n    \"\"\"该变体的编码对应的算法集。\"\"\"\n    if variant in BIT_VARIANTS:\n        return _BIN_ALGOS\n    if variant in VEC_VARIANTS:\n        return _CN_ALGOS\n    return _ES_PERM_ALGOS\n\n\ndef _es_defaults(variant):\n    if variant in BIT_VARIANTS:\n        return _ES_BIT_DEF\n    if variant in VEC_VARIANTS:\n        return _CN_DEF\n    return _ES_DEF\n\n\ndef _es_blocked(variant, algo):\n    \"\"\"变体级不可用判定：domain_list 过滤与 domain_start 拒绝共用，避免页面列出幽灵选项。\n    算法不在该变体编码的算法集里即不可用；另有个别组合因发散被撤下。\"\"\"\n    return algo not in _es_registry(variant) or (variant in (\"vrp\", \"vrptw\", \"vrpstw\", \"mdvrp\") and algo == \"pk_sma\")  # pk_sma：Levy 大步在 VRP 路径域发散（严口径门，2026-09-28）\n\n\n# ---- M3 指派域挂载（2026-09-28）：round+clamp 解码，gap 域专用 ----\n_AS_ALGOS = {k: {\"fn\": getattr(__import__(__name__), \"_\" + k), \"name\": nm, \"category\": cat, \"desc\": ds, \"tune\": []}\n             for k, nm, cat, ds in (\n    (\"as_pso\", \"粒子群 PSO（指派）\", \"群体智能\", \"实值位置+round-clamp\"),\n    (\"as_sca\", \"正弦余弦 SCA（指派）\", \"群体智能\", \"正弦余弦+round-clamp\"),\n    (\"as_mfo\", \"蛾焰 MFO（指派）\", \"群体智能\", \"经典多焰递减螺旋+round-clamp（Mirjalili 2015）\"),\n    (\"as_eo\", \"均衡 EO（指派）\", \"物理定律\", \"经典平衡池+GCP 开关+round-clamp\"),\n    (\"as_ao\", \"天鹰 AO（指派）\", \"群体智能\", \"经典四阶段+round-clamp（核对修正）\"),\n    (\"as_sma\", \"黏菌 SMA（指派）\", \"群体智能\", \"经典位移式+log 权重+round-clamp\"),\n    (\"as_fa\", \"萤火虫 FA（指派）\", \"群体智能\", \"亮度吸引+round-clamp\"),\n    (\"as_ba\", \"蝙蝠 BA（指派）\", \"群体智能\", \"频率调谐+round-clamp\"),\n    (\"as_jaya\", \"Jaya（指派）\", \"群体智能\", \"向优避劣+round-clamp\"),\n    (\"as_tlbo\", \"TLBO（指派）\", \"人类与社会启发\", \"教师/学习+round-clamp\"),\n    (\"as_cem\", \"交叉熵 CEM（指派）\", \"进化计算\", \"精英均值回写+停滞重启\"),\n    (\"as_cmaes\", \"CMA-ES（指派·对角近似）\", \"进化计算\", \"对角步长自适应（诚实简化）\"))}\n_GAP_ALGOS.update(_AS_ALGOS)\n_GAP_ALGOS.pop(\"as_mfo\")  # gap 撤下 as_mfo（终审A 抓到 M4 续 4 撤下被条件分支静默跳过——多焰后 471 vs 427 严口径负，现真正落地）\n# as_eo 曾撤下（470 vs 427），M4 文献核对（Faramarzi 2020 正典平衡池+GCP 开关）修正后 400 vs 427 过门 → 回挂\n# as_sca 曾撤下（471 vs 427），M4 文献核对发现 SCA 更新式偏离正典（拼接变体 vs 标准 sin/cos），\n# 修正为标准式（r4 切换 sin/cos，r3∈[0,2] 目的地权重）后 385 vs 427 过门 → 回挂\n\n# ---- 把 56_generic_bridges.py 里的新算法挂进各域的算法注册表（2026-10）----\n# 连续域与实数向量变体（自带问题 real、entryseq 的 16 个实数变体）直接用连续内核；\n# 位向量 / 排列 / 指派向量问题经通用适配器（bv_* / pk_* / as_*）。\n# 哪些「域 × 变体 × 算法」在等评价次数下赢不了随机搜索而被撤下，见 88_withdrawn_cells.py（由 tools/fair_budget.py 生成）。\n\n_NEW_CN_ENTRIES, _NEW_BV_ENTRIES, _NEW_PK_ENTRIES, _NEW_AS_ENTRIES = {}, {}, {}, {}\nfor _k, (_fn, _nm, _ds) in _NEW_CN.items():\n    _cat = category_of(_k, \"群体智能\")\n    _NEW_CN_ENTRIES[_k] = {\"fn\": _fn, \"name\": _nm, \"category\": _cat, \"desc\": \"原生域！\" + _ds, \"tune\": []}\n    _NEW_BV_ENTRIES[\"bv_\" + _k] = {\"fn\": _bridge(_fn, \"bits\", \"bv\"), \"name\": _nm + \"（位）\", \"category\": _cat,\n                                   \"desc\": _ds + \"；实数位置经 sigmoid 取 0/1\", \"tune\": []}\n    _NEW_PK_ENTRIES[\"pk_\" + _k] = {\"fn\": _bridge(_fn, \"perm\", \"pk\"), \"name\": _nm + \"（排列）\", \"category\": _cat,\n                                   \"desc\": _ds + \"；随机键桥接（Bean 1994）\", \"tune\": []}\n    _NEW_AS_ENTRIES[\"as_\" + _k] = {\"fn\": _bridge(_fn, \"assign\", \"as\"), \"name\": _nm + \"（指派）\", \"category\": _cat,\n                                   \"desc\": _ds + \"；实数位置四舍五入 + 截断\", \"tune\": []}\n\n_CN_ALGOS.update(_NEW_CN_ENTRIES)\n\n# 位向量：与 _bv_reg() 同一批注册表（min 协议）；knapsack 是 max 协议，经 _maximize 取负代理适配\nfor _reg in (_SAT_ALGOS, _BIN_ALGOS, _UF_ALGOS, _SC_ALGOS, _MIS_ALGOS, _KPV_ALGOS, _SSP_ALGOS, _CMP_ALGOS, _KPVAR_ALGOS):\n    _reg.update(_NEW_BV_ENTRIES)\ntry:\n    _GCVAR_ALGOS.update(_NEW_BV_ENTRIES)\nexcept NameError:\n    pass\nfor _bk, _be in _NEW_BV_ENTRIES.items():\n    _KS_ALGOS[_bk] = {\"fn\": _maximize(_be[\"fn\"]), \"name\": _be[\"name\"] + \"（max）\", \"category\": _be[\"category\"],\n                      \"desc\": _be[\"desc\"] + \"；max 域经 obj 取负代理适配\", \"tune\": []}\n\n# 排列：与 _PK_ALGOS 同一批注册表\nfor _reg in (_GC_ALGOS, _GCV_ALGOS, _BP_ALGOS, _BPVAR_ALGOS, _ES_ALGOS, _ES_PERM_ALGOS):\n    _reg.update(_NEW_PK_ENTRIES)\ntry:\n    _GCVAR_ALGOS.update(_NEW_PK_ENTRIES)\nexcept NameError:\n    pass\n\n# 指派：gap\n_GAP_ALGOS.update(_NEW_AS_ENTRIES)\n\n# entryseq 的总表（_DOMAINS[\"entryseq\"][\"algos\"] 引用它）\nfor _reg_x in (_ES_PERM_ALGOS, _BIN_ALGOS, _CN_ALGOS):\n    for _k_x, _v_x in _reg_x.items():\n        _ES_ALGOS_ALL.setdefault(_k_x, _v_x)\n\n\n# ---- 通用离散 / 局部搜索系内核（57_generic_discrete_kernels.py）：按编码挂到对应的注册表 ----\n_GENERIC_BITS_REGS = [_SAT_ALGOS, _BIN_ALGOS, _UF_ALGOS, _SC_ALGOS, _MIS_ALGOS, _KPV_ALGOS, _SSP_ALGOS, _CMP_ALGOS, _KPVAR_ALGOS, _KS_ALGOS]\ntry:\n    _GENERIC_BITS_REGS.append(_GCVAR_ALGOS)\nexcept NameError:\n    pass\n_GENERIC_PERM_REGS = [_GC_ALGOS, _GCV_ALGOS, _BP_ALGOS, _BPVAR_ALGOS, _ES_ALGOS, _ES_PERM_ALGOS]\n_GENERIC_KIND_REGS = {\"bits\": _GENERIC_BITS_REGS, \"perm\": _GENERIC_PERM_REGS, \"assign\": [_GAP_ALGOS], \"real\": [_CN_ALGOS]}\n_KIND_LABEL = {\"bits\": \"位向量\", \"perm\": \"排列\", \"assign\": \"指派向量\", \"real\": \"实数向量\"}\nfor _k, (_fn, _nm, _ds, _kinds) in _NEW_GENERIC.items():\n    for _kind in _kinds:\n        _entry = {\"fn\": _viewed(_fn, f\"_mv_{_k}_{_kind}\"), \"name\": _nm, \"category\": category_of(_k, \"局部搜索与轨迹法\"),\n                  \"desc\": _ds + f\"（{_KIND_LABEL[_kind]}问题通用版）\", \"tune\": []}\n        for _reg in _GENERIC_KIND_REGS[_kind]:\n            _reg.setdefault(_k, _entry)\nfor _reg_x in (_ES_PERM_ALGOS, _BIN_ALGOS, _CN_ALGOS):\n    for _k_x, _v_x in _reg_x.items():\n        _ES_ALGOS_ALL.setdefault(_k_x, _v_x)\n# 撤下账本——AUTO-GENERATED，请勿手改：python tools/fair_budget.py --write-ledger\n# 判定：等评价次数（算法自己用了多少次评价，随机搜索基线就给多少次）、200 代、9 个种子取中位数，\n# 算法仍比随机搜索差（相对差距超过边际）的「域 × 变体 × 算法」格子。证据见 data/withdrawn_cells.json。\n_WITHDRAWN = {\n    (\"binpack\", \"-\"): frozenset(['gwo', 'hc', 'ts', 'vns']),\n    (\"bpvar\", \"strippack\"): frozenset(['pk_sma']),\n    (\"continuous\", \"-\"): frozenset(['bfo', 'hc']),\n    (\"custom\", \"bits\"): frozenset(['bv_gsa', 'bv_mfo', 'bv_sma', 'bv_tlbo']),\n    (\"custom\", \"perm\"): frozenset(['pk_sma']),\n    (\"custom\", \"real\"): frozenset(['mfo', 'sca', 'sma']),\n    (\"entryseq\", \"atsp\"): frozenset(['pk_bfo', 'pk_eo', 'pk_sma']),\n    (\"entryseq\", \"blo\"): frozenset(['mfo']),\n    (\"entryseq\", \"carp\"): frozenset(['pk_bfo', 'pk_sma']),\n    (\"entryseq\", \"cbbb\"): frozenset(['mfo']),\n    (\"entryseq\", \"cflp\"): frozenset(['pk_ba', 'pk_bbo', 'pk_bfo', 'pk_boa', 'pk_eo', 'pk_ica', 'pk_kh', 'pk_mfo', 'pk_pso', 'pk_sca', 'pk_ssa']),\n    (\"entryseq\", \"domset\"): frozenset(['bv_gsa', 'bv_tlbo']),\n    (\"entryseq\", \"ebbb\"): frozenset(['mfo']),\n    (\"entryseq\", \"fjsp\"): frozenset(['pk_bfo', 'pk_boa', 'pk_eo', 'pk_sma']),\n    (\"entryseq\", \"fkp\"): frozenset(['boa', 'gsa', 'mfo', 'sca']),\n    (\"entryseq\", \"freqasg\"): frozenset(['pk_eo', 'pk_sca', 'pk_sma', 'pk_ssa']),\n    (\"entryseq\", \"fss\"): frozenset(['pk_bfo', 'pk_cem', 'pk_eo', 'pk_sca', 'pk_sma']),\n    (\"entryseq\", \"fvs\"): frozenset(['bv_boa', 'bv_ssa', 'bv_tlbo']),\n    (\"entryseq\", \"ged\"): frozenset(['boa', 'fa', 'gsa', 'mfo', 'sca']),\n    (\"entryseq\", \"gmatch\"): frozenset(['pk_boa', 'pk_sca']),\n    (\"entryseq\", \"gpp\"): frozenset(['pk_eo']),\n    (\"entryseq\", \"hc\"): frozenset(['pk_eo', 'pk_sma', 'pk_ssa']),\n    (\"entryseq\", \"hset\"): frozenset(['bv_gsa']),\n    (\"entryseq\", \"jss\"): frozenset(['pk_eo']),\n    (\"entryseq\", \"kmeans\"): frozenset(['boa', 'mfo', 'sca', 'sma']),\n    (\"entryseq\", \"lap\"): frozenset(['pk_boa', 'pk_eo', 'pk_sma']),\n    (\"entryseq\", \"lbbb\"): frozenset(['mfo']),\n    (\"entryseq\", \"lop\"): frozenset(['gwo', 'pk_sma']),\n    (\"entryseq\", \"lpath\"): frozenset(['gwo', 'pk_ba', 'pk_boa', 'pk_da', 'pk_eo', 'pk_sca', 'pk_sma', 'pk_ssa']),\n    (\"entryseq\", \"lrp\"): frozenset(['pk_bfo', 'pk_boa', 'pk_da', 'pk_eo', 'pk_fwa', 'pk_mfo', 'pk_sca', 'pk_sma']),\n    (\"entryseq\", \"maxcut\"): frozenset(['bv_boa', 'bv_gsa', 'bv_kh', 'bv_mfo', 'bv_sma', 'bv_ssa', 'bv_tlbo', 'hc', 'qb_sca']),\n    (\"entryseq\", \"maxflow\"): frozenset(['boa', 'fa']),\n    (\"entryseq\", \"mincostflow\"): frozenset(['boa', 'fa']),\n    (\"entryseq\", \"mmo\"): frozenset(['cem', 'mfo']),\n    (\"entryseq\", \"msa\"): frozenset(['bv_bfo', 'bv_boa', 'bv_gsa', 'hc']),\n    (\"entryseq\", \"mst\"): frozenset(['pk_ba', 'pk_bfo', 'pk_boa', 'pk_eo', 'pk_sca', 'pk_sma']),\n    (\"entryseq\", \"nbbb\"): frozenset(['cem', 'mfo']),\n    (\"entryseq\", \"ndp\"): frozenset(['bv_ais', 'bv_bfo', 'bv_boa', 'bv_gsa', 'bv_mfo', 'bv_sma', 'bv_ssa', 'bv_tlbo', 'grasp', 'hc', 'qb_sca']),\n    (\"entryseq\", \"numpart\"): frozenset(['abc', 'alo', 'ao', 'ba', 'bbo', 'bfo', 'boa', 'cmaes', 'cscrow', 'da', 'de', 'eo', 'fa', 'fpa', 'fwa', 'gsa', 'gwo', 'hc', 'hho', 'hs', 'ica', 'ils', 'kh', 'mfo', 'mpa', 'pso', 'sa', 'salp', 'sca', 'sma', 'ssa', 'tlbo', 'vns', 'woa']),\n    (\"entryseq\", \"orienteering\"): frozenset(['gwo', 'pk_ba', 'pk_bfo', 'pk_boa', 'pk_eo', 'pk_fwa', 'pk_kh', 'pk_pso', 'pk_sca', 'pk_sma']),\n    (\"entryseq\", \"oss\"): frozenset(['pk_bfo', 'pk_boa', 'pk_eo', 'pk_sca', 'pk_sma']),\n    (\"entryseq\", \"pcenter\"): frozenset(['pk_sca']),\n    (\"entryseq\", \"pmedian\"): frozenset(['sa']),\n    (\"entryseq\", \"proteinfold\"): frozenset(['pk_eo', 'pk_sma']),\n    (\"entryseq\", \"pvessel\"): frozenset(['boa', 'gsa', 'gwo', 'mfo', 'sfla', 'sma', 'woa']),\n    (\"entryseq\", \"qap\"): frozenset(['pk_bbo', 'pk_bfo', 'pk_da', 'pk_kh', 'pk_sca', 'pk_sma', 'pk_ssa']),\n    (\"entryseq\", \"reducer\"): frozenset(['boa', 'fa', 'gwo', 'mfo', 'sca', 'sfla', 'woa']),\n    (\"entryseq\", \"ro\"): frozenset(['mfo']),\n    (\"entryseq\", \"rpostman\"): frozenset(['pk_bfo', 'pk_eo', 'pk_sma']),\n    (\"entryseq\", \"shortestpath\"): frozenset(['hc', 'ils', 'vns']),\n    (\"entryseq\", \"sms\"): frozenset(['pk_sma']),\n    (\"entryseq\", \"stp\"): frozenset(['bv_tlbo']),\n    (\"entryseq\", \"tcspring\"): frozenset(['bbo', 'boa', 'gsa', 'gwo', 'mfo', 'sfla', 'sma']),\n    (\"entryseq\", \"tdm\"): frozenset(['bv_bfo', 'bv_sma', 'bv_ssa', 'bv_tlbo']),\n    (\"entryseq\", \"topsort\"): frozenset(['pk_sma']),\n    (\"entryseq\", \"vcover\"): frozenset(['bv_mfo', 'bv_tlbo']),\n    (\"entryseq\", \"vrp\"): frozenset(['pk_bfo', 'pk_boa']),\n    (\"entryseq\", \"vrpstw\"): frozenset(['pk_boa']),\n    (\"entryseq\", \"vrptw\"): frozenset(['pk_alo', 'pk_boa', 'pk_sca']),\n    (\"entryseq\", \"wbeam\"): frozenset(['ao', 'bbo', 'boa', 'fa', 'fwa', 'gsa', 'gwo', 'hho', 'mfo', 'sca', 'sfla', 'sma', 'woa']),\n    (\"gap\", \"-\"): frozenset(['as_boa', 'as_sca', 'as_sma', 'gwo']),\n    (\"gcvar\", \"mis\"): frozenset(['aco', 'bv_ao', 'bv_ba', 'bv_bbo', 'bv_bfo', 'bv_boa', 'bv_cem', 'bv_cscrow', 'bv_hho', 'bv_ica', 'bv_jaya', 'bv_kh', 'bv_mfo', 'bv_pso', 'bv_salp', 'bv_sca', 'bv_sma', 'bv_ssa', 'bv_tlbo', 'hc', 'ts']),\n    (\"graphcolor\", \"-\"): frozenset(['pk_ba', 'pk_bfo', 'pk_boa', 'pk_da', 'pk_eo', 'pk_sma', 'pk_ssa']),\n    (\"knapsack\", \"-\"): frozenset(['bv_bfo', 'bv_sma']),\n    (\"kpvar\", \"bkp\"): frozenset(['bv_ais', 'bv_bfo', 'grasp', 'hc']),\n    (\"kpvar\", \"cmp\"): frozenset(['bv_alo', 'bv_ba', 'bv_bbo', 'bv_bfo', 'bv_fa', 'bv_jaya', 'bv_kh', 'bv_mfo', 'bv_pso', 'bv_salp', 'bv_sca', 'bv_sma', 'bv_ssa', 'ts']),\n    (\"kpvar\", \"mdkp\"): frozenset(['bv_bfo', 'bv_boa', 'bv_gsa']),\n    (\"kpvar\", \"mkpm\"): frozenset(['sa']),\n    (\"kpvar\", \"qkp\"): frozenset(['bv_gsa']),\n    (\"kpvar\", \"ssp\"): frozenset(['bv_mfo', 'bv_sca', 'bv_tlbo', 'hc']),\n    (\"kpvar\", \"ukp\"): frozenset(['bv_afsa', 'bv_bfo', 'bv_boa', 'grasp', 'hc']),\n    (\"qubo\", \"-\"): frozenset(['bv_afsa', 'bv_bfo', 'bv_boa', 'bv_sma']),\n    (\"sat\", \"-\"): frozenset(['bv_ais', 'bv_ba', 'bv_bfo', 'bv_boa', 'bv_gsa', 'bv_sca', 'bv_sma', 'bv_tlbo']),\n    (\"setcover\", \"-\"): frozenset(['bv_afsa', 'bv_ais', 'bv_alo', 'bv_bbo', 'bv_bfo', 'bv_boa', 'bv_cscrow', 'bv_da', 'bv_fa', 'bv_fpa', 'bv_fwa', 'bv_ica', 'bv_jaya', 'bv_kh', 'bv_mpa', 'bv_salp', 'bv_sfla', 'bv_sos', 'bv_tlbo']),\n    (\"uflp\", \"-\"): frozenset(['bv_ais', 'bv_ba', 'bv_bfo', 'bv_boa', 'bv_cscrow', 'bv_da', 'bv_gsa', 'bv_kh', 'bv_mfo', 'bv_sca', 'bv_sma', 'bv_ssa', 'bv_tlbo']),\n}\n\n\ndef _is_withdrawn(domain, variant, algo):\n    \"\"\"该格子是否因「等评价次数下赢不了随机搜索」被撤下。\"\"\"\n    return algo in _WITHDRAWN.get((domain, variant or \"-\"), ())\n_DOMAINS = {\n    \"knapsack\": {\"algos\": _KS_ALGOS, \"def\": _KS_DEF, \"make\": ks_make},\n    \"continuous\": {\"algos\": _CN_ALGOS, \"def\": _CN_DEF, \"make\": cn_make},\n    \"multiobj\": {\"algos\": _MO_ALGOS, \"def\": _MO_DEF, \"make\": mo_make},\n    \"mocont\": {\"algos\": MOC_ALGOS, \"def\": MOC_DEF, \"make\": mc_make},\n    \"graphcolor\": {\"algos\": _GC_ALGOS, \"def\": _GC_DEF, \"make\": gc_make},\n    \"binpack\": {\"algos\": _BP_ALGOS, \"def\": _BP_DEF, \"make\": bp_make},\n    \"setcover\": {\"algos\": _SC_ALGOS, \"def\": _SC_DEF, \"make\": sc_make},\n    \"sat\": {\"algos\": _SAT_ALGOS, \"def\": _SAT_DEF, \"make\": sat_make},\n    \"qubo\": {\"algos\": _BIN_ALGOS, \"def\": _QB_DEF, \"make\": qb_make},\n    \"gap\": {\"algos\": _GAP_ALGOS, \"def\": _GAP_DEF, \"make\": gap_make},\n    \"uflp\": {\"algos\": _UF_ALGOS, \"def\": _UF_DEF, \"make\": uf_make},\n    \"entryseq\": {\"algos\": _ES_ALGOS_ALL, \"def\": _ES_DEF, \"make\": es_make},\n    \"kpvar\": {\"algos\": _KPVAR_ALGOS,\n              # t0=25/decay=0.995：背包家族全变体标定值（bkp/ukp 需要高温慢冷；\n              # _KS_DEF 的 8/0.985 只适用于背包枢纽实例）；F/CR/pm/limit/pa 供 _ks_de/ga/abc/cs\n              \"def\": dict(_BIN_DEF, t0=25.0, decay=0.995, F=0.7, CR=0.6, pm=0.04,\n                          limit=12, pa=0.25),\n              \"make\": kpv_make},\n    \"gcvar\": {\"algos\": _GCVAR_ALGOS,\n              # 排列变体（listcolor 等）沿用图着色标定 t0=800/decay=0.985；\n              # 但 ts_sample 降到 36（edgecolor/totalcolor 线图/全图 N 暴涨，O(N²) 解码下\n              # 120 会让 TS 卡死浏览器）；mis 位串变体在 domain_start 内被 t0=30/decay=0.98 覆盖\n              \"def\": dict(_GCVAR_DEF),\n              \"make\": gcv_make},\n    \"bpvar\": {\"algos\": _BPVAR_ALGOS,\n              # 3 变体共用排列内核；VSBPP 成本目标 / 2D 箱数 / 条带高度，皆 FF/shelf 解码\n              \"def\": dict(_BPVAR_DEF),\n              \"make\": bpv_make},\n    # 自带问题：三个变体 = 三种编码，各复用一批现成内核（位向量=QUBO 那批，排列=装箱那批，实数=连续函数那批）\n    \"custom\": {\"algos\": _BIN_ALGOS, \"def\": _QB_DEF,\n               \"make\": lambda seed=7, **kw: up_preset(kw.get(\"variant\", \"bits\"), kw.get(\"n\"), seed)},\n}\n_CUSTOM_REG = {\"bits\": (_BIN_ALGOS, _QB_DEF), \"perm\": (_BP_ALGOS, _BP_DEF), \"real\": (_CN_ALGOS, _CN_DEF)}\n\n# === 排程域接线（2026-09-29 完善战役：nrp/ttp/sls 专业编码，见 py/scheduling.py）===\n# 两种导入顺序都必须安全（2026-09-29 集成期抓到反向导入炸裂）：\n#   A) 先 import domains：try-import scheduling 时 scheduling 反向 from domains import 四内核，\n#      此点前四内核已全部定义 → scheduling 完整加载 → _wire_sched_domains 正常挂接；\n#   B) 先 import scheduling：scheduling 第 26 行 from domains import → domains 重新入栈执行，\n#      执行到本 wire 块时 scheduling 尚停在自身第 26 行（半加载，无 _SCHED_ALGOS）——\n#      必须 fail-soft 跳过，等 scheduling 加载完成后由其尾部回挂（见 scheduling.py 尾注）。\n# 浏览器拼接环境：import 抛 ImportError → gen_domains_src 在调度源码后注入 _schedmod 并调 _wire_sched_domains。\ntry:\n    import scheduling as _schedmod\nexcept ImportError:\n    _schedmod = None\n\n_SCHED_DOMAINS = (\"nrp\", \"etp\", \"ttp\", \"sls\")\n\n\ndef _wire_sched_domains(m):\n    if not hasattr(m, \"_SCHED_ALGOS\"):\n        return  # scheduling 半加载中（B 序循环导入保护）：主线 A 序/浏览器拼接环境不受影响\n    _DOMAINS[\"nrp\"] = {\"algos\": m._SCHED_ALGOS, \"def\": m._SCHED_DEF, \"make\": m.nrp_make}\n    _DOMAINS[\"etp\"] = {\"algos\": m._SCHED_ALGOS, \"def\": m._SCHED_DEF, \"make\": m.etp_make}\n    _DOMAINS[\"ttp\"] = {\"algos\": m._SCHED_ALGOS, \"def\": m._SCHED_DEF, \"make\": m.tour_make}\n    _DOMAINS[\"sls\"] = {\"algos\": m._SCHED_ALGOS, \"def\": m._SCHED_DEF, \"make\": m.sls_make}\n\n\nif _schedmod is not None:\n    _wire_sched_domains(_schedmod)\n\n_RUN = {\"gen\": None, \"ctx\": None, \"domain\": None}\n\n\ndef _kpvar_reg(variant):\n    \"\"\"kpvar 变体 → 该变体可用的算法注册表（mckp/mkpm 与位向量变体内核不同；\n    精确 DP 锚点按变体专属：ssp_dp 只挂 ssp，cmp_dp 只挂 cmp；\n    密度贪心对 ssp（可达 0 差）/cmp（币值密度陷阱）无意义，不挂）。\"\"\"\n    if variant == \"mkpm\":\n        return _MKPM_ALGOS\n    if variant in (\"mckp\", \"dkp\"):\n        return _MCKP_ALGOS\n    if variant == \"ssp\":\n        return _SSP_ALGOS\n    if variant == \"cmp\":\n        return _CMP_ALGOS\n    return _KPV_ALGOS\n\n\ndef _gcvar_reg(variant):\n    \"\"\"gcvar 变体 → 该变体可用的算法注册表。mis 用位串内核（_MIS_ALGOS），\n    其余 4 个排列变体复用图着色内核（_GCV_ALGOS，含度序贪心锚点）。\"\"\"\n    if variant == \"mis\":\n        return _MIS_ALGOS\n    return _GCV_ALGOS\n\n\ndef _bpvar_reg(variant):\n    \"\"\"bpvar 变体 → 算法注册表（3 变体共用排列内核 + 构造贪心锚点）。\"\"\"\n    return _BPVAR_ALGOS\n\n\ndef domain_list(domain, opts=None):\n    if isinstance(opts, str):\n        opts = json.loads(opts) if opts else {}\n    opts = opts or {}\n    if domain in _SCHED_DOMAINS:\n        lst = json.loads(_schedmod.sched_list(domain))\n        for a in lst[\"algos\"]:\n            a[\"category\"] = category_of(a[\"key\"], a[\"category\"])\n        return json.dumps(lst)\n    d = _DOMAINS[domain]\n    algos = d[\"algos\"]\n    if domain == \"kpvar\":  # H 期：变体分派算法集（list 调用带 preset opts）\n        algos = _kpvar_reg(opts.get(\"variant\", \"ssp\"))\n    elif domain == \"gcvar\":  # H2 期：变体分派算法集（着色家族 5 变体）\n        algos = _gcvar_reg(opts.get(\"variant\", \"listcolor\"))\n    elif domain == \"bpvar\":  # H3 期：变体分派算法集（装箱家族 3 变体）\n        algos = _bpvar_reg(opts.get(\"variant\", \"vsbinpack\"))\n    elif domain == \"entryseq\":  # 算法集按变体的编码分派（排列 / 位向量 / 实数向量），与 domain_start 的拒绝规则一致\n        algos = {k: v for k, v in _es_registry(opts.get(\"variant\", \"sms\")).items()\n                 if not _es_blocked(opts.get(\"variant\", \"sms\"), k)}\n    elif domain == \"custom\":  # 自带问题：算法集按编码分派\n        algos = _CUSTOM_REG[opts.get(\"variant\", \"bits\")][0]\n    if domain != \"custom\":  # 等评价次数门撤下的格子不再列出（自带问题的目标函数是用户的，不适用）\n        _v = opts.get(\"variant\") or {\"kpvar\": \"ssp\", \"gcvar\": \"listcolor\", \"bpvar\": \"vsbinpack\", \"entryseq\": \"sms\",\n                                     \"multiobj\": \"moco\", \"mocont\": \"zdt1\"}.get(domain)\n        algos = {k: v for k, v in algos.items() if not _is_withdrawn(domain, _v, k)}\n    out = []\n    for key, a in algos.items():\n        # 分类以家族体系为准：同一个内核（如 bv_pso）在所有域/变体里标签一致；基线/贪心等不在体系里的沿用注册表\n        out.append({\"key\": key, \"name\": a[\"name\"], \"category\": category_of(key, a[\"category\"]),\n                    \"desc\": a[\"desc\"], \"tune\": a[\"tune\"]})\n    defs = dict(_CUSTOM_REG[opts.get(\"variant\", \"bits\")][1]) if domain == \"custom\" else dict(d[\"def\"])\n    if domain == \"entryseq\":\n        defs = dict(_es_defaults(opts.get(\"variant\", \"sms\")))\n    # 终审2/审查2：变体专属参数覆盖必须同步到 defaults，否则面板展示值与引擎实跑不符\n    if domain == \"gcvar\" and opts.get(\"variant\", \"listcolor\") == \"mis\":\n        defs.update(t0=30.0, decay=0.98)  # mis 位串内核口径（与 domain_start 覆盖一致）\n    if domain == \"kpvar\" and opts.get(\"variant\", \"ssp\") == \"mkpm\":\n        defs.update(t0=25.0, decay=0.97)  # mkpm 指派景观口径（与 domain_start 覆盖一致）\n    return json.dumps({\"algos\": out, \"defaults\": defs})\n\n\ndef domain_preset(domain, seed=7, opts=None):\n    # 兼容两种传入：dict（Python 侧测试）或 JSON 字符串（worker 侧，globals.set 只能传标量）\n    if isinstance(opts, str):\n        opts = json.loads(opts) if opts else {}\n    opts = opts or {}\n    if domain in _SCHED_DOMAINS:\n        return _schedmod.sched_preset(domain, seed=seed, opts=opts)\n    if domain == \"custom\":\n        return json.dumps(up_preset(opts.get(\"variant\", \"bits\"), opts.get(\"n\"), seed))\n    if domain == \"knapsack\":\n        return json.dumps(ks_make(n=int(opts.get(\"n\", 40)), seed=seed))\n    if domain == \"continuous\":\n        return json.dumps(cn_make(fn=opts.get(\"fn\", \"rastrigin\"), dim=int(opts.get(\"dim\", 2))))\n    if domain == \"mocont\":\n        return json.dumps(mc_make(variant=opts.get(\"variant\", \"zdt1\"), n=opts.get(\"n\"), seed=seed))\n    if domain == \"multiobj\":\n        return json.dumps(mo_make(variant=opts.get(\"variant\", \"moco\"),\n                                  n=int(opts.get(\"n\", 40)), seed=seed))\n    if domain == \"graphcolor\":\n        return json.dumps(gc_make(n=int(opts.get(\"n\", 50)), seed=seed, p=float(opts.get(\"p\", 0.5))))\n    if domain == \"binpack\":\n        return json.dumps(bp_make(n=int(opts.get(\"n\", 40)), seed=seed))\n    if domain == \"setcover\":\n        return json.dumps(sc_make(n_el=int(opts.get(\"n_el\", 80)), m=int(opts.get(\"m\", 50)), seed=seed))\n    if domain == \"sat\":\n        return json.dumps(sat_make(n_vars=int(opts.get(\"n_vars\", 30)),\n                                   ratio=float(opts.get(\"ratio\", 4.26)), seed=seed))\n    if domain == \"qubo\":\n        return json.dumps(qb_make(n=int(opts.get(\"n\", 30)), seed=seed))\n    if domain == \"gap\":\n        return json.dumps(gap_make(n_a=int(opts.get(\"n_a\", 8)), n_j=int(opts.get(\"n_j\", 25)), seed=seed))\n    if domain == \"uflp\":\n        return json.dumps(uf_make(n_f=int(opts.get(\"n_f\", 15)), n_c=int(opts.get(\"n_c\", 45)), seed=seed))\n    if domain == \"entryseq\":  # 原子词条域：9 变体统一 make\n        return json.dumps(es_make(variant=opts.get(\"variant\", \"vrp\"),\n                                  n=int(opts.get(\"n\", 12)), seed=seed))\n    if domain == \"kpvar\":\n        return json.dumps(kpv_make(variant=opts.get(\"variant\", \"ssp\"),\n                                   n=int(opts.get(\"n\", 40)), seed=seed,\n                                   k=(int(opts[\"k\"]) if opts.get(\"k\") else None),\n                                   r=(int(opts[\"r\"]) if opts.get(\"r\") else None)))\n    if domain == \"gcvar\":\n        return json.dumps(gcv_make(variant=opts.get(\"variant\", \"listcolor\"),\n                                   n=int(opts.get(\"n\", 40)), seed=seed,\n                                   p=float(opts.get(\"p\", 0.5))))\n    if domain == \"bpvar\":\n        return json.dumps(bpv_make(variant=opts.get(\"variant\", \"vsbinpack\"),\n                                   n=int(opts.get(\"n\", 40)), seed=seed))\n    raise ValueError(domain)\n\n\ndef domain_start(domain, problem_json, algo, params_json):\n    if domain in _SCHED_DOMAINS:\n        _RUN[\"domain\"] = domain  # domain_step 据此路由到 scheduling.sched_step\n        return _schedmod.sched_start(domain, problem_json, algo, params_json)\n    d = _DOMAINS[domain]\n    if domain == \"custom\":\n        return _custom_start(problem_json, algo, params_json)\n    if algo not in d[\"algos\"]:\n        raise ValueError(f\"unknown algo {algo} for {domain}\")\n    problem = json.loads(problem_json)\n    if _is_withdrawn(domain, problem.get(\"variant\"), algo):\n        raise ValueError(f\"algo {algo} withdrawn for {domain}/{problem.get('variant') or '-'}（等评价次数下赢不了随机搜索，见 data/withdrawn_cells.json）\")\n    p = dict(d[\"def\"])\n    p.update(json.loads(params_json) if params_json else {})\n    rng = random.Random(p[\"seed\"])\n    if domain == \"knapsack\":\n        ctx = _KS(problem)\n        info = {\"n\": ctx.n, \"cap\": ctx.cap, \"items\": [[w, v] for w, v in ctx.items], \"sense\": \"max\"}\n    elif domain == \"continuous\":\n        ctx = _CN(problem)\n        if problem[\"fn\"] in _NEW_FUNCS:\n            # 后加的函数取值范围和量级差别很大（Schwefel 的范围是 ±500、Zakharov 的值能到 1e5）：\n            # 模拟退火的温度、各算法的步长是按 ±5 的老函数标定的，这里按函数的范围与随机点上的离散程度换算\n            # （用户在算法参数里显式填了的不动）。老函数不走这里，行为与黄金快照保持一致。\n            user_keys = set(json.loads(params_json)) if params_json else set()\n            vals = [ctx.eval(ctx.random(random.Random(97 + i))) for i in range(24)]\n            mu = sum(vals) / len(vals)\n            sd = (sum((v - mu) ** 2 for v in vals) / len(vals)) ** 0.5\n            if \"t0\" not in user_keys and sd > 0:\n                p[\"t0\"] = sd * 0.5\n            if \"sigma\" not in user_keys:\n                p[\"sigma\"] = 0.06 * (ctx.hi - ctx.lo)\n        info = {\"fn\": problem[\"fn\"], \"dim\": ctx.dim, \"lo\": ctx.lo, \"hi\": ctx.hi,\n                \"sense\": \"min\", \"optimum\": FUNCS[problem[\"fn\"]][3]}\n    elif domain == \"mocont\":\n        ctx = MOC(problem)\n        info = {\"variant\": ctx.variant, \"name\": ctx.name, \"n\": ctx.n, \"m\": ctx.m, \"sense\": \"min\",\n                \"ref\": ctx.ref, \"front\": true_front(ctx.variant)}\n    elif domain == \"multiobj\":\n        vt = problem.get(\"variant\", \"moco\")\n        if vt == \"maop\":\n            ctx = _MO3(problem)\n            info = {\"n\": ctx.n, \"cap\": ctx.cap,\n                    \"items\": [[w, v1, v2, v3] for w, v1, v2, v3 in ctx.items],\n                    \"sense\": \"max3\"}\n        else:\n            ctx = _MO(problem)\n            info = {\"n\": ctx.n, \"cap\": ctx.cap, \"items\": [[w, v1, v2] for w, v1, v2 in ctx.items], \"sense\": \"max2\"}\n    elif domain == \"graphcolor\":\n        ctx = _GC(problem)\n        info = {\"n\": ctx.n, \"edges\": problem[\"edges\"], \"pos\": problem[\"pos\"], \"sense\": \"min\"}\n    elif domain == \"binpack\":\n        ctx = _BP(problem)\n        total = sum(ctx.items)\n        info = {\"n\": ctx.n, \"cap\": ctx.cap, \"items\": ctx.items, \"sense\": \"min\",\n                \"lb\": -(-total // ctx.cap)}\n    elif domain == \"entryseq\":  # 原子词条域：变体专属可视化信息\n        ctx = es_ctx(problem)\n        if _es_blocked(problem.get(\"variant\"), algo):  # 算法与该变体的编码不匹配 / 已撤下 → 明确拒绝，不静默乱跑\n            raise ValueError(f\"algo {algo} not available for variant {problem.get('variant')}\")\n        user = json.loads(params_json) if params_json else {}\n        if ctx.bits or ctx.vec:  # 位向量 / 实数向量变体用各自编码的默认参数\n            p = dict(_es_defaults(ctx.variant))\n            if ctx.vec:\n                ctx = _ESVecCN(ctx)\n                vals = [ctx.eval(ctx.random(random.Random(97 + i))) for i in range(24)]\n                mu = sum(vals) / len(vals)\n                sd = (sum((v - mu) ** 2 for v in vals) / len(vals)) ** 0.5\n                ctx.best_val, ctx.best_x = float(\"inf\"), None  # 标定用的随机点不算「找到的最优」\n                if sd > 0:\n                    p[\"t0\"] = sd * 0.5  # 目标量级未知（SSE 上千、设计问题带罚项上万）：温度按随机点的离散程度换算\n            p.update(user)\n            rng = random.Random(p[\"seed\"])\n        info = {\"n\": ctx.n, \"variant\": ctx.variant, \"sense\": \"min\"}\n    elif domain == \"setcover\":\n        ctx = _SC(problem)\n        info = {\"n_el\": ctx.n_el, \"m\": ctx.m, \"sets\": ctx.sets, \"costs\": ctx.costs,\n                \"sense\": \"min\"}\n    elif domain == \"sat\":\n        ctx = _SAT(problem)\n        info = {\"n_vars\": ctx.n, \"clauses\": ctx.clauses, \"sense\": \"min\",\n                \"n_clauses\": len(ctx.clauses)}\n    elif domain == \"qubo\":\n        ctx = _QB(problem)\n        info = {\"n\": ctx.n, \"Q\": ctx.Q, \"sense\": \"min\"}\n    elif domain == \"gap\":\n        ctx = _GAP(problem)\n        info = {\"n_a\": ctx.n_a, \"n_j\": ctx.n_j, \"c\": ctx.c, \"r\": ctx.r,\n                \"cap\": ctx.cap, \"sense\": \"min\"}\n    elif domain == \"uflp\":\n        ctx = _UF(problem)\n        info = {\"n_f\": ctx.n_f, \"n_c\": ctx.n_c, \"f_cost\": ctx.f_cost,\n                \"c_cost\": ctx.c_cost, \"pos_f\": problem[\"pos_f\"],\n                \"pos_c\": problem[\"pos_c\"], \"sense\": \"min\"}\n    elif domain == \"kpvar\":\n        vt = problem.get(\"variant\", \"ssp\")\n        ctx = _MKPM(problem) if vt == \"mkpm\" else (_MCKP(problem) if vt in (\"mckp\", \"dkp\")\n                                                   else _KPV(problem))\n        reg = _kpvar_reg(vt)\n        if algo not in reg:\n            raise ValueError(f\"algo {algo} not available for variant {vt}\")\n        if vt == \"mkpm\":\n            # mkpm 指派景观标定：SA 需要 t0=25/decay=0.97（位编码变体用 0.995）；\n            # 用户显式调 t0/decay 则不覆盖\n            user_keys = set(json.loads(params_json)) if params_json else set()\n            for k, v in ((\"t0\", 25.0), (\"decay\", 0.97)):\n                if k not in user_keys:\n                    p[k] = v\n        if reg[algo][\"fn\"] in _KS_FNS:\n            # _KS 内核是 max-sense + polish 组件：位编码变体走 max 包装器\n            ctx = _KPVMaxWrap(ctx)\n        info = dict(problem, sense=\"min\")\n    elif domain == \"gcvar\":\n        vt = problem.get(\"variant\", \"listcolor\")\n        if vt == \"mis\":\n            ctx = _MIS(problem)\n            reg = _MIS_ALGOS\n            # mis 位串变体用 _BIN_DEF 口径（t0=30/decay=0.98），覆盖 _GC_DEF 的 800/0.985\n            user_keys = set(json.loads(params_json)) if params_json else set()\n            for k, v in ((\"t0\", 30.0), (\"decay\", 0.98)):\n                if k not in user_keys:\n                    p[k] = v\n        else:\n            ctx = _GCV(problem)\n            reg = _GCV_ALGOS\n        if algo not in reg:\n            raise ValueError(f\"algo {algo} not available for variant {vt}\")\n        info = dict(problem, sense=\"min\")\n    elif domain == \"bpvar\":\n        ctx = _BPV(problem)\n        reg = _BPVAR_ALGOS\n        if algo not in reg:\n            raise ValueError(f\"algo {algo} not available for bpvar\")\n        info = dict(problem, sense=\"min\")\n    else:\n        raise ValueError(domain)\n    _RUN[\"domain\"] = domain\n    _RUN[\"ctx\"] = ctx\n    if domain == \"entryseq\":\n        gen = _es_stream(_es_registry(ctx.variant)[algo][\"fn\"](ctx, p, rng), ctx)\n    else:\n        gen = reg[algo][\"fn\"](ctx, p, rng) if domain in (\"kpvar\", \"gcvar\") else d[\"algos\"][algo][\"fn\"](ctx, p, rng)\n    if domain == \"kpvar\" and isinstance(ctx, _KPVMaxWrap):\n        gen = _neg_stream(gen)  # _KS 内核报 max-value；kpvar 全站 min-sense 口径\n    _RUN[\"gen\"] = gen\n    return json.dumps(info)\n\n\ndef _custom_start(problem_json, algo, params_json):\n    \"\"\"自带问题：校验 → 建上下文 → 按编码挑内核 → 把内核的状态流整理成统一口径（sense、完整最优解、出错统计）。\"\"\"\n    problem, errs, _warns, _info = up_check(json.loads(problem_json), dry_runs=6)\n    if problem is None:\n        raise ValueError(\"custom: \" + \"; \".join(e[\"msg\"] for e in errs))\n    reg, defs = _CUSTOM_REG[problem[\"variant\"]]\n    if algo not in reg:\n        raise ValueError(f\"algo {algo} not available for custom/{problem['variant']}\")\n    user = json.loads(params_json) if params_json else {}\n    ctx = up_make_ctx(problem)\n    p = dict(defs)\n    p.update(up_auto_params(ctx, set(user)))  # 温度 / 步长按用户目标函数的量级换算（用户显式给了的不动）\n    p.update(user)\n    rng = random.Random(p[\"seed\"])\n    _RUN[\"domain\"] = \"custom\"\n    _RUN[\"ctx\"] = ctx\n    _RUN[\"gen\"] = up_wrap_stream(reg[algo][\"fn\"](ctx, p, rng), ctx)\n    info = dict(problem)\n    info[\"sense\"] = problem[\"sense\"]\n    info[\"auto_params\"] = {k: v for k, v in p.items() if k in (\"t0\", \"sigma\") and k not in user}\n    return json.dumps(info)\n\n\ndef domain_step():\n    if _RUN.get(\"domain\") in _SCHED_DOMAINS:\n        return _schedmod.sched_step()\n    s = next(_RUN[\"gen\"], None)\n    if s is None:\n        return None\n    return json.dumps(s)\n\n\ndef domain_bench(domain, iters=200, seed=7, algos=None):\n    \"\"\"命令行快速基准：返回 {algo: 终值}，用于页面数据与测试阈值校准。\"\"\"\n    if domain in _SCHED_DOMAINS:\n        return _schedmod.sched_bench(domain, iters=iters, seed=seed, algos=algos)\n    d = _DOMAINS[domain]\n    prob = d[\"make\"](seed=seed)\n    out = {}\n    for key in (algos or list(d[\"algos\"])):\n        info = json.loads(domain_start(domain, json.dumps(prob), key, json.dumps({\"max_iter\": iters, \"seed\": seed})))\n        last = None\n        while True:\n            s = domain_step()\n            if s is None:\n                break\n            last = json.loads(s)\n        out[key] = last[\"best\"] if domain != \"multiobj\" else last[\"nd\"]\n    return out\n\n\nif __name__ == \"__main__\" and __import__(\"sys\").platform != \"emscripten\":\n    # Pyodide/WASM 里 __name__ 也是 \"__main__\"，必须用平台判断挡住，否则浏览器加载时就跑基准\n    for dm in (\"knapsack\", \"continuous\", \"multiobj\", \"graphcolor\", \"binpack\",\n               \"setcover\", \"sat\", \"qubo\", \"gap\", \"uflp\", \"kpvar\"):\n        print(dm, domain_bench(dm))\n\n\n# -*- coding: utf-8 -*-\n\"\"\"排程建模线（批 2 撤下词条 nrp/ttp/sls 重设计）——独立模块，禁止改动 domains.py。\n\n背景：原 entryseq 排列内核把\"人×时\"矩阵硬塞进排列/向量编码，导致 SA=random 恒同值\n（解码与排列无关）。本模块为三问题各建\"指派型\"专业编码，域协议与 domains.py 完全一致：\n    ctx 提供 random(rng) / obj(s) / swap(s,rng) / repair(s) / n；内核 yield {iter,best,cur,best_sol}。\n    注册表 _SCHED_ALGOS（fn/name/category/desc/tune），预设 _SCHED_DEF，问题表 _SCHED_PROBLEMS。\n\n内核复用策略（诚实说明）：\n    - hc/sa/ts/random 四个 _SW 内核只依赖 ctx.swap/repair/obj/random，与编码无关，直接从\n      domains 复用（import 实测 0.06s 无副作用）。\n    - ga/de/gwo/cs 在 domains 里是「二进制交叉 / 取值钳到 [0,n-1]」假设，对整数指派编码失效\n      （护士班次、考试时段、赛程队伍都是分类取值且 repair 语义不同），故本文件自写整数指派版，\n      代码风格与 _sw_* 一致（整数均匀交叉 / 类别差分 / 三狼投票 / 莱维 swap 串），全部只走\n      ctx.swap/repair/obj/random，编码无关。\n\n四个问题的建模选择（软硬约束权重、邻域设计）均在各自 docstring 写清；不美化。\n域名实（2026-09-29 正名）：引擎键 ttp=旅行锦标赛 TTP（Traveling Tournament Problem，\nEaston & Nemhauser 2001）；考试时间表正名为 etp（Exam Timetabling，Kempen 规格）——\n此前引擎键 ttp 实为考试排课，与 problems.json 的 ttp 词条（旅行锦标赛）名实冲突，本版纠正。\n\ndispatch 接口（供主线挂接）：sched_make / sched_preset / sched_start / sched_step / sched_list / sched_bench。\n主线接线说明见文件末尾 __MAIN_HOOK_NOTE__。\n\"\"\"\nimport json\nimport random as _random\n\n# 复用 domains 的编码无关内核（hc/sa/ts/random）；import 仅构建 dict/函数，无重活。\n# 浏览器拼接环境：四内核已在同名字空间（domains 段在前），无需 from-import\n\n\n# ============================================================\n# 通用调度内核（整数指派版：ga/de/gwo/cs）——编码无关，只走 ctx 协议\n# ============================================================\n\ndef _sch_pop(ctx, p, rng):\n    \"\"\"种群组装：n_pop 个 random 可行解。\"\"\"\n    n_pop = p.get(\"n_pop\", 30)\n    pop = [ctx.random(rng) for _ in range(n_pop)]\n    return pop, [ctx.obj(x) for x in pop]\n\n\ndef _sch_ga(ctx, p, rng):\n    \"\"\"整数均匀交叉 GA + 修复 + 半数个体叠一次 swap（memetic）。值取自父代合法值，无越界。\"\"\"\n    pop, vals = _sch_pop(ctx, p, rng)\n    n = ctx.n\n    bi = min(range(len(pop)), key=lambda i: vals[i])\n    best, bs = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        new = [list(pop[bi])]\n        while len(new) < p[\"n_pop\"]:\n            a, b = rng.sample(range(p[\"n_pop\"]), 2)\n            child = [pop[a][k] if rng.random() < 0.5 else pop[b][k] for k in range(n)]\n            child = ctx.repair(child) if getattr(ctx, \"search_repair\", True) else child\n            if rng.random() < 0.5:\n                child = ctx.swap(child, rng)\n            new.append(child)\n        pop = new\n        vals = [ctx.obj(s) for s in pop]\n        bi = min(range(len(pop)), key=lambda i: vals[i])\n        if vals[bi] < best:\n            best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"cur\": min(vals), \"best_sol\": list(bs)}\n\n\ndef _sch_de(ctx, p, rng):\n    \"\"\"类别差分 DE：每个分量以概率 F 取 donor 个体的合法值，再 repair；不假设数值范围。\"\"\"\n    pop, vals = _sch_pop(ctx, p, rng)\n    F = p.get(\"F\", 0.7)\n    n = ctx.n\n    for it in range(1, p[\"max_iter\"] + 1):\n        for i in range(len(pop)):\n            idxs = [j for j in range(len(pop)) if j != i]\n            r1, r2, r3 = rng.sample(idxs, 3)\n            cand = list(pop[i])\n            for k in range(n):\n                if rng.random() < F:\n                    cand[k] = pop[r3][k]\n            cand = ctx.repair(cand) if getattr(ctx, \"search_repair\", True) else cand\n            c = ctx.obj(cand)\n            if c <= vals[i]:\n                pop[i], vals[i] = cand, c\n        bi = min(range(len(pop)), key=lambda i: vals[i])\n        best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bs), \"cur\": sum(vals) / len(vals)}\n\n\ndef _sch_gwo(ctx, p, rng):\n    \"\"\"整数指派灰狼 GWO：三狼投票，每个分量以 0.6 概率取 alpha/beta/delta 的合法值 + repair。\"\"\"\n    pop, vals = _sch_pop(ctx, p, rng)\n    n = ctx.n\n    for it in range(1, p[\"max_iter\"] + 1):\n        order = sorted(range(len(pop)), key=lambda i: vals[i])\n        alpha, beta, delta = pop[order[0]], pop[order[1]], pop[order[2]]\n        for i in range(len(pop)):\n            cand = list(pop[i])\n            for k in range(n):\n                lead = rng.choice([alpha, beta, delta])\n                if rng.random() < 0.6:\n                    cand[k] = lead[k]\n            cand = ctx.repair(cand) if getattr(ctx, \"search_repair\", True) else cand\n            c = ctx.obj(cand)\n            if c <= vals[i]:\n                pop[i], vals[i] = cand, c\n        bi = min(range(len(pop)), key=lambda i: vals[i])\n        best, bs = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bs), \"cur\": sum(vals) / len(vals)}\n\n\ndef _sch_cs(ctx, p, rng):\n    \"\"\"整数指派布谷鸟 CS：莱维 swap 串（≥4 步保底）+ 局部贪心精修 + 弃巢（pa）。\n\n    说明：纯莱维飞行在邻接/对阵这类\"软项主导\"景观上易与随机打平（缺乏局部开发），\n    故每个巢在飞行后叠一段短贪心精修（只接受改进），使其真正优化而非仅采样。\n    \"\"\"\n    pop, vals = _sch_pop(ctx, p, rng)\n    pa = p.get(\"pa\", 0.15)\n    bi = min(range(len(pop)), key=lambda i: vals[i])\n    best, bpos = vals[bi], list(pop[bi])\n    for it in range(1, p[\"max_iter\"] + 1):\n        i = rng.randrange(len(pop))\n        levy = int(rng.paretovariate(1.5))\n        cand = list(pop[i])\n        for _ in range(min(levy + 4, 10)):\n            cand = ctx.swap(cand, rng)\n        cand = ctx.repair(cand) if getattr(ctx, \"search_repair\", True) else cand\n        # 局部贪心精修（best-improvement：每步在 8 个随机 swap 候选里挑最优，≤8 步）\n        for _ in range(8):\n            best_nb, best_v = None, ctx.obj(cand)\n            for _ in range(8):\n                nb = ctx.swap(cand, rng)\n                nb = ctx.repair(nb) if getattr(ctx, \"search_repair\", True) else nb\n                v = ctx.obj(nb)\n                if v < best_v:\n                    best_v, best_nb = v, nb\n            if best_nb is None:\n                break\n            cand = best_nb\n        c = ctx.obj(cand)\n        if c <= vals[i]:\n            pop[i], vals[i] = cand, c\n        wi = max(range(len(pop)), key=lambda i2: vals[i2])\n        if rng.random() < pa:\n            pop[wi] = ctx.random(rng)\n            vals[wi] = ctx.obj(pop[wi])\n        bi = min(range(len(pop)), key=lambda i2: vals[i2])\n        best, bpos = vals[bi], list(pop[bi])\n        yield {\"iter\": it, \"best\": best, \"best_sol\": list(bpos), \"cur\": sum(vals) / len(vals)}\n\n\n# ============================================================\n# 域七之一：护士排班 NRP（Nurse Rostering Problem）\n# ============================================================\ndef nrp_make(N=10, D=7, S=3, seed=7, hard_gap=1000, pref_w=8, consec_w=20):\n    \"\"\"护士×天×班次排班。\n    编码：s[n*D + d] = 班次 ∈ {0..S-1} 工作班次 ∪ {S} 休息（OFF），长度 n = N*D。\n    实例：\n      - 需求 req[d][k]：每天每个工作班次至少需要的护士数；构造保证 Σ_k req[d][k] <= N（可行性前提）。\n      - 偏好 pref[n][d]：约半数 (n,d) 有期望班次 ∈ {0..S-1}（无偏好记为 -1）；偏好违约即惩罚。\n      - 技能分级：本建模不单列技能矩阵，以\"偏好违约\"近似个体差异（诚实简化，见下方目标说明）。\n    目标（min，软硬分层加权）：\n      硬：覆盖缺口——对每个 (d,k) 求 max(0, req[d][k]-实际覆盖)，×hard_gap（主导项，确保 random 明显更差）。\n      软1：偏好违约——pref[n][d]>=0 且分配≠偏好 时 ×pref_w。\n      软2：连班惩罚——护士连续工作 >5 天（无休息）每多 1 天 ×consec_w（鼓励穿插休息）。\n    邻域 swap：随机选一个 (n,d) 改到随机班次（含 OFF）；single-position，SA/HC/TS 直接可用。\n    random：纯随机指派（不过修复，留有覆盖缺口）——作为被碾压的基线。\n    repair：贪心覆盖补位（按缺口最大优先）——遍历找缺口最大的 (d,k)，优先把当天 OFF 护士挪过去，\n           否则从超编班次挪；因 Σreq<=N 必能补到零缺口。\n    \"\"\"\n    if N < S:\n        N = S  # 可行性前提：每天每班至少 1 人可排；页面自定义输入挡不住 N<S，入口规整化\n    rng = _random.Random(seed)\n    OFF = S\n    nshifts = S + 1\n    req = [[0] * nshifts for _ in range(D)]\n    for d in range(D):\n        total = rng.randint(min(7, N), N)  # 7..N（N<7 时收窄为 N..N），保证当天总需求 <= N\n        base = [1] * S\n        rem = total - S\n        for _ in range(rem):\n            base[rng.randrange(S)] += 1\n        rng.shuffle(base)\n        for k in range(S):\n            req[d][k] = base[k]\n    pref = [[-1] * D for _ in range(N)]\n    for n in range(N):\n        for d in range(D):\n            if rng.random() < 0.5:\n                pref[n][d] = rng.randrange(S)\n    return {\"N\": N, \"D\": D, \"S\": S, \"OFF\": OFF, \"nshifts\": nshifts,\n            \"req\": req, \"pref\": pref,\n            \"hard_gap\": hard_gap, \"pref_w\": pref_w, \"consec_w\": consec_w}\n\n\nclass _NRP:\n    def __init__(self, problem):\n        self.N = problem[\"N\"]; self.D = problem[\"D\"]; self.S = problem[\"S\"]\n        self.OFF = problem[\"OFF\"]; self.nshifts = problem[\"nshifts\"]\n        self.req = problem[\"req\"]; self.pref = problem[\"pref\"]\n        self.hard_gap = problem[\"hard_gap\"]; self.pref_w = problem[\"pref_w\"]\n        self.consec_w = problem[\"consec_w\"]\n        self.n = self.N * self.D\n\n    def coverage_gap(self, s):\n        \"\"\"总硬覆盖缺口（可行性断言用）。\"\"\"\n        N, D, S, OFF = self.N, self.D, self.S, self.OFF\n        cnt = [[0] * self.nshifts for _ in range(D)]\n        for n in range(N):\n            for d in range(D):\n                cnt[d][s[n * D + d]] += 1\n        gap = 0\n        for d in range(D):\n            for k in range(S):\n                gap += max(0, self.req[d][k] - cnt[d][k])\n        return gap\n\n    def obj(self, s):\n        pen = self.hard_gap * self.coverage_gap(s)\n        N, D, S, OFF = self.N, self.D, self.S, self.OFF\n        for n in range(N):\n            for d in range(D):\n                p = self.pref[n][d]\n                if p >= 0 and s[n * D + d] != p:\n                    pen += self.pref_w\n        for n in range(N):\n            run = 0\n            for d in range(D):\n                if s[n * D + d] != OFF:\n                    run += 1\n                    if run > 5:\n                        pen += self.consec_w\n                else:\n                    run = 0\n        return pen\n\n    def repair(self, s):\n        s = list(s)\n        N, D, S, OFF = self.N, self.D, self.S, self.OFF\n        for _ in range(N * D):\n            cnt = [[0] * self.nshifts for _ in range(D)]\n            for n in range(N):\n                for d in range(D):\n                    cnt[d][s[n * D + d]] += 1\n            best = None; bestgap = 0\n            for d in range(D):\n                for k in range(S):\n                    g = self.req[d][k] - cnt[d][k]\n                    if g > bestgap:\n                        bestgap = g; best = (d, k)\n            if bestgap <= 0:\n                break\n            d, k = best\n            cand = None\n            for n in range(N):\n                if s[n * D + d] == OFF:\n                    cand = n; break\n            if cand is None:\n                for n in range(N):\n                    sk = s[n * D + d]\n                    if sk != k and cnt[d][sk] > self.req[d][sk]:\n                        cand = n; break\n            if cand is None:\n                break\n            s[cand * D + d] = k\n        return s\n\n    def random(self, rng):\n        return [rng.randrange(self.nshifts) for _ in range(self.n)]\n\n    def swap(self, s, rng):\n        s = list(s)\n        i = rng.randrange(self.n)\n        s[i] = rng.randrange(self.nshifts)\n        return s\n\n\n# ============================================================\n# 域七之二：考试时间表 ETP（Exam Timetabling，Kempen 规格）\n# （2026-09-29 正名：原引擎键 ttp 实为本问题，现键位让给旅行锦标赛，见域八）\n# ============================================================\ndef etp_make(E=30, seed=7, hard_conf=1000, adj_w=12, cap_w=50):\n    \"\"\"考试×学生选课表×时段/教室容量。\n    构造保证存在零硬冲突的 T-着色：先随机生成冲突图 G(E,p)，取 T = 最大度+1 用贪心染出 proper\n    着色（T>=χ(G)），再据每条边造一个\"选这两门\"的学生——故零冲突解必然存在，repair 可达成。\n    编码：s[e] = 时段 ∈ {0..T-1}，长度 n = E。\n    目标（min，软硬分层）：\n      硬：同时段学生冲突——每个学生(=一条边两门)若被分到同段，×hard_conf（主导，random 明显更差）。\n      软：相邻时段同学生（Kempen 规格）——两门时段差为 1 ×adj_w。\n      软：教室容量——某段考试数超过 rooms ×cap_w（rooms 设宽松，通常不饱和）。\n    邻域 swap：随机选一门考试改到随机时段。\n    random：纯随机时段（不过修复，留有冲突）——被碾压基线。\n    repair：冲突驱动重排（图着色式 largest-degree-first 贪心着色为主 + min-conflicts 兜底）。\n    \"\"\"\n    rng = _random.Random(seed)\n    edges = []\n    adj = [set() for _ in range(E)]\n    p = 0.18\n    for a in range(E):\n        for b in range(a + 1, E):\n            if rng.random() < p:\n                edges.append((a, b)); adj[a].add(b); adj[b].add(a)\n    T = max((len(adj[i]) for i in range(E)), default=0) + 1\n    students = [list(e) for e in edges]            # 每学生恰选两门（边）\n    rooms = max(3, T // 2 + 2)\n    return {\"E\": E, \"T\": T, \"edges\": edges,\n            \"adj\": [list(a) for a in adj], \"students\": students, \"rooms\": rooms,\n            \"hard_conf\": hard_conf, \"adj_w\": adj_w, \"cap_w\": cap_w}\n\n\nclass _ETP:\n    def __init__(self, problem):\n        self.E = problem[\"E\"]; self.T = problem[\"T\"]\n        self.adj = problem[\"adj\"]; self.students = problem[\"students\"]\n        self.rooms = problem[\"rooms\"]\n        self.hard_conf = problem[\"hard_conf\"]; self.adj_w = problem[\"adj_w\"]\n        self.cap_w = problem[\"cap_w\"]\n        self.search_repair = False   # 搜索中不调 repair：proper-coloring 会抹掉邻接优化，硬冲突交由 obj 硬罚驱动\n        self.n = self.E\n\n    def n_conflicts(self, s):\n        \"\"\"硬冲突数（可行性断言用）。\"\"\"\n        c = 0\n        for st in self.students:\n            if len(st) == 2 and s[st[0]] == s[st[1]]:\n                c += 1\n        return c\n\n    def _conf_of(self, e, s):\n        c = 0\n        for st in self.students:\n            if len(st) == 2 and e in st:\n                o = st[0] if st[1] == e else st[1]\n                if s[o] == s[e]:\n                    c += 1\n        return c\n\n    def obj(self, s):\n        conf = self.n_conflicts(s)\n        pen = self.hard_conf * conf\n        for st in self.students:\n            slots = sorted(s[e] for e in st)\n            for i in range(len(slots) - 1):\n                if slots[i + 1] - slots[i] == 1:\n                    pen += self.adj_w\n        cnt = [0] * self.T\n        for e in range(self.E):\n            cnt[s[e]] += 1\n        pen += self.cap_w * sum(max(0, c - self.rooms) for c in cnt)\n        return pen\n\n    def repair(self, s):\n        \"\"\"冲突驱动重排：最大度优先贪心 proper 着色（零冲突保证，因 T>=χ）+ min-conflicts 兜底。\"\"\"\n        s = list(s)\n        E, T = self.E, self.T\n        # 1) largest-degree-first 贪心着色（确定性，从当前 s 的最大度考试开始重染）\n        order = sorted(range(E), key=lambda i: -len(self.adj[i]))\n        assigned = {}\n        for v in order:\n            used = {s[u] for u in self.adj[v] if u in assigned}\n            for c in range(T):\n                if c not in used:\n                    s[v] = c; assigned[v] = c; break\n            else:\n                s[v] = T - 1\n        # 2) 兜底：若仍有冲突（理论不发生），min-conflicts 净化\n        for _ in range(E * T * 4):\n            if self.n_conflicts(s) == 0:\n                break\n            conf = [self._conf_of(e, s) for e in range(E)]\n            worst = max(range(E), key=lambda e: conf[e])\n            bestc = None; bestslot = s[worst]\n            for c in range(T):\n                s[worst] = c\n                cc = self._conf_of(worst, s)\n                if bestc is None or cc < bestc:\n                    bestc = cc; bestslot = c\n            s[worst] = bestslot\n        return s\n\n    def random(self, rng):\n        return [rng.randrange(self.T) for _ in range(self.n)]\n\n    def swap(self, s, rng):\n        s = list(s)\n        i = rng.randrange(self.n)\n        j = rng.randrange(self.T)\n        s[i] = j\n        return s\n\n\n# ============================================================\n# 域七之三：赛程生成 SLS（Sports League Scheduling，双循环）\n# ============================================================\ndef sls_make(m=8, seed=7, ha_w=5, consec_w=15, pair_w=50, focus_w=30):\n    \"\"\"偶数队双循环赛程。\n    实例：m 队（偶数），R = 2*(m-1) 轮，每轮 g = m/2 场（主,客）；marquee=焦点队集合（用于焦点战分布）。\n    编码：s 扁平向量，每轮 2*g 个队号（主/客交替），长度 n = R*2*g = R*m。\n          round r 的第 i 场 = (s[r*per+2i], s[r*per+2i+1])，前者主、后者客。\n    可行性定义（\"轮次完整\"）：每个轮次 2*g 个队号恰好是 {0..m-1} 各一次——即每轮为完美匹配，\n          每队每轮恰赛一场。该性质由编码结构（repair 负责）保证；交叉轮的对阵完整性(每对恰遇2次)\n          作为软目标 pair_w 引导（严格 DRR 完整性见 docstring 诚实说明）。\n    目标（min，全软，主客场/连主连客/焦点战均为软约束——与任务描述一致）：\n      - 主客场平衡：每队 |主场次-客场次| ×ha_w（理想各 R/2）。\n      - 连主/连客：每队连续同场地 >=3 场，每多 1 场 ×consec_w。\n      - 对阵完整：每无序对出现次数与 2 的偏差 ×pair_w（双循环应恰 2 次；主导可分化项）。\n      - 焦点战分布：同轮出现 >=2 场\"双方皆焦点队\"的对阵 ×focus_w（避免焦点战扎堆）。\n    邻域 swap：随机选一轮，轮内交换两个队号（保持该轮仍为排列 → 始终可行）。\n    random：随机可行轮（每轮随机排列 → 轮次完整，但对阵/连主分布差）——被碾压基线。\n    repair：轮内交换恢复可行——把每轮重复队号换为缺失队号，保证 {0..m-1} 各一次（轮次完整）。\n    \"\"\"\n    if m % 2 != 0:\n        m += 1  # 双循环需偶数队（每轮 g=m/2 场恰覆盖 m 队）；页面自定义输入挡不住奇数，入口规整化\n    rng = _random.Random(seed)\n    R = 2 * (m - 1)\n    g = m // 2\n    marquee = [0, 1, 2] if m >= 3 else [0, 1]\n    return {\"m\": m, \"R\": R, \"g\": g, \"per\": 2 * g, \"marquee\": marquee,\n            \"ha_w\": ha_w, \"consec_w\": consec_w, \"pair_w\": pair_w, \"focus_w\": focus_w}\n\n\nclass _SLS:\n    def __init__(self, problem):\n        self.m = problem[\"m\"]; self.R = problem[\"R\"]; self.g = problem[\"g\"]\n        self.per = problem[\"per\"]; self.marquee = set(problem[\"marquee\"])\n        self.ha_w = problem[\"ha_w\"]; self.consec_w = problem[\"consec_w\"]\n        self.pair_w = problem[\"pair_w\"]; self.focus_w = problem[\"focus_w\"]\n        self.n = self.R * self.per\n\n    def rounds_complete(self, s):\n        \"\"\"每轮是否恰含 {0..m-1} 各一次（可行性断言用）；返回不满足的轮数。\"\"\"\n        bad = 0\n        for r in range(self.R):\n            base = r * self.per\n            if sorted(s[base:base + self.per]) != list(range(self.m)):\n                bad += 1\n        return bad\n\n    def obj(self, s):\n        m, g, R, per = self.m, self.g, self.R, self.per\n        home = [0] * m; away = [0] * m\n        venue = [[-1] * R for _ in range(m)]\n        paircnt = {}\n        for r in range(R):\n            base = r * per\n            for i in range(g):\n                h = s[base + 2 * i]; a = s[base + 2 * i + 1]\n                home[h] += 1; away[a] += 1\n                venue[h][r] = 0; venue[a][r] = 1\n                key = (h, a) if h < a else (a, h)\n                paircnt[key] = paircnt.get(key, 0) + 1\n        pen = 0\n        for t in range(m):\n            pen += self.ha_w * abs(home[t] - away[t])\n        for t in range(m):\n            run = 1\n            for r in range(1, R):\n                if venue[t][r] == venue[t][r - 1] and venue[t][r] != -1:\n                    run += 1\n                    if run > 2:\n                        pen += self.consec_w\n                else:\n                    run = 1\n        for a in range(m):\n            for b in range(a + 1, m):\n                c = paircnt.get((a, b), 0)\n                pen += self.pair_w * abs(c - 2)\n        for r in range(R):\n            base = r * per\n            inround = set()\n            for i in range(g):\n                h = s[base + 2 * i]; a = s[base + 2 * i + 1]\n                if h in self.marquee and a in self.marquee:\n                    inround.add((h, a) if h < a else (a, h))\n            if len(inround) >= 2:\n                pen += self.focus_w * (len(inround) - 1)\n        return pen\n\n    def repair(self, s):\n        \"\"\"轮内交换恢复可行：每轮重复队号换为缺失队号，使 {0..m-1} 各一次。\"\"\"\n        import collections\n        s = list(s)\n        m, g, per = self.m, self.g, self.per\n        for r in range(self.R):\n            base = r * per\n            L = s[base:base + per]\n            cnt = collections.Counter(L)\n            missing = [t for t in range(m) if cnt[t] == 0]\n            mi = 0\n            for pos in range(per):\n                t = L[pos]\n                if cnt[t] > 1:\n                    cnt[t] -= 1\n                    L[pos] = missing[mi]; mi += 1\n            s[base:base + per] = L\n        return s\n\n    def random(self, rng):\n        out = []\n        for _ in range(self.R):\n            row = list(range(self.m))\n            rng.shuffle(row)\n            out.extend(row)\n        return out\n\n    def swap(self, s, rng):\n        s = list(s)\n        r = rng.randrange(self.R)\n        base = r * self.per\n        i = rng.randrange(self.per)\n        j = rng.randrange(self.per)\n        s[base + i], s[base + j] = s[base + j], s[base + i]\n        return s\n\n\n# ============================================================\n# 域八：旅行锦标赛 TTP（Traveling Tournament Problem，Easton & Nemhauser 2001）\n# ============================================================\ndef tour_make(m=8, seed=7, pair_w=500, streak_w=6, repeat_w=12):\n    \"\"\"m 队双循环巡回赛：赛程×城市地理耦合，最小化总旅行距离。\n    实例：m 队（偶数，奇数入口规整化 +1），每队一个主城（100×100 网格确定性撒点，seed 复现）；\n          R = 2(m-1) 轮、每轮 g = m/2 场；dist 为取整欧氏距离阵。\n    编码：与 sls 同构扁平向量——round r 第 i 场 = (s[r*per+2i], s[r*per+2i+1])，前者主队；\n          长度 n = R*per = R*m。每轮为 {0..m-1} 排列（完美匹配），由 repair 保证。\n    目标（min，分层加权）：\n      主导：对阵完整——每无序对出现次数与 2 的偏差 ×pair_w（严格 DRR 应恰 2 次）。\n            诚实说明：与 sls 同款软罚松弛；文献 TTP 把 DRR 完整性定为硬约束，本建模以\n            pair_w=500 主导权重近似（引擎面向教学演示，松弛后 8 内核可复用、邻域保持可行）。\n      旅行：每队从主城出发按轮次访问客场比赛城市、赛毕回主城的行程距离和（原始距离，无权重）。\n      连场：连续主/客 >3 场每多 1 场 ×streak_w（TTP 经典 at-most-3 约束软罚）。\n      重复对阵：相邻两轮出现同对（任一方向）×repeat_w（经典 no-repeat 软罚）。\n    邻域 swap：随机选一轮轮内交换两个队号（保持轮次完整，与 sls 同款）。\n    random：随机可行轮——轮次完整但对阵/地理全乱，被 pair_w 主导碾压。\n    repair：轮内交换恢复排列（与 sls 同款）。\n    \"\"\"\n    if m % 2 != 0:\n        m += 1  # 双循环需偶数队；页面自定义输入挡不住奇数，入口规整化\n    if m < 4:\n        m = 4   # 下限：至少 4 队才有锦标赛结构\n    rng = _random.Random(seed)\n    R = 2 * (m - 1)\n    g = m // 2\n    pts = [[rng.randint(0, 100), rng.randint(0, 100)] for _ in range(m)]\n    dist = [[0] * m for _ in range(m)]\n    for a in range(m):\n        for b in range(a + 1, m):\n            d = int(round(((pts[a][0] - pts[b][0]) ** 2 + (pts[a][1] - pts[b][1]) ** 2) ** 0.5))\n            dist[a][b] = d\n            dist[b][a] = d\n    return {\"m\": m, \"R\": R, \"g\": g, \"per\": 2 * g, \"pts\": pts, \"dist\": dist,\n            \"pair_w\": pair_w, \"streak_w\": streak_w, \"repeat_w\": repeat_w}\n\n\nclass _TOUR:\n    def __init__(self, problem):\n        self.m = problem[\"m\"]; self.R = problem[\"R\"]; self.g = problem[\"g\"]\n        self.per = problem[\"per\"]\n        self.dist = problem[\"dist\"]; self.pts = problem.get(\"pts\", [])\n        self.pair_w = problem[\"pair_w\"]; self.streak_w = problem[\"streak_w\"]\n        self.repeat_w = problem[\"repeat_w\"]\n        self.n = self.R * self.per\n\n    def rounds_complete(self, s):\n        \"\"\"每轮是否恰含 {0..m-1} 各一次（可行性断言用）；返回不满足的轮数。\"\"\"\n        bad = 0\n        for r in range(self.R):\n            base = r * self.per\n            if sorted(s[base:base + self.per]) != list(range(self.m)):\n                bad += 1\n        return bad\n\n    def _games(self, s):\n        \"\"\"展开为 [(r, h, a), ...]（h 主 a 客）。\"\"\"\n        out = []\n        for r in range(self.R):\n            base = r * self.per\n            for i in range(self.g):\n                out.append((r, s[base + 2 * i], s[base + 2 * i + 1]))\n        return out\n\n    def obj(self, s):\n        m, R, per = self.m, self.R, self.per\n        # 主导：对阵完整\n        paircnt = {}\n        venue = [[-1] * R for _ in range(m)]   # 0=主场 1=客场\n        oppo = [[-1] * R for _ in range(m)]\n        for r in range(R):\n            base = r * per\n            for i in range(self.g):\n                h = s[base + 2 * i]; a = s[base + 2 * i + 1]\n                key = (h, a) if h < a else (a, h)\n                paircnt[key] = paircnt.get(key, 0) + 1\n                venue[h][r] = 0; venue[a][r] = 1\n                oppo[h][r] = a; oppo[a][r] = h\n        pen = 0\n        for a in range(m):\n            for b in range(a + 1, m):\n                pen += self.pair_w * abs(paircnt.get((a, b), 0) - 2)\n        # 旅行：每队按轮次走访问客城市（每轮必有比赛），赛毕回主城\n        for t in range(m):\n            cur = t\n            for r in range(R):\n                o = oppo[t][r]\n                nxt = cur if venue[t][r] == 0 else o   # 主场不出门，客场去对方城市\n                pen += self.dist[cur][nxt]\n                cur = nxt\n            pen += self.dist[cur][t]\n        # 连主/连客 >3\n        for t in range(m):\n            run = 1\n            for r in range(1, R):\n                if venue[t][r] == venue[t][r - 1]:\n                    run += 1\n                    if run > 3:\n                        pen += self.streak_w\n                else:\n                    run = 1\n        # 重复对阵：相邻轮同对（任一方向）\n        for r in range(R - 1):\n            base = r * per\n            seen = set()\n            for i in range(self.g):\n                a = s[base + 2 * i]; b = s[base + 2 * i + 1]\n                seen.add((a, b) if a < b else (b, a))\n            base2 = base + per\n            for i in range(self.g):\n                a = s[base2 + 2 * i]; b = s[base2 + 2 * i + 1]\n                if (a, b) in seen or (b, a) in seen:\n                    pen += self.repeat_w\n        return pen\n\n    def repair(self, s):\n        \"\"\"轮内交换恢复可行：每轮重复队号换为缺失队号（与 sls 同款）。\"\"\"\n        import collections\n        s = list(s)\n        m, g, per = self.m, self.g, self.per\n        for r in range(self.R):\n            base = r * per\n            L = s[base:base + per]\n            cnt = collections.Counter(L)\n            missing = [t for t in range(m) if cnt[t] == 0]\n            mi = 0\n            for pos in range(per):\n                t = L[pos]\n                if cnt[t] > 1:\n                    cnt[t] -= 1\n                    L[pos] = missing[mi]; mi += 1\n            s[base:base + per] = L\n        return s\n\n    def random(self, rng):\n        out = []\n        for _ in range(self.R):\n            row = list(range(self.m))\n            rng.shuffle(row)\n            out.extend(row)\n        return out\n\n    def swap(self, s, rng):\n        s = list(s)\n        r = rng.randrange(self.R)\n        base = r * self.per\n        i = rng.randrange(self.per)\n        j = rng.randrange(self.per)\n        s[base + i], s[base + j] = s[base + j], s[base + i]\n        return s\n\n\n# ============================================================\n# 注册表 / 预设 / 问题表（与 domains.py 惯例一致）\n# ============================================================\n_SCHED_ALGOS = {\n    \"random\": {\"fn\": _sw_random, \"name\": \"随机搜索\", \"category\": \"基线\",\n               \"desc\": \"盲采样基线：一切算法都要显著降低目标\", \"tune\": []},\n    \"hc\": {\"fn\": _sw_hc, \"name\": \"爬山法 HC\", \"category\": \"局部搜索\",\n           \"desc\": \"交换邻域单点贪心 + 停滞重启\", \"tune\": [\"tries\"]},\n    \"sa\": {\"fn\": _sw_sa, \"name\": \"模拟退火 SA\", \"category\": \"物理启发\",\n           \"desc\": \"交换移动 + Metropolis + 卡死重启\", \"tune\": [\"t0\", \"decay\"]},\n    \"ts\": {\"fn\": _sw_ts, \"name\": \"禁忌搜索 TS\", \"category\": \"局部搜索\",\n           \"desc\": \"交换禁忌表 + 采样邻域 + 特赦\", \"tune\": [\"tenure\"]},\n    \"ga\": {\"fn\": _sch_ga, \"name\": \"遗传 GA\", \"category\": \"进化计算\",\n           \"desc\": \"整数均匀交叉 + 修复 + 叠交换(memetic)\", \"tune\": [\"pm\"]},\n    \"de\": {\"fn\": _sch_de, \"name\": \"差分 DE\", \"category\": \"进化计算\",\n           \"desc\": \"类别差分：随 F 取 donor 合法值 + 修复\", \"tune\": [\"F\"]},\n    \"gwo\": {\"fn\": _sch_gwo, \"name\": \"灰狼 GWO\", \"category\": \"群体智能\",\n            \"desc\": \"三狼指派投票（整数自适应）\", \"tune\": []},\n    \"cs\": {\"fn\": _sch_cs, \"name\": \"布谷鸟 CS\", \"category\": \"群体智能\",\n           \"desc\": \"莱维 swap 串 + 弃巢\", \"tune\": [\"pa\"]},\n}\n\n# 共享参数口径（沿用 _BIN_DEF 风格；t0/decay 对覆盖/冲突主导项已标定可降温）\n_SCHED_DEF = {\"n_pop\": 30, \"pm\": 0.04, \"t0\": 30.0, \"decay\": 0.98, \"tries\": 20,\n              \"tenure\": 8, \"ts_sample\": 40, \"restart_at\": 25, \"max_iter\": 200,\n              \"seed\": 7, \"F\": 0.7, \"pa\": 0.25, \"limit\": 12}\n\n_SCHED_PROBLEMS = {\n    \"nrp\": {\"make\": nrp_make, \"name\": \"护士排班 NRP\", \"category\": \"排程\",\n            \"desc\": \"护士×天×班次指派；覆盖缺口(硬)+偏好违约+连班(软)\",\n            \"ctx\": _NRP, \"def\": dict(_SCHED_DEF)},\n    \"etp\": {\"make\": etp_make, \"name\": \"考试时间表 ETP\", \"category\": \"排程\",\n            \"desc\": \"考试→时段指派；同时段冲突(硬,Kempen)+相邻段(软)\",\n            \"ctx\": _ETP, \"def\": dict(_SCHED_DEF)},\n    \"ttp\": {\"make\": tour_make, \"name\": \"旅行锦标赛 TTP\", \"category\": \"排程\",\n            \"desc\": \"双循环赛程×城市地理；总旅行距离+对阵完整(主导)+连场/重复(软)\",\n            \"ctx\": _TOUR, \"def\": dict(_SCHED_DEF)},\n    \"sls\": {\"make\": sls_make, \"name\": \"赛程生成 SLS\", \"category\": \"排程\",\n            \"desc\": \"轮次排列指派；主客场平衡+连主连客+焦点战分布(软)\",\n            \"ctx\": _SLS, \"def\": dict(_SCHED_DEF)},\n}\n\n\n# ============================================================\n# 调度线 dispatch（供主线在 domains.py 内挂接的镜像接口）\n# ============================================================\n_SCHED_RUN = {\"gen\": None, \"ctx\": None, \"problem\": None}\n\n\ndef sched_make(problem, **kw):\n    return _SCHED_PROBLEMS[problem][\"make\"](**kw)\n\n\ndef sched_preset(problem, seed=7, opts=None):\n    if isinstance(opts, str):\n        opts = json.loads(opts) if opts else {}\n    opts = opts or {}\n    return json.dumps(sched_make(problem, seed=seed, **opts))\n\n\ndef sched_start(problem, problem_json, algo, params_json):\n    d = _SCHED_PROBLEMS[problem]\n    if algo not in _SCHED_ALGOS:\n        raise ValueError(f\"unknown algo {algo} for {problem}\")\n    prob = json.loads(problem_json)\n    p = dict(d[\"def\"])\n    p.update(json.loads(params_json) if params_json else {})\n    rng = _random.Random(p[\"seed\"])\n    ctx = d[\"ctx\"](prob)\n    info = {\"problem\": problem, \"sense\": \"min\",\n            \"n\": ctx.n,\n            \"inst\": {k: prob[k] for k in\n                     (\"N\", \"D\", \"S\", \"E\", \"T\", \"m\", \"R\", \"g\") if k in prob}}\n    gen = _SCHED_ALGOS[algo][\"fn\"](ctx, p, rng)\n    _SCHED_RUN[\"gen\"] = gen; _SCHED_RUN[\"ctx\"] = ctx; _SCHED_RUN[\"problem\"] = problem\n    return json.dumps(info)\n\n\ndef sched_step():\n    s = next(_SCHED_RUN[\"gen\"], None)\n    if s is None:\n        return None\n    return json.dumps(s)\n\n\ndef sched_list(problem):\n    out = []\n    for k, a in _SCHED_ALGOS.items():\n        out.append({\"key\": k, \"name\": a[\"name\"], \"category\": a[\"category\"],\n                    \"desc\": a[\"desc\"], \"tune\": a[\"tune\"]})\n    return json.dumps({\"algos\": out, \"defaults\": dict(_SCHED_PROBLEMS[problem][\"def\"])})\n\n\ndef sched_bench(problem, iters=200, seed=7, algos=None):\n    \"\"\"命令行/测试快速基准：返回 {algo: 终值}。\"\"\"\n    prob = sched_make(problem, seed=seed)\n    out = {}\n    for key in (algos or list(_SCHED_ALGOS)):\n        sched_start(problem, json.dumps(prob), key,\n                    json.dumps({\"max_iter\": iters, \"seed\": seed}))\n        last = None\n        while True:\n            s = sched_step()\n            if s is None:\n                break\n            last = json.loads(s)\n        out[key] = last[\"best\"]\n    return out\n\n\n__MAIN_HOOK_NOTE__ = \"\"\"\n主线接线说明（供 domains.py 维护者）：\n  1) 顶部 import：在 domains.py 加  `import scheduling`（建议放到批 7 续写段之后）；\n  2) _DOMAINS 挂接：新增四项\n       \"nrp\":  {\"algos\": scheduling._SCHED_ALGOS, \"def\": scheduling._SCHED_DEF, \"make\": scheduling.nrp_make},\n       \"etp\":  {\"algos\": scheduling._SCHED_ALGOS, \"def\": scheduling._SCHED_DEF, \"make\": scheduling.etp_make},\n       \"ttp\":  {\"algos\": scheduling._SCHED_ALGOS, \"def\": scheduling._SCHED_DEF, \"make\": scheduling.tour_make},\n       \"sls\":  {\"algos\": scheduling._SCHED_ALGOS, \"def\": scheduling._SCHED_DEF, \"make\": scheduling.sls_make},\n     （四门共用同一 _SCHED_ALGOS 内核集；若以后要 per-variant 算法集，改 _SCHED_PROBLEMS 即可。）\n  3) domain_start 分发分支：在 domain_start 的 if-elif 链末尾加\n       elif domain in (\"nrp\", \"etp\", \"ttp\", \"sls\"):\n           ctx = _SCHED_PROBLEMS[domain][\"ctx\"](problem)\n           info = {\"problem\": domain, \"sense\": \"min\", \"n\": ctx.n,\n                   \"inst\": {k: problem[k] for k in (\"N\",\"D\",\"S\",\"E\",\"T\",\"m\",\"R\",\"g\") if k in problem}}\n           gen = _SCHED_ALGOS[algo][\"fn\"](ctx, p, rng)\n     或更直接：令 domain_start 对这三域 `from scheduling import sched_start as _sched_start; return _sched_start(...)`。\n     注意 domain_start 已统一用 d[\"algos\"][algo][\"fn\"](ctx,p,rng)，本模块 ctx 协议一致，直接复用即可，\n     无需改 step（domain_step 仍读 _SCHED_RUN[\"gen\"]——但本模块用自有 _SCHED_RUN；若合并需统一 _SCHED_RUN 命名空间，\n     建议主线调用 scheduling.sched_start / scheduling.sched_step 而非复用 domain_*）。\n  4) domain_list / domain_preset：加对应分支转发到 scheduling.sched_list / scheduling.sched_preset；\n     domain_bench 同理可转发。\n  5) 页面侧 pages_domains.py / build_pages.py / data/** 本次未触碰（任务禁令），需主线另接词条↔域映射。\n     （2026-09-29 主线已完成接线：domains.py 六分发分支 + wire 块；同日正名后词条挂载=\n       nrp→nrp / etp→etp / ttp(旅行锦标赛)→ttp / sls→sls，problems.json 的 ttp 词条不再空挂。）\n\"\"\"\n\n\n# B 序循环导入回挂（2026-09-29 集成期修复）：\n#   A 序（先 import domains）：domains wire 块 import scheduling → 本模块加载，此处 sys.modules\n#     已有半加载 domains（_wire_sched_domains 已定义于 wire 块前）→ 回挂成功；随后 domains\n#     wire 块尾部的 _wire_sched_domains(_schedmod) 再挂一次（幂等，无害）。\n#   B 序（先 import scheduling）：本模块第 26 行 from domains import → domains 执行到 wire 块\n#     时本模块仍半加载，domains 侧 hasattr 防御 fail-soft 跳过；本模块加载完成后在此回挂。\n#   浏览器拼接环境：本模块源码与 domains 同名字空间 exec，sys.modules 无 \"domains\" → 跳过，\n#     由 gen_domains_src 注入的 _schedmod 显式装配负责挂接。\nimport sys as _sys\n\n_dm = _sys.modules.get(\"domains\")\nif _dm is not None and hasattr(_dm, \"_wire_sched_domains\"):\n    _dm._wire_sched_domains(_sys.modules[__name__])\n\n\n# 浏览器（Pyodide）里源码以 __main__ 身份拼接执行，必须用平台判断挡住，否则每次页面加载都会跑一遍自测\nif __name__ == \"__main__\" and __import__(\"sys\").platform != \"emscripten\":\n    for pr in (\"nrp\", \"etp\", \"ttp\", \"sls\"):\n        print(pr, sched_bench(pr))\n\n\n# --- 浏览器拼接环境排程装配（与 domains 末尾 try-import 等价）---\nimport types as _types_mod\n_schedmod = _types_mod.SimpleNamespace(\n    _SCHED_ALGOS=_SCHED_ALGOS, _SCHED_DEF=_SCHED_DEF,\n    nrp_make=nrp_make, etp_make=etp_make, tour_make=tour_make, sls_make=sls_make,\n    sched_start=sched_start, sched_step=sched_step, sched_list=sched_list,\n    sched_preset=sched_preset, sched_bench=sched_bench)\n_wire_sched_domains(_schedmod)\n\n\n# --- 浏览器拼接环境别名绑定（与 try-import 分支等价；本地重复赋值无害）---\n_pm_insert = pm_insert; _pm_ox = pm_ox; _pm_polish = pm_polish; _pm_swap = pm_swap\n";
export const VALIDATE_SRC = "# -*- coding: utf-8 -*-\n\"\"\"\n标准化数据层：把「用户上传的数据」变成「引擎能放心吃的实例」。\n\n三件事：\n  1. 校验：给出带路径的中文错误（\"items[3][0]：重量必须大于 0\"），而不是 IndexError；\n  2. 规整：n / m / K 等冗余字段由数据推出（用户不用再手写，也不会写错）；绘图坐标缺省自动布局；\n  3. 解析：JSON 信封、CSV（背包/装箱/图/QUBO）、DIMACS（.cnf 可满足性 / .col 图着色）。\n\n纯标准库，浏览器（Pyodide）与本地 Python 共用同一份。\n\n入口：\n    load(text_or_obj, domain=None, filename=None) -> (domain, data, issues)\n    validate(domain, data, variant=None, dry_run=False) -> Result\n    Result = {\"ok\": bool, \"errors\": [...], \"warnings\": [...], \"problem\": dict|None}\n    每条问题 = {\"path\": \"items[3][0]\", \"msg\": \"...\"}\n\n信封格式（swarm-problem/v1）：\n    {\"schema\": \"swarm-problem/v1\", \"domain\": \"knapsack\", \"data\": {...}}\n    裸实例（不带信封）+ 显式 domain 参数也可；页面导出的 domain-experiment/v1 同样接受。\n\"\"\"\nimport csv\nimport io\nimport json\nimport math\nimport re\n\nSCHEMA = \"swarm-problem/v1\"\nRESULT_SCHEMA = \"swarm-result/v1\"  # 求解结果；里面带完整实例，所以也可以当作「问题文件」重新导入\n\n# 支持上传的域。排程四域（etp/nrp/sls/ttp）暂不开放上传。\nCORE_DOMAINS = (\"tsp\", \"knapsack\", \"kpvar\", \"multiobj\", \"binpack\", \"bpvar\", \"graphcolor\", \"gcvar\",\n                \"setcover\", \"sat\", \"qubo\", \"gap\", \"uflp\", \"continuous\", \"entryseq\", \"custom\", \"mocont\")\n\n# 规模上限：Pyodide 在浏览器里跑，过大实例会卡死标签页\nLIMITS = {\n    \"tsp\": 500, \"knapsack\": 1000, \"kpvar\": 1000, \"multiobj\": 1000, \"binpack\": 1000, \"bpvar\": 500,\n    \"graph_nodes\": 500, \"graph_edges\": 50000, \"setcover_cells\": 250000, \"sat_vars\": 1000,\n    \"sat_clauses\": 10000, \"qubo\": 200, \"gap_agents\": 50, \"gap_jobs\": 500, \"uflp_f\": 100,\n    \"uflp_c\": 1000, \"continuous_dim\": 100, \"entryseq\": 300,\n}\n\n\n# ------------------------------------------------------------------ 引擎定位\n\ndef _engine():\n    \"\"\"问题域引擎模块。本地/测试里是 `import domains`；浏览器（Pyodide）里引擎源码以 __main__ 身份拼接执行，\n    没有名为 domains 的模块，此时从 __main__ 取同一批函数（domain_preset / FUNCS / _DOMAINS …）。\"\"\"\n    try:\n        import domains\n        return domains\n    except ImportError:\n        import sys\n        m = sys.modules.get(\"__main__\")\n        if m is not None and hasattr(m, \"domain_preset\"):\n            return m\n        raise\n\n\n# ------------------------------------------------------------------ 工具\n\nclass _R:\n    def __init__(self):\n        self.errors = []\n        self.warnings = []\n\n    def err(self, path, msg):\n        self.errors.append({\"path\": path, \"msg\": msg})\n\n    def warn(self, path, msg):\n        self.warnings.append({\"path\": path, \"msg\": msg})\n\n\ndef _show(x):\n    s = json.dumps(x, ensure_ascii=False) if not isinstance(x, str) else repr(x)\n    return s if len(s) <= 40 else s[:37] + \"…\"\n\n\ndef _isnum(x):\n    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)\n\n\ndef _int(R, path, x, lo=None, hi=None, what=\"整数\"):\n    if isinstance(x, float) and math.isfinite(x) and x.is_integer():\n        x = int(x)\n    if not isinstance(x, int) or isinstance(x, bool):\n        R.err(path, f\"应为{what}，收到 {_show(x)}\")\n        return None\n    if lo is not None and x < lo:\n        R.err(path, f\"应 ≥ {lo}，收到 {x}\")\n        return None\n    if hi is not None and x > hi:\n        R.err(path, f\"应 ≤ {hi}，收到 {x}\")\n        return None\n    return x\n\n\ndef _num(R, path, x, lo=None, hi=None, positive=False, what=\"数字\"):\n    if not _isnum(x):\n        R.err(path, f\"应为{what}，收到 {_show(x)}\")\n        return None\n    if positive and x <= 0:\n        R.err(path, f\"必须大于 0，收到 {x}\")\n        return None\n    if lo is not None and x < lo:\n        R.err(path, f\"应 ≥ {lo}，收到 {x}\")\n        return None\n    if hi is not None and x > hi:\n        R.err(path, f\"应 ≤ {hi}，收到 {x}\")\n        return None\n    return x\n\n\ndef _list(R, path, x, min_len=1, max_len=None, what=\"列表\"):\n    if not isinstance(x, list):\n        R.err(path, f\"应为{what}（JSON 数组），收到 {_show(x)}\")\n        return None\n    if len(x) < min_len:\n        R.err(path, f\"{what}至少需要 {min_len} 项，收到 {len(x)} 项\")\n        return None\n    if max_len is not None and len(x) > max_len:\n        R.err(path, f\"{what}最多 {max_len} 项（浏览器内运行的规模上限），收到 {len(x)} 项\")\n        return None\n    return x\n\n\ndef _need(R, p, key, alias=()):\n    for k in (key,) + tuple(alias):\n        if k in p:\n            return p[k]\n    R.err(key, f\"缺少必填字段 '{key}'\")\n    return None\n\n\ndef _num_vec(R, path, x, length=None, **kw):\n    \"\"\"数值向量；kw 透传 _num。返回新列表或 None。\"\"\"\n    xs = _list(R, path, x, what=\"数组\")\n    if xs is None:\n        return None\n    if length is not None and len(xs) != length:\n        R.err(path, f\"长度应为 {length}，收到 {len(xs)}\")\n        return None\n    out = []\n    ok = True\n    for i, v in enumerate(xs):\n        c = _num(R, f\"{path}[{i}]\", v, **kw)\n        ok &= c is not None\n        out.append(c)\n    return out if ok else None\n\n\ndef _matrix(R, path, x, rows=None, cols=None, **kw):\n    \"\"\"矩形数值矩阵。返回新的二维列表或 None。\"\"\"\n    xs = _list(R, path, x, what=\"矩阵\")\n    if xs is None:\n        return None\n    if rows is not None and len(xs) != rows:\n        R.err(path, f\"行数应为 {rows}，收到 {len(xs)}\")\n        return None\n    out = []\n    width = cols\n    ok = True\n    for i, row in enumerate(xs):\n        r = _list(R, f\"{path}[{i}]\", row, what=\"行\")\n        if r is None:\n            ok = False\n            continue\n        if width is None:\n            width = len(r)\n        elif len(r) != width:\n            R.err(f\"{path}[{i}]\", f\"每行长度必须一致：第 0 行 {width} 列，本行 {len(r)} 列\")\n            ok = False\n            continue\n        vec = []\n        for j, v in enumerate(r):\n            c = _num(R, f\"{path}[{i}][{j}]\", v, **kw)\n            ok &= c is not None\n            vec.append(c)\n        out.append(vec)\n    return out if ok else None\n\n\ndef _circle_layout(n):\n    return [[round(50 + 42 * math.cos(2 * math.pi * i / max(n, 1)), 1),\n             round(50 + 42 * math.sin(2 * math.pi * i / max(n, 1)), 1)] for i in range(n)]\n\n\ndef _pos_or_layout(R, p, key, n):\n    \"\"\"可选的绘图坐标：给了就校验，没给就环形布局（只影响画面，不影响求解）。\"\"\"\n    if key in p and p[key] is not None:\n        return _matrix(R, key, p[key], rows=n, cols=2)\n    return _circle_layout(n)\n\n\n# ------------------------------------------------------------------ 各域校验（核心域）\n\nTSP_METRICS = (\"EUC_2D\", \"CEIL_2D\", \"ATT\", \"GEO\", \"MAN_2D\", \"MAX_2D\")\nTSP_MIN = 4  # 3 城市只有一条回路（正反向同长），无需求解，部分算子也要求至少 4 个不同位置\n_ATSP_MSG = (\"距离不对称（A→B 与 B→A 不同）：这是非对称 TSP（ATSP）。TSP 演示页的算法用了 2-opt / OX 等默认距离对称的算子，\"\n             \"用在非对称数据上会得出错误结果，所以这里拒绝导入——请到「问题 ▸ 非对称旅行商 ATSP」页导入\"\n             \"（那里的算法每次重新计算整条回路的代价，不依赖对称性；也能直接读 TSPLIB 的 .atsp 文件）\")\n\n\ndef _tsp_matrix(R, path, mat, n_max):\n    \"\"\"显式距离矩阵：方阵、非负、零对角、对称。返回规整后的 float 矩阵或 None。\"\"\"\n    m = _matrix(R, path, mat, lo=0)\n    if m is None:\n        return None\n    n = len(m)\n    if n != len(m[0]):\n        R.err(path, f\"距离矩阵必须是方阵，收到 {n} 行 × {len(m[0])} 列\")\n        return None\n    if n < TSP_MIN or n > n_max:\n        R.err(path, f\"城市数应在 {TSP_MIN} ~ {n_max} 之间（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    if any(m[i][i] != 0 for i in range(n)):\n        i = next(i for i in range(n) if m[i][i] != 0)\n        R.err(f\"{path}[{i}][{i}]\", f\"对角线（到自己的距离）应为 0，收到 {m[i][i]}\")\n        return None\n    for i in range(n):\n        for j in range(i + 1, n):\n            if abs(m[i][j] - m[j][i]) > 1e-9 * max(1.0, abs(m[i][j])):\n                R.err(f\"{path}[{i}][{j}]\", f\"{_ATSP_MSG}（第 {i} 行第 {j} 列是 {m[i][j]}，对称位置是 {m[j][i]}）\")\n                return None\n    return m\n\n\ndef _v_tsp(p, R):\n    metric = None\n    mat = None\n    pts = None\n    if isinstance(p, dict):\n        metric = p.get(\"metric\")\n        mat = p.get(\"matrix\", p.get(\"dist\"))\n        pts = p.get(\"cities\", p.get(\"pts\"))\n        if pts is None and mat is None:\n            R.err(\"cities\", \"缺少 'cities'（[[x, y], …] 坐标）或 'matrix'（n×n 距离矩阵）\")\n            return None\n    else:\n        pts = p\n        if isinstance(p, list) and len(p) >= TSP_MIN and all(isinstance(r, list) for r in p) \\\n                and all(len(r) == len(p) for r in p):\n            pts, mat = None, p  # 方阵：按距离矩阵读取（n×2 的坐标不可能是方阵，除非 n=2，而 n≥3）\n            R.warn(\"\", f\"按 {len(p)}×{len(p)} 距离矩阵读取；如果你想给的是坐标，每行应只有 [x, y] 两个数\")\n    if metric is not None and metric not in TSP_METRICS and metric not in (\"euc\", \"matrix\"):\n        R.err(\"metric\", f\"不支持的距离类型 {_show(metric)}。可选：euc（默认，浮点欧氏）、{', '.join(TSP_METRICS)}\")\n        return None\n    if mat is not None:\n        if metric not in (None, \"euc\", \"matrix\"):\n            R.err(\"metric\", \"给了距离矩阵就不需要 metric（距离以矩阵为准）\")\n            return None\n        m = _tsp_matrix(R, \"matrix\", mat, LIMITS[\"tsp\"])\n        if m is None:\n            return None\n        n = len(m)\n        if pts is None:\n            R.warn(\"cities\", \"没有给坐标：路线图按圆环布局，只用来示意；路线长度仍以你的距离矩阵为准\")\n            pos = _circle_layout(n)\n        else:\n            pos = _matrix(R, \"cities\", _list(R, \"cities\", pts, min_len=n, max_len=n, what=\"绘图坐标列表\"), cols=2)\n            if pos is None:\n                return None\n        return {\"cities\": pos, \"metric\": \"matrix\", \"matrix\": m}\n    pts = _list(R, \"cities\", pts, min_len=TSP_MIN, max_len=LIMITS[\"tsp\"], what=\"城市坐标列表\")\n    if pts is None:\n        return None\n    m = _matrix(R, \"cities\", pts, cols=2)\n    if m is None:\n        return None\n    if len({tuple(c) for c in m}) < len(m):\n        R.warn(\"cities\", \"存在重复坐标的城市（距离为 0），可以求解但路线图上会重叠\")\n    if metric in TSP_METRICS:\n        return {\"cities\": m, \"metric\": metric}\n    return {\"cities\": m}\n\n\n# ------------------------------------------------------------------ TSPLIB 解析\n\n_TSPLIB_KEY = re.compile(r\"^\\s*([A-Z_]+)\\s*:?\\s*(.*)$\")\n\n\ndef _looks_like_tsplib(txt):\n    return bool(re.search(r\"^\\s*(NODE_COORD_SECTION|EDGE_WEIGHT_SECTION|DIMENSION\\s*:|EDGE_WEIGHT_TYPE\\s*:)\", txt, re.M))\n\n\ndef _tsplib_matrix_from_list(R, fmt, vals, n):\n    \"\"\"把 EDGE_WEIGHT_SECTION 的一维数列按格式还原成 n×n 对称矩阵（列优先格式与行优先的镜像等价）。\"\"\"\n    fmt = {\"UPPER_COL\": \"LOWER_ROW\", \"LOWER_COL\": \"UPPER_ROW\", \"UPPER_DIAG_COL\": \"LOWER_DIAG_ROW\",\n           \"LOWER_DIAG_COL\": \"UPPER_DIAG_ROW\"}.get(fmt, fmt)\n    need = {\"FULL_MATRIX\": n * n, \"UPPER_ROW\": n * (n - 1) // 2, \"LOWER_ROW\": n * (n - 1) // 2,\n            \"UPPER_DIAG_ROW\": n * (n + 1) // 2, \"LOWER_DIAG_ROW\": n * (n + 1) // 2}.get(fmt)\n    if need is None:\n        R.err(\"EDGE_WEIGHT_FORMAT\", f\"不支持的 EDGE_WEIGHT_FORMAT {_show(fmt)}\")\n        return None\n    if len(vals) != need:\n        R.err(\"EDGE_WEIGHT_SECTION\", f\"{fmt} 在 DIMENSION={n} 时应有 {need} 个数，收到 {len(vals)} 个\")\n        return None\n    M = [[0] * n for _ in range(n)]\n    it = iter(vals)\n    if fmt == \"FULL_MATRIX\":\n        for i in range(n):\n            for j in range(n):\n                M[i][j] = next(it)\n        return M\n    for i in range(n):\n        if fmt.startswith(\"UPPER\"):\n            cols = range(i if fmt.endswith(\"DIAG_ROW\") else i + 1, n)\n        else:\n            cols = range(0, i + 1 if fmt.endswith(\"DIAG_ROW\") else i)\n        for j in cols:\n            v = next(it)\n            M[i][j] = v\n            M[j][i] = v\n    return M\n\n\ndef _parse_tsplib(txt, R, atsp=False):\n    \"\"\"TSPLIB95 的 TSP 子集 → 校验器认识的 dict。不是 TSP（ATSP / CVRP / HCP …）一律明确拒绝。\n    atsp=True：改读 TYPE: ATSP 文件（给 entryseq 的 atsp 变体用，只收显式 FULL_MATRIX），其余类型拒绝。\"\"\"\n    hdr, sections, cur = {}, {}, None\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s:\n            continue\n        if s == \"EOF\":\n            break\n        m = _TSPLIB_KEY.match(s)\n        if m and m.group(1).endswith(\"_SECTION\") and m.group(2) == \"\":\n            cur = m.group(1)\n            sections[cur] = []\n            continue\n        if cur and re.match(r\"^[-+\\d.eE\\s]+$\", s):\n            sections[cur].append((ln, s))\n            continue\n        if m and \":\" in s:\n            cur = None\n            k, v = s.split(\":\", 1)\n            hdr[k.strip()] = v.strip()\n            continue\n        R.err(f\"第 {ln} 行\", f\"无法识别的 TSPLIB 内容：{_show(s)}\")\n        return None\n    typ = hdr.get(\"TYPE\", \"TSP\").upper()\n    if atsp:\n        return _parse_atsplib(hdr, sections, typ, R)\n    if typ == \"ATSP\":\n        R.err(\"TYPE\", _ATSP_MSG)\n        return None\n    if typ != \"TSP\":\n        R.err(\"TYPE\", f\"这是 TSPLIB 的 {typ} 文件；这里只支持 TYPE: TSP（对称旅行商）\")\n        return None\n    try:\n        n = int(hdr[\"DIMENSION\"])\n    except (KeyError, ValueError):\n        R.err(\"DIMENSION\", \"缺少或无法读取 DIMENSION（城市数）\")\n        return None\n    ewt = hdr.get(\"EDGE_WEIGHT_TYPE\", \"\").upper()\n\n    def numbers(name):\n        out = []\n        for ln, s in sections.get(name, []):\n            for t in s.split():\n                try:\n                    out.append(float(t))\n                except ValueError:\n                    R.err(f\"第 {ln} 行\", f\"应为数字，收到 {_show(t)}\")\n                    return None\n        return out\n\n    if ewt == \"EXPLICIT\":\n        vals = numbers(\"EDGE_WEIGHT_SECTION\")\n        if vals is None:\n            return None\n        if \"EDGE_WEIGHT_SECTION\" not in sections:\n            R.err(\"EDGE_WEIGHT_SECTION\", \"EDGE_WEIGHT_TYPE 是 EXPLICIT，但文件里没有 EDGE_WEIGHT_SECTION\")\n            return None\n        mat = _tsplib_matrix_from_list(R, hdr.get(\"EDGE_WEIGHT_FORMAT\", \"\").upper(), vals, n)\n        if mat is None:\n            return None\n        out = {\"matrix\": mat}\n        disp = sections.get(\"DISPLAY_DATA_SECTION\")\n        if disp and hdr.get(\"DISPLAY_DATA_TYPE\", \"\").upper() == \"TWOD_DISPLAY\":\n            pos = _tsplib_coords(R, \"DISPLAY_DATA_SECTION\", disp, n)\n            if pos is not None:\n                out[\"cities\"] = pos\n        return out\n    if ewt not in TSP_METRICS:\n        R.err(\"EDGE_WEIGHT_TYPE\", f\"不支持 EDGE_WEIGHT_TYPE {_show(ewt) if ewt else '（缺失）'}。支持：\"\n                                   f\"{', '.join(TSP_METRICS)}、EXPLICIT（距离矩阵）\")\n        return None\n    if \"NODE_COORD_SECTION\" not in sections:\n        R.err(\"NODE_COORD_SECTION\", \"缺少 NODE_COORD_SECTION（城市坐标）\")\n        return None\n    pos = _tsplib_coords(R, \"NODE_COORD_SECTION\", sections[\"NODE_COORD_SECTION\"], n)\n    return None if pos is None else {\"cities\": pos, \"metric\": ewt}\n\n\ndef _parse_atsplib(hdr, sections, typ, R):\n    \"\"\"TSPLIB 的 .atsp（非对称 TSP）→ entryseq/atsp 实例。官方 .atsp 文件的对角线常写成 9999 之类的占位值，读入时统一置 0。\"\"\"\n    if typ != \"ATSP\":\n        R.err(\"TYPE\", f\"这是 TYPE: {typ} 的文件。这里读的是非对称 TSP（TYPE: ATSP）；对称 TSP 请到「TSP 演示」页导入\")\n        return None\n    try:\n        n = int(hdr[\"DIMENSION\"])\n    except (KeyError, ValueError):\n        R.err(\"DIMENSION\", \"缺少或无法读取 DIMENSION（城市数）\")\n        return None\n    if hdr.get(\"EDGE_WEIGHT_TYPE\", \"\").upper() != \"EXPLICIT\" or hdr.get(\"EDGE_WEIGHT_FORMAT\", \"\").upper() != \"FULL_MATRIX\":\n        R.err(\"EDGE_WEIGHT_FORMAT\", \"ATSP 文件需要 EDGE_WEIGHT_TYPE: EXPLICIT 且 EDGE_WEIGHT_FORMAT: FULL_MATRIX（TSPLIB 的 .atsp 都是这种）\")\n        return None\n    vals = []\n    for ln, s in sections.get(\"EDGE_WEIGHT_SECTION\", []):\n        for t in s.split():\n            try:\n                vals.append(float(t))\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"应为数字，收到 {_show(t)}\")\n                return None\n    if len(vals) != n * n:\n        R.err(\"EDGE_WEIGHT_SECTION\", f\"FULL_MATRIX 在 DIMENSION={n} 时应有 {n * n} 个数，收到 {len(vals)} 个\")\n        return None\n    mat = [[(int(v) if float(v).is_integer() else v) for v in vals[i * n:(i + 1) * n]] for i in range(n)]\n    if any(mat[i][i] != 0 for i in range(n)):\n        R.warn(\"EDGE_WEIGHT_SECTION\", \"对角线（到自己的代价）不是 0——TSPLIB 的 .atsp 常用 9999 之类的占位值，已置为 0（不影响求解）\")\n        for i in range(n):\n            mat[i][i] = 0\n    return {\"variant\": \"atsp\", \"d\": mat, \"pts\": _circle_layout(n), \"n\": n}\n\n\ndef _tsplib_coords(R, name, rows, n):\n    pos = []\n    for ln, s in rows:\n        t = s.split()\n        if len(t) != 3:\n            R.err(f\"第 {ln} 行\", f\"{name} 每行应为「编号 x y」三个数，收到 {len(t)} 个（只支持二维坐标）\")\n            return None\n        try:\n            pos.append([float(t[1]), float(t[2])])\n        except ValueError:\n            R.err(f\"第 {ln} 行\", f\"坐标应为数字，收到 {_show(s)}\")\n            return None\n    if len(pos) != n:\n        R.err(name, f\"DIMENSION={n}，但这一段有 {len(pos)} 行\")\n        return None\n    return pos\n\n\ndef _csv_tsp(table, meta, R):\n    \"\"\"CSV 的 TSP 读法：每行 x,y；或 id,x,y（第一列是 1..n / 0..n-1 的编号）；或 n×n 距离矩阵。\"\"\"\n    widths = {len(r) for r in table}\n    if len(widths) != 1:\n        R.err(\"\", f\"每行的列数必须一致，收到 {sorted(widths)}\")\n        return None\n    w, n = widths.pop(), len(table)\n    if w == n and n >= TSP_MIN and all(table[i][i] == 0 for i in range(n)):  # 零对角的方阵才可能是距离矩阵\n        R.warn(\"\", f\"{n}×{n} 的方阵，按距离矩阵读取；如果想给坐标，每行应只有 x,y（或 id,x,y）\")\n        return {\"matrix\": table}\n    if w == 2:\n        return {\"cities\": table}\n    if w == 3:\n        ids = [r[0] for r in table]\n        if ids in (list(range(1, n + 1)), list(range(n))) or ids in ([float(i) for i in range(1, n + 1)],\n                                                                       [float(i) for i in range(n)]):\n            R.warn(\"\", \"第一列是 1..n 的编号，已忽略，按 id,x,y 读取\")\n            return {\"cities\": [r[1:] for r in table]}\n        R.err(\"\", \"每行 3 个数：看起来像 id,x,y，但第一列不是 1..n（或 0..n-1）的连续编号。\"\n                  \"如果是三维坐标，本站只支持二维；如果第一列是别的含义，请删掉它\")\n        return None\n    R.err(\"\", f\"每行 {w} 个数，无法判断含义：坐标请用 x,y（或 id,x,y）；距离矩阵必须是 n×n 方阵（当前 {n} 行 {w} 列）\")\n    return None\n\n\ndef _v_knapsack(p, R):\n    items = _list(R, \"items\", _need(R, p, \"items\"), max_len=LIMITS[\"knapsack\"], what=\"物品列表\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), positive=True, what=\"容量\")\n    if items is None or cap is None:\n        return None\n    out, ok = [], True\n    for i, it in enumerate(items):\n        row = _list(R, f\"items[{i}]\", it, min_len=2, what=\"[重量, 价值]\")\n        if row is None:\n            ok = False\n            continue\n        if len(row) != 2:\n            R.err(f\"items[{i}]\", f\"每个物品应为 [重量, 价值] 两个数，收到 {len(row)} 个\")\n            ok = False\n            continue\n        w = _num(R, f\"items[{i}][0]\", row[0], positive=True, what=\"重量\")\n        v = _num(R, f\"items[{i}][1]\", row[1], lo=0, what=\"价值\")\n        ok &= w is not None and v is not None\n        out.append([w, v])\n    if not ok:\n        return None\n    big = [i for i, (w, _) in enumerate(out) if w > cap]\n    if big:\n        R.warn(\"items\", f\"{len(big)} 个物品比背包容量还重（如第 {big[0]} 项），永远不会被选中\")\n    if sum(w for w, _ in out) <= cap:\n        R.warn(\"cap\", \"全部物品总重量不超过容量，全选就是最优解，问题是平凡的\")\n    _warn_n(R, p, len(out))\n    return {\"n\": len(out), \"cap\": cap, \"items\": out}\n\n\ndef _warn_n(R, p, n, key=\"n\"):\n    if key in p and p[key] != n:\n        R.warn(key, f\"已忽略 {key}={_show(p[key])}，以数据实际长度 {n} 为准\")\n\n\ndef _v_multiobj(p, R):\n    items = _list(R, \"items\", _need(R, p, \"items\"), max_len=LIMITS[\"multiobj\"], what=\"物品列表\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), positive=True, what=\"容量\")\n    if items is None or cap is None:\n        return None\n    width = len(items[0]) if isinstance(items[0], list) else 0\n    if width not in (3, 4):\n        R.err(\"items[0]\", \"每个物品应为 [重量, 目标1, 目标2] 或 [重量, 目标1, 目标2, 目标3]\")\n        return None\n    m = _matrix(R, \"items\", items, cols=width, lo=0)\n    if m is None:\n        return None\n    if any(r[0] <= 0 for r in m):\n        R.err(\"items\", \"重量（每行第 0 列）必须大于 0\")\n        return None\n    variant = \"moco\" if width == 3 else \"maop\"\n    if p.get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"物品每行 {width} 列对应变体 '{variant}'，但 variant 写的是 {_show(p.get('variant'))}\")\n        return None\n    _warn_n(R, p, len(m))\n    return {\"variant\": variant, \"n\": len(m), \"cap\": cap, \"items\": m}\n\n\ndef _v_binpack(p, R):\n    items = _num_vec(R, \"items\", _need(R, p, \"items\", (\"sizes\",)), positive=True, what=\"尺寸\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\", \"bin_cap\")), positive=True, what=\"箱容量\")\n    if items is None or cap is None:\n        return None\n    if len(items) > LIMITS[\"binpack\"]:\n        R.err(\"items\", f\"最多 {LIMITS['binpack']} 件（浏览器内运行的规模上限），收到 {len(items)} 件\")\n        return None\n    big = [i for i, w in enumerate(items) if w > cap]\n    if big:\n        R.err(f\"items[{big[0]}]\", f\"物品尺寸 {items[big[0]]} 超过箱容量 {cap}，无论如何装不下（共 {len(big)} 件）\")\n        return None\n    _warn_n(R, p, len(items))\n    return {\"n\": len(items), \"cap\": cap, \"items\": items}\n\n\ndef _edges(R, p, n_given):\n    \"\"\"图的边表校验与规整：返回 (n, edges, pos) 或 None。顶点编号从 0 开始。\"\"\"\n    raw = _list(R, \"edges\", _need(R, p, \"edges\"), min_len=0, max_len=LIMITS[\"graph_edges\"], what=\"边列表\")\n    if raw is None:\n        return None\n    pairs, ok = [], True\n    for i, e in enumerate(raw):\n        if not isinstance(e, list) or len(e) < 2:\n            R.err(f\"edges[{i}]\", f\"每条边应为 [顶点u, 顶点v]，收到 {_show(e)}\")\n            ok = False\n            continue\n        u = _int(R, f\"edges[{i}][0]\", e[0], lo=0, what=\"顶点编号（从 0 开始的整数）\")\n        v = _int(R, f\"edges[{i}][1]\", e[1], lo=0, what=\"顶点编号（从 0 开始的整数）\")\n        ok &= u is not None and v is not None\n        pairs.append((u, v))\n    if not ok:\n        return None\n    n = n_given\n    top = max((max(u, v) for u, v in pairs), default=-1)\n    if n is None:\n        if top < 0:\n            R.err(\"n\", \"没有边也没有给 n，无法确定顶点数\")\n            return None\n        n = top + 1\n        R.warn(\"n\", f\"未提供 n，按最大顶点编号推断为 {n}（若末尾有孤立点请显式提供 n）\")\n    else:\n        n = _int(R, \"n\", n, lo=2, what=\"顶点数\")\n        if n is None:\n            return None\n        if top >= n:\n            hint = \"（看起来是从 1 开始编号；本格式顶点编号为 0..n-1）\" if top == n and min(min(e) for e in pairs) >= 1 else \"\"\n            R.err(\"edges\", f\"顶点编号 {top} 超出范围 0..{n - 1}{hint}\")\n            return None\n    if n > LIMITS[\"graph_nodes\"]:\n        R.err(\"n\", f\"顶点数最多 {LIMITS['graph_nodes']}（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    seen, edges, loops = set(), [], 0\n    for u, v in pairs:\n        if u == v:\n            loops += 1\n            continue\n        k = (min(u, v), max(u, v))\n        if k not in seen:\n            seen.add(k)\n            edges.append([k[0], k[1]])\n    if loops:\n        R.warn(\"edges\", f\"忽略了 {loops} 条自环边\")\n    if len(edges) < len(pairs) - loops:\n        R.warn(\"edges\", f\"合并了 {len(pairs) - loops - len(edges)} 条重复边\")\n    return n, edges\n\n\ndef _v_graphcolor(p, R):\n    got = _edges(R, p, p.get(\"n\"))\n    if got is None:\n        return None\n    n, edges = got\n    pos = _pos_or_layout(R, p, \"pos\", n)\n    if pos is None:\n        return None\n    return {\"n\": n, \"edges\": edges, \"pos\": pos}\n\n\ndef _v_setcover(p, R):\n    sets = _list(R, \"sets\", _need(R, p, \"sets\"), max_len=1000, what=\"集合列表\")\n    costs = _need(R, p, \"costs\", (\"cost\",))\n    if sets is None or costs is None:\n        return None\n    m = _matrix(R, \"sets\", sets)\n    if m is None:\n        return None\n    if len(m) * len(m[0]) > LIMITS[\"setcover_cells\"]:\n        R.err(\"sets\", f\"矩阵过大（{len(m)}×{len(m[0])}），上限 {LIMITS['setcover_cells']} 格\")\n        return None\n    for i, row in enumerate(m):\n        for j, v in enumerate(row):\n            if v not in (0, 1):\n                R.err(f\"sets[{i}][{j}]\", f\"覆盖矩阵只能是 0 或 1，收到 {v}\")\n                return None\n    c = _num_vec(R, \"costs\", costs, length=len(m), positive=True, what=\"成本\")\n    if c is None:\n        return None\n    n_el = len(m[0])\n    unc = [e for e in range(n_el) if not any(m[i][e] for i in range(len(m)))]\n    if unc:\n        R.err(\"sets\", f\"元素 {unc[:5]}{'…' if len(unc) > 5 else ''} 没有被任何集合覆盖，问题无解（共 {len(unc)} 个）\")\n        return None\n    return {\"n_el\": n_el, \"m\": len(m), \"sets\": [[int(v) for v in r] for r in m], \"costs\": c}\n\n\ndef _v_sat(p, R):\n    cl = _list(R, \"clauses\", _need(R, p, \"clauses\"), max_len=LIMITS[\"sat_clauses\"], what=\"子句列表\")\n    if cl is None:\n        return None\n    out, ok, top = [], True, 0\n    for i, c in enumerate(cl):\n        row = _list(R, f\"clauses[{i}]\", c, what=\"子句（非零整数文字列表）\")\n        if row is None:\n            ok = False\n            continue\n        lits = []\n        for j, lit in enumerate(row):\n            v = _int(R, f\"clauses[{i}][{j}]\", lit, what=\"非零整数（正=变量，负=取反，变量编号从 1 开始）\")\n            if v is None:\n                ok = False\n            elif v == 0:\n                R.err(f\"clauses[{i}][{j}]\", \"文字不能为 0（变量编号从 1 开始；0 只在 DIMACS 文件里作行尾标记）\")\n                ok = False\n            else:\n                lits.append(v)\n                top = max(top, abs(v))\n        if ok and len(set(lits)) < len(lits):\n            lits = list(dict.fromkeys(lits))\n            R.warn(f\"clauses[{i}]\", \"子句内有重复文字，已去重\")\n        if ok and any(-x in lits for x in lits):\n            R.warn(f\"clauses[{i}]\", \"子句同时含 x 与 ¬x，恒为真（永远满足）\")\n        out.append(lits)\n    if not ok:\n        return None\n    n = p.get(\"n_vars\", p.get(\"n\"))\n    if n is None:\n        n = top\n        R.warn(\"n_vars\", f\"未提供 n_vars，按最大变量编号推断为 {n}\")\n    n = _int(R, \"n_vars\", n, lo=1, hi=LIMITS[\"sat_vars\"], what=\"变量数\")\n    if n is None:\n        return None\n    if top > n:\n        R.err(\"clauses\", f\"子句里出现变量 {top}，超过 n_vars={n}\")\n        return None\n    return {\"n_vars\": n, \"clauses\": out}\n\n\ndef _v_qubo(p, R):\n    Q = _matrix(R, \"Q\", _need(R, p, \"Q\"))\n    if Q is None:\n        return None\n    n = len(Q)\n    if len(Q[0]) != n:\n        R.err(\"Q\", f\"QUBO 矩阵必须是方阵，收到 {n}×{len(Q[0])}\")\n        return None\n    if n > LIMITS[\"qubo\"]:\n        R.err(\"Q\", f\"最多 {LIMITS['qubo']} 个变量（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    return {\"n\": n, \"Q\": Q}\n\n\ndef _v_gap(p, R):\n    c = _matrix(R, \"c\", _need(R, p, \"c\", (\"cost\",)))\n    if c is None:\n        return None\n    n_a, n_j = len(c), len(c[0])\n    r = _matrix(R, \"r\", _need(R, p, \"r\", (\"resource\",)), rows=n_a, cols=n_j, lo=0)\n    cap = _num_vec(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), length=n_a, lo=0, what=\"容量\")\n    if r is None or cap is None:\n        return None\n    if n_a > LIMITS[\"gap_agents\"] or n_j > LIMITS[\"gap_jobs\"]:\n        R.err(\"c\", f\"最多 {LIMITS['gap_agents']} 个代理 × {LIMITS['gap_jobs']} 个任务，收到 {n_a}×{n_j}\")\n        return None\n    for j in range(n_j):\n        if all(r[a][j] > cap[a] for a in range(n_a)):\n            R.err(f\"r[*][{j}]\", f\"任务 {j} 的资源需求超过所有代理的容量，无法指派，问题无解\")\n            return None\n    return {\"n_a\": n_a, \"n_j\": n_j, \"c\": c, \"r\": r, \"cap\": cap}\n\n\ndef _v_uflp(p, R):\n    f = _num_vec(R, \"f_cost\", _need(R, p, \"f_cost\", (\"fixed_cost\",)), lo=0, what=\"开设成本\")\n    if f is None:\n        return None\n    cc = _matrix(R, \"c_cost\", _need(R, p, \"c_cost\", (\"assign_cost\",)), rows=len(f), lo=0)\n    if cc is None:\n        return None\n    n_f, n_c = len(f), len(cc[0])\n    if n_f > LIMITS[\"uflp_f\"] or n_c > LIMITS[\"uflp_c\"]:\n        R.err(\"c_cost\", f\"最多 {LIMITS['uflp_f']} 个设施 × {LIMITS['uflp_c']} 个客户，收到 {n_f}×{n_c}\")\n        return None\n    pf = _pos_or_layout(R, p, \"pos_f\", n_f)\n    pc = _pos_or_layout(R, p, \"pos_c\", n_c)\n    if pf is None or pc is None:\n        return None\n    return {\"n_f\": n_f, \"n_c\": n_c, \"f_cost\": f, \"c_cost\": cc, \"pos_f\": pf, \"pos_c\": pc}\n\n\ndef _v_continuous(p, R):\n    D = _engine()\n    fn = _need(R, p, \"fn\", (\"function\",))\n    if fn is None:\n        return None\n    if fn not in D.FUNCS:\n        R.err(\"fn\", f\"未知函数 {_show(fn)}。可选：{', '.join(D.FUNCS)}（自定义函数见「自带问题」）\")\n        return None\n    dim = _int(R, \"dim\", p.get(\"dim\", 2), lo=1, hi=LIMITS[\"continuous_dim\"], what=\"维度\")\n    if dim is None:\n        return None\n    if \"lo\" in p or \"hi\" in p:\n        R.warn(\"lo/hi\", \"搜索范围由所选函数决定，已忽略 lo/hi\")\n    return D.cn_make(fn=fn, dim=dim)\n\n\n# ------------------------------------------------------------------ 着色家族（含边/全着色的线图推导）\n\ndef _line_adj(edges):\n    m = len(edges)\n    inc = {}\n    for k, (u, v) in enumerate(edges):\n        inc.setdefault(u, []).append(k)\n        inc.setdefault(v, []).append(k)\n    adj = [set() for _ in range(m)]\n    for ks in inc.values():\n        for a in ks:\n            for b in ks:\n                if a != b:\n                    adj[a].add(b)\n    return [sorted(s) for s in adj]\n\n\ndef _v_gcvar(p, R, variant):\n    got = _edges(R, p, p.get(\"n\"))\n    if got is None:\n        return None\n    n, edges = got\n    pos = _pos_or_layout(R, p, \"pos\", n)\n    if pos is None:\n        return None\n    deg = [0] * n\n    for u, v in edges:\n        deg[u] += 1\n        deg[v] += 1\n    out = {\"variant\": variant, \"n\": n, \"edges\": edges, \"pos\": pos,\n           \"p\": round(2 * len(edges) / max(n * (n - 1), 1), 3)}\n    if variant == \"listcolor\":\n        lists = _list(R, \"lists\", _need(R, p, \"lists\"), what=\"每个顶点的可选颜色表\")\n        if lists is None:\n            return None\n        if len(lists) != n:\n            R.err(\"lists\", f\"应为每个顶点一张颜色表（共 {n} 张），收到 {len(lists)} 张\")\n            return None\n        L, K = [], 0\n        for i, row in enumerate(lists):\n            r = _list(R, f\"lists[{i}]\", row, what=\"颜色表\")\n            if r is None:\n                return None\n            cs = [_int(R, f\"lists[{i}][{j}]\", c, lo=0, what=\"颜色编号（从 0 开始的整数）\") for j, c in enumerate(r)]\n            if None in cs:\n                return None\n            L.append(sorted(set(cs)))\n            K = max(K, max(cs) + 1)\n        out[\"lists\"], out[\"K\"] = L, K\n    elif variant == \"precolor\":\n        pc = _list(R, \"precol\", _need(R, p, \"precol\"), what=\"预着色表\")\n        if pc is None:\n            return None\n        if len(pc) != n:\n            R.err(\"precol\", f\"应为每个顶点一项（共 {n} 项，-1 表示未预着色），收到 {len(pc)} 项\")\n            return None\n        cols = [_int(R, f\"precol[{i}]\", c, lo=-1, what=\"颜色编号（-1=未预着色）\") for i, c in enumerate(pc)]\n        if None in cols:\n            return None\n        for u, v in edges:\n            if cols[u] >= 0 and cols[u] == cols[v]:\n                R.err(\"precol\", f\"相邻顶点 {u} 与 {v} 被预着成同一颜色 {cols[u]}，无合法着色\")\n                return None\n        out[\"precol\"] = cols\n        out[\"K\"] = max(max(cols) + 1, max(deg, default=0) + 1)\n    elif variant == \"edgecolor\":\n        out[\"ladj\"] = _line_adj(edges)\n        out[\"m\"] = len(edges)\n    elif variant == \"totalcolor\":\n        m = len(edges)\n        tad = [set() for _ in range(n + m)]\n        for u, v in edges:\n            tad[u].add(v)\n            tad[v].add(u)\n        for a, nb in enumerate(_line_adj(edges)):\n            tad[n + a].update(n + b for b in nb)\n        for a, (u, v) in enumerate(edges):\n            for x in (u, v):\n                tad[x].add(n + a)\n                tad[n + a].add(x)\n        out.update({\"tadj\": [sorted(s) for s in tad], \"nV\": n, \"m\": m, \"N\": n + m})\n    elif variant != \"mis\":\n        R.err(\"variant\", f\"gcvar 的变体应为 listcolor/precolor/edgecolor/totalcolor/mis，收到 {_show(variant)}\")\n        return None\n    return out\n\n\n# ------------------------------------------------------------------ 长尾域：按示例实例自动推结构\n\ndef _ref_check(R, path, ref, val, key=None):\n    \"\"\"按示例 ref 的结构检查 val；返回规整后的值或 None。\"\"\"\n    if isinstance(ref, bool):\n        R.err(path, \"内部：不支持布尔字段\")\n        return None\n    if isinstance(ref, (int, float)):\n        if not _isnum(val):\n            R.err(path, f\"应为数字，收到 {_show(val)}\")\n            return None\n        if isinstance(ref, int) and isinstance(val, float):\n            if not val.is_integer():\n                R.err(path, f\"应为整数，收到 {val}\")\n                return None\n            return int(val)\n        return val\n    if isinstance(ref, str):\n        if not isinstance(val, str):\n            R.err(path, f\"应为文本，收到 {_show(val)}\")\n            return None\n        return val\n    if isinstance(ref, list):\n        if not isinstance(val, list):\n            R.err(path, f\"应为列表（JSON 数组），收到 {_show(val)}\")\n            return None\n        if not ref:\n            return val\n        if len(val) == 0:\n            if key in _RAGGED_KEYS:  # 不规则字段允许空行（如无前驱的工序）\n                return val\n            R.err(path, \"不能为空列表\")\n            return None\n        # 行结构三类：记录型字段（坐标 [x,y]、边 [u,v,w]）行长必须等于示例；\n        # 不规则字段（前驱列表等）各行可不等长；其余视为矩阵，要求同一矩阵内等宽\n        first = ref[0]\n        fixed = len(first) if isinstance(first, list) and key in _RECORD_KEYS else None\n        width = None\n        out = []\n        ok = True\n        for i, x in enumerate(val):\n            if isinstance(first, list):\n                if not isinstance(x, list):\n                    R.err(f\"{path}[{i}]\", f\"应为列表，收到 {_show(x)}\")\n                    ok = False\n                    continue\n                if fixed is not None and len(x) != fixed:\n                    R.err(f\"{path}[{i}]\", f\"每项应有 {fixed} 个值，收到 {len(x)} 个\")\n                    ok = False\n                    continue\n                if fixed is None and key not in _RAGGED_KEYS:\n                    width = len(x) if width is None else width\n                    if len(x) != width:\n                        R.err(f\"{path}[{i}]\", f\"每行长度必须一致：前面是 {width}，本行 {len(x)}\")\n                        ok = False\n                        continue\n            c = _ref_check(R, f\"{path}[{i}]\", first, x, key)\n            ok &= c is not None\n            out.append(c)\n        return out if ok else None\n    return val\n\n\n_RECORD_KEYS = {\"pts\", \"edges\", \"items\", \"bin_types\", \"pos\"}\n_RAGGED_KEYS = {\"preds\", \"chains\", \"lists\", \"sets\", \"adj\", \"students\", \"jobs\"}\n_OPTIONAL_KEYS = {\"name\", \"opt\"}  # 只用来显示（实例名、文献最优值）：有就收，没有不要求\n\n\ndef _derive_n(ref, p):\n    \"\"\"示例里 n 恰好等于某个列表长度（或少 1）时，从用户数据推 n。返回 n 或 None。\"\"\"\n    n_ref = ref.get(\"n\")\n    if not isinstance(n_ref, int):\n        return None\n    for k, v in ref.items():\n        if k in (\"n\", \"pos\") or not isinstance(v, list):\n            continue\n        for off in (0, -1):\n            if len(v) + off == n_ref and isinstance(p.get(k), list):\n                return len(p[k]) + off\n    return None\n\n\ndef _v_mocont(p, R, variant):\n    \"\"\"连续多目标基准：变体 + 决策变量个数。函数本身是固定的，没有别的数据。\"\"\"\n    D = _engine()\n    v = variant or p.get(\"variant\")\n    if v not in D.MOC_VARIANTS:\n        R.err(\"variant\", f\"未知变体 {_show(v)}。可选：{', '.join(D.MOC_VARIANTS)}\")\n        return None\n    n_min = D.MOC_SPEC[v][3]\n    n = _int(R, \"n\", p.get(\"n\", D.MOC_SPEC[v][2]), lo=n_min, hi=100, what=\"决策变量个数\")\n    if n is None:\n        return None\n    if v in D.MOC_NFIX and n != D.MOC_NFIX[v]:\n        R.err(\"n\", f\"{v} 的决策变量个数固定为 {D.MOC_NFIX[v]}（真前沿的公式依赖它），收到 {n}\")\n        return None\n    return D.mc_make(v, n)\n\n\ndef _v_custom(p, R, variant):\n    \"\"\"自带问题：编码（variant）+ 目标函数（表达式）+ 数据表。检查与试跑都在 py/userproblem.py。\"\"\"\n    D = _engine()\n    q = dict(p)\n    v = q.get(\"variant\", q.get(\"encoding\"))\n    if variant and v and variant != v:\n        R.err(\"variant\", f\"数据里写的编码是 {v!r}，但这里要求 {variant!r}\")\n        return None\n    if variant:\n        q[\"variant\"] = variant\n    out, errs, warns, _info = D.up_check(q)\n    for e in errs:\n        R.err(e[\"path\"], e[\"msg\"])\n    for w in warns:\n        R.warn(w[\"path\"], w[\"msg\"])\n    return out\n\n\ndef _v_generic(domain, p, R, variant):\n    D = _engine()\n    opts = {\"variant\": variant} if variant else {}\n    try:\n        ref = json.loads(D.domain_preset(domain, 7, opts))\n    except Exception:\n        ref = None\n    if not isinstance(ref, dict):\n        R.err(\"variant\", f\"未知变体 {_show(variant)}\")\n        return None\n    out = {}\n    for k, rv in ref.items():\n        if k == \"variant\":\n            out[k] = ref[k]\n            continue\n        if k in _OPTIONAL_KEYS:\n            if k in p:\n                out[k] = p[k]\n            continue\n        if k not in p:\n            if k == \"pos\":\n                continue\n            if k == \"n\" and _derive_n(ref, p) is not None:\n                continue\n            R.err(k, f\"缺少必填字段 '{k}'\")\n            continue\n        c = _ref_check(R, k, rv, p[k], k)\n        if c is not None:\n            out[k] = c\n    if R.errors:\n        return None\n    dn = _derive_n(ref, p)\n    if dn is not None:\n        if \"n\" in p and p[\"n\"] != dn:\n            R.err(\"n\", f\"n={p['n']} 与数据长度不符（数据推出 n={dn}）\")\n            return None\n        out[\"n\"] = dn\n    n = out.get(\"n\")\n    cap_n = LIMITS[\"entryseq\"] if domain == \"entryseq\" else LIMITS.get(domain, 1000)\n    if isinstance(n, int) and not (1 <= n <= cap_n):\n        R.err(\"n\", f\"n 应在 1..{cap_n}（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    return out\n\n\ndef _es_fill(variant, p):\n    \"\"\"调度 / 路径 / 选址类变体里由数据推得出的字段（规模、机器数、下界、名字……）：上传时只需要给核心数据，其余这里补上。\n    数据形状不对时原样返回，交给通用检查去报错。\"\"\"\n    q = dict(p)\n\n    def mat(x):\n        return isinstance(x, list) and len(x) > 0 and all(isinstance(r, list) and len(r) > 0 for r in x)\n    try:\n        if variant == \"fss\" and mat(q.get(\"p\")):\n            q.setdefault(\"m_mach\", len(q[\"p\"]))\n            q.setdefault(\"n\", len(q[\"p\"][0]))\n        elif variant == \"oss\" and mat(q.get(\"t\")):\n            nj, m = len(q[\"t\"]), len(q[\"t\"][0])\n            q.setdefault(\"n_jobs\", nj)\n            q.setdefault(\"m_mach\", m)\n            q.setdefault(\"n\", nj * m)\n            if all(len(r) == m for r in q[\"t\"]) and all(_isnum(x) for r in q[\"t\"] for x in r):\n                q.setdefault(\"lb\", max(max(sum(r) for r in q[\"t\"]), max(sum(q[\"t\"][j][k] for j in range(nj)) for k in range(m))))\n        elif variant in (\"jss\", \"fjsp\") and isinstance(q.get(\"jobs\"), list) and q[\"jobs\"] and all(isinstance(j, list) and j for j in q[\"jobs\"]):\n            jobs = q[\"jobs\"]\n            q.setdefault(\"n_jobs\", len(jobs))\n            q.setdefault(\"n\", sum(len(j) for j in jobs))\n            if variant == \"jss\":\n                q.setdefault(\"m_mach\", max(k for j in jobs for k, _t in j) + 1)\n                q.setdefault(\"lb\", 0)\n            else:\n                q.setdefault(\"m_mach\", max(k for j in jobs for op in j for k, _t in op) + 1)\n                q.setdefault(\"lb\", 0)\n        elif variant in (\"hc\", \"lpath\") and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n        elif variant in (\"mst\", \"gmatch\") and isinstance(q.get(\"pts\"), list) and isinstance(q.get(\"edges\"), list):\n            q.setdefault(\"n_nodes\", len(q[\"pts\"]))\n            q.setdefault(\"n\", len(q[\"edges\"]))\n            q.setdefault(\"opt\", 0)\n        elif variant == \"shortestpath\" and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n            q.setdefault(\"src\", 0)\n            q.setdefault(\"dst\", len(q[\"pts\"]) - 1)\n            q.setdefault(\"opt\", 0)\n        elif variant in (\"maxflow\", \"mincostflow\") and isinstance(q.get(\"pts\"), list) and isinstance(q.get(\"arcs\"), list):\n            q.setdefault(\"n_nodes\", len(q[\"pts\"]))\n            q.setdefault(\"n\", len(q[\"arcs\"]))\n            q.setdefault(\"src\", 0)\n            q.setdefault(\"snk\", len(q[\"pts\"]) - 1)\n            q.setdefault(\"opt\", 0)\n            if variant == \"mincostflow\":\n                q.setdefault(\"need\", 1)\n        elif variant == \"topsort\" and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n            q.setdefault(\"opt\", 0)\n        elif variant == \"msa\" and isinstance(q.get(\"seqs\"), list) and q[\"seqs\"] and all(isinstance(x, str) for x in q[\"seqs\"]):\n            q.setdefault(\"W\", max(len(x) for x in q[\"seqs\"]) + 4)\n            q.setdefault(\"n\", 3 * q[\"W\"])\n            q.setdefault(\"opt\", 0)\n        elif variant in (\"carp\", \"rpostman\") and isinstance(q.get(\"req\"), list):\n            q.setdefault(\"n\", len(q[\"req\"]))\n            q.setdefault(\"dem\", [0] * len(q[\"req\"]))\n            q.setdefault(\"depot\", 0)\n            q.setdefault(\"cap\", 20 if variant == \"carp\" else 10 ** 6)\n        elif variant == \"ndp\" and isinstance(q.get(\"edges\"), list) and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"edges\"]))\n            q.setdefault(\"n_pts\", len(q[\"pts\"]))\n        elif variant == \"tdm\" and mat(q.get(\"sets\")):\n            sets = q[\"sets\"]\n            q.setdefault(\"n\", len(sets))\n            q.setdefault(\"q\", len(sets[0]) // 3)\n            if len(sets[0]) % 3 == 0:\n                w = len(sets[0]) // 3\n                q.setdefault(\"triples\", [[r.index(1) if 1 in r else 0, (r[w:2 * w].index(1) if 1 in r[w:2 * w] else 0),\n                                          (r[2 * w:].index(1) if 1 in r[2 * w:] else 0)] for r in sets])\n    except (TypeError, ValueError, AttributeError):\n        return dict(p)\n    return q\n\n\ndef _v_entryseq(p, R, variant):\n    \"\"\"词条域：通用的形状检查之外，给语义要求严格的变体补上「数据之间必须自洽」的检查。\"\"\"\n    if variant == \"kmeans\" and \"n\" not in p and isinstance(p.get(\"k\"), int) and not isinstance(p.get(\"k\"), bool):\n        p = dict(p, n=2 * p[\"k\"])  # n = 决策向量长度 = 2k，用户只需要给簇数 k\n    p = _es_fill(variant, p)\n    out = _v_generic(\"entryseq\", p, R, variant)\n    if out is None:\n        return None\n    n = out.get(\"n\")\n    if variant == \"atsp\":\n        d = out[\"d\"]\n        if len(d) != n or any(len(r) != n for r in d):\n            R.err(\"d\", f\"距离矩阵应为 {n}×{n}（与城市数一致），收到 {len(d)} 行\")\n            return None\n        for i in range(n):\n            if d[i][i] != 0:\n                R.err(f\"d[{i}][{i}]\", f\"对角线（到自己的代价）应为 0，收到 {d[i][i]}\")\n                return None\n            for j in range(n):\n                if d[i][j] < 0:\n                    R.err(f\"d[{i}][{j}]\", f\"代价不能为负，收到 {d[i][j]}\")\n                    return None\n        if len(out[\"pts\"]) != n:\n            R.err(\"pts\", f\"绘图坐标应有 {n} 个点（只用来画图，不影响求解），收到 {len(out['pts'])} 个\")\n            return None\n        if all(d[i][j] == d[j][i] for i in range(n) for j in range(i + 1, n)):\n            R.warn(\"d\", \"这个矩阵是对称的——它其实是普通 TSP，可以在演示页用 TSP 导入（那里的专用算法更快）\")\n    elif variant in (\"vrptw\", \"vrpstw\"):\n        hard = variant == \"vrptw\"\n        pts, dem, e, l, svc = out[\"pts\"], out[\"demand\"], out[\"e\"], out[\"l\"], out[\"svc\"]\n        if not hard and (not isinstance(out[\"lam\"], (int, float)) or out[\"lam\"] < 0):\n            R.err(\"lam\", f\"迟到罚系数 lam 不能为负，收到 {_show(out['lam'])}\")\n            return None\n        for name, arr in ((\"pts\", pts), (\"demand\", dem), (\"e\", e), (\"l\", l), (\"svc\", svc)):\n            if len(arr) != n + 1:\n                R.err(name, f\"应有 {n + 1} 项（第 0 项是仓库，后面 {n} 个客户），收到 {len(arr)} 项\")\n                return None\n        cap, H = out[\"cap\"], l[0]\n        if not (isinstance(cap, (int, float)) and cap > 0):\n            R.err(\"cap\", f\"车辆容量必须大于 0，收到 {_show(cap)}\")\n            return None\n        if H <= 0:\n            R.err(\"l[0]\", f\"仓库关门时刻（l[0]）必须大于 0，收到 {H}\")\n            return None\n        if out[\"m_veh\"] < 1:\n            R.err(\"m_veh\", \"车辆数至少 1 辆\")\n            return None\n        if sum(dem) > out[\"m_veh\"] * cap:\n            R.err(\"m_veh\", f\"{out['m_veh']} 辆车 × 容量 {cap} 装不下总需求 {sum(dem)}——无论怎么排都没有可行解\")\n            return None\n        for i in range(1, n + 1):\n            if dem[i] < 0 or dem[i] > cap:\n                R.err(f\"demand[{i}]\", f\"客户需求应在 0..容量({cap}) 之间，收到 {dem[i]}\")\n                return None\n            if svc[i] < 0:\n                R.err(f\"svc[{i}]\", f\"服务时间不能为负，收到 {svc[i]}\")\n                return None\n            if e[i] < 0 or e[i] > l[i]:\n                R.err(f\"e[{i}]\", f\"时间窗应满足 0 ≤ e ≤ l，收到 [{e[i]}, {l[i]}]\")\n                return None\n            d0 = math.dist(pts[0], pts[i])\n            if not hard:\n                continue  # 软时间窗：来不及只是要付罚金，不是无解\n            if d0 > l[i] + 1e-9:\n                R.err(f\"l[{i}]\", f\"客户 {i} 的窗口在 {l[i]} 关闭，而从仓库直接开过去就要 {d0:.1f}——永远来不及\")\n                return None\n            back = max(d0, e[i]) + svc[i] + d0\n            if back > H + 1e-9:\n                R.err(f\"l[{i}]\", f\"客户 {i} 单独跑一趟也要到 {back:.1f} 才能回仓库，而仓库在 {H} 关门——没有可行解\")\n                return None\n    elif variant == \"mdvrp\":\n        pts, dem, cap = out[\"pts\"], out[\"demand\"], out[\"cap\"]\n        Dp, m_dep = out[\"D\"], out[\"m_dep\"]\n        if len(pts) != n + 1 or len(dem) != n + 1:\n            R.err(\"pts\", f\"pts 与 demand 都应有 {n + 1} 项（前 D 个是仓库，后面是客户），收到 {len(pts)} / {len(dem)} 项\")\n            return None\n        if not (isinstance(Dp, int) and 1 <= Dp < n + 1):\n            R.err(\"D\", f\"仓库数 D 应是 1..{n} 的整数（pts 里前 D 个是仓库），收到 {_show(Dp)}\")\n            return None\n        if any(dem[d] != 0 for d in range(Dp)):\n            R.err(\"demand\", \"前 D 项是仓库，需求必须为 0\")\n            return None\n        if not (isinstance(cap, (int, float)) and cap > 0):\n            R.err(\"cap\", f\"车辆容量必须大于 0，收到 {_show(cap)}\")\n            return None\n        if not (isinstance(m_dep, int) and m_dep >= 1):\n            R.err(\"m_dep\", f\"每个仓库的车辆数至少 1 辆，收到 {_show(m_dep)}\")\n            return None\n        for i in range(Dp, n + 1):\n            if dem[i] < 0 or dem[i] > cap:\n                R.err(f\"demand[{i}]\", f\"客户需求应在 0..容量({cap}) 之间，收到 {dem[i]}\")\n                return None\n        if sum(dem) > Dp * m_dep * cap:\n            R.err(\"m_dep\", f\"{Dp} 个仓库 × {m_dep} 辆车 × 容量 {cap} 装不下总需求 {sum(dem)}——没有可行解\")\n            return None\n    elif variant == \"fss\":\n        P_ = out[\"p\"]\n        if any(len(r) != len(P_[0]) for r in P_):\n            R.err(\"p\", \"p 应为「机器数 × 作业数」的矩阵（每行是一台机器上各作业的加工时间），各行长度必须一致\")\n            return None\n        if any(x <= 0 for r in P_ for x in r):\n            R.err(\"p\", \"加工时间必须大于 0\")\n            return None\n        if len(P_[0]) != n or len(P_) != out[\"m_mach\"]:\n            R.err(\"n\", f\"n 应等于作业数 {len(P_[0])}、m_mach 应等于机器数 {len(P_)}\")\n            return None\n    elif variant == \"oss\":\n        T = out[\"t\"]\n        if any(len(r) != len(T[0]) for r in T) or len(T) != len(T[0]):\n            R.err(\"t\", \"开放车间要求「作业数 = 机器数」的方阵（t[j][k] = 作业 j 在机器 k 上的加工时间）\")\n            return None\n        if any(x <= 0 for r in T for x in r):\n            R.err(\"t\", \"加工时间必须大于 0\")\n            return None\n        out[\"n_jobs\"], out[\"m_mach\"], out[\"n\"] = len(T), len(T[0]), len(T) * len(T[0])\n        out[\"lb\"] = max(max(sum(r) for r in T), max(sum(T[j][k] for j in range(len(T))) for k in range(len(T[0]))))\n    elif variant in (\"jss\", \"fjsp\"):\n        jobs = out[\"jobs\"]\n        L = len(jobs[0])\n        if any(len(j) != L for j in jobs):\n            R.err(\"jobs\", f\"每个作业的工序数必须相同（这里第一个作业有 {L} 道）——标准作业车间基准里每个作业都经过每台机器一次\")\n            return None\n        mm = -1\n        for a, job in enumerate(jobs):\n            for b, op in enumerate(job):\n                pairs = [op] if variant == \"jss\" else op\n                if variant == \"fjsp\" and (not isinstance(op, list) or not op):\n                    R.err(f\"jobs[{a}][{b}]\", \"每道工序至少要有一台可选机器\")\n                    return None\n                for pr in pairs:\n                    if not (isinstance(pr, list) and len(pr) == 2 and all(_isnum(x) for x in pr)):\n                        R.err(f\"jobs[{a}][{b}]\", \"应为 [机器编号, 加工时间]\" + (\"\" if variant == \"jss\" else \" 的列表（每台可选机器一对）\"))\n                        return None\n                    k, t = pr\n                    if k < 0 or int(k) != k or t <= 0:\n                        R.err(f\"jobs[{a}][{b}]\", f\"机器编号应为非负整数、加工时间应大于 0，收到 {pr}\")\n                        return None\n                    mm = max(mm, int(k))\n        if variant == \"jss\":\n            for a, job in enumerate(jobs):\n                if len({k for k, _t in job}) != len(job):\n                    R.warn(f\"jobs[{a}]\", \"同一个作业两次用到同一台机器——标准作业车间里每个作业经过每台机器一次，这会是更一般的实例\")\n        out[\"jobs\"] = [[[int(k), t] for k, t in job] if variant == \"jss\" else [[[int(k), t] for k, t in op] for op in job] for job in jobs]\n        out[\"n_jobs\"], out[\"m_mach\"], out[\"n\"] = len(jobs), mm + 1, len(jobs) * L\n        mload = [0] * (mm + 1)\n        if variant == \"jss\":\n            for job in jobs:\n                for k, t in job:\n                    mload[int(k)] += t\n            out[\"lb\"] = max(max(mload), max(sum(t for _k, t in job) for job in jobs))\n        else:\n            lb_job = max(sum(min(t for _k, t in op) for op in job) for job in jobs)\n            lb_work = -(-sum(min(t for _k, t in op) for job in jobs for op in job) // (mm + 1))\n            out[\"lb\"] = max(lb_job, lb_work)\n    elif variant in (\"hc\", \"lpath\"):\n        pts, edges = out[\"pts\"], out[\"edges\"]\n        if len(pts) != n:\n            R.err(\"pts\", f\"pts 应有 {n} 个点（只用来画图），收到 {len(pts)} 个\")\n            return None\n        for i, e in enumerate(edges):\n            a, b = e[0], e[1]\n            if not (0 <= a < n and 0 <= b < n) or a == b:\n                R.err(f\"edges[{i}]\", f\"边的两端应是 0..{n - 1} 里互不相同的点，收到 {e}\")\n                return None\n            if variant == \"lpath\" and not (len(e) >= 3 and e[2] > 0):\n                R.err(f\"edges[{i}]\", \"最长路径的边应为 [u, v, 权重]，权重大于 0\")\n                return None\n    elif variant in (\"carp\", \"rpostman\"):\n        pts, edges, req, dem = out[\"pts\"], out[\"edges\"], out[\"req\"], out[\"dem\"]\n        nv = len(pts)\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] < 1:\n                R.err(f\"edges[{i}]\", f\"路网的边应为 [u, v, 费用]：两端是 0..{nv - 1} 里不同的路口，费用 ≥ 1，收到 {e}\")\n                return None\n        if not (isinstance(out[\"depot\"], int) and 0 <= out[\"depot\"] < nv):\n            R.err(\"depot\", f\"仓库应是 0..{nv - 1} 的路口编号，收到 {_show(out['depot'])}\")\n            return None\n        if len(set(req)) != len(req) or any(not (0 <= r < len(edges)) for r in req):\n            R.err(\"req\", f\"必需边应是 edges 下标（0..{len(edges) - 1}）且互不相同\")\n            return None\n        if len(dem) != len(req):\n            R.err(\"dem\", f\"dem 应与 req 一一对应（{len(req)} 项），收到 {len(dem)} 项\")\n            return None\n        if not (out[\"cap\"] > 0):\n            R.err(\"cap\", \"车容量必须大于 0\")\n            return None\n        if any(d < 0 or d > out[\"cap\"] for d in dem):\n            R.err(\"dem\", f\"每条必需边的需求应在 0..容量({out['cap']}) 之间\")\n            return None\n        par = list(range(nv))\n\n        def _f(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _c in edges:\n            par[_f(a)] = _f(b)\n        if len({_f(i) for i in range(nv)}) > 1:\n            R.err(\"edges\", \"路网不连通——车辆到不了所有必需边，没有可行解\")\n            return None\n    elif variant == \"ndp\":\n        pts, edges, pairs = out[\"pts\"], out[\"edges\"], out[\"pairs\"]\n        nv = len(pts)\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] < 0:\n                R.err(f\"edges[{i}]\", f\"候选边应为 [u, v, 建设费]：两端是 0..{nv - 1} 里不同的点，费用 ≥ 0，收到 {e}\")\n                return None\n        for i, q in enumerate(pairs):\n            if len(q) != 2 or not all(isinstance(x, int) and 0 <= x < nv for x in q) or q[0] == q[1]:\n                R.err(f\"pairs[{i}]\", f\"需求对应是 0..{nv - 1} 里两个不同的点，收到 {q}\")\n                return None\n        par = list(range(nv))\n\n        def _f2(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _c in edges:\n            par[_f2(a)] = _f2(b)\n        for i, (a, b) in enumerate(pairs):\n            if _f2(a) != _f2(b):\n                R.err(f\"pairs[{i}]\", f\"点 {a} 与 {b} 在候选边构成的图里就不连通——怎么买都连不起来\")\n                return None\n        out[\"n\"], out[\"n_pts\"] = len(edges), nv\n    elif variant == \"cflp\":\n        if not (len(out[\"cap\"]) == len(out[\"dem\"]) == len(out[\"fc\"]) == len(out[\"pts\"]) == n):\n            R.err(\"cap\", f\"pts / cap / dem / fc 都应有 {n} 项（每个点既是客户也是候选设施）\")\n            return None\n        if any(x <= 0 for x in out[\"cap\"]) or any(x < 0 for x in out[\"dem\"]) or any(x < 0 for x in out[\"fc\"]):\n            R.err(\"cap\", \"容量应大于 0，需求与固定费不能为负\")\n            return None\n        if sum(out[\"cap\"]) < sum(out[\"dem\"]):\n            R.err(\"cap\", f\"总容量 {sum(out['cap'])} 小于总需求 {sum(out['dem'])}——没有可行解\")\n            return None\n    elif variant == \"lrp\":\n        if not (len(out[\"pts\"]) == len(out[\"dem\"]) == n):\n            R.err(\"dem\", f\"pts 与 dem 都应有 {n} 项\")\n            return None\n        if not (isinstance(out[\"p\"], int) and 1 <= out[\"p\"] < n):\n            R.err(\"p\", f\"仓库数 p 应是 1..{n - 1} 的整数，收到 {_show(out['p'])}\")\n            return None\n        if not (out[\"cap\"] > 0) or any(d < 0 or d > out[\"cap\"] for d in out[\"dem\"]):\n            R.err(\"cap\", f\"车容量应大于 0，且每个客户的需求在 0..{out['cap']} 之间\")\n            return None\n    elif variant == \"tdm\":\n        sets = out[\"sets\"]\n        w = len(sets[0]) // 3\n        if len(sets[0]) % 3 or w < 2:\n            R.err(\"sets\", \"每行应有 3q 列（X、Y、Z 各 q 个元素，q ≥ 2）\")\n            return None\n        for i, r in enumerate(sets):\n            if any(x not in (0, 1) for x in r) or sum(r[:w]) != 1 or sum(r[w:2 * w]) != 1 or sum(r[2 * w:]) != 1:\n                R.err(f\"sets[{i}]\", \"每个三元组恰在 X、Y、Z 三段各有一个 1\")\n                return None\n        out[\"n\"], out[\"q\"] = len(sets), w\n    elif variant in (\"mst\", \"gmatch\", \"shortestpath\"):\n        D = _engine()\n        pts, edges = out[\"pts\"], out[\"edges\"]\n        nv = len(pts)\n        if variant != \"shortestpath\" and out[\"n_nodes\"] != nv:\n            R.err(\"n_nodes\", f\"n_nodes 应等于点数 {nv}\")\n            return None\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] <= 0:\n                R.err(f\"edges[{i}]\", f\"边应为 [u, v, 权重]：两端是 0..{nv - 1} 里不同的点，权重大于 0，收到 {e}\")\n                return None\n        par = list(range(nv))\n\n        def _f3(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _w in edges:\n            par[_f3(a)] = _f3(b)\n        if len({_f3(i) for i in range(nv)}) > 1:\n            R.err(\"edges\", \"图不连通\" + (\"：没有生成树\" if variant == \"mst\" else \"：有些点之间没有任何路径\"))\n            return None\n        if variant == \"mst\":\n            out[\"n\"], out[\"opt\"] = len(edges), D._opt_mst(nv, edges)\n        elif variant == \"gmatch\":\n            if nv > 16:\n                R.err(\"pts\", f\"匹配的精确对照用顶点子集动态规划，最多支持 16 个点，收到 {nv}\")\n                return None\n            out[\"n\"], out[\"opt\"] = len(edges), D._opt_gmatch(nv, edges)\n        else:\n            src, dst = out[\"src\"], out[\"dst\"]\n            if not (isinstance(src, int) and isinstance(dst, int) and 0 <= src < nv and 0 <= dst < nv and src != dst):\n                R.err(\"src\", f\"起点与终点应是 0..{nv - 1} 里两个不同的点\")\n                return None\n            out[\"n\"], out[\"opt\"] = nv, D._opt_sp(nv, edges, src, dst)\n    elif variant in (\"maxflow\", \"mincostflow\"):\n        D = _engine()\n        pts, arcs = out[\"pts\"], out[\"arcs\"]\n        nv = len(pts)\n        w = 3 if variant == \"maxflow\" else 4\n        for i, a in enumerate(arcs):\n            if len(a) != w or not (0 <= a[0] < nv and 0 <= a[1] < nv) or a[0] == a[1] or a[2] <= 0 or (w == 4 and a[3] < 0):\n                R.err(f\"arcs[{i}]\", f\"弧应为 [起点, 终点, 容量{', 单位费用' if w == 4 else ''}]：两端是 0..{nv - 1} 里不同的点，容量大于 0\" + (\"，费用 ≥ 0\" if w == 4 else \"\") + f\"，收到 {a}\")\n                return None\n        src, snk = out[\"src\"], out[\"snk\"]\n        if not (isinstance(src, int) and isinstance(snk, int) and 0 <= src < nv and 0 <= snk < nv and src != snk):\n            R.err(\"src\", f\"源点与汇点应是 0..{nv - 1} 里两个不同的点\")\n            return None\n        cap_arcs = [[a[0], a[1], a[2]] for a in arcs]\n        fmax, _c = D._pc_max_flow(nv, cap_arcs, src, snk)\n        if fmax <= 0:\n            R.err(\"arcs\", \"源点到不了汇点——最大流为 0，没有可行的流\")\n            return None\n        out[\"n_nodes\"], out[\"n\"] = nv, len(arcs)\n        if variant == \"maxflow\":\n            out[\"opt\"] = fmax\n        else:\n            need = out[\"need\"]\n            if not (isinstance(need, (int, float)) and 0 < need <= fmax):\n                R.err(\"need\", f\"需要送出的流量应在 (0, {fmax}] 之间（{fmax} 是这张网络的最大流），收到 {_show(need)}\")\n                return None\n            _f, out[\"opt\"] = D._pc_max_flow(nv, cap_arcs, src, snk, cost=[a[3] for a in arcs], want=int(need))\n    elif variant == \"topsort\":\n        pts, arcs = out[\"pts\"], out[\"arcs\"]\n        nv = len(pts)\n        for i, a in enumerate(arcs):\n            if len(a) != 2 or not (0 <= a[0] < nv and 0 <= a[1] < nv) or a[0] == a[1]:\n                R.err(f\"arcs[{i}]\", f\"弧应为 [起点, 终点]：0..{nv - 1} 里两个不同的点，收到 {a}\")\n                return None\n        indeg = [0] * nv\n        for a, b in arcs:\n            indeg[b] += 1\n        queue = [v for v in range(nv) if indeg[v] == 0]\n        seen = 0\n        while queue:\n            u = queue.pop()\n            seen += 1\n            for a, b in arcs:\n                if a == u:\n                    indeg[b] -= 1\n                    if indeg[b] == 0:\n                        queue.append(b)\n        if seen < nv:\n            R.err(\"arcs\", \"图里有环，不存在拓扑序（目标「违反的弧数」最小只能到 > 0）；拓扑排序要求有向无环图\")\n            return None\n        out[\"n\"], out[\"opt\"] = nv, 0\n    elif variant == \"msa\":\n        D = _engine()\n        seqs = out[\"seqs\"]\n        if len(seqs) != 3 or any(not x or len(x) > 20 or not x.isalpha() for x in seqs):\n            R.err(\"seqs\", \"多序列比对目前固定为 3 条序列，每条 1–20 个字母（精确对照用三维动态规划）\")\n            return None\n        W = out[\"W\"]\n        if not (isinstance(W, int) and W >= max(len(x) for x in seqs)):\n            R.err(\"W\", f\"比对宽度 W 至少要等于最长序列的长度 {max(len(x) for x in seqs)}\")\n            return None\n        out[\"n\"], out[\"opt\"] = 3 * W, D._msa_dp(seqs)\n    elif variant == \"pms\":\n        if any(x <= 0 for x in out[\"p\"]):\n            R.err(\"p\", \"加工时间必须大于 0\")\n            return None\n        m = out[\"m_mach\"]\n        if not isinstance(m, int) or isinstance(m, bool) or m < 2:\n            R.err(\"m_mach\", f\"机器数应为 ≥ 2 的整数，收到 {m!r}\")\n            return None\n    elif variant == \"numpart\":\n        if any(x <= 0 for x in out[\"a\"]) or len(out[\"a\"]) < 2:\n            R.err(\"a\", \"需要至少 2 个正数\")\n            return None\n    elif variant == \"kmeans\":\n        k = out[\"k\"]\n        if not isinstance(k, int) or isinstance(k, bool) or k < 2:\n            R.err(\"k\", f\"簇数 k 应为 ≥ 2 的整数，收到 {k!r}\")\n            return None\n        if len(out[\"pts\"]) < k:\n            R.err(\"pts\", f\"点数（{len(out['pts'])}）不能少于簇数 k={k}\")\n            return None\n        if \"n\" in p and p[\"n\"] != 2 * k:\n            R.err(\"n\", f\"n 应为 2k = {2 * k}（k 个中心的 x、y 坐标），收到 {p['n']}\")\n            return None\n        if len({tuple(q) for q in out[\"pts\"]}) < k:\n            R.err(\"pts\", \"互不相同的点比簇数还少，无法分成 k 簇\")\n            return None\n        out[\"n\"] = 2 * k\n    elif variant in (\"wbeam\", \"pvessel\", \"tcspring\", \"reducer\"):\n        D = _engine()\n        want = len(D._DESIGN[variant][\"names\"])\n        if n != want:\n            R.err(\"n\", f\"{variant} 是固定的设计问题，n 必须为 {want}，收到 {n}\")\n            return None\n    return out\n\n\ndef _v_kpvar(p, R, variant):\n    out = _v_generic(\"kpvar\", p, R, variant)\n    if out is None:\n        return None\n    for key in (\"w\", \"w2\"):\n        flat = out.get(key)\n        if flat is not None:\n            xs = [x for row in flat for x in (row if isinstance(row, list) else [row])]\n            if any(x <= 0 for x in xs):\n                R.err(key, \"重量必须全部大于 0\")\n                return None\n    for it in out.get(\"items\", []):\n        if it[0] <= 0:\n            R.err(\"items\", \"物品重量（每项第 0 个数）必须大于 0\")\n            return None\n    return out\n\n\ndef _v_bpvar(p, R, variant):\n    out = _v_generic(\"bpvar\", p, R, variant)\n    if out is None:\n        return None\n    if variant == \"vsbinpack\":\n        biggest = max(b[0] for b in out[\"bin_types\"])\n        bad = [i for i, w in enumerate(out[\"items\"]) if w > biggest]\n        if bad:\n            R.err(f\"items[{bad[0]}]\", f\"物品尺寸超过最大箱型容量 {biggest}，装不下\")\n            return None\n    elif variant == \"binpack2d\":\n        for i, (w, h) in enumerate(out[\"items\"]):\n            if w > out[\"binW\"] or h > out[\"binH\"]:\n                R.err(f\"items[{i}]\", f\"物品 {w}×{h} 比箱子 {out['binW']}×{out['binH']} 还大，装不下\")\n                return None\n    return out\n\n\n# ------------------------------------------------------------------ 总入口\n\n_SIMPLE = {\"tsp\": _v_tsp, \"knapsack\": _v_knapsack, \"multiobj\": _v_multiobj, \"binpack\": _v_binpack,\n           \"graphcolor\": _v_graphcolor, \"setcover\": _v_setcover, \"sat\": _v_sat, \"qubo\": _v_qubo,\n           \"gap\": _v_gap, \"uflp\": _v_uflp, \"continuous\": _v_continuous}\n\n\ndef validate(domain, data, variant=None, dry_run=False):\n    \"\"\"校验并规整一个实例。dry_run=True 时额外用引擎真跑 2 代做兜底（会占用引擎的全局运行态，\n    页面上只应在空闲时调用）。\"\"\"\n    R = _R()\n    if domain not in CORE_DOMAINS:\n        R.err(\"domain\", f\"不支持的问题域 {_show(domain)}。可选：{', '.join(CORE_DOMAINS)}\")\n        return _result(R, None)\n    if domain == \"tsp\":\n        prob = _v_tsp(data, R)\n        return _result(R, prob)\n    if not isinstance(data, dict):\n        R.err(\"\", \"实例应为 JSON 对象（花括号），收到 \" + _show(data))\n        return _result(R, None)\n    variant = variant or data.get(\"variant\")\n    try:\n        if domain in _SIMPLE:\n            prob = _SIMPLE[domain](data, R)\n        elif domain == \"gcvar\":\n            prob = _v_gcvar(data, R, variant or \"mis\")\n        elif domain == \"custom\":\n            prob = _v_custom(data, R, variant)\n        elif domain == \"mocont\":\n            prob = _v_mocont(data, R, variant or \"zdt1\")\n        elif domain in (\"kpvar\", \"bpvar\", \"entryseq\"):\n            if not variant:\n                R.err(\"variant\", f\"{domain} 需要指定 variant（变体）\")\n                prob = None\n            elif domain == \"kpvar\":\n                prob = _v_kpvar(data, R, variant)\n            elif domain == \"bpvar\":\n                prob = _v_bpvar(data, R, variant)\n            else:\n                prob = _v_entryseq(data, R, variant)\n        else:  # pragma: no cover\n            prob = None\n    except ImportError:\n        R.err(\"\", \"缺少 domains.py（校验器需要与引擎同目录）\")\n        prob = None\n    if prob is not None and not R.errors:\n        _fidelity_warning(domain, prob.get(\"variant\") if isinstance(prob, dict) else None, R)\n    if prob is not None and dry_run and not R.errors:\n        _dry_run(domain, prob, R)\n        if R.errors:\n            prob = None\n    return _result(R, prob if not R.errors else None)\n\n\n_FID_PREFIX = {\"simplified\": \"这是「教学简化模型」\", \"illustrative\": \"这是「示意模型」\"}\n_FID_TAIL = {\"simplified\": \"结果不能与文献对照。\", \"illustrative\": \"它只借这个问题的名字演示形态，不是该问题本身。\"}\n\n\ndef _fidelity_warning(domain, variant, R):\n    \"\"\"entryseq 词条的变体多为教学简化/示意模型：用户上传自己的数据时必须被告知。\"\"\"\n    if domain != \"entryseq\" or not variant:\n        return\n    try:\n        fid = getattr(_engine(), \"FIDELITY\", {}).get(variant)\n    except ImportError:\n        return\n    if fid and fid[\"level\"] in _FID_PREFIX:\n        R.warn(\"\", f\"{_FID_PREFIX[fid['level']]}（{domain}/{variant}）：{fid['note']}。{_FID_TAIL[fid['level']]}\")\n\n\ndef _dry_run(domain, prob, R):\n    D = _engine()\n    try:\n        opts = {\"variant\": prob[\"variant\"]} if \"variant\" in prob else {}\n        algos = [a[\"key\"] for a in json.loads(D.domain_list(domain, opts))[\"algos\"]]\n        for algo in [a for a in (\"random\", \"sa\") if a in algos] or algos[:1]:\n            D.domain_start(domain, json.dumps(prob), algo, json.dumps({\"max_iter\": 3, \"seed\": 7}))\n            for _ in range(3):\n                D.domain_step()\n    except Exception as e:\n        R.err(\"\", f\"引擎试跑失败：{type(e).__name__}: {str(e)[:120]}（实例结构通过了检查，但引擎无法处理，请核对数据含义）\")\n\n\ndef _result(R, prob):\n    return {\"ok\": not R.errors, \"errors\": R.errors, \"warnings\": R.warnings,\n            \"problem\": prob if not R.errors else None}\n\n\n# ------------------------------------------------------------------ 文件解析\n\n_GUESS = (  # (必须出现的键, 域)——只在唯一匹配时使用\n    ({\"cities\"}, \"tsp\"), ({\"n_vars\", \"clauses\"}, \"sat\"), ({\"clauses\"}, \"sat\"), ({\"Q\"}, None),\n    ({\"n_el\", \"sets\"}, \"setcover\"), ({\"sets\", \"costs\"}, \"setcover\"),\n    ({\"n_f\", \"c_cost\"}, \"uflp\"), ({\"f_cost\", \"c_cost\"}, \"uflp\"), ({\"n_a\", \"c\", \"r\"}, \"gap\"),\n    ({\"c\", \"r\", \"cap\"}, \"gap\"), ({\"fn\"}, \"continuous\"), ({\"variant\", \"objective\", \"n\"}, \"custom\"),\n)\n\n\ndef guess_domain(data):\n    if not isinstance(data, dict):\n        return None\n    keys = set(data)\n    if \"Q\" in keys:\n        return \"kpvar\" if \"w\" in keys else \"qubo\"\n    for need, dom in _GUESS:\n        if dom and need <= keys:\n            return dom\n    if \"edges\" in keys and \"variant\" not in keys:\n        return \"graphcolor\"\n    return None\n\n\ndef load(text_or_obj, domain=None, filename=None):\n    \"\"\"把上传内容读成 (domain, data, issues)。支持 JSON 信封 / 裸 JSON / CSV / DIMACS。\"\"\"\n    R = _R()\n    obj = text_or_obj\n    name = (filename or \"\").lower()\n    if isinstance(obj, (bytes, bytearray)):\n        obj = obj.decode(\"utf-8-sig\", errors=\"replace\")\n    if isinstance(obj, str):\n        txt = obj.lstrip(\"﻿\").strip()\n        if not txt:\n            R.err(\"\", \"文件是空的\")\n            return domain, None, R\n        if name.endswith((\".tsp\", \".atsp\")) or (txt[0] not in \"[{\" and _looks_like_tsplib(txt)):\n            if domain == \"entryseq\":  # ATSP 页：读 TYPE: ATSP 的 TSPLIB 文件\n                return \"entryseq\", _parse_tsplib(txt, R, atsp=True), R\n            if domain not in (None, \"tsp\"):\n                R.err(\"domain\", f\"这是 TSPLIB（旅行商）文件，但当前页面是 '{domain}'\")\n                return domain, None, R\n            return \"tsp\", _parse_tsplib(txt, R), R\n        if name.endswith(\".cnf\") or re.search(r\"^p\\s+cnf\\b\", txt, re.M):\n            return \"sat\", _parse_cnf(txt, R), R\n        if name.endswith(\".col\") or re.search(r\"^p\\s+edge\\b\", txt, re.M):\n            return \"graphcolor\" if domain in (None, \"graphcolor\") else domain, _parse_col(txt, R), R\n        if txt[0] in \"[{\":\n            try:\n                obj = json.loads(txt)\n            except ValueError as e:\n                R.err(\"\", f\"不是合法 JSON：{e}\")\n                return domain, None, R\n        else:\n            if domain is None:\n                R.err(\"domain\", \"CSV/文本文件需要指定问题域（knapsack/binpack/graphcolor/qubo/tsp）\")\n                return None, None, R\n            return domain, _parse_csv(domain, txt, R), R\n    if isinstance(obj, dict) and obj.get(\"schema\") == SCHEMA:\n        d = obj.get(\"domain\")\n        if domain and d and domain != d:\n            R.err(\"domain\", f\"文件内容属于 '{d}'，但当前页面/参数是 '{domain}'\")\n            return domain, None, R\n        data = obj.get(\"data\")\n        if obj.get(\"variant\") and isinstance(data, dict):\n            data = dict(data, variant=data.get(\"variant\", obj[\"variant\"]))\n        return d or domain, data, R\n    if isinstance(obj, dict) and obj.get(\"schema\") == RESULT_SCHEMA:\n        d = obj.get(\"domain\")\n        if domain and d and domain != d:\n            R.err(\"domain\", f\"这个结果文件属于 '{d}'，但当前页面/参数是 '{domain}'\")\n            return domain, None, R\n        prob = obj.get(\"problem\")\n        if not isinstance(prob, dict):\n            R.err(\"problem\", \"结果文件里没有 problem（实例）字段，无法当作问题文件导入\")\n            return d or domain, None, R\n        if obj.get(\"variant\") and \"variant\" not in prob:\n            prob = dict(prob, variant=obj[\"variant\"])\n        return d or domain, prob, R\n    if isinstance(obj, dict) and obj.get(\"format\") in (\"domain-experiment/v1\", \"domain-experiment-bundle/v1\"):\n        return obj.get(\"domain\") or domain, obj.get(\"problem\"), R\n    if domain is None:\n        domain = guess_domain(obj)\n        if domain is None and not (isinstance(obj, list) and obj and isinstance(obj[0], list)):\n            R.err(\"domain\", \"无法判断问题域：请使用 swarm-problem/v1 信封，或显式指定 domain\")\n            return None, None, R\n        if domain is None:\n            domain = \"tsp\"\n    return domain, obj, R\n\n\ndef _num_or_err(R, where, tok):\n    try:\n        f = float(tok)\n        return int(f) if f.is_integer() and re.fullmatch(r\"[+-]?\\d+(\\.0+)?\", tok.strip()) else f\n    except ValueError:\n        R.err(where, f\"应为数字，收到 {_show(tok)}\")\n        return None\n\n\ndef _csv_rows(txt):\n    meta, rows = {}, []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s:\n            continue\n        if s.startswith(\"#\"):\n            for k, v in re.findall(r\"(\\w+)\\s*=\\s*([^\\s,]+)\", s):\n                meta[k] = v\n            continue\n        rows.append((ln, next(csv.reader([s], delimiter=\";\" if \";\" in s and \",\" not in s else \",\"))))\n    return meta, rows\n\n\ndef _parse_csv(domain, txt, R):\n    meta, rows = _csv_rows(txt)\n    if rows and not all(re.fullmatch(r\"[+-]?\\d*\\.?\\d+([eE][+-]?\\d+)?\", t.strip()) for t in rows[0][1] if t.strip()):\n        rows = rows[1:]  # 跳过表头\n    table = []\n    for ln, r in rows:\n        vals = [_num_or_err(R, f\"第 {ln} 行\", t) for t in r if t.strip() != \"\"]\n        if None in vals:\n            return None\n        table.append(vals)\n    if not table:\n        R.err(\"\", \"没有读到任何数据行\")\n        return None\n    if domain == \"knapsack\":\n        if \"cap\" not in meta and \"capacity\" not in meta:\n            R.err(\"cap\", \"CSV 需要在文件开头用注释行写容量，例如：# cap=532\")\n            return None\n        return {\"cap\": _num_or_err(R, \"cap\", meta.get(\"cap\", meta.get(\"capacity\"))), \"items\": table}\n    if domain == \"binpack\":\n        if \"cap\" not in meta and \"capacity\" not in meta:\n            R.err(\"cap\", \"CSV 需要在文件开头用注释行写箱容量，例如：# cap=150\")\n            return None\n        return {\"cap\": _num_or_err(R, \"cap\", meta.get(\"cap\", meta.get(\"capacity\"))), \"items\": [r[0] for r in table]}\n    if domain == \"qubo\":\n        return {\"Q\": table}\n    if domain == \"tsp\":\n        return _csv_tsp(table, meta, R)\n    if domain in (\"graphcolor\", \"gcvar\"):\n        d = {\"edges\": table}\n        if \"n\" in meta:\n            d[\"n\"] = int(meta[\"n\"])\n        return d\n    R.err(\"domain\", f\"域 '{domain}' 不支持 CSV；请使用 JSON（见 docs/data-formats.md）\")\n    return None\n\n\ndef _parse_cnf(txt, R):\n    n_vars, clauses, cur = None, [], []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s or s[0] in \"c%\":\n            continue\n        if s.startswith(\"p\"):\n            parts = s.split()\n            if len(parts) < 4 or parts[1] != \"cnf\":\n                R.err(f\"第 {ln} 行\", \"DIMACS 头应为：p cnf <变量数> <子句数>\")\n                return None\n            n_vars = int(parts[2])\n            continue\n        for tok in s.split():\n            try:\n                v = int(tok)\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"DIMACS 里应为整数，收到 {_show(tok)}\")\n                return None\n            if v == 0:\n                if cur:\n                    clauses.append(cur)\n                cur = []\n            else:\n                cur.append(v)\n    if cur:\n        clauses.append(cur)\n    if n_vars is None:\n        R.warn(\"n_vars\", \"缺少 'p cnf' 头，将按最大变量编号推断\")\n    return {\"n_vars\": n_vars, \"clauses\": clauses} if n_vars is not None else {\"clauses\": clauses}\n\n\ndef _parse_col(txt, R):\n    n, edges = None, []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip().split()\n        if not s or s[0] == \"c\":\n            continue\n        if s[0] == \"p\":\n            if len(s) < 3:\n                R.err(f\"第 {ln} 行\", \"DIMACS 头应为：p edge <顶点数> <边数>\")\n                return None\n            n = int(s[2])\n        elif s[0] == \"e\" and len(s) >= 3:\n            try:\n                edges.append([int(s[1]) - 1, int(s[2]) - 1])  # DIMACS 顶点从 1 起，转 0 起\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"边应为 e <u> <v>，收到 {_show(line.strip())}\")\n                return None\n    d = {\"edges\": edges}\n    if n is not None:\n        d[\"n\"] = n\n    return d\n\n\ndef to_envelope(domain, data, variant=None):\n    env = {\"schema\": SCHEMA, \"domain\": domain}\n    if variant:\n        env[\"variant\"] = variant\n    env[\"data\"] = data\n    return env\n\n\ndef supported(domain):\n    return domain in CORE_DOMAINS\n\n\ndef check_text(text, domain=None, filename=None, dry_run=False, variant=None):\n    \"\"\"一步到位：读取 + 校验。返回 {\"domain\", \"ok\", \"errors\", \"warnings\", \"problem\"}。\n    variant：调用方（如固定变体的页面）期望的变体；文件里写了不同变体时报错，而不是悄悄按错的结构去跑。\"\"\"\n    d, data, R = load(text, domain, filename)\n    if data is None or R.errors:\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings, \"problem\": None}\n    if variant and isinstance(data, dict) and data.get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"文件是变体 '{data['variant']}' 的数据，而这里需要变体 '{variant}'（请到对应变体的页面导入）\")\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings, \"problem\": None}\n    res = validate(d, data, variant=variant, dry_run=dry_run)\n    if variant and res[\"ok\"] and res[\"problem\"].get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"数据是变体 '{res['problem']['variant']}' 的格式，而这里需要变体 '{variant}'（请到对应变体的页面导入）\")\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings + res[\"warnings\"], \"problem\": None}\n    res[\"domain\"] = d\n    res[\"warnings\"] = R.warnings + res[\"warnings\"]\n    return res\n";
